BEGIN;
CREATE TABLE IF NOT EXISTS public.curriculum_substrands (
    code TEXT PRIMARY KEY, subject_key TEXT NOT NULL, grade INT NOT NULL CHECK (grade BETWEEN 1 AND 12),
    strand TEXT NOT NULL, sub_strand TEXT NOT NULL, sequence INT NOT NULL DEFAULT 0, source TEXT NOT NULL DEFAULT 'starter',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    framework TEXT NOT NULL DEFAULT 'cbc', lessons INT, detail JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS curriculum_substrands_lookup ON public.curriculum_substrands (subject_key, grade, sequence);
CREATE TABLE IF NOT EXISTS public.curriculum_outcomes (
    code TEXT PRIMARY KEY, substrand_code TEXT NOT NULL REFERENCES public.curriculum_substrands(code) ON DELETE CASCADE,
    letter TEXT NOT NULL, text TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'kicd_verified', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.curriculum_skills (
    code TEXT PRIMARY KEY, substrand_code TEXT NOT NULL REFERENCES public.curriculum_substrands(code) ON DELETE CASCADE,
    subject_key TEXT NOT NULL, grade INT NOT NULL, name TEXT NOT NULL, outcome_codes TEXT[] NOT NULL DEFAULT '{}',
    mastery TEXT, question_forms JSONB NOT NULL DEFAULT '[]'::jsonb, thinking JSONB NOT NULL DEFAULT '[]'::jsonb,
    horeb_skill_ids TEXT[] NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'proposed', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS curriculum_skills_substrand ON public.curriculum_skills (substrand_code);
CREATE TABLE IF NOT EXISTS public.curriculum_prerequisites (
    skill_code TEXT NOT NULL REFERENCES public.curriculum_skills(code) ON DELETE CASCADE, requires_code TEXT NOT NULL,
    requires_kind TEXT NOT NULL CHECK (requires_kind IN ('skill','outcome')), strength TEXT NOT NULL DEFAULT 'essential',
    reason TEXT, status TEXT NOT NULL DEFAULT 'proposed', PRIMARY KEY (skill_code, requires_code));
CREATE TABLE IF NOT EXISTS public.curriculum_misconceptions (
    code TEXT PRIMARY KEY, skill_code TEXT NOT NULL REFERENCES public.curriculum_skills(code) ON DELETE CASCADE,
    error TEXT NOT NULL, example JSONB NOT NULL, cause TEXT, reveals TEXT, help TEXT, status TEXT NOT NULL DEFAULT 'draft',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS curriculum_misconceptions_skill ON public.curriculum_misconceptions (skill_code);

DO $$
DECLARE d jsonb := $CURR${"framework":"cbc","subject_key":"mathematics","grade":5,"source":"KICD Grade 5 Mathematics Curriculum Design, revised 2024 (text layer)","status":"structure verified against KICD; skills and prerequisites proposed; misconceptions draft; all awaiting teacher review","totals":{"strands":4,"sub_strands":19,"outcomes":122,"lessons":150,"skills":167,"prerequisites":422,"misconceptions":414},"sub_strands":[{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS","number":"1.1","strand":"Numbers","sub_strand":"Whole Numbers","sequence":101,"lessons":20,"content_topics":["Place value and total value","Reading and writing numbers in words","Rounding off numbers","Divisibility tests","HCF/GCD and LCM"],"learning_experiences":["identify place value of digits up to hundreds of thousands using place value apparatus or place value charts","identify total value of digits up to hundreds of thousands using place value charts","read numbers up to hundreds of thousands in symbols from number charts or cards","read and write numbers up to tens of thousands in words from number charts or cards","arrange numbers up to tens of thousands in increasing and decreasing order","discuss and round off numbers up to tens of thousands to the nearest hundred and thousand using number cards and share with other groups","carry out the divisibility test for 2, 5 and 10 and come up with divisibility rules","express numbers in terms of their factors then identify the common factors","express the multiples of numbers and identify multiples of the common multiples as well as the least common multiples","play games involving numbers using digital devices or other resources"],"key_inquiry_questions":["Where can we use ordering of numbers in real life?","Why should we round off numbers?"],"core_competences":"● Critical thinking and problem solving: learner orders and rounds off numbers. ● Learning to learn: learner reads and writes numbers, computing the total values of numbers.","values":"Unity: learner works with peers in identifying factors, divisors and multiples of numbers to enhance unity.","pcis":"Safety: learner observes safety precautions while handling apparatus for carrying out operations on numbers.","links":"The learner is able to relate whole numbers to reading and writing numbers symbols and words in languages.","design_notes":"1) Outcome h ('appreciate use of whole numbers in real-life situations') is attitudinal and is not mapped to a skill. It could be observed through project or group work. 2) The number ranges are uneven, but each skill respects its outcome's limit. Outcome a goes up to hundreds of thousands (999,999), while b, c and d go only up to tens of thousands (99,999). One learning experience, 'read numbers up to hundreds of thousands in symbols', has no matching outcome; it is placed under G5_TOTAL_VALUE_HTH as a proposed inclusion. 3) Rounding numbers near the top of the range can give answers outside it (99,960 rounds to 100,000). Proposed: treat this as valid, since 'numbers up to tens of thousands' describes the input. 4) Outcomes e, f and g set no size limits. The limits used here are proposed: up to 99,999 for divisibility, up to 100 for HCF, and up to 20 for LCM (two or three numbers). The design does not say whether prime factorisation is expected; 'express numbers in terms of their factors' may mean factor-pair or product form, so listing is treated as the core method. 5) HCF and GCD are the same quantity. The outcome lists them as two names, and the skill tests both terms rather than splitting them. 6) Outcome c does not say whether the symbols > and < are expected; they appear as proposed only (HOREB places them under G6_INEQUALITIES). 7) The key inquiry questions in the input are garbled. They appear to read: 'Where can we use ordering of numbers in real life?' and 'Why should we round off numbers?' 8) Grade 4 ordered numbers only up to 1,000 (G4:1.1d) and wrote words only up to 1,000 (G4:1.1c). Grade 5 jumps to tens of thousands, so bridging practice may be needed. 9) The existing HOREB skill G5_PLACE_VALUE is labelled 'Thousands', which is narrower than outcome a (hundreds of thousands); its label or range may need updating. HOREB's G5_FACTORS and G5_MULTIPLES overlap the factor/multiple listing skills, but there are no existing HOREB skills for rounding, divisibility tests or reading/writing numbers in words.","outcomes":[{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.a","letter":"a","text":"use place value and total value of digits up to hundreds of thousands in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.b","letter":"b","text":"read and write numbers up to tens of thousands in words in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.c","letter":"c","text":"order numbers up to tens of thousands in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.d","letter":"d","text":"round off numbers up to tens of thousands to the nearest hundred and thousand in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.e","letter":"e","text":"apply divisibility tests of 2, 5 and 10 in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.f","letter":"f","text":"determine Highest Common Factor (HCF) and Greatest Common Divisor (GCD) in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.g","letter":"g","text":"determine Least Common Multiple (LCM) in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.h","letter":"h","text":"appreciate use of whole numbers in real-life situations","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","name":"Place value of digits up to hundreds of thousands","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.a"],"mastery":"Given any whole number up to 999,999, the child names the place of any digit (ones, tens, hundreds, thousands, ten thousands, hundred thousands), including digits next to or after zeros. Given a place, the child says which digit is in it. The child can show the number on a place value chart or apparatus.","question_forms":["name the place of an underlined digit","which digit is in the given place","read a place value chart or abacus","build a number from place clues (missing number)"],"thinking":["recall","procedure"],"horeb_skill_ids":["G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Extends place value from tens of thousands to hundreds of thousands.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.b","kind":"outcome","strength":"helpful","reason":"Fluent reading of numbers in symbols up to 10,000 supports reading six-digit numbers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH","name":"Total value of digits and expanded form up to hundreds of thousands","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.a"],"mastery":"For numbers up to 999,999 the child gives the total value of any digit (for example, the 8 in 487,306 is worth 80,000). The child writes a number as the sum of the total values of its digits and rebuilds a number from total values, including when some places are empty. Proposed: this skill also covers reading six-digit numbers in symbols from charts or cards, which the learning experiences mention.","question_forms":["total value of an underlined digit","write as sum of total values (expanded form)","number from given total values, including empty places","difference between total values of two digits","word problem: money in shillings by place"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"essential","reason":"Total value is the digit times its place, so the place must be known first.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Total value up to tens of thousands was introduced in Grade 4.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS","name":"Write numbers up to tens of thousands in words","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.b"],"mastery":"The child reads aloud and writes in correctly spelt words any whole number up to 99,999. This includes numbers with zeros in the middle, such as 40,507 (forty thousand, five hundred and seven), and uses 'and' and hyphens in the British way.","question_forms":["write the number in words","read the number aloud","spot and correct the spelling or wording error","word problem: write the amount on a cheque or receipt"],"thinking":["recall","procedure"],"horeb_skill_ids":["G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.c","kind":"outcome","strength":"essential","reason":"Writing numbers to 1,000 in words gives the 'hundreds, tens and ones' wording used in each part of a larger number.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"essential","reason":"The child must split the number into thousands and the rest to say it correctly.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS","name":"Write numbers given in words in symbols (up to tens of thousands)","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.b"],"mastery":"The child turns any number up to 99,999 given in words into digits. Zeros go in the correct places, as in twelve thousand and five = 12,005, and the child does not write the number as it sounds.","question_forms":["write the number in symbols","match words to numerals","dictation: write the number you hear","word problem: number of people in a news report or census"],"thinking":["procedure"],"horeb_skill_ids":["G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS","kind":"skill","strength":"helpful","reason":"Knowing how numbers are spoken helps reverse the process.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.b","kind":"outcome","strength":"essential","reason":"Writing numbers in symbols up to 10,000 is the base for writing larger ones.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"essential","reason":"Zeros must be placed in empty places, which needs place value.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMPARE_NUMBERS","name":"Compare two numbers up to tens of thousands","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.c"],"mastery":"The child decides which of two numbers up to 99,999 is greater or smaller. First the child compares the number of digits, then compares place by place from the left. The child explains the decision using place value.","question_forms":["which is greater/smaller","compare and explain","fill in 'greater than'/'less than' (proposed: or the symbols > and <)","word problem: which county or school has more"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_PLACE_VALUE","G6_INEQUALITIES"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"essential","reason":"Comparison is done place by place from the highest place.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.d","kind":"outcome","strength":"essential","reason":"Ordering numbers to 1,000 is the same method on smaller numbers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ORDER_NUMBERS","name":"Arrange numbers up to tens of thousands in increasing and decreasing order","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.c"],"mastery":"The child arranges a set of numbers, each up to 99,999 (proposed: 3 to 6 numbers), in increasing or decreasing order as asked. This includes sets where the numbers share leading digits or have different numbers of digits.","question_forms":["arrange in increasing order","arrange in decreasing order","which number is out of place","word problem: order distances, populations or prices from smallest to largest"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMPARE_NUMBERS","kind":"skill","strength":"essential","reason":"Ordering a set is repeated comparison of pairs.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.d","kind":"outcome","strength":"essential","reason":"Increasing/decreasing order language was learnt in Grade 4.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED","name":"Round off numbers up to tens of thousands to the nearest hundred","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.d"],"mastery":"The child rounds any whole number up to 99,999 to the nearest hundred by looking only at the tens digit. The child keeps the place of every digit, handles rounding that carries into the next place (for example, 39,960 becomes 40,000) and rounds a tens digit of 5 up.","question_forms":["round to the nearest hundred","which hundred is it closest to (number line)","which numbers round to a given value","word problem: approximate amount in shillings"],"thinking":["procedure","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"essential","reason":"Rounding to the nearest ten uses the same 'look at the next digit to the right' rule.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"essential","reason":"The child must find the hundreds and tens digits.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND","name":"Round off numbers up to tens of thousands to the nearest thousand","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.d"],"mastery":"The child rounds any whole number up to 99,999 to the nearest thousand by looking only at the hundreds digit. This includes rounding that carries into the next place (for example, 59,650 becomes 60,000). The child can explain why we round, for example when reporting crowd sizes or prices.","question_forms":["round to the nearest thousand","round the same number to the nearest hundred and to the nearest thousand","which numbers round to a given thousand","word problem: estimate attendance or cost"],"thinking":["procedure","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED","kind":"skill","strength":"helpful","reason":"The same rule applied one place higher.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"essential","reason":"The child must find the thousands and hundreds digits.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2","name":"Apply the divisibility test for 2","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.e"],"mastery":"The child states the rule that a number is divisible by 2 when its ones digit is 0, 2, 4, 6 or 8. The child uses it to decide, without dividing, whether a number is divisible by 2. Proposed limit: numbers up to 99,999.","question_forms":["is it divisible by 2? yes/no with reason","pick the numbers divisible by 2 from a list","missing digit so the number is divisible by 2","state the rule"],"thinking":["recall","procedure"],"horeb_skill_ids":["G5_DIVISION","G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.h","kind":"outcome","strength":"essential","reason":"Divisible by 2 means even, so the child needs to recognise even numbers.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.a","kind":"outcome","strength":"helpful","reason":"Dividing and seeing a remainder lets children check and discover the rule.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10","name":"Apply the divisibility tests for 5 and 10","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.e"],"mastery":"The child states and uses two rules: a number is divisible by 5 if its ones digit is 0 or 5, and by 10 if its ones digit is 0. The child recognises that any number divisible by 10 is also divisible by 2 and by 5. Proposed limit: numbers up to 99,999.","question_forms":["is it divisible by 5/10? with reason","sort numbers into divisible by 2, 5, 10 (Venn or table)","missing digit","which of 2, 5 and 10 divide this number","discover the rule from a pattern of examples"],"thinking":["recall","procedure","reasoning"],"horeb_skill_ids":["G5_DIVISION","G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.g","kind":"outcome","strength":"essential","reason":"The rules come from the ending-digit pattern in multiples of 5 and 10.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.a","kind":"outcome","strength":"helpful","reason":"Division with and without remainder gives meaning to 'divisible'.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","kind":"skill","strength":"helpful","reason":"Knowing which digit is the ones digit is needed in long numbers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBILITY_PROBLEMS","name":"Use divisibility tests of 2, 5 and 10 in real-life problems","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.e"],"mastery":"In everyday situations such as sharing, packing or paying with coins and notes, the child picks the relevant divisor (2, 5 or 10). The child applies the test to decide whether the items or money can be shared or packed exactly with nothing left over, and explains the answer.","question_forms":["word problem: sharing equally between 2","word problem: packing in fives or tens","word problem: paying exactly with Sh 5 / Sh 10 coins","yes/no with explanation"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_DIVISION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2","kind":"skill","strength":"essential","reason":"Sharing between two needs the test for 2.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10","kind":"skill","strength":"essential","reason":"Packing in fives or tens needs these tests.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS","name":"List factors and identify common factors","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.f"],"mastery":"The child lists all factors of numbers up to 100 (proposed limit) systematically in pairs, including 1 and the number itself. The child writes a number as a product of factors and picks out the factors common to two or three numbers.","question_forms":["list all factors","write as a product of factors","list common factors of two/three numbers","is n a common factor of a and b?"],"thinking":["procedure"],"horeb_skill_ids":["G5_FACTORS"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.f","kind":"outcome","strength":"essential","reason":"Identifying factors of numbers to 50 extends to common factors.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.b","kind":"outcome","strength":"essential","reason":"Factor pairs come from relating multiplication and division.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2","kind":"skill","strength":"helpful","reason":"Quickly spotting 2 as a factor speeds up listing.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10","kind":"skill","strength":"helpful","reason":"Quickly spotting 5 and 10 as factors speeds up listing.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD","name":"Determine the HCF (GCD) of two or three numbers","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.f"],"mastery":"The child finds the Highest Common Factor of two or three numbers up to 100 (proposed limit) by listing common factors. Proposed: the child may also use factor or prime-factor form. The child knows that HCF and GCD (Greatest Common Divisor) name the same number.","question_forms":["find the HCF","find the GCD (same task, other name)","true/false: the HCF of a and b is n","missing number given the HCF"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_FACTORS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS","kind":"skill","strength":"essential","reason":"The HCF is the greatest of the common factors.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_PROBLEMS","name":"Solve real-life problems using HCF/GCD","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.f"],"mastery":"The child recognises 'largest equal piece/group with nothing left over' situations and uses the HCF to solve them. Examples are cutting ribbons or timber, or packing two kinds of fruit into identical bags. The child answers the question actually asked: the size of each group or the number of groups.","question_forms":["word problem: longest equal pieces","word problem: largest number of identical groups","word problem: biggest equal containers","choose HCF or LCM and explain"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_FACTORS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD","kind":"skill","strength":"essential","reason":"The problem is solved by finding the HCF.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.a","kind":"outcome","strength":"helpful","reason":"Finding the number of groups after the HCF needs division.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_MULTIPLES","name":"List multiples and identify common multiples","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.g"],"mastery":"The child lists multiples of numbers up to 20 (proposed limit), starting with the number itself. The child identifies common multiples of two or three such numbers and notices that common multiples repeat at regular steps.","question_forms":["list the first n multiples","list common multiples of two/three numbers","is n a common multiple of a and b?","continue the pattern of common multiples"],"thinking":["procedure"],"horeb_skill_ids":["G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.g","kind":"outcome","strength":"essential","reason":"Identifying multiples to 100 is the base for common multiples.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"helpful","reason":"Multiplying 2-digit numbers helps extend lists beyond times tables.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM","name":"Determine the LCM of two or three numbers","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.g"],"mastery":"The child finds the Least Common Multiple of two or three numbers, each not exceeding 20 (proposed limit), by listing multiples. Proposed: the child may also use factor or prime-factor form. The child knows the LCM is never smaller than the largest of the numbers.","question_forms":["find the LCM","true/false: the LCM of a and b is n","missing number given the LCM","compare the LCM with the product"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_MULTIPLES","kind":"skill","strength":"essential","reason":"The LCM is the smallest of the common multiples.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM_PROBLEMS","name":"Solve real-life problems using LCM","outcomes":["MATH.G5.NUMBER.WHOLE_NUMBERS.g"],"mastery":"The child recognises 'when will they next happen together / smallest amount that fits both' situations and uses the LCM to solve them. Examples are matatus leaving a stage, bells ringing, and buying items sold in different pack sizes. The child converts the answer to the form asked, such as a clock time.","question_forms":["word problem: events repeating together (bells, buses)","word problem: smallest number that can be packed in a's or b's","word problem: clock time of next meeting","choose HCF or LCM and explain"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM","kind":"skill","strength":"essential","reason":"The problem is solved by finding the LCM.","status":"proposed"},{"requires":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_PROBLEMS","kind":"skill","strength":"helpful","reason":"Contrasting the two problem types helps children choose the right one.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH.M_PV_GIVES_TOTAL_VALUE","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","error":"Gives the total value when asked for the place value.","example":{"question":"What is the place value of 7 in 374,512?","wrong_answer":"70,000","correct_answer":"Ten thousands"},"cause":"The child mixes up the two terms 'place value' (the name of the position) and 'total value' (what the digit is worth).","reveals":"Ask for both values of the same digit in one item, or offer '70,000' as a distractor among place names.","help":"Use a place value chart with labelled columns. Have the child first read the column name (place value), then multiply by the digit (total value), saying both aloud.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH.M_PV_MISCOUNT_PLACES","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","error":"Counts places wrongly in six-digit numbers, often naming the place one too low.","example":{"question":"What is the place value of 2 in 203,415?","wrong_answer":"Ten thousands","correct_answer":"Hundred thousands"},"cause":"The child counts places from the left, or does not yet extend the place sequence past ten thousands.","reveals":"Use digits in the leftmost place of six-digit numbers, with the neighbouring place name as a distractor.","help":"Always count places from the ones (right) end, using the comma to find the thousands group: ones, tens, hundreds | thousands, ten thousands, hundred thousands.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH.M_PV_SKIPS_ZERO","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HTH","error":"Ignores a zero digit when counting places, shifting every digit to its left.","example":{"question":"What is the place value of 3 in 305,214?","wrong_answer":"Ten thousands","correct_answer":"Hundred thousands"},"cause":"The child believes zero 'is nothing' and does not need its own place.","reveals":"Ask about digits to the left of an internal zero.","help":"Write the number into a place value chart. Show that the zero column is an empty but real place, like an empty seat that still counts.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH.M_TV_FACE_VALUE","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH","error":"Gives the digit itself as its total value.","example":{"question":"What is the total value of 8 in 487,306?","wrong_answer":"8","correct_answer":"80,000"},"cause":"The child sees the digit as a separate number rather than a count of its place.","reveals":"Include the bare digit as a distractor in multiple choice.","help":"Use bundles or place value cards (80,000 + 7,000 + ...) to show that the 8 stands for 8 ten-thousands.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH.M_TV_WRONG_NUMBER_OF_ZEROS","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH","error":"Adds the wrong number of zeros, for example making the total value as long as the whole number.","example":{"question":"What is the total value of 6 in 162,450?","wrong_answer":"600,000","correct_answer":"60,000"},"cause":"The child counts all the digits in the number instead of the digits to the right of the chosen digit.","reveals":"Use distractors with one zero too many and one too few.","help":"Teach the check: the number of zeros equals the number of digits to the right of the chosen digit, then confirm the place on a chart.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH.M_TV_COMPOSE_DROPS_ZEROS","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH","error":"When building a number from total values, writes the non-zero digits side by side and leaves out empty places.","example":{"question":"Write the number: 400,000 + 5,000 + 30 + 2","wrong_answer":"4,532","correct_answer":"405,032"},"cause":"The child joins the leading digits together without checking which places they belong to.","reveals":"Give expanded forms with missing places, such as no ten thousands and no hundreds.","help":"Have the child stack the place value cards on top of each other, or fill a six-column chart, writing 0 in every empty column.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS.M_WORDS_OMITS_THOUSAND_GROUP","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS","error":"Reads a five-digit number with a zero wrongly, dropping or shrinking the thousands part.","example":{"question":"Write 40,507 in words.","wrong_answer":"four thousand five hundred and seven","correct_answer":"forty thousand, five hundred and seven"},"cause":"The child reads digit by digit and loses track of the zero in the thousands group.","reveals":"Use numbers with zeros in the thousands or hundreds places.","help":"Cover the last three digits and read the thousands group first ('forty thousand'), then uncover and read the rest.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS.M_WORDS_SPELLING_TY","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS","error":"Misspells common tens words, especially 'forty' and 'ninety'.","example":{"question":"Write 45,090 in words.","wrong_answer":"fourty-five thousand and ninty","correct_answer":"forty-five thousand and ninety"},"cause":"The child spells by sound and by analogy with 'four' and 'nine'.","reveals":"Ask the child to choose the correctly written version, with misspelt options alongside.","help":"Display a number-word wall chart and practise spelling 'forty', 'ninety' and 'twelve' regularly.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS.M_SYMBOLS_WRITE_AS_HEARD","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS","error":"Writes each spoken part as its own numeral and joins them together.","example":{"question":"Write 'twelve thousand and five' in symbols.","wrong_answer":"12,0005","correct_answer":"12,005"},"cause":"The child writes '12' and then '000' for thousand, and adds the '5' as heard, without knowing that thousands fill only three places after the comma.","reveals":"Use dictation or words with small endings after 'thousand'.","help":"Draw two groups of digit boxes, thousands and the rest, with exactly three boxes after the comma, and fill each group from the words.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS.M_SYMBOLS_MISSING_PLACEHOLDER","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS","error":"Leaves out zeros for places not mentioned in the words.","example":{"question":"Write 'thirty thousand, four hundred and six' in symbols.","wrong_answer":"30,46","correct_answer":"30,406"},"cause":"Places with no word spoken (here the tens) are not given a digit.","reveals":"Use words that skip the tens or hundreds, and check that the answer has the right number of digits.","help":"Ask 'How many tens?' for every place, including those not said, and write 0 when the answer is none.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS.M_SYMBOLS_TEEN_TY","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS","error":"Confuses 'teen' and 'ty' numbers in the thousands.","example":{"question":"Write 'seventeen thousand' in symbols.","wrong_answer":"70,000","correct_answer":"17,000"},"cause":"The two words sound alike, so the child mishears or misreads which one it is.","reveals":"Use dictation items pairing 'seventeen thousand' and 'seventy thousand'.","help":"Stress the endings when speaking ('seven-TEEN', 'SEV-en-ty') and link 'teen' to 1 ten and 'ty' to several tens.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMPARE_NUMBERS.M_COMPARE_FIRST_DIGIT_ONLY","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMPARE_NUMBERS","error":"Compares the first digits without checking how many digits each number has.","example":{"question":"Which is greater: 9,876 or 12,345?","wrong_answer":"9,876","correct_answer":"12,345"},"cause":"The child applies 'look at the first digit' without first lining up the places.","reveals":"Pair a four-digit number with a large first digit against a five-digit number with a small one.","help":"Write both numbers in a place value chart aligned on the ones. A number with a ten-thousands digit is always bigger than one with none.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMPARE_NUMBERS.M_COMPARE_SYMBOL_DIRECTION","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMPARE_NUMBERS","error":"Knows which number is bigger but writes the comparison symbol the wrong way round.","example":{"question":"Fill in > or <: 45,210 ___ 45,120","wrong_answer":"<","correct_answer":">"},"cause":"The child confuses the two symbols and may read the symbol as pointing to the bigger number.","reveals":"Ask the child to say the statement in words after writing the symbol.","help":"Teach that the open (wide) side faces the bigger number, and have the child read the statement aloud as 'is greater than'.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ORDER_NUMBERS.M_ORDER_DIRECTION_CONFUSED","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ORDER_NUMBERS","error":"Arranges numbers in increasing order when decreasing is asked, or the reverse.","example":{"question":"Arrange in decreasing order: 34,500; 34,050; 35,400","wrong_answer":"34,050; 34,500; 35,400","correct_answer":"35,400; 34,500; 34,050"},"cause":"The child does not yet link 'decreasing' to 'getting smaller'.","reveals":"Ask for both orders of the same set in one item.","help":"Link the words to actions: increasing is climbing up the stairs, decreasing is going down. Have the child say the first number and explain why it comes first.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ORDER_NUMBERS.M_ORDER_LAST_DIGIT","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ORDER_NUMBERS","error":"When the leading digits are the same, sorts by the ones digit instead of the next highest place.","example":{"question":"Arrange in increasing order: 47,815; 47,158; 47,581","wrong_answer":"47,581; 47,815; 47,158","correct_answer":"47,158; 47,581; 47,815"},"cause":"When the first digits tie, the child stops comparing place by place and looks at the last digit.","reveals":"Give sets that share their first two digits but have their ones digits in the opposite order.","help":"Line the numbers up in a chart and have the child cross out matching columns from the left until a difference appears.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED.M_ROUND_CHAIN_ROUNDING","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED","error":"Rounds in steps from the ones upward, so a rounding-up carries forward wrongly.","example":{"question":"Round 23,449 to the nearest hundred.","wrong_answer":"23,500","correct_answer":"23,400"},"cause":"The child first rounds 49 up to 50, then rounds 450 up to 500, instead of looking only at the tens digit.","reveals":"Use numbers whose tens digit is 4 and whose ones digit is 5 or more.","help":"Show the number on a number line between 23,400 and 23,500. Teach the child to underline the hundreds digit and look only at the digit immediately to its right.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED.M_ROUND_DOWN_DECREASES_DIGIT","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED","error":"When rounding down, makes the hundreds digit one smaller.","example":{"question":"Round 45,620 to the nearest hundred.","wrong_answer":"45,500","correct_answer":"45,600"},"cause":"The child takes 'round down' to mean 'reduce the digit'.","reveals":"Include the 'one hundred less' value as a distractor.","help":"Have the child first write the two hundreds the number lies between (45,600 and 45,700), then choose the closer one.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED.M_ROUND_DROPS_DIGITS","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_HUNDRED","error":"Removes the digits after the rounding place instead of replacing them with zeros.","example":{"question":"Round 23,449 to the nearest hundred.","wrong_answer":"234","correct_answer":"23,400"},"cause":"The child thinks rounding means cutting off the end digits.","reveals":"Ask whether the rounded number is close in size to the original, or offer the truncated answer as a distractor.","help":"Stress that the rounded number must be close to the original in size, and have the child compare the two on a number line.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_NO_REGROUP","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND","error":"When rounding up from a 9, writes '10' inside the number instead of regrouping into the next place.","example":{"question":"Round 59,650 to the nearest thousand.","wrong_answer":"510,000","correct_answer":"60,000"},"cause":"The child adds 1 to the 9 and writes the 10 in place, without regrouping 10 thousands into 1 ten thousand.","reveals":"Use numbers with 9 in the rounding place that must round up.","help":"Have the child count on in thousands on a number line (58,000, 59,000, 60,000) and see where the next thousand after 59,000 lands.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_FIVE_DOWN","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND","error":"Rounds down when the deciding digit is exactly 5.","example":{"question":"Round 36,500 to the nearest thousand.","wrong_answer":"36,000","correct_answer":"37,000"},"cause":"The child does not know the convention that a halfway number rounds up, or thinks 5 is 'small'.","reveals":"Use numbers whose hundreds digit is 5 with zeros after.","help":"State the rule clearly that 5 or more rounds up, and practise halfway cases in particular.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_WRONG_PLACE","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND","error":"Rounds to the nearest hundred when asked for the nearest thousand.","example":{"question":"Round 72,480 to the nearest thousand.","wrong_answer":"72,500","correct_answer":"72,000"},"cause":"The child looks at the wrong deciding digit, or carries over habits from rounding to the nearest hundred.","reveals":"Ask for the same number rounded to both the nearest hundred and the nearest thousand.","help":"Have the child check that a number rounded to the nearest thousand ends in at least three zeros.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2.M_DIV2_WRONG_DIGIT","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2","error":"Decides divisibility by 2 from the first digit or any even digit, not the ones digit.","example":{"question":"Is 4,567 divisible by 2?","wrong_answer":"Yes, because 4 is even","correct_answer":"No, the ones digit 7 is odd"},"cause":"The child remembers 'even digit' but not which digit of the number to check.","reveals":"Use numbers that start with an even digit and end with an odd one.","help":"Have the child circle the ones digit before deciding, and check one example by actually dividing.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2.M_DIV2_ZERO_NOT_EVEN","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_2","error":"Thinks a number ending in 0 is not divisible by 2.","example":{"question":"Is 3,450 divisible by 2?","wrong_answer":"No","correct_answer":"Yes, it ends in 0, so 3,450 ÷ 2 = 1,725"},"cause":"The child sees zero as 'nothing' rather than an even digit.","reveals":"Include numbers ending in 0 in sorting tasks.","help":"Count in twos (2, 4, 6, 8, 10, 12 ...) and point out that the multiples ending in 0 appear in the pattern.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10.M_DIV5_ONLY_ENDS_5","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10","error":"Thinks only numbers ending in 5 are divisible by 5.","example":{"question":"Is 2,340 divisible by 5?","wrong_answer":"No","correct_answer":"Yes, it ends in 0, so 2,340 ÷ 5 = 468"},"cause":"The child remembers only half of the rule.","reveals":"Include numbers ending in 0 when asking about 5.","help":"List the multiples of 5 and highlight the endings: 5, 0, 5, 0 ...","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10.M_DIV10_ANY_ZERO","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10","error":"Thinks a number is divisible by 10 if it has a 0 anywhere in it.","example":{"question":"Is 1,205 divisible by 10?","wrong_answer":"Yes","correct_answer":"No, the ones digit is 5, not 0"},"cause":"The child remembers 'zero' but not that it must be the ones digit.","reveals":"Use numbers with a middle zero and a non-zero ones digit.","help":"Have the child circle the ones digit first, as for the test for 2.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10.M_DIV_TESTS_EXCLUSIVE","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBLE_BY_5_AND_10","error":"Treats divisibility by 2, 5 and 10 as separate categories, so a number can belong to only one.","example":{"question":"Which of 2, 5 and 10 divide 7,350 exactly?","wrong_answer":"10 only","correct_answer":"2, 5 and 10"},"cause":"Sorting activities with one box per number lead the child to think each number fits only one rule.","reveals":"Use 'tick all that apply' or Venn diagram sorting tasks.","help":"Sort numbers in a Venn diagram and discuss why every multiple of 10 is in the overlap of the 2 and 5 circles.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBILITY_PROBLEMS.M_DIVPROB_DIVIDE_ANYWAY","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBILITY_PROBLEMS","error":"Answers 'yes' because the number can be divided, ignoring the 'none left over' condition.","example":{"question":"A Kakamega school has 1,235 bananas. Can they be shared equally between 2 classes with none left over?","wrong_answer":"Yes, each class gets 617 and a half","correct_answer":"No. 1,235 ends in 5 (odd), so 1 banana is left over."},"cause":"The child does not yet understand that 'divisible' means dividing exactly, with no remainder.","reveals":"Use contexts with indivisible objects, and ask for yes/no with a reason.","help":"Act out sharing real counters to show what a remainder is, and connect 'divisible' to 'zero remainder'.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBILITY_PROBLEMS.M_DIVPROB_5_NEEDS_0","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.DIVISIBILITY_PROBLEMS","error":"Applies the test for 10 when the problem needs the test for 5.","example":{"question":"Mama Wanjiku has 485 mandazi. Can she pack them in bags of 5 with none left?","wrong_answer":"No, because 485 does not end in 0","correct_answer":"Yes, it ends in 5, so she fills 97 bags"},"cause":"The child mixes up the rules or does not pick out the divisor from the context.","reveals":"Use word problems where the divisor is 5 and the number ends in 5.","help":"Before testing, have the child underline the group size in the question and write 'test for __'.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS.M_FACTORS_AS_MULTIPLES","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS","error":"Lists multiples when asked for factors.","example":{"question":"List the factors of 12.","wrong_answer":"12, 24, 36, 48","correct_answer":"1, 2, 3, 4, 6, 12"},"cause":"'Factor' and 'multiple' are both linked to times tables, so the words get swapped.","reveals":"Ask for factors and multiples of the same number side by side.","help":"Use the phrase 'factors fit into the number, multiples grow out of it' and arrange 12 bottle tops in rectangles to find factors.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS.M_FACTORS_MISS_1_AND_SELF","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS","error":"Leaves out 1 and the number itself from the factor list.","example":{"question":"List the common factors of 8 and 12.","wrong_answer":"2, 4","correct_answer":"1, 2, 4"},"cause":"The child thinks 1 and the number itself are too obvious to count.","reveals":"Ask 'How many factors does 8 have?' or ask for the common factors of numbers whose only common factor is 1.","help":"Always start the factor-pair list with '1 × the number'.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS.M_FACTORS_INCOMPLETE","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_FACTORS","error":"Misses some factor pairs when listing, so loses common factors.","example":{"question":"List the common factors of 18 and 24.","wrong_answer":"1, 2, 3","correct_answer":"1, 2, 3, 6"},"cause":"The child lists factors at random rather than testing 1, 2, 3 ... in order.","reveals":"Use numbers with several factor pairs and count the factors listed.","help":"Teach systematic pair listing (1 × 18, 2 × 9, 3 × 6 ...) and stop when the pairs start to repeat.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD.M_HCF_GIVES_LCM_OR_PRODUCT","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD","error":"Gives the LCM or the product of the numbers as the HCF.","example":{"question":"Find the HCF of 12 and 18.","wrong_answer":"36","correct_answer":"6"},"cause":"The child confuses 'highest' with 'big result', or HCF with LCM.","reveals":"Offer the LCM and the product (216) as distractors.","help":"Have the child check that the HCF divides both numbers and is no bigger than the smaller number.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD.M_HCF_ANY_COMMON","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD","error":"Gives a common factor that is not the highest, often the first one found.","example":{"question":"Find the GCD of 24 and 36.","wrong_answer":"2","correct_answer":"12"},"cause":"The child stops after finding one common factor.","reveals":"Offer small common factors (2, 3, 4, 6) as distractors.","help":"Have the child list all common factors first and then circle the greatest.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD.M_HCF_SMALLER_NUMBER","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_GCD","error":"Assumes the smaller number is always the HCF.","example":{"question":"Find the HCF of 8 and 12.","wrong_answer":"8","correct_answer":"4"},"cause":"The child overgeneralises from cases like HCF of 4 and 12 = 4.","reveals":"Use pairs where the smaller number does not divide the larger.","help":"Ask 'Does 8 divide 12 exactly?' and have the child test before deciding.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_PROBLEMS.M_HCFPROB_USES_LCM","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_PROBLEMS","error":"Uses the LCM in a 'largest equal pieces' problem.","example":{"question":"A tailor in Kisumu has ribbons 24 m and 36 m long. She cuts both into equal pieces, as long as possible, with nothing left. How long is each piece?","wrong_answer":"72 m","correct_answer":"12 m"},"cause":"The child chooses the method by keywords or guesses, rather than thinking about whether the answer must divide the numbers or be divided by them.","reveals":"Mix HCF and LCM problems and ask the child to justify the method.","help":"Ask 'Can a 72 m piece come from a 24 m ribbon?' so the child sees that the piece must be smaller than both lengths.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_PROBLEMS.M_HCFPROB_WRONG_QUANTITY","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.HCF_PROBLEMS","error":"Gives the number of pieces when the size of a piece was asked, or the reverse.","example":{"question":"Same ribbons (24 m and 36 m) cut into the longest equal pieces. How long is each piece?","wrong_answer":"5 pieces","correct_answer":"12 m (which makes 2 + 3 = 5 pieces)"},"cause":"The child solves the problem correctly but does not re-read the question to see which quantity was asked for.","reveals":"Ask for each piece's size and the number of pieces in separate parts.","help":"Have the child write the answer with its unit and check it against the question's wording.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_MULTIPLES.M_MULT_PRODUCT_ONLY","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_MULTIPLES","error":"Thinks common multiples start at the product of the numbers.","example":{"question":"Write the first three common multiples of 4 and 6.","wrong_answer":"24, 48, 72","correct_answer":"12, 24, 36"},"cause":"The child knows the product is a common multiple and assumes it is the first one.","reveals":"Use pairs that share a factor, so that the product is not the first common multiple.","help":"List both rows of multiples on a hundred square or number line and circle where they meet.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_MULTIPLES.M_MULT_EXCLUDES_SELF","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.COMMON_MULTIPLES","error":"Starts the list of multiples at twice the number, leaving out the number itself.","example":{"question":"Is 6 a common multiple of 2 and 6?","wrong_answer":"No","correct_answer":"Yes, because 6 = 2 × 3 and 6 = 6 × 1"},"cause":"The child does not think of '× 1' as making a multiple.","reveals":"Use pairs where one number is a multiple of the other.","help":"Always start the list of multiples with '× 1'.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM.M_LCM_ALWAYS_PRODUCT","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM","error":"Always multiplies the numbers to get the LCM.","example":{"question":"Find the LCM of 4 and 6.","wrong_answer":"24","correct_answer":"12"},"cause":"The child uses a shortcut that only works when the numbers share no factor.","reveals":"Use pairs that share a factor, with the product as a distractor.","help":"Have the child list multiples of the larger number and test each one in turn for the smaller number.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM.M_LCM_GIVES_HCF","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM","error":"Gives the HCF, or a common factor, as the LCM.","example":{"question":"Find the LCM of 6 and 8.","wrong_answer":"2","correct_answer":"24"},"cause":"The child mixes up the terms, linking 'least' with 'small factor'.","reveals":"Ask for both HCF and LCM of the same pair.","help":"Teach the check that the LCM must be at least as big as the larger number, because it is a multiple of it.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM.M_LCM_SMALLER_NUMBER","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM","error":"Gives the smaller number as the LCM because it is 'least'.","example":{"question":"Find the LCM of 3 and 9.","wrong_answer":"3","correct_answer":"9"},"cause":"The child reads 'least' as 'the smaller of the two numbers'.","reveals":"Use pairs where one number is a multiple of the other.","help":"Ask 'Is 3 a multiple of 9?' and have the child check that the answer is a multiple of both numbers.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM_PROBLEMS.M_LCMPROB_USES_HCF","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM_PROBLEMS","error":"Uses the HCF in a 'when will they next happen together' problem.","example":{"question":"At Kencom stage one matatu leaves every 12 minutes and another every 18 minutes. Both leave at 8:00 a.m. When do they next leave together?","wrong_answer":"8:06 a.m.","correct_answer":"8:36 a.m."},"cause":"The child chooses a method without picturing the repeating events.","reveals":"Mix HCF and LCM contexts and offer the HCF-based time as a distractor.","help":"List the departure times of each matatu in two rows and look for the first time that appears in both.","status":"draft"},{"code":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM_PROBLEMS.M_LCMPROB_ADDS_INTERVALS","skill":"MATH.G5.NUMBER.WHOLE_NUMBERS.LCM_PROBLEMS","error":"Adds the two intervals instead of finding the LCM.","example":{"question":"Two bells at a Nyeri school ring every 12 minutes and every 18 minutes. They ring together at 8:00 a.m. When do they next ring together?","wrong_answer":"8:30 a.m. (12 + 18 = 30)","correct_answer":"8:36 a.m."},"cause":"The child combines the numbers with the most familiar operation.","reveals":"Offer the sum-based time as a distractor and ask the child to check whether 30 is a multiple of 12.","help":"Have the child test the answer: does each bell actually ring at that time?","status":"draft"}]},{"code":"MATH.G5.NUMBER.ADDITION","number":"1.2","strand":"Numbers","sub_strand":"Addition","sequence":102,"lessons":6,"content_topics":["Addition of numbers","Creating patterns"],"learning_experiences":["work out the sum of three 6-digit numbers without regrouping up to 1,000,000 using place charts or any other resource, collaborates with others to work out the sum of two 6-digit numbers with double regrouping with the number not more than 1,000,000 using place value apparatus or any other resource, estimate sums by rounding off the addends to the nearest hundred and thousand, come up with patterns involving addition of numbers up to a sum of 1,000,000, play games involving addition of numbers using digital devices and other resources"],"key_inquiry_questions":["How can you estimate the sum of given numbers?","How can you create patterns in addition?"],"core_competences":"● Creativity and imagination: learner makes number patterns involving addition. ● Digital literacy: learner uses digital devices and other resources to learn and play games in addition concept development.","values":"• Unity: learner collaborates with others to work out the sum of two 6-digit numbers. • Responsibility: learner takes roles individually to achieve common solutions in addition of numbers.","pcis":"Social cohesion: leaner works with peers in using digital resources for learning the addition of numbers.","links":"The learner is able to relate the concept of addition to value addition in Agriculture and Nutrition.","design_notes":"Attitudinal outcome, not mapped to a skill: (e) 'appreciate use of the addition of whole numbers in real-life situations'.\n\nOutcome (a): adding with no regrouping cannot reach 1,000,000, because every column total is at most 9. The real maximum sum is 999,999, so the limit 'not exceeding 1,000,000' is never binding.\n\nOutcome (b): 'double regrouping' is not defined in the design.\n- It is commonly read as regrouping in two columns, which may be adjacent or not.\n- Proposed: allow exactly two regroupings, including the case where a carry makes a column total exactly 10.\n- A sum of exactly 1,000,000 from two 6-digit numbers (e.g. 456,789 + 543,211) needs regrouping in every column. It is therefore beyond double regrouping, even though the outcome's limit allows it.\n- The design prints the limit as '1,000, 000'; this is a typographical slip.\n\nOutcome (c):\n- The design does not state the number or size of addends; the proposed range is two or three addends of up to 6 digits.\n- Grade 4 only covers rounding to the nearest ten (G4:1.1e). Rounding to the nearest hundred and thousand is presumably taught in Grade 5 Whole Numbers (1.1), but those codes were not supplied, so they are not cited as prerequisites.\n- The same applies to place value of 6-digit numbers: G4:1.1a only reaches tens of thousands, and G4:1.1b only reaches 10,000 in symbols.\n- Grade 6 rounds numbers up to 100,000 to the nearest thousand (G6 1.1e). Rounding 6-digit addends to the nearest thousand in Grade 5 therefore slightly overlaps or goes beyond that; teachers may wish to keep estimation addends to 5 digits.\n- G5_ESTIMATE_TO_CHECK_SUM is proposed. It draws on the key inquiry question, not an explicit outcome.\n\nOutcome (d): the design does not say whether patterns must use a constant step. Constant-step patterns are proposed as the core; growing steps could be an extension. 'Addition grid' patterns are also proposed, not stated in the design.\n\nOther points:\n- Outcome (b) covers only two addends, while outcome (a) allows three. Three addends with regrouping are therefore outside the stated outcomes.\n- The second key inquiry question contains stray text ('Inquiry Question(s)'), probably an extraction artefact.\n- The learning experiences mention games on digital devices. This is a method, not an assessable outcome.\n- Six suggested lessons is tight for this range of content.\n- HOREB has one broad G5_ADDITION skill. The finer skills above could sit beneath it, with G5_PLACE_VALUE overlapping the alignment and rounding work.","outcomes":[{"code":"MATH.G5.NUMBER.ADDITION.a","letter":"a","text":"add up to three 6-digit numbers without regrouping up to a sum not exceeding 1,000,000 in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.ADDITION.b","letter":"b","text":"add up to two 6-digit numbers with double regrouping with the sum not exceeding 1,000, 000 in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.ADDITION.c","letter":"c","text":"estimate sum by rounding off the addends to the nearest hundred and thousand in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.ADDITION.d","letter":"d","text":"create patterns involving the addition of numbers up to a sum of 1,000,000 in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.ADDITION.e","letter":"e","text":"appreciate use of the addition of whole numbers in real-life situations","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE","name":"Add up to three numbers of up to 6 digits without regrouping","outcomes":["MATH.G5.NUMBER.ADDITION.a"],"mastery":"Lines up two or three whole numbers of up to 6 digits by place value, including numbers with different numbers of digits and internal zeros, and adds them correctly where no column total exceeds 9. The sum stays within 999,999, since a sum with no regrouping cannot reach 1,000,000. Can do this on a place value chart and in vertical (column) form.","question_forms":["vertical sum: two or three addends","horizontal sum to rewrite in columns","addends of different lengths (e.g. 6-digit + 5-digit + 4-digit)","place value chart / abacus representation","missing digit in an addend or the sum"],"thinking":["procedure"],"horeb_skill_ids":["G5_ADDITION","G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Lining up columns depends on knowing the place value of each digit.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.a","kind":"outcome","strength":"essential","reason":"Column addition of 4-digit numbers is the method being extended to 6 digits.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.b","kind":"outcome","strength":"helpful","reason":"Writing numbers correctly in symbols is needed before they can be set out in columns.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","name":"Add two numbers of up to 6 digits with double regrouping","outcomes":["MATH.G5.NUMBER.ADDITION.b"],"mastery":"Adds two whole numbers of up to 6 digits where two columns need regrouping (e.g. ones to tens and tens to hundreds). Writes the ones digit of each column total and carries the ten to the next column, including when the carried 1 makes the next column total exactly 10. Sum not exceeding 1,000,000.","question_forms":["vertical sum with regrouping in two columns (adjacent or non-adjacent)","horizontal sum to rewrite in columns","place value apparatus: exchange 10 ones for 1 ten, and so on","missing digit where a carry is involved","spot and correct the error in a worked sum"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_ADDITION"],"prerequisites":[{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"essential","reason":"Double regrouping with 4-digit numbers is the same procedure on smaller numbers.","status":"proposed"},{"requires":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE","kind":"skill","strength":"essential","reason":"Learners should first align and add 6-digit numbers reliably without carrying.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Regrouping means exchanging ten of one place value for one of the next.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS","name":"Solve real-life addition problems with numbers up to 6 digits","outcomes":["MATH.G5.NUMBER.ADDITION.a","MATH.G5.NUMBER.ADDITION.b"],"mastery":"Reads a short real-life situation (shillings, harvests in kg, populations, votes, distances), picks out the quantities to be combined, writes them correctly in figures, and adds them. Covers up to three addends without regrouping, or two addends with double regrouping, with a sum not exceeding 1,000,000. Gives the answer with its unit.","question_forms":["word problem: combining totals (altogether, in total)","word problem with numbers given in words","word problem with extra (irrelevant) information","read values from a table or price list and add","write your own story for a given sum (proposed)"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_ADDITION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE","kind":"skill","strength":"essential","reason":"Problems without regrouping need this calculation.","status":"proposed"},{"requires":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","kind":"skill","strength":"essential","reason":"Problems with regrouping need this calculation.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.c","kind":"outcome","strength":"helpful","reason":"Reading numbers in words supports reading quantities given in words in a problem.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.b","kind":"outcome","strength":"helpful","reason":"Quantities read from a problem must be written correctly in figures.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100","name":"Estimate a sum by rounding the addends to the nearest hundred","outcomes":["MATH.G5.NUMBER.ADDITION.c"],"mastery":"Rounds each addend to the nearest hundred by looking at the tens digit (5 or more rounds up), including rounding that bridges into the next thousand (e.g. 4,960 to 5,000). Then adds the rounded numbers to give an estimate. The design does not state addend sizes; the proposed range is addends of up to 6 digits, with two or three addends.","question_forms":["round each addend then add","choose the best estimate (multiple choice)","word problem: about how much altogether?"],"thinking":["procedure"],"horeb_skill_ids":["G5_ADDITION","G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"essential","reason":"Rounding to the nearest ten is the same idea applied at a lower place.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.c","kind":"outcome","strength":"essential","reason":"Learners already estimate sums by rounding addends, but only to the nearest ten.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Learners must find the hundreds digit and the digit to its right.","status":"proposed"},{"requires":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","kind":"skill","strength":"helpful","reason":"Adding the rounded numbers often needs regrouping (e.g. 3,400 + 2,700).","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000","name":"Estimate a sum by rounding the addends to the nearest thousand","outcomes":["MATH.G5.NUMBER.ADDITION.c"],"mastery":"Rounds each addend to the nearest thousand by looking at the hundreds digit, including rounding that bridges into the next ten thousand. Writes the rounded numbers in full with their zeros and adds them to give an estimate. Can say whether a question asks for the nearest hundred or the nearest thousand. Proposed range: addends of up to 6 digits.","question_forms":["round each addend then add","nearest hundred or nearest thousand: same addends, two estimates","choose the best estimate (multiple choice)","word problem: about how many altogether?"],"thinking":["procedure"],"horeb_skill_ids":["G5_ADDITION","G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"essential","reason":"The rounding rule is the same, applied at the thousands place.","status":"proposed"},{"requires":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100","kind":"skill","strength":"helpful","reason":"Rounding to the nearest hundred first builds the habit of checking the digit to the right.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.c","kind":"outcome","strength":"helpful","reason":"This is the same estimating routine as Grade 4, at a higher place.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_TO_CHECK_SUM","name":"Use an estimate to judge whether an exact sum is reasonable (proposed)","outcomes":["MATH.G5.NUMBER.ADDITION.c"],"mastery":"Compares an exact sum with an estimate and decides whether the exact answer is reasonable. Understands that a correct exact answer is close to the estimate but need not equal it. Proposed: this follows from the key inquiry question 'How can you estimate the sum of given numbers?' and is not an explicit outcome.","question_forms":["is this answer reasonable? explain","which of these answers must be wrong?","compare an estimate with the exact sum"],"thinking":["reasoning"],"horeb_skill_ids":["G5_ADDITION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000","kind":"skill","strength":"essential","reason":"Learners need a quick estimate to compare with the exact answer.","status":"proposed"},{"requires":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","kind":"skill","strength":"helpful","reason":"Learners should know how exact sums are produced and where errors creep in.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND","name":"Find the rule and extend or complete addition patterns","outcomes":["MATH.G5.NUMBER.ADDITION.d"],"mastery":"Finds the constant amount added in a number pattern by comparing neighbouring terms. Uses it to find the next terms, missing middle terms, or a named term (e.g. the 5th), with all terms not exceeding 1,000,000. Handles steps that cross a place boundary (e.g. 249,600 + 2,000 = 251,600). The constant-step limit is proposed; the design does not say whether growing steps are included.","question_forms":["next term(s) in a pattern","missing term(s) in the middle","find the nth term in a real-life pattern (savings, harvests)","complete a pattern table"],"thinking":["reasoning","procedure"],"horeb_skill_ids":["G5_ADDITION"],"prerequisites":[{"requires":"MATH.G4.NUMBER.ADDITION.d","kind":"outcome","strength":"essential","reason":"Learners have already made addition patterns, with sums up to 10,000.","status":"proposed"},{"requires":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","kind":"skill","strength":"helpful","reason":"Pattern steps often cross place boundaries and need regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.i","kind":"outcome","strength":"helpful","reason":"Earlier work on even and odd number patterns builds the idea of a rule.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_CREATE","name":"Create and describe addition patterns in real-life situations","outcomes":["MATH.G5.NUMBER.ADDITION.d"],"mastery":"Given a starting number and an amount to add, or a real-life situation (e.g. a chama adding the same contribution each month), writes a correct pattern of several terms not exceeding 1,000,000. States a pattern's rule in full value terms (e.g. 'add 10,000', not 'add 1').","question_forms":["create a pattern from a start number and a rule","describe the rule of a given pattern","make up a real-life pattern and explain it","addition grid / number chart patterns (proposed)"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_ADDITION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND","kind":"skill","strength":"essential","reason":"Learners who can recognise and apply a rule are ready to invent and describe one.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"helpful","reason":"Describing the step as a full value (10,000, not 1) relies on total value.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE.M_LEFT_ALIGN","skill":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE","error":"Lines up numbers of different lengths from the left instead of the right, so digits of different place values are added together.","example":{"question":"412,301 + 25,103 + 1,042","wrong_answer":"767,531 (worked as 412,301 + 251,030 + 104,200)","correct_answer":"438,446"},"cause":"The child treats numbers like words written from the left margin, without linking each column to a place value.","reveals":"Give a horizontal sum with addends of different lengths and include the left-aligned total as a distractor.","help":"Have learners write each addend on a place value chart headed HTh–TTh–Th–H–T–O before adding, always starting with the ones.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE.M_ZERO_ANNIHILATES","skill":"MATH.G5.NUMBER.ADDITION.ADD_NO_REGROUP_UP_TO_THREE","error":"Writes 0 for any column that contains a zero, as if adding 0 makes the total 0.","example":{"question":"230,104 + 405,032","wrong_answer":"600,006","correct_answer":"635,136"},"cause":"The child confuses the zero fact for multiplication (n × 0 = 0) with addition (n + 0 = n).","reveals":"Use addends with zeros in different columns, so that the zero rule wipes out several digits of the answer.","help":"Model 0 + 4 with counters as 'nothing added to four' and contrast it directly with 4 groups of 0.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO.M_NO_CARRY_WRITE_ALL","skill":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","error":"Writes the whole two-digit column total under the column instead of regrouping, producing an answer with too many digits.","example":{"question":"246,358 + 312,475","wrong_answer":"55,871,213","correct_answer":"558,833"},"cause":"The child sees each column as a separate sum and does not understand that 13 ones is 1 ten and 3 ones.","reveals":"Use a sum with column totals of 10 or more; an answer longer than either addend plus one digit exposes it.","help":"Use bundles of sticks or place value discs so that learners physically exchange ten ones for one ten before writing.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO.M_DROP_CARRY","skill":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","error":"Writes the ones digit of the column total but forgets to add the carried 1 into the next column.","example":{"question":"246,358 + 312,475","wrong_answer":"558,723","correct_answer":"558,833"},"cause":"The child knows to 'write the units' but loses track of the regrouped ten, often because it is not recorded.","reveals":"Include the answer that is too small by 10 or 100 (exactly the dropped carries) as a distractor.","help":"Insist that the carried 1 is written clearly at the top of the next column and ticked off once added.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO.M_CARRY_MAKES_TEN","skill":"MATH.G5.NUMBER.ADDITION.ADD_DOUBLE_REGROUP_TWO","error":"When a column totals 9 before the carry, the child decides 'no regrouping here', adds the carried 1, writes 0, and does not carry again.","example":{"question":"235,247 + 140,155","wrong_answer":"375,302","correct_answer":"375,402"},"cause":"The child decides whether to regroup from the two digits alone, before including the carried 1.","reveals":"Design sums where a column is 4 + 5 or 3 + 6 and receives a carry, so the regrouping is easy to miss.","help":"Teach learners to add the carried 1 first, then look at the column total and ask 'is it 10 or more?'","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS.M_WORDS_TO_FIGURES_ZEROS","skill":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS","error":"Leaves out place-holder zeros when changing a number in words into figures, then adds the wrong number.","example":{"question":"A county planted two hundred and four thousand and fifty trees in March and 112,306 trees in April. How many trees were planted altogether?","wrong_answer":"132,756 (wrote 20,450)","correct_answer":"316,356 trees (204,050 + 112,306)"},"cause":"The child writes down the digits heard ('two', 'four', 'fifty') without checking that every place is filled.","reveals":"Give one quantity in words with internal zeros and include the total based on the mis-written number as a distractor.","help":"Have learners write the number in words into a place value chart first and fill each empty place with 0.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS.M_ADD_ALL_NUMBERS","skill":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS","error":"Adds every number in the problem, including information that is not needed.","example":{"question":"A matatu Sacco with 15 matatus earned Sh 213,400 in January and Sh 142,300 in February. How much did it earn in the two months?","wrong_answer":"Sh 355,715","correct_answer":"Sh 355,700"},"cause":"The child believes every number in a word problem must be used, rather than reasoning about what the question asks.","reveals":"Include a small, irrelevant number in the problem, so that adding it gives a total that is slightly too large.","help":"Ask learners to underline the question first and say which quantities answer it before calculating.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS.M_KEYWORD_ADD","skill":"MATH.G5.NUMBER.ADDITION.ADD_IN_SITUATIONS","error":"Adds whenever words like 'more', 'received' or 'after' appear, even when the question asks for a missing part.","example":{"question":"A school fund had Sh 245,300. After a harambee it had Sh 618,500. How much was raised at the harambee?","wrong_answer":"Sh 863,800","correct_answer":"Sh 373,200"},"cause":"The child relies on keywords instead of picturing the situation as a whole made of two parts.","reveals":"Mix in a few problems where the total is given and a part is missing; the added answer is an obvious distractor.","help":"Use a part–part–whole bar diagram so learners can see whether the whole or a part is unknown.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100.M_ROUND_BY_TRUNCATING","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100","error":"Always rounds down by replacing the tens and ones with zeros, whatever the tens digit.","example":{"question":"Estimate 4,367 + 2,851 by rounding each number to the nearest hundred.","wrong_answer":"4,300 + 2,800 = 7,100","correct_answer":"4,400 + 2,900 = 7,300"},"cause":"The child thinks rounding means 'make the end digits zero' rather than 'find the nearest hundred'.","reveals":"Use addends whose tens digit is 5 or more, so that the truncated estimate appears as a distractor.","help":"Mark the number on a number line between the two hundreds and ask which one it is nearer to.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100.M_CHAIN_ROUNDING","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100","error":"Rounds in steps from the ones digit upwards, so a number like 3,449 becomes 3,450 and then 3,500.","example":{"question":"Estimate 3,449 + 1,620 by rounding each number to the nearest hundred.","wrong_answer":"3,500 + 1,600 = 5,100","correct_answer":"3,400 + 1,600 = 5,000"},"cause":"The child applies the Grade 4 rule (round to the nearest ten) repeatedly instead of looking only at the tens digit.","reveals":"Use an addend ending in 45 to 49 in the tens and ones places.","help":"Have learners circle the hundreds digit and look only at the digit immediately to its right.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100.M_ROUND_BRIDGE","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_100","error":"Cannot round when the hundreds digit is 9 and must round up, writing things like '4,1000' or leaving the thousands unchanged.","example":{"question":"Estimate 4,960 + 3,215 by rounding each number to the nearest hundred.","wrong_answer":"4,000 + 3,200 = 7,200","correct_answer":"5,000 + 3,200 = 8,200"},"cause":"The child changes only one digit and does not see that 49 hundreds plus 1 hundred is 50 hundreds.","reveals":"Use an addend with 9 in the hundreds place and a tens digit of 5 or more.","help":"Count on in hundreds aloud across the thousand (4,800; 4,900; 5,000) on a number line.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000.M_WRONG_ROUNDING_PLACE","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000","error":"Rounds to the nearest hundred when the question asks for the nearest thousand.","example":{"question":"Estimate 23,640 + 15,280 by rounding each number to the nearest thousand.","wrong_answer":"23,600 + 15,300 = 38,900","correct_answer":"24,000 + 15,000 = 39,000"},"cause":"The child carries over a familiar rounding routine without reading which place is asked for.","reveals":"Ask for both estimates of the same sum, or offer the nearest-hundred estimate as a distractor.","help":"Ask learners to underline the place named in the question and circle that digit in each addend before rounding.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000.M_DECIDE_BY_LAST_DIGIT","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000","error":"Decides whether to round up by looking at the last (ones) digit instead of the hundreds digit.","example":{"question":"Estimate 46,409 + 31,750 by rounding each number to the nearest thousand.","wrong_answer":"47,000 + 32,000 = 79,000","correct_answer":"46,000 + 32,000 = 78,000"},"cause":"The child remembers 'look at the end digit' from rounding to the nearest ten in Grade 4.","reveals":"Use an addend whose hundreds digit is below 5 but whose ones digit is 5 or more.","help":"Teach the rule as 'look at the digit just to the right of the place you are rounding to', and practise across different places.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000.M_DROP_ZEROS_ROUNDED","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_SUM_NEAREST_1000","error":"Writes the rounded number without its zeros (e.g. '129' for 129,000), so the estimate is far too small.","example":{"question":"Estimate 128,700 + 205,300 by rounding each number to the nearest thousand.","wrong_answer":"334","correct_answer":"129,000 + 205,000 = 334,000"},"cause":"The child hears 'one hundred and twenty-nine thousand' but writes only the digits spoken before 'thousand'.","reveals":"Offer options of 334, 33,400 and 334,000, and ask learners to explain their choice.","help":"Have learners check that a rounded number has the same number of digits as the original addend.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_TO_CHECK_SUM.M_NO_SENSE_CHECK","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_TO_CHECK_SUM","error":"Accepts an exact answer as reasonable without comparing it with an estimate, even when it is far off.","example":{"question":"Wanjiru worked out 386,450 + 207,380 = 493,830. Is her answer reasonable?","wrong_answer":"Yes","correct_answer":"No. The estimate is 386,000 + 207,000 = 593,000; the correct sum is 593,830."},"cause":"The child sees estimation as a separate exercise, not a tool for checking work.","reveals":"Give worked sums with a dropped or extra carry in a high place and ask whether each is reasonable.","help":"Make 'estimate first, then calculate, then compare' a routine for every addition problem.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ESTIMATE_TO_CHECK_SUM.M_EXACT_MUST_EQUAL_ESTIMATE","skill":"MATH.G5.NUMBER.ADDITION.ESTIMATE_TO_CHECK_SUM","error":"Thinks a correct exact answer must equal the estimate, so rejects correct answers that are close to it.","example":{"question":"The estimate for 386,450 + 207,380 is 593,000. Otieno's exact answer is 593,830. Is Otieno wrong?","wrong_answer":"Yes, because it is not 593,000","correct_answer":"No, 593,830 is correct and close to the estimate"},"cause":"The child does not understand that an estimate is approximate.","reveals":"Ask whether a correct answer that differs slightly from the estimate is wrong.","help":"Use market examples ('about Sh 600 for the sukuma wiki and onions') to show that 'about' allows a small difference.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND.M_PATTERN_BRIDGE_DROP","skill":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND","error":"When the step makes a digit go past 9, the child writes only part of the new digit total and does not regroup into the next place.","example":{"question":"Find the next number: 245,600, 247,600, 249,600, ___","wrong_answer":"241,600","correct_answer":"251,600"},"cause":"The child changes only the thousands digit (9 + 2 = 11, writing 1) and forgets that 11 thousands needs regrouping.","reveals":"Choose patterns where the next term crosses a ten-thousand or hundred-thousand boundary.","help":"Have learners add the step in column form, or count on along a number line across the boundary.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND.M_PATTERN_NON_ADJACENT_STEP","skill":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND","error":"Finds the step from two terms that are not next to each other, so the missing term is wrong.","example":{"question":"Fill in the missing number: 450,000, 475,000, ___, 525,000","wrong_answer":"550,000","correct_answer":"500,000"},"cause":"The child does not check that the difference is the same between every pair of neighbouring terms.","reveals":"Place the gap in the middle of the pattern, and check that the answer fits both of its neighbours.","help":"Have learners draw jump arrows between each pair of neighbouring terms and write the difference on every arrow.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND.M_PATTERN_OFF_BY_ONE","skill":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_EXTEND","error":"To find the nth term, adds the step n times instead of n − 1 times.","example":{"question":"A co-operative had Sh 100,000 in month 1 and saves Sh 25,000 more each month. How much does it have in month 5?","wrong_answer":"Sh 225,000","correct_answer":"Sh 200,000"},"cause":"The child counts terms and steps as the same thing, forgetting that the first term has no step added.","reveals":"Ask for a specific term number and include the answer that is one step too high as a distractor.","help":"Build a table of month numbers and amounts so learners see that month 5 is four jumps after month 1.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_CREATE.M_RULE_AS_DIGIT_CHANGE","skill":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_CREATE","error":"Describes the rule by how a digit changes ('add 1') rather than by the value added ('add 10,000').","example":{"question":"What is the rule for this pattern: 200,500, 210,500, 220,500, 230,500?","wrong_answer":"Add 1","correct_answer":"Add 10,000"},"cause":"The child notices that the ten-thousands digit goes up by one but does not use its total value.","reveals":"Ask for the rule in words, then ask the child to use their rule to get the next term.","help":"Have learners test their rule by adding it to a term and checking that they get the next term.","status":"draft"},{"code":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_CREATE.M_PATTERN_RULE_DRIFT","skill":"MATH.G5.NUMBER.ADDITION.ADD_PATTERN_CREATE","error":"Starts with the given rule but makes later steps the wrong size, often where a term crosses a place boundary, so the pattern is not constant.","example":{"question":"Start at 120,000 and add 15,000 each time. Write the first four numbers.","wrong_answer":"120,000, 135,000, 140,000, 155,000","correct_answer":"120,000, 135,000, 150,000, 165,000"},"cause":"The child adds only the thousands digit at the boundary (5 + 5) and does not regroup into the ten-thousands.","reveals":"Ask learners to check their own pattern by finding the difference between every pair of neighbouring terms.","help":"Require a 'check row' under every created pattern showing the difference between each pair of terms.","status":"draft"}]},{"code":"MATH.G5.NUMBER.SUBTRACTION","number":"1.3","strand":"Numbers","sub_strand":"Subtraction","sequence":103,"lessons":6,"content_topics":["Subtraction of numbers","Combined operations of additions and subtraction s","Creating patterns"],"learning_experiences":["work with peers to subtract up to two 6-digit numbers without regrouping using place value apparatus","discuss and work out subtraction of up to two 6-digit numbers with regrouping using place value apparatus","team up with peers to estimate difference by rounding off the minuend and subtrahend to the nearest hundred and thousand using a number line","work out questions involving addition and subtraction","generate patterns involving subtraction of whole numbers from up to 1,000,000","play games involving subtraction of numbers using digital devices and other resources"],"key_inquiry_questions":["How do you estimate difference to the nearest hundred?","How can you create number patterns involving subtraction?"],"core_competences":"● Creativity and imagination: learner creates number patterns involving subtraction. ● Self-efficacy: learner reports the group&apos;s discussion to others in carrying out the various subtraction skills.","values":"Unity: learner harmoniously works with peers to subtract of up to 6-digit numbers without regrouping using place value apparatus.","pcis":"Social cohesion: learner carries out the group work in estimation of differences.","links":"The learner is able to relate the concept of subtraction to the decrease of economic resources in Social Studies.","design_notes":"1. Outcome f ('appreciate subtraction of numbers in real-life situations') is attitudinal. It is not mapped to a skill and is best observed through the real-life tasks and digital games in the learning experiences.\n\n2. Wording of outcomes a and b:\n- The phrase 'up to two 6-digit numbers' is ambiguous. It is interpreted here (proposed) as a subtraction of two numbers, each with up to 6 digits, and a whole-number (non-negative) difference.\n- Outcome b contains a typo in the design ('subtract of up to').\n- The design does not say how many regroupings are expected. This map includes single, multiple and across-zero regrouping (proposed).\n\n3. Limits of outcome e: it allows starting numbers up to 1,000,000, which is a 7-digit number, while outcomes a and b stop at 6 digits. Patterns starting at 1,000,000 therefore need subtraction from a 7-digit minuend, mainly across zeros. This is taken as intended, but it is a mismatch.\n\n4. Rounding for outcome c:\n- Outcome c requires rounding to the nearest hundred and thousand, but Grade 4 only covered rounding numbers up to 1,000 to the nearest ten (G4:1.1e).\n- The Grade 5 Whole Numbers sub-strand was not provided. That sub-strand probably teaches this rounding, but its codes could not be used.\n- G5_ROUND_NEAREST_100_1000 is therefore included here as a proposed enabling skill.\n- The number sizes for rounding and estimation are not stated. Up to 6 digits is proposed.\n\n5. Outcome d gives no number limits and does not mention brackets.\n- Proposed: numbers up to 6 digits, no brackets, left-to-right evaluation, and whole-number intermediate results.\n- Grade 6 (1.3c) extends combined operations to all four operations, overlapping HOREB's G6_BODMAS_BASIC. Teachers should avoid teaching 'add before subtract' rules now that would conflict with this later work.\n\n6. Scope and existing skills:\n- Six suggested lessons is a small allocation for ten assessable skills. Teachers may need to combine work on outcomes a and b, and on outcomes c and d.\n- HOREB's G5_SUBTRACTION is a coarse skill that overlaps most skills here. Consider splitting it along the lines above.\n\n7. Source of wording: everything beyond the official outcome text is proposed professional judgement, not KICD wording. This includes the mastery descriptions, question forms, limits marked 'proposed' and the misconceptions. The key inquiry question as supplied ends with a stray 'Question(s)', which appears to be a text-extraction artefact.","outcomes":[{"code":"MATH.G5.NUMBER.SUBTRACTION.a","letter":"a","text":"subtract up to two 6-digit numbers without regrouping in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SUBTRACTION.b","letter":"b","text":"subtract of up to two 6-digit numbers with regrouping in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SUBTRACTION.c","letter":"c","text":"estimate difference by rounding off the minuend and subtrahend to the nearest hundred and thousand in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SUBTRACTION.d","letter":"d","text":"perform combined operations involving addition and subtraction in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SUBTRACTION.e","letter":"e","text":"create patterns involving subtraction from up to 1,000,000 in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SUBTRACTION.f","letter":"f","text":"appreciate subtraction of numbers in real-life situations","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP","name":"Subtract up to 6-digit numbers without regrouping","outcomes":["MATH.G5.NUMBER.SUBTRACTION.a"],"mastery":"Subtracts a number of up to 6 digits from a number of up to 6 digits where every digit of the minuend is at least as large as the digit below it (e.g. 875,964 − 342,531). The child lines up the digits by place value, including when the subtrahend has fewer digits. The child handles zero digits in either number correctly and writes the difference with its internal zeros in place.","question_forms":["vertical column subtraction","horizontal subtraction to rewrite in columns","subtrahend with fewer digits than minuend","missing digit in a subtraction","place value apparatus / abacus representation","short real-life word problem: take away"],"thinking":["procedure"],"horeb_skill_ids":["G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G4.NUMBER.SUBTRACTION.a","kind":"outcome","strength":"essential","reason":"Column subtraction without regrouping for 4-digit numbers extends directly to 6 digits.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Lining up columns depends on knowing the place value of each digit.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.b","kind":"outcome","strength":"helpful","reason":"Reading and writing large numbers in symbols is needed to set out and record the answer.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP","name":"Subtract up to 6-digit numbers with regrouping (non-zero digits)","outcomes":["MATH.G5.NUMBER.SUBTRACTION.b"],"mastery":"Subtracts a number of up to 6 digits from a larger or equal number of up to 6 digits where one or more columns need regrouping (e.g. 724,352 − 315,128). The child exchanges one unit of the next place for ten of the current place and reduces the digit regrouped from. The child can check the answer by adding the difference to the subtrahend. Proposed limit: the difference is a whole number (no negative results).","question_forms":["vertical column subtraction with one regrouping","vertical column subtraction with several regroupings","check by inverse addition","spot and correct the error in a worked subtraction","missing digit with regrouping"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"essential","reason":"Regrouping in 4-digit subtraction is the same procedure applied across more columns.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP","kind":"skill","strength":"essential","reason":"Column layout and digit alignment for 6-digit numbers must be secure before regrouping is added.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"helpful","reason":"Checking a difference by addition uses addition with regrouping.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_REGROUP_ACROSS_ZEROS","name":"Subtract with regrouping across zeros","outcomes":["MATH.G5.NUMBER.SUBTRACTION.b"],"mastery":"Subtracts correctly when regrouping must pass through one or more zero digits in the minuend, for minuends of up to 6 digits. Examples are 500,000 − 237,468 and 403,215 − 128,436. The child changes each zero to 9 except the column being worked on, which becomes 10, and reduces the first non-zero digit by one.","question_forms":["subtraction from a round number (e.g. 300,000 − n)","subtraction with an internal zero in the minuend","change from a large note or budget (e.g. Sh 100,000 − cost)","spot and correct the error"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP","kind":"skill","strength":"essential","reason":"Regrouping across zeros is a chain of single regroupings.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"The child must see, for example, 500,000 as 49,999 tens and 10 ones to understand the exchange.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_WORD_PROBLEMS","name":"Solve real-life subtraction problems with up to 6-digit numbers","outcomes":["MATH.G5.NUMBER.SUBTRACTION.a","MATH.G5.NUMBER.SUBTRACTION.b"],"mastery":"Recognises when a situation calls for subtraction and writes the subtraction with the larger number first. Situations include: take away; comparison ('how many more/fewer', 'difference'); missing part ('how much more is needed'). The child then solves it with numbers of up to 6 digits, with or without regrouping, and states the answer with its unit (shillings, bags, people, litres).","question_forms":["word problem: take away (spent, sold, used)","word problem: comparison / difference","word problem: missing part (how much more needed)","write the number sentence for a story","write a story for a given subtraction"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP","kind":"skill","strength":"essential","reason":"Real-life problems at this level usually need regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"helpful","reason":"Experience of subtraction word problems with smaller numbers transfers to larger ones.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.d","kind":"outcome","strength":"helpful","reason":"Deciding which number is larger tells the child which number to write first.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000","name":"Round numbers to the nearest hundred and nearest thousand","outcomes":["MATH.G5.NUMBER.SUBTRACTION.c"],"mastery":"Rounds a whole number of up to 6 digits to the nearest hundred or the nearest thousand, using a number line or the digit to the right of the rounding place. This includes cases where a 5 decides the rounding (round up) and cases where rounding up carries into higher places (e.g. 239,962 → 240,000 to the nearest hundred). Proposed: this is the rounding step needed for outcome c; it may also be taught in the Grade 5 Whole Numbers sub-strand.","question_forms":["round to the nearest hundred","round to the nearest thousand","place the number on a number line between two hundreds/thousands","which number rounds to …? (reverse rounding)","rounding that carries (…9… digits)"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"essential","reason":"Rounding to the nearest ten builds the idea of 'closer to' and the round-half-up rule.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Rounding to a place requires identifying the hundreds or thousands digit and the digit to its right.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ESTIMATE_DIFFERENCE","name":"Estimate a difference by rounding the minuend and subtrahend","outcomes":["MATH.G5.NUMBER.SUBTRACTION.c"],"mastery":"Estimates a difference by first rounding both the minuend and the subtrahend to the nearest hundred or nearest thousand (as asked), then subtracting the rounded numbers. For example, 58,640 − 23,270 ≈ 59,000 − 23,000 = 36,000. The child uses the estimate to judge whether an exact answer is reasonable. Numbers are up to 6 digits.","question_forms":["estimate to the nearest hundred","estimate to the nearest thousand","estimate on a number line","is this answer reasonable? (compare estimate with exact)","word problem: about how much more"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_SUBTRACTION","G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000","kind":"skill","strength":"essential","reason":"Both numbers must be rounded correctly before subtracting.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.c","kind":"outcome","strength":"essential","reason":"Estimating a difference by rounding to the nearest ten is the same method at a smaller scale.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP","kind":"skill","strength":"helpful","reason":"Subtracting rounded numbers is usually a subtraction without regrouping, or mental work.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_CALC","name":"Work out combined addition and subtraction expressions","outcomes":["MATH.G5.NUMBER.SUBTRACTION.d"],"mastery":"Evaluates expressions with two or more additions and subtractions, such as 85,000 − 20,000 + 15,000, by working from left to right. Proposed limits: numbers up to 6 digits, no brackets, and every intermediate and final result a whole number. The child recognises that adding all the subtracted amounts first gives the wrong answer.","question_forms":["evaluate a horizontal expression (e.g. a − b + c)","evaluate with three or more operations","missing number in a combined expression","spot and correct the error","true or false: two expressions are equal"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_ADDITION","G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP","kind":"skill","strength":"essential","reason":"Each subtraction step may need regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"essential","reason":"Each addition step may need regrouping.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_PROBLEMS","name":"Solve multi-step real-life problems using addition and subtraction","outcomes":["MATH.G5.NUMBER.SUBTRACTION.d"],"mastery":"Reads a situation with several changes and decides for each step whether to add or subtract. Steps may include money received and spent, passengers boarding and alighting, or stock delivered and sold. The child writes one combined number sentence or a sequence of steps and finds the result with numbers up to 6 digits (proposed limit).","question_forms":["multi-step word problem: money (received and spent)","multi-step word problem: stock or produce (delivered and sold)","write a single number sentence for a story","table of changes: find the final amount"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_ADDITION","G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_CALC","kind":"skill","strength":"essential","reason":"The child must evaluate the combined number sentence correctly once it is written.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_WORD_PROBLEMS","kind":"skill","strength":"essential","reason":"Each step needs the child to recognise whether the situation is subtraction.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CONTINUE","name":"Identify the rule and complete subtraction patterns up to 1,000,000","outcomes":["MATH.G5.NUMBER.SUBTRACTION.e"],"mastery":"Finds the constant amount being subtracted in a decreasing sequence starting from a number up to 1,000,000, and states the rule in words (e.g. 'subtract 25,000'). The child fills in missing terms at the end or in the middle, including where a term crosses a place-value boundary, as in 302,500 → 301,500 → 300,500 → 299,500.","question_forms":["next term(s) in a pattern","missing term in the middle","state the rule","pattern in a table or on a number line","spot the term that does not fit"],"thinking":["reasoning","procedure"],"horeb_skill_ids":["G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G4.NUMBER.SUBTRACTION.d","kind":"outcome","strength":"essential","reason":"Subtraction patterns from up to 10,000 are the direct forerunner.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_REGROUP_ACROSS_ZEROS","kind":"skill","strength":"essential","reason":"Patterns that cross boundaries (e.g. 300,500 → 299,500) require regrouping across zeros.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"helpful","reason":"Finding the rule means reading the value of the digit that changes.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CREATE","name":"Create subtraction patterns from up to 1,000,000","outcomes":["MATH.G5.NUMBER.SUBTRACTION.e"],"mastery":"Given a starting number up to 1,000,000 and a rule, or choosing their own, the child produces a correct decreasing pattern of several terms with a constant step. The child explains the rule and knows the pattern must stop before going below zero. Real-life examples include a savings balance going down by a fixed withdrawal, or a water tank emptying by a fixed amount each day.","question_forms":["create a pattern from a given start and rule","create your own pattern and state its rule","real-life pattern: fixed amount used each day or week","how many steps until the pattern reaches a given number"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CONTINUE","kind":"skill","strength":"essential","reason":"A child who cannot recognise a constant-step rule cannot reliably produce one.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.d","kind":"outcome","strength":"helpful","reason":"The child will have created simpler subtraction patterns in Grade 4.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP.M_MISALIGN_COLUMNS","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP","error":"Lines the numbers up on the left instead of by place value when the subtrahend has fewer digits.","example":{"question":"485,762 − 3,241","wrong_answer":"161,662","correct_answer":"482,521"},"cause":"Treats numbers like words written from the left, not as digits with place values that must match ones under ones.","reveals":"Horizontal questions with unequal digit counts; include the left-aligned result as a distractor.","help":"Have the child label the place-value headings (HTh TTh Th H T O) and write each number under them, starting from the ones.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP.M_DIGIT_MINUS_ZERO_IS_ZERO","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP","error":"Writes 0 when subtracting 0 from a digit (thinks n − 0 = 0).","example":{"question":"573,846 − 201,030","wrong_answer":"302,010","correct_answer":"372,816"},"cause":"Confuses subtracting zero with multiplying by zero, or believes 'zero makes things zero'.","reveals":"Use subtrahends with several internal zeros; the distractor has zeros in those columns.","help":"Use counters or a place-value chart: take away no bundles of hundreds and ask how many are still there.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP.M_DROP_INTERNAL_ZEROS","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_NO_REGROUP","error":"Leaves gaps where a column difference is 0, then closes them up and reads the answer as a much smaller number.","example":{"question":"658,947 − 258,543","wrong_answer":"444","correct_answer":"400,404"},"cause":"Thinks zero means 'nothing to write', not realising that zero holds a place.","reveals":"Choose questions whose differences contain internal zeros; offer the collapsed number as a distractor and ask the child to read the answer aloud.","help":"Insist that every column gets a digit in the answer row, and have the child read the result in words to check its size.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP.M_SMALLER_FROM_LARGER","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP","error":"In each column, subtracts the smaller digit from the larger, whichever is on top, so never regroups.","example":{"question":"524,316 − 182,549","wrong_answer":"462,233","correct_answer":"341,767"},"cause":"Believes 'you always take the small number from the big one' and treats each column as a separate one-digit problem.","reveals":"Questions where several bottom digits are larger than the top digits; check by adding the answer to the subtrahend (462,233 + 182,549 ≠ 524,316).","help":"Model the column with place-value apparatus: 6 ones cannot give away 9, so exchange one ten for ten ones.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP.M_REGROUP_NO_DECREMENT","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_6DIGIT_REGROUP","error":"Adds 10 to the top digit when regrouping but forgets to reduce the digit in the next column.","example":{"question":"724,352 − 315,128","wrong_answer":"419,234","correct_answer":"409,224"},"cause":"Sees regrouping as a rule for 'making the top digit big enough', not as exchanging one unit of the next place.","reveals":"Questions with two or more separate regroupings; the distractor is 10 or 10,000 (etc.) too large in each regrouped place.","help":"Have the child physically move one bundle from the next column on the abacus or chart and cross out and rewrite that digit before subtracting.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_REGROUP_ACROSS_ZEROS.M_ZEROS_ALL_BECOME_TEN","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_REGROUP_ACROSS_ZEROS","error":"Changes every zero in the minuend to 10 and reduces the first non-zero digit only once, so each zero column is worked as 10 − digit.","example":{"question":"500,000 − 237,468","wrong_answer":"273,642","correct_answer":"262,532"},"cause":"Does not understand that passing through a zero turns it into 9 (one unit is passed on to the next place).","reveals":"Subtract from round numbers such as 500,000 or 300,000; check by inverse addition (273,642 + 237,468 = 511,110).","help":"Show 500,000 as 499,999 + 1 on a place-value chart so the child sees the 9s, then subtract.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_REGROUP_ACROSS_ZEROS.M_ZERO_MINUS_DIGIT_IS_ZERO","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_REGROUP_ACROSS_ZEROS","error":"Writes 0 for any column where the top digit is 0 ('you can't take from nothing') instead of regrouping.","example":{"question":"500,000 − 237,468","wrong_answer":"300,000","correct_answer":"262,532"},"cause":"Believes that subtracting from zero gives zero, so avoids the difficult regrouping step.","reveals":"Offer a round-number answer as a distractor; ask whether a difference can be so 'neat' when the subtrahend is not round.","help":"Use a money context such as Sh 500,000 in Sh 100,000 bundles: to pay Sh 237,468 a bundle must be broken into smaller notes.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_WORD_PROBLEMS.M_KEYWORD_MORE_MEANS_ADD","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_WORD_PROBLEMS","error":"Adds whenever the word 'more' appears, even when the problem asks for the smaller quantity.","example":{"question":"Kisumu stored 245,600 bags of maize. This is 38,450 more than Nyeri stored. How many bags did Nyeri store?","wrong_answer":"284,050 bags","correct_answer":"207,150 bags"},"cause":"Relies on keywords rather than understanding which quantity is bigger in the situation.","reveals":"Comparison problems where 'more' describes the known larger amount; include the sum as a distractor.","help":"Have the child draw two bars (Kisumu longer, Nyeri shorter) before choosing the operation.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_WORD_PROBLEMS.M_MISSING_PART_ADDS","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_WORD_PROBLEMS","error":"Adds the two given numbers in a 'how much more is needed' problem instead of finding the missing part.","example":{"question":"A school in Nakuru has raised Sh 85,250 towards a target of Sh 120,000. How much more does it need?","wrong_answer":"Sh 205,250","correct_answer":"Sh 34,750"},"cause":"Sees 'raised' and 'target' as amounts to combine, and does not recognise the missing-addend structure as subtraction.","reveals":"Missing-part problems; the sum distractor exceeds the target, which a reasoning child will reject.","help":"Ask 'Can the amount still needed be bigger than the whole target?' and show the problem as a part–whole bar.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000.M_ROUND_USES_OWN_DIGIT","skill":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000","error":"Looks at the digit in the rounding place itself instead of the digit to its right to decide whether to round up.","example":{"question":"Round 46,382 to the nearest thousand.","wrong_answer":"47,000","correct_answer":"46,000"},"cause":"Has memorised '5 or more, round up' without knowing which digit to apply it to.","reveals":"Choose numbers where the rounding digit is 5 or more but the next digit is less than 5.","help":"Mark 46,000 and 47,000 on a number line and have the child place 46,382 to see which it is closer to.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000.M_ROUND_KEEPS_TAIL","skill":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000","error":"Changes the rounding digit correctly but leaves the digits to its right unchanged.","example":{"question":"Round 46,382 to the nearest hundred.","wrong_answer":"46,482","correct_answer":"46,400"},"cause":"Sees rounding as 'changing a digit' rather than finding the nearest multiple of 100.","reveals":"Ask 'Is your answer a whole number of hundreds?'; include the tail-kept number as a distractor.","help":"Remind the child that a number rounded to the nearest hundred always ends in 00, and have them check this every time.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000.M_ROUND_NO_CARRY","skill":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000","error":"When rounding up a 9, writes 0 but does not carry 1 into the next place.","example":{"question":"Round 239,962 to the nearest hundred.","wrong_answer":"239,000","correct_answer":"240,000"},"cause":"Treats rounding up as 'change this digit' and does not see 9 + 1 = 10 as an exchange into the next place.","reveals":"Numbers with a 9 in the rounding place; the distractor is the rounded-down value or a non-standard numeral.","help":"Count on in hundreds on a number line: 239,800, 239,900, 240,000, so the child sees what comes after 239,900.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000.M_ROUND_FIVE_DOWN","skill":"MATH.G5.NUMBER.SUBTRACTION.ROUND_NEAREST_100_1000","error":"Rounds down when the deciding digit is exactly 5.","example":{"question":"Round 73,500 to the nearest thousand.","wrong_answer":"73,000","correct_answer":"74,000"},"cause":"Sees 5 as 'small' or 'halfway, so either', and does not know the convention of rounding a half up.","reveals":"Include halfway numbers such as 73,500 or 18,250 (nearest hundred).","help":"State the convention explicitly ('halfway goes up') and practise with halfway numbers on a number line.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ESTIMATE_DIFFERENCE.M_EXACT_THEN_ROUND","skill":"MATH.G5.NUMBER.SUBTRACTION.ESTIMATE_DIFFERENCE","error":"Works out the exact difference first and then rounds it, instead of rounding both numbers first.","example":{"question":"Estimate 6,480 − 2,550 by rounding each number to the nearest thousand.","wrong_answer":"4,000","correct_answer":"3,000 (6,000 − 3,000)"},"cause":"Does not see estimation as a quick method; thinks the estimate must be the exact answer rounded.","reveals":"Choose numbers where rounding first and rounding last give different results; ask for the rounded numbers to be shown.","help":"Require the child to write the rounded number sentence (6,000 − 3,000) before giving the estimate.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.ESTIMATE_DIFFERENCE.M_ROUND_ONLY_ONE","skill":"MATH.G5.NUMBER.SUBTRACTION.ESTIMATE_DIFFERENCE","error":"Rounds only the minuend (or only the subtrahend) and subtracts the other number exactly.","example":{"question":"Estimate 58,640 − 23,270 by rounding to the nearest thousand.","wrong_answer":"35,730","correct_answer":"36,000"},"cause":"Has not understood that both minuend and subtrahend are rounded so the subtraction becomes easy.","reveals":"An answer that is not a whole number of thousands shows that something was not rounded.","help":"Ask 'Should an estimate to the nearest thousand end in 000?', then circle both numbers to be rounded.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_CALC.M_ADD_BEFORE_SUBTRACT","skill":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_CALC","error":"Does the addition first in an expression like a − b + c, so subtracts the sum b + c.","example":{"question":"85,000 − 20,000 + 15,000","wrong_answer":"50,000","correct_answer":"80,000"},"cause":"Believes addition always comes before subtraction, often from half-remembered order-of-operations rules.","reveals":"Expressions with subtraction before addition; the distractor is a − (b + c).","help":"Tell it as a story (had 85,000, gave away 20,000, then received 15,000) and work left to right step by step.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_PROBLEMS.M_ADD_ALL_NUMBERS","skill":"MATH.G5.NUMBER.SUBTRACTION.COMBINED_ADD_SUB_PROBLEMS","error":"Adds every number in a multi-step story regardless of whether each amount goes in or out.","example":{"question":"Wanjiku had Sh 12,500. She spent Sh 4,750 on sugar and flour, then her mother gave her Sh 3,200. How much does she have now?","wrong_answer":"Sh 20,450","correct_answer":"Sh 10,950"},"cause":"Does not track the direction of each change; treats 'find the total' as the default for any story with several numbers.","reveals":"Stories mixing increases and decreases; the all-addition total is offered as a distractor.","help":"Have the child mark each amount '+' (comes in) or '−' (goes out) before writing the number sentence.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CONTINUE.M_PATTERN_BOUNDARY_NO_REGROUP","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CONTINUE","error":"When a pattern crosses a place-value boundary, changes the 0 to 9 but does not reduce the digit to its left.","example":{"question":"302,500; 301,500; 300,500; ___","wrong_answer":"309,500","correct_answer":"299,500"},"cause":"Continues the pattern by adjusting one digit instead of actually subtracting 1,000, so the regrouping across zeros is missed.","reveals":"Patterns whose next term crosses a hundred-thousand or ten-thousand boundary; check whether the sequence is still decreasing.","help":"Ask 'Is your next number smaller than 300,500?' and have the child do the subtraction in columns.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CONTINUE.M_RULE_DIGIT_NOT_VALUE","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CONTINUE","error":"States the rule using the face value of the changing digit rather than its place value.","example":{"question":"What is the rule? 845,300; 835,300; 825,300","wrong_answer":"Subtract 1","correct_answer":"Subtract 10,000"},"cause":"Notices which digit goes down by 1 but does not connect it to the ten-thousands place.","reveals":"Ask for the rule in words, then ask the child to apply it to the last term.","help":"Have the child subtract two consecutive terms in columns to find the step, not just look at which digit changed.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CREATE.M_PATTERN_PAST_ZERO","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CREATE","error":"Keeps a pattern going after the next step would go below zero, by subtracting the smaller number from the larger.","example":{"question":"Start at 100,000 and subtract 30,000 each time. Write as many terms as you can.","wrong_answer":"100,000; 70,000; 40,000; 10,000; 20,000","correct_answer":"100,000; 70,000; 40,000; 10,000 (stop: 30,000 cannot be taken from 10,000 in whole numbers)"},"cause":"Applies 'take smaller from larger', so does not notice that the step can no longer be subtracted.","reveals":"Rules that do not divide the starting number exactly; check whether each term is smaller than the one before.","help":"Use a real context (a tank with 100,000 litres losing 30,000 a week) and ask what happens when only 10,000 litres are left.","status":"draft"},{"code":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CREATE.M_PATTERN_STEP_NOT_CONSTANT","skill":"MATH.G5.NUMBER.SUBTRACTION.SUB_PATTERN_CREATE","error":"Creates a 'pattern' that simply decreases, without keeping the same step each time, while stating one rule.","example":{"question":"Create a pattern starting at 60,000 using the rule 'subtract 5,000'. Write the next four terms.","wrong_answer":"55,000; 50,000; 40,000; 35,000","correct_answer":"55,000; 50,000; 45,000; 40,000"},"cause":"Thinks a subtraction pattern only needs to go down, rather than following a fixed rule.","reveals":"Ask the child to write the difference between each pair of terms under the pattern.","help":"Have the child check each new term by subtracting it from the previous one and confirming the result equals the rule.","status":"draft"}]},{"code":"MATH.G5.NUMBER.MULTIPLICATION","number":"1.4","strand":"Numbers","sub_strand":"Multiplication","sequence":104,"lessons":6,"content_topics":["Multiplication of numbers","Creating patterns"],"learning_experiences":["work out multiplication of up to a 3-digit number by up to a 2-digit number using different methods","round off numbers to the nearest tens then get their product using compatibility of numbers or own strategies","team up with peers to create patterns involving multiplication of numbers with products not exceeding 1000","play games involving multiplication of whole numbers using digital devices and other resources"],"key_inquiry_questions":["Where can multiplication be used in real life?","How can you form patterns involving multiplication?"],"core_competences":"● Communication and collaboration: learner works with peers to make patterns involving multiplication. ● Learning to learn: learner explores other methods of working out products of numbers.","values":"Unity: learner teams up with peers to create patterns involving multiplication of numbers with products not exceeding 1000.","pcis":"Self-awareness: learner discovers own strategies in multiplication and estimation of products of numbers.","links":"The learner is able to relate the concept of multiplication to sowing tiny seeds gardening skills in Agriculture and Nutrition.","design_notes":"1. Outcome d ('appreciate use of multiplication in real life') is attitudinal. It is not mapped to a skill and should be observed through discussion and the key inquiry question 'Where can multiplication be used in real life?'.\n\n2. Outcome a sets no product limit. 999 × 99 = 98,901, so products can reach five digits.\n- The Grade 5 Whole Numbers outcomes were not supplied, so it is not confirmed that Grade 5 learners handle numbers this large.\n- Grade 4 addition (1.2a/b) only reaches a sum of 10,000, yet adding partial products can exceed it. Proposed: keep most assessment items with products below 100,000 and check against the Grade 5 1.1 outcomes.\n\n3. 'Up to a 3-digit number by up to a 2-digit number' is read as including 1-digit multipliers. That is why G5_MULT_3D_BY_1D is a separate skill (proposed).\n\n4. The learning experience says 'using different methods'. No method is prescribed, so the proposal is to accept column, grid/area and expanded partial-product methods.\n\n5. Outcome b says round to the nearest ten. The learning experience also mentions 'compatibility of numbers or own strategies', which is a different estimation strategy (e.g. 25 × 48 ≈ 25 × 40).\n- Proposed: score nearest-ten estimates as the expected answer and treat compatible-number estimates as acceptable extension work.\n- It is unclear how a 1-digit factor should be rounded (e.g. 4 → 0 would give an estimate of 0). Proposed: estimation items should use factors of at least two digits.\n\n6. Outcome c contains a typo in the design ('in in different situations'). The text 'product not exceeding 1000' is read here as meaning every term in the pattern stays at or below 1000.\n- 'Patterns involving multiplication' is not defined. It could mean repeated-multiplication sequences (3, 6, 12, 24), times-table/multiples patterns, or patterns within multiplication facts. Both readings are covered and should be accepted.\n- The content topic says 'Creating patterns' while the outcome says 'make patterns'. These are treated as the same.\n- Grade 6 1.2c repeats this outcome almost word for word, so Grade 6 should differ mainly in context and complexity.\n\n7. The second key inquiry question carries stray text in the source ('Inquiry Question(s)'), probably a layout artefact.\n\n8. HOREB's existing G5_MULTIPLICATION is labelled '2-digit × 1-digit', which is below the Grade 5 outcome (up to 3-digit × 2-digit). It overlaps only partly with the skills here; consider renaming it or splitting it. HOREB has no existing skill for estimating products or for multiplication patterns; G5_MULTIPLES is the closest match for patterns.","outcomes":[{"code":"MATH.G5.NUMBER.MULTIPLICATION.a","letter":"a","text":"multiply up to a 3-digit number by up to a 2-digit number in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.b","letter":"b","text":"estimate product by rounding off numbers to the nearest ten in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.c","letter":"c","text":"make patterns involving multiplication of numbers with product not exceeding 1000 in in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.d","letter":"d","text":"appreciate use of multiplication in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","name":"Multiply up to a 3-digit number by a 1-digit number","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.a"],"mastery":"Multiplies any number up to 999 by a 1-digit number accurately, regrouping in any column and handling zeros inside the number (e.g. 305 × 6). Products go up to 8,991. Works in the column method or another method such as expanded form or the grid.","question_forms":["bare calculation: column","multiply with a zero in the middle","missing digit in a worked multiplication","spot and correct the error"],"thinking":["procedure"],"horeb_skill_ids":["G5_MULTIPLICATION","G4_MULTIPLY"],"prerequisites":[{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"essential","reason":"Multiplying 2-digit numbers with regrouping is the same procedure, extended here by one more column.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Regrouping relies on knowing that 10 ones make a ten and 10 tens make a hundred.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D","name":"Multiply up to a 3-digit number by a 2-digit number","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.a"],"mastery":"Multiplies any number up to 999 by any number from 10 to 99, for products up to 98,901. Correctly forms the tens partial product (multiplying by the tens digit as tens) and adds the partial products. Can use long multiplication, the grid/area method or expanded partial products, and can explain why the second row is worth ten times as much.","question_forms":["bare calculation: long multiplication","grid/area method","complete the partial products","spot and correct the error","compare two methods"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_MULTIPLICATION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","kind":"skill","strength":"essential","reason":"Each partial product is a 3-digit × 1-digit multiplication.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.a","kind":"outcome","strength":"essential","reason":"The tens partial product is multiplication by a multiple of 10.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"essential","reason":"The partial products must be added, often with double regrouping.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_WORD_PROBLEMS","name":"Solve real-life problems using multiplication (up to 3-digit × 2-digit)","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.a"],"mastery":"Recognises when a real-life situation calls for multiplication, for example equal groups, a cost per item or a rate per trip. Writes the multiplication, works it out within the 3-digit × 2-digit limit and gives the answer with the correct unit (shillings, kg, pupils). Can complete a simple second step, such as finding change, when the problem asks for it.","question_forms":["word problem: equal groups","word problem: cost (shillings)","word problem: two-step (multiply then subtract/add)","write the number sentence for the story","make up a story for a multiplication"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_MULTIPLICATION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D","kind":"skill","strength":"essential","reason":"The problems need the full 3-digit × 2-digit calculation.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"helpful","reason":"Two-step problems such as finding change need subtraction with regrouping.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10","name":"Estimate a product by rounding each number to the nearest ten","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.b"],"mastery":"Rounds each factor (2- or 3-digit) to the nearest ten before multiplying, for example 347 × 26 becomes 350 × 30. Then multiplies the rounded numbers correctly, handling the zeros (350 × 30 = 10,500).","question_forms":["round then estimate","choose the best estimate (multiple choice)","word problem: about how much","which rounding is correct"],"thinking":["procedure"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"essential","reason":"Learners must round numbers up to 1000 to the nearest ten.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.c","kind":"outcome","strength":"essential","reason":"Grade 4 introduced estimating products by rounding to the nearest ten, for products up to 1000.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.a","kind":"outcome","strength":"essential","reason":"Rounded factors are multiples of 10, so learners need fluency with multiplying by multiples of 10.","status":"proposed"},{"requires":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","kind":"skill","strength":"helpful","reason":"Estimates such as 350 × 30 reduce to 35 × 3, then multiplying by 100.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_CHECK_REASONABLE","name":"Use an estimate to judge whether a product is reasonable","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.b"],"mastery":"Compares an exact product with its nearest-ten estimate and decides whether the answer is sensible. Knows that an estimate is close to the exact answer but not equal to it, and spots answers that are wrong by a factor of about 10. Uses estimates in situations such as checking whether money is enough.","question_forms":["is this answer reasonable? explain","compare estimate and exact answer","word problem: is there enough money","which calculation is wrong"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10","kind":"skill","strength":"essential","reason":"A learner must first produce an estimate before using it to check an answer.","status":"proposed"},{"requires":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D","kind":"skill","strength":"helpful","reason":"Checking is most meaningful when the learner has produced or can follow the exact calculation.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND","name":"Identify the rule and extend or complete multiplication patterns (terms not exceeding 1000)","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.c"],"mastery":"Finds the multiplying rule in a number pattern, such as ×2, ×3, ×5 or ×10, or the pattern in a times table. Uses the rule to find the next terms or missing terms, including earlier terms found by dividing. All numbers stay at or below 1000.","question_forms":["next term","missing term in the middle or at the start","state the rule","table/input-output pattern","odd one out in a pattern"],"thinking":["reasoning"],"horeb_skill_ids":["G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G4.NUMBER.MULTIPLICATION.d","kind":"outcome","strength":"essential","reason":"Grade 4 multiplication patterns (product up to 100) are extended here to 1000.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.g","kind":"outcome","strength":"essential","reason":"Recognising multiples is the basis of times-table patterns.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.b","kind":"outcome","strength":"helpful","reason":"Finding an earlier missing term means reversing multiplication with division.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.d","kind":"outcome","strength":"helpful","reason":"Experience with addition patterns lets learners contrast adding a fixed amount with multiplying by a fixed number.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_CREATE","name":"Create and describe own multiplication patterns (terms not exceeding 1000)","outcomes":["MATH.G5.NUMBER.MULTIPLICATION.c"],"mastery":"Given a starting number and a multiplying rule, or choosing their own, makes a pattern of at least four terms that never goes over 1000. Describes the rule clearly in words, and can explain why the pattern must stop before 1000 is passed.","question_forms":["make a pattern from a start number and rule","make your own pattern and state its rule","how many terms before passing 1000","peer check: does this pattern follow its rule"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_MULTIPLES"],"prerequisites":[{"requires":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND","kind":"skill","strength":"essential","reason":"Learners must recognise and apply a rule before inventing and describing their own.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D.M_ADD_CARRY_BEFORE_MULTIPLY","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","error":"Adds the carried digit to the next digit and then multiplies, instead of multiplying first and then adding the carry.","example":{"question":"A dairy in Nyandarua fills 268 packets of milk each hour. How many packets does it fill in 4 hours? (268 × 4)","wrong_answer":"2062","correct_answer":"1072"},"cause":"Mixes up the carrying routine from addition with multiplication, so the carried tens get multiplied too.","reveals":"Use a column with a large carry into it. The 'add then multiply' answer (2062) is a distractor next to 1072 and 842.","help":"Have the learner say each step aloud, 'six fours are 24, plus the 3 I carried is 27', and check it with the grid method (800 + 240 + 32).","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D.M_DROP_CARRY","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","error":"Writes only the ones digit of each column's product and forgets the carried digits.","example":{"question":"268 × 4","wrong_answer":"842","correct_answer":"1072"},"cause":"Thinks of each column as a separate fact and does not see the carried tens and hundreds as part of the value.","reveals":"Offer a distractor smaller than a simple estimate (270 × 4 is about 1000), so 842 can be spotted as too small.","help":"Ask learners to write the small carried digit above the next column before moving on, and to compare their answer with a rounded estimate.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D.M_WRITE_WHOLE_COLUMN_PRODUCTS","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","error":"Writes the full product of every column side by side without regrouping.","example":{"question":"268 × 4","wrong_answer":"82432","correct_answer":"1072"},"cause":"Does not understand that a 2-digit column product has to be regrouped into the next place.","reveals":"Include an answer with far too many digits among the options, and ask 'can 268 × 4 be more than 268 × 10?'","help":"Use place-value cards or bundles of sticks to show that 32 ones are 3 tens and 2 ones, so only the 2 stays in the ones column.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D.M_ZERO_DIGIT_SKIPPED","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_1D","error":"When there is a zero inside the number, treats that column as 'nothing to do' and loses the carried digit.","example":{"question":"A school buys 6 bags of maize, each 305 kg. What is the total mass? (305 × 6)","wrong_answer":"1800 kg","correct_answer":"1830 kg"},"cause":"Believes 0 × 6 means the column stays empty, forgetting that the carry still has to be written there.","reveals":"Use numbers with a zero in the tens place where the ones column produces a carry.","help":"Show 305 × 6 as 300 × 6 + 5 × 6 = 1800 + 30 so the learner sees where the 3 tens must go.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D.M_NO_PLACEHOLDER_ZERO","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D","error":"Multiplies by the tens digit as if it were ones, forgetting to shift one place or write the zero, so the second partial product is ten times too small.","example":{"question":"243 × 26","wrong_answer":"1944","correct_answer":"6318"},"cause":"Sees the '2' in 26 as 2 rather than 20, so the procedure is followed without place value.","reveals":"Use a 'complete the partial products' task asking for 243 × 20 = ____, or include 1944 as a distractor beside an estimate of 240 × 30 = 7200.","help":"Have learners write the partial products in words first ('243 × 6' and '243 × 20') and use the grid method until the shift makes sense.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D.M_MULTIPLY_LIKE_ADDITION","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D","error":"Multiplies only digits in the same column (ones by ones, tens by tens), as in column addition.","example":{"question":"312 × 23","wrong_answer":"326","correct_answer":"7176"},"cause":"Over-applies the column-by-column habit from addition and does not see that every digit multiplies every other digit.","reveals":"Ask 'Is 312 × 23 more or less than 312 × 10?' The 326 answer cannot survive this check.","help":"Draw the grid (300, 10, 2 across; 20, 3 down) so the learner sees there are six separate products to find.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D.M_CARRIES_MIXED_BETWEEN_ROWS","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_3D_BY_2D","error":"Uses the carried digits left over from the ones row when working the tens row.","example":{"question":"243 × 26","wrong_answer":"8418","correct_answer":"6318"},"cause":"Carried digits from the first row are still written above the number and the learner adds them again in the second row.","reveals":"Use a spot-the-error task showing a worked example where the old carries were reused. Learners must find the faulty row.","help":"Teach learners to cross out carries once a row is finished, or to write each row's carries in a separate place.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_WORD_PROBLEMS.M_ADD_INSTEAD_OF_MULTIPLY","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_WORD_PROBLEMS","error":"Adds the two numbers in an equal-groups problem instead of multiplying them.","example":{"question":"Each school bus carries 48 pupils to a music festival in Kisumu. How many pupils travel in 12 buses?","wrong_answer":"60 pupils","correct_answer":"576 pupils"},"cause":"Relies on key words such as 'how many' or 'altogether' instead of picturing the equal groups.","reveals":"Put the sum as a distractor, or ask the learner to draw the situation before calculating.","help":"Ask 'How many groups? How many in each group?' and have the learner write the number sentence before working it out.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_WORD_PROBLEMS.M_STOP_AFTER_FIRST_STEP","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_WORD_PROBLEMS","error":"In a two-step problem, gives the result of the multiplication as the final answer.","example":{"question":"Wanjiru buys 15 kg of sugar at sh 145 per kg. She pays with sh 3,000. How much change does she get?","wrong_answer":"sh 2,175","correct_answer":"sh 825"},"cause":"Treats finishing the hard calculation as finishing the problem, without re-reading the question.","reveals":"Include the cost from the first step as a distractor in multiple-choice two-step problems.","help":"Train learners to underline the question sentence and check that their final answer answers it.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_EXACT_THEN_ROUND","skill":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10","error":"Works out the exact product first and then rounds the answer, instead of rounding the numbers being multiplied.","example":{"question":"Estimate 47 × 23 by rounding each number to the nearest ten.","wrong_answer":"1080","correct_answer":"50 × 20 = 1000"},"cause":"Sees 'estimate' as 'give a rounded answer' rather than as a quick strategy that avoids the long calculation.","reveals":"Ask learners to show the rounded numbers, and include the rounded exact answer as a distractor.","help":"Require a 'rounded numbers' box to be filled in before the estimate, and time estimates so the long method is not attractive.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_TRUNCATE_NOT_ROUND","skill":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10","error":"Always rounds down by chopping off the ones digit.","example":{"question":"Estimate 347 × 26 by rounding each number to the nearest ten.","wrong_answer":"340 × 20 = 6800","correct_answer":"350 × 30 = 10,500"},"cause":"Believes rounding means 'make the ones digit zero', ignoring whether the number is closer to the ten above.","reveals":"Choose factors whose ones digit is 5 or more, and include the truncated estimate as a distractor.","help":"Have learners place the number on a number line between two tens and ask which ten it is nearer to.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_ZEROS_MISCOUNTED","skill":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10","error":"Multiplies the non-zero digits correctly but attaches the wrong number of zeros.","example":{"question":"Estimate 347 × 26 by rounding each number to the nearest ten.","wrong_answer":"1050","correct_answer":"10,500"},"cause":"Uses a 'stick on the zeros' rule without understanding it, so zeros from one of the factors are forgotten.","reveals":"Offer answers that differ only by a power of ten (1050, 10,500, 105,000).","help":"Write 350 × 30 as 35 × 10 × 3 × 10 so the learner can see both tens being multiplied.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_CHECK_REASONABLE.M_ESTIMATE_MUST_MATCH","skill":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_CHECK_REASONABLE","error":"Rejects a correct answer because it is not exactly equal to the estimate.","example":{"question":"Juma says 48 × 21 = 1008. Use an estimate to decide if his answer is reasonable.","wrong_answer":"No, it should be 1000","correct_answer":"Yes: 50 × 20 = 1000, and 1008 is close to 1000"},"cause":"Thinks an estimate is the 'real' answer rather than an approximate check.","reveals":"Use 'reasonable or not' items where the exact answer is close to, but not equal to, the estimate.","help":"Discuss 'close enough' using the class's own estimates and exact answers side by side, noting how far apart they are.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_CHECK_REASONABLE.M_NO_SIZE_CHECK","skill":"MATH.G5.NUMBER.MULTIPLICATION.ESTIMATE_CHECK_REASONABLE","error":"Accepts an exact answer that is about ten times too small or too large, without comparing it to the estimate.","example":{"question":"Amina worked out 243 × 26 = 1944. Is this reasonable?","wrong_answer":"Yes","correct_answer":"No: 240 × 30 = 7200, so 1944 is far too small (the correct product is 6318)"},"cause":"Does not link the estimate to the size of the answer and trusts any figure produced by the method.","reveals":"Use 'which calculation is wrong?' sets where one answer is off by a place-value shift.","help":"Make 'estimate first, then calculate, then compare' a routine step in every long multiplication.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND.M_ADDITIVE_RULE","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND","error":"Takes the difference between the first two terms as the rule and keeps adding it, missing the multiplying rule.","example":{"question":"A boda boda business doubles its riders each year: 5, 10, 20, 40, __","wrong_answer":"45","correct_answer":"80"},"cause":"Addition patterns from Grade 4 are more familiar, so the learner checks only the first step.","reveals":"Use patterns where the first difference equals the first term (5, 10, …). The answer from adding is a distractor.","help":"Have learners test their rule on every pair of terms, not just the first two, and record 'how did we get from each to the next?'","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND.M_ALWAYS_DOUBLE","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND","error":"Assumes any growing pattern is 'doubling'.","example":{"question":"4, 12, 36, __","wrong_answer":"72","correct_answer":"108"},"cause":"Over-generalises from the most common pattern met in class.","reveals":"Use patterns with rules of ×3, ×4 or ×5, and include the doubled value as a distractor.","help":"Ask 'What do I multiply 4 by to get 12?' and check that the same multiplier works for 12 to 36.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND.M_NO_REVERSE_FOR_EARLIER_TERM","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_EXTEND","error":"To find a missing first term, multiplies forwards instead of dividing backwards.","example":{"question":"__, 12, 36, 108","wrong_answer":"36","correct_answer":"4"},"cause":"Applies the rule only in the forward direction and does not see division as undoing multiplication.","reveals":"Put the missing term at the start of the pattern rather than the end.","help":"Link to 'what number times 3 gives 12?' and to the inverse relationship between multiplication and division.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_CREATE.M_TABLE_VS_REPEATED_MULTIPLY","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_CREATE","error":"Asked to multiply the previous term each time, produces a times-table list (adding the same amount) instead.","example":{"question":"Make a pattern of 5 numbers starting at 3. Rule: multiply the previous number by 2.","wrong_answer":"3, 6, 9, 12, 15","correct_answer":"3, 6, 12, 24, 48"},"cause":"Confuses 'multiples of 3' with 'multiplying by 2 each time', because the first two terms are the same.","reveals":"Use start-and-rule tasks where the times-table list and the repeated-multiplication pattern agree at first and then separate.","help":"Have learners write each step as a calculation (3 × 2 = 6, 6 × 2 = 12, …) before writing the pattern.","status":"draft"},{"code":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_CREATE.M_RULE_CHANGES_MIDWAY","skill":"MATH.G5.NUMBER.MULTIPLICATION.MULT_PATTERN_CREATE","error":"Creates a pattern in which the rule changes partway, mixing multiplying and adding, but describes it as a single rule.","example":{"question":"Make your own multiplication pattern and write its rule.","wrong_answer":"2, 4, 8, 10, 20 — rule: multiply by 2","correct_answer":"For example 2, 4, 8, 16, 32 — rule: multiply by 2 (8 + 2 = 10 breaks the rule)"},"cause":"Does not check every step against the stated rule.","reveals":"Use a peer-check task where learners test a classmate's pattern step by step.","help":"Ask learners to annotate each arrow between terms with the operation used, so any change of rule becomes visible.","status":"draft"}]},{"code":"MATH.G5.NUMBER.DIVISION","number":"1.5","strand":"Numbers","sub_strand":"Division","sequence":105,"lessons":6,"content_topics":["Division of numbers","Combined operations","Creating patterns"],"learning_experiences":["work out division of up to a 3digit number by up to a 2-digit number where the dividend is greater than the divisor using long and short form","collaborate to show that multiplication is the opposite of division","estimate quotients by rounding off the dividend and divisor to the nearest ten","work out questions involving addition, subtraction, multiplication and division","create number games and puzzles involving division","share digital resources or other resources with peers while playing games involving the division of whole numbers"],"key_inquiry_questions":["Where is division used in real life?","How can we estimate quotients?"],"core_competences":"● Creativity and Imagination: learner creates number games and puzzles involving division. ● Digital Literacy: learner plays digital games involving divisions.","values":"Social Justice: learner shares digital resources or other resources with peers while playing games involving the division of whole numbers.","pcis":"Self-esteem: learner discovers strategies of working out division and creates number games and puzzles.","links":"The learner is able to relate the concept of division to the allocation and sharing in Agriculture.","design_notes":"1) Outcome (f) 'appreciate use of division of whole numbers in real-life situations' is attitudinal. It is not mapped to a skill, but teachers can observe it through the real-life division tasks and the game-making learning experience.\n\n2) Outcome (a): the design does not say whether remainders are included. G4 1.5a explicitly includes them, so including remainders is proposed. The learning experience asks for both 'long and short form'; short form is realistic only for 1-digit divisors, which is why there are separate 1-digit and 2-digit skills (proposed split). The 'dividend greater than divisor' limit is respected; 2-digit ÷ 2-digit items (e.g. 96 ÷ 12) are included because the outcome says 'up to'.\n\n3) Outcome (c), 'divide up to 3-digit number by 1000', is ambiguous. Any whole number from 1 to 999 divided by 1000 is less than 1, so the answer must be a decimal to thousandths (or a fraction over 1000). G4 decimals reach only hundredths (G4 1.7c), and the G5 Decimals sub-strand was not supplied, so it cannot be linked. It also conflicts with the 'dividend greater than divisor' idea in (a). The interpretation used here (answer as a decimal, with measurement conversions) is proposed. Other possible intended meanings are 'divide by 10, 100 and 1000' or 'divide up to a 4-digit number by 1000'. This should be checked against the full design or the KICD-approved textbooks before items are written.\n\n4) Outcome (d): rounding to the nearest ten does not suit 1-digit divisors (4 rounds to 0, 7 rounds to 10). Restricting estimation items to 2-digit divisors is proposed. Rounded divisions often do not come out whole (e.g. 487 ÷ 23 becomes 490 ÷ 20 = 24.5). It is proposed that items be chosen so the rounded division is exact, or that 'about 24' be accepted.\n\n5) Outcome (e) gives no limit on number size and does not mention brackets or the order-of-operations rule, although it is needed. G6 1.3c adds 'up to 3-digit number', and keeping the same limit in G5 is proposed. HOREB's G6_BODMAS_BASIC overlaps but sits in Grade 6, whereas this outcome requires it in Grade 5. There is a known Kenyan classroom issue: teaching BODMAS letter order literally (A before S, sometimes M before D) gives wrong answers for expressions like 50 − 20 + 10. HOREB should decide and state the convention (× and ÷ before + and −, each pair left to right is the standard one) and avoid deliberately ambiguous items. Note that strict 'D before M' never changes the result; only 'M before D' and 'A before S' produce errors.\n\n6) The content topic 'Creating patterns' and the learning experience 'create number games and puzzles involving division' have no matching outcome. No skill is assigned; teachers may treat them as enrichment within (a) and (b).\n\n7) The key inquiry questions text is garbled in the source. The two readable questions are 'Where is division used in real life?' and 'How can we estimate quotients?'\n\n8) HOREB id mismatches: G5_DIVISION is labelled 'by 1-digit', which covers only part of outcome (a). G5_MULTIPLICATION is labelled '2-digit × 1-digit', although G4 1.4b already covers 2-digit × 2-digit. G4_DIVIDE is labelled 'Long', but G4 1.5a is only 2-digit ÷ 1-digit. There is no existing HOREB skill for estimating quotients or for dividing by 1000.","outcomes":[{"code":"MATH.G5.NUMBER.DIVISION.a","letter":"a","text":"divide up to a 3-digit number by up to a 2-digit number where the dividend is greater than the divisor in real life","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DIVISION.b","letter":"b","text":"apply the relationship between multiplication and division in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DIVISION.c","letter":"c","text":"divide up to 3-digit number by 1000 in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DIVISION.d","letter":"d","text":"estimate quotients by rounding off the dividend and divisor to the nearest ten in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DIVISION.e","letter":"e","text":"perform combined operations involving addition, subtraction, multiplication and division of whole numbers in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DIVISION.f","letter":"f","text":"appreciate use of division of whole numbers in real-life situations","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","name":"Divide a 3-digit number by a 1-digit number (short and long form)","outcomes":["MATH.G5.NUMBER.DIVISION.a"],"mastery":"Divides any dividend from 100 to 999 by a divisor from 2 to 9 using both short form and long form. Places zeros in the quotient correctly and gives a remainder that is always smaller than the divisor. Including remainders is proposed, because the outcome does not mention them but G4 1.5a includes them.","question_forms":["bare calculation: short form","bare calculation: long form","quotient with a zero digit (e.g. 618 ÷ 6)","division with remainder","spot the error in a worked division"],"thinking":["procedure"],"horeb_skill_ids":["G5_DIVISION","G4_DIVIDE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.DIVISION.a","kind":"outcome","strength":"essential","reason":"Extends 2-digit ÷ 1-digit division, with and without remainder, to 3-digit dividends.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"essential","reason":"Each step of division works on hundreds, tens and ones in turn.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"helpful","reason":"Fluent multiplication facts make choosing each quotient digit quick.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"helpful","reason":"Long form needs subtraction with regrouping at each step.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT","name":"Divide up to a 3-digit number by a 2-digit number (long division)","outcomes":["MATH.G5.NUMBER.DIVISION.a"],"mastery":"Divides any dividend up to 999 by a divisor from 10 to 99, where the dividend is greater than the divisor, using long division. Chooses each trial quotient digit sensibly, recognises when a remainder is too big, and handles quotients ending in or containing zero (e.g. 840 ÷ 42 = 20).","question_forms":["bare calculation: long division","2-digit ÷ 2-digit (e.g. 96 ÷ 12)","quotient with a zero digit","division with remainder","spot the error in a worked division"],"thinking":["procedure"],"horeb_skill_ids":["G4_DIVIDE"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","kind":"skill","strength":"essential","reason":"Long division by a 2-digit number uses the same bring-down routine.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"essential","reason":"Each trial product is a 2-digit number multiplied by a 1-digit number.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"essential","reason":"Subtracting trial products often needs regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"helpful","reason":"Rounding the divisor to the nearest ten helps guess each quotient digit.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS","name":"Solve real-life division problems and interpret the remainder","outcomes":["MATH.G5.NUMBER.DIVISION.a"],"mastery":"Recognises sharing and grouping situations as division, with numbers within the limits above (dividend up to 999, divisor up to 99). Writes the correct division and decides from the context whether the answer is the quotient, the quotient rounded up, or the remainder (e.g. matatus needed, money left over).","question_forms":["word problem: equal sharing","word problem: grouping / how many fit","word problem: round up the remainder","word problem: what is left over","choose the operation"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_DIVISION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT","kind":"skill","strength":"essential","reason":"Real-life problems use divisors up to 2 digits.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","kind":"skill","strength":"essential","reason":"Many sharing problems use 1-digit divisors.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES","name":"Use multiplication and division as inverse operations","outcomes":["MATH.G5.NUMBER.DIVISION.b"],"mastery":"From one multiplication or division fact, with products up to 999 and factors up to 2 digits, writes the related facts (e.g. 24 × 6 = 144, so 144 ÷ 6 = 24 and 144 ÷ 24 = 6). Uses the inverse operation to find a missing number in a multiplication or division sentence.","question_forms":["write the fact family","missing number: ☐ ÷ a = b","missing number: a × ☐ = c","true or false: related facts","explain why division is not commutative"],"thinking":["reasoning","recall"],"horeb_skill_ids":["G5_MULTIPLICATION","G5_DIVISION"],"prerequisites":[{"requires":"MATH.G4.NUMBER.DIVISION.b","kind":"outcome","strength":"essential","reason":"G4 introduced relating multiplication to division of the same numbers.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"helpful","reason":"Facts with 2-digit factors need 2-digit multiplication.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.CHECK_DIVISION_BY_MULT","name":"Check a division by multiplying (and adding the remainder)","outcomes":["MATH.G5.NUMBER.DIVISION.b"],"mastery":"Checks any division within the G5 limits by working out quotient × divisor + remainder and comparing the result with the dividend (e.g. 395 ÷ 12 = 32 r 11 because 12 × 32 + 11 = 395). Uses the check to decide whether a given answer is right.","question_forms":["check this answer","find the dividend from quotient, divisor and remainder","which worked answer is correct (multiple choice)"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_MULTIPLICATION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES","kind":"skill","strength":"essential","reason":"Checking relies on knowing that multiplication undoes division.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT","kind":"skill","strength":"essential","reason":"The divisions being checked are of this size.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"essential","reason":"Quotient × divisor is a 2-digit by 2-digit multiplication.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.a","kind":"outcome","strength":"helpful","reason":"The remainder must be added back to the product.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000","name":"Divide up to a 3-digit number by 1000 (proposed interpretation: answer as a decimal)","outcomes":["MATH.G5.NUMBER.DIVISION.c"],"mastery":"Proposed: divides a whole number from 1 to 999 by 1000 by shifting the digits three places to the right, and writes the result as a decimal less than 1 (e.g. 375 ÷ 1000 = 0.375, 45 ÷ 1000 = 0.045, 300 ÷ 1000 = 0.3). Uses this in measurement contexts such as grams to kilograms, millilitres to litres and metres to kilometres. See notes: the outcome is ambiguous.","question_forms":["bare calculation","unit conversion in context (g → kg, ml → l, m → km)","place the decimal point","match the number to its value ÷ 1000"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_DECIMALS_INTRO","G5_PLACE_VALUE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.DECIMALS.c","kind":"outcome","strength":"essential","reason":"The answer is a decimal, so place value after the decimal point is needed (G4 reaches only hundredths).","status":"proposed"},{"requires":"MATH.G4.NUMBER.DECIMALS.b","kind":"outcome","strength":"essential","reason":"The child must write the result in decimal notation.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"helpful","reason":"Seeing ÷ 1000 as a shift of every digit three places relies on place value.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.a","kind":"outcome","strength":"helpful","reason":"The zeros pattern for × 10, 100 and 1000 is the mirror of ÷ 1000.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.ESTIMATE_QUOTIENTS","name":"Estimate quotients by rounding dividend and divisor to the nearest ten","outcomes":["MATH.G5.NUMBER.DIVISION.d"],"mastery":"Rounds a dividend up to 999 and a 2-digit divisor each to the nearest ten, then divides the rounded numbers mentally (e.g. 598 ÷ 31 ≈ 600 ÷ 30 = 20). Uses the estimate to judge whether an exact answer or a real-life claim is reasonable. Restricting divisors to 2 digits is proposed (see notes).","question_forms":["estimate the quotient","round then divide (show both roundings)","is this answer reasonable?","word problem: about how many","compare estimate with exact answer"],"thinking":["procedure","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.e","kind":"outcome","strength":"essential","reason":"Both numbers must be rounded correctly to the nearest ten.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.a","kind":"outcome","strength":"essential","reason":"Dividing multiples of ten mentally rests on multiplying by multiples of 10.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.c","kind":"outcome","strength":"helpful","reason":"The same rounding-then-calculating idea was used for products.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES","kind":"skill","strength":"helpful","reason":"600 ÷ 30 is quickest found by asking 30 × ? = 600.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS","name":"Work out combined operations (+, −, ×, ÷) in the correct order","outcomes":["MATH.G5.NUMBER.DIVISION.e"],"mastery":"Evaluates whole-number expressions mixing two to four of +, −, × and ÷, using the proposed limits below. Does × and ÷ before + and −, and works left to right within each pair (e.g. 20 + 30 ÷ 5 = 26; 50 − 20 + 10 = 40). Proposed limits: each operation stays within G5 ranges and every step gives a whole number; brackets are optional and proposed.","question_forms":["evaluate the expression","which operation first?","insert brackets to make it true (proposed extension)","spot the error in a worked solution","true or false: two expressions are equal"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G6_BODMAS_BASIC"],"prerequisites":[{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"essential","reason":"Expressions include addition with regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"essential","reason":"Expressions include subtraction with regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"essential","reason":"Expressions include multiplication up to 2-digit by 2-digit.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","kind":"skill","strength":"essential","reason":"Expressions include division steps.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DIVISION.COMBINED_OPS_PROBLEMS","name":"Solve multi-step real-life problems using combined operations","outcomes":["MATH.G5.NUMBER.DIVISION.e"],"mastery":"Turns a 2- or 3-step Kenyan everyday situation (shopping and change, sharing after buying, harvest packing) into a sequence of operations or a single expression, then solves it with whole numbers within G5 limits. Answers the question actually asked.","question_forms":["word problem: buy then change","word problem: share then remove/add","write the expression for the story","create a story for an expression"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G6_BODMAS_BASIC"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS","kind":"skill","strength":"essential","reason":"Multi-step stories are solved as combined-operation expressions.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS","kind":"skill","strength":"helpful","reason":"The child must already recognise when a step is division.","status":"proposed"},{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.b","kind":"outcome","strength":"helpful","reason":"Forming expressions from situations was begun in G4.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT.M_ZERO_QUOTIENT_DROPPED","skill":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","error":"When the divisor will not go into a digit, the child skips that place instead of writing 0 in the quotient.","example":{"question":"618 ÷ 6","wrong_answer":"13","correct_answer":"103"},"cause":"Believes 'goes 0 times' means 'write nothing', and does not track place value in the quotient.","reveals":"Use dividends with a zero quotient digit and offer 13 as a distractor. Asking for a check (6 × 13 = 78, far from 618) also exposes it.","help":"Have the child write the quotient digits above the matching dividend digits, put a digit above every column, and estimate first (600 ÷ 6 is about 100).","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT.M_REMAINDER_TOO_BIG","skill":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","error":"Accepts a remainder that is equal to or larger than the divisor.","example":{"question":"157 ÷ 5","wrong_answer":"30 r 7","correct_answer":"31 r 2"},"cause":"Stops as soon as some multiple of the divisor fits, without seeing that the remainder must be less than the divisor.","reveals":"Multiple choice including '30 r 7', or ask 'Could 5 more be taken from the remainder?'","help":"Make 'is my remainder smaller than the divisor?' a fixed final check, and model it with bottle tops grouped in fives.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT.M_SHORT_DIV_NO_CARRY","skill":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_1DIGIT","error":"In short division the child drops the remainder from one digit instead of carrying it to the next digit.","example":{"question":"852 ÷ 4 (short form)","wrong_answer":"210","correct_answer":"213"},"cause":"Treats each digit as a separate small division (8 ÷ 4, 5 ÷ 4, 2 ÷ 4) and does not see that the leftover 1 ten is 10 ones.","reveals":"Use short-form items where middle digits leave remainders, and include 210 as a distractor.","help":"Model with place-value cards or bundles of sticks: unbundle the leftover ten into ones and write the small carried 1 beside the next digit.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT.M_TRIAL_DIGIT_TOO_SMALL","skill":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT","error":"Chooses a trial quotient digit that is too small and leaves a remainder equal to or bigger than the 2-digit divisor.","example":{"question":"864 ÷ 24","wrong_answer":"35 r 24","correct_answer":"36"},"cause":"Guesses quotient digits without a strategy (such as rounding 24 to 20 or 25) and does not compare the remainder with the divisor.","reveals":"Use a 'spot the error' item showing 35 r 24, or a multiple-choice question with that distractor.","help":"Have the child write a quick multiples list of the divisor (24, 48, 72, 96 …) before starting, and check that each remainder is less than 24.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT.M_TRAILING_ZERO_DROPPED","skill":"MATH.G5.NUMBER.DIVISION.DIV_3DIGIT_BY_2DIGIT","error":"Leaves off the final zero of the quotient when the last digit brought down is too small to divide.","example":{"question":"840 ÷ 42","wrong_answer":"2","correct_answer":"20"},"cause":"Stops once the remainder is 0 after the first step, forgetting that the ones digit still needs a quotient digit.","reveals":"Use dividends whose quotient ends in 0 (840 ÷ 42, 960 ÷ 32) and ask for an estimate alongside.","help":"Insist that every digit of the dividend is brought down and gets a quotient digit, and compare with the estimate 840 ÷ 40 ≈ 20.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS.M_REMAINDER_NOT_INTERPRETED","skill":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS","error":"Gives the bare quotient when the context needs rounding up.","example":{"question":"250 pupils are going on a trip to Nairobi National Park. Each matatu carries 14 pupils. How many matatus are needed?","wrong_answer":"17 matatus (or 17 r 12)","correct_answer":"18 matatus (250 ÷ 14 = 17 r 12, so 12 pupils need one more matatu)"},"cause":"Treats the computation as the answer without asking what the remainder means in the story.","reveals":"Use contexts where the quotient alone is wrong, with 17 and '17 r 12' as distractors.","help":"After every word problem, ask 'What does the remainder stand for here, and what happens to those pupils?'","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS.M_GIVES_QUOTIENT_NOT_REMAINDER","skill":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS","error":"Answers with the quotient when the question asks what is left over.","example":{"question":"Akinyi has Sh 500. Exercise books cost Sh 45 each. She buys as many as she can. How much money is left?","wrong_answer":"Sh 11","correct_answer":"Sh 5 (500 ÷ 45 = 11 r 5)"},"cause":"Assumes the quotient is always the answer in a division problem.","reveals":"Ask 'how much is left' questions and include the quotient as a distractor.","help":"Have pupils underline the question sentence and label quotient and remainder with their meanings ('11 books', 'Sh 5 left').","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS.M_KEYWORD_EACH_MEANS_MULTIPLY","skill":"MATH.G5.NUMBER.DIVISION.DIV_WORD_PROBLEMS","error":"Multiplies because the problem contains the word 'each'.","example":{"question":"A farmer in Murang'a packs 360 mangoes into crates. Each crate holds 24 mangoes. How many crates does he fill?","wrong_answer":"8640 crates","correct_answer":"15 crates"},"cause":"Relies on keyword rules instead of picturing the situation, and does not check whether the answer is sensible.","reveals":"Use 'choose the operation' items where 'each' appears in grouping (division) stories, with the product as a distractor.","help":"Have pupils draw a quick sketch of crates and mangoes and ask 'Should the answer be more or fewer than 360?'","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES.M_DIVISION_COMMUTATIVE","skill":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES","error":"Writes the numbers of a division fact in any order, as if division were commutative like multiplication.","example":{"question":"Given 24 × 6 = 144, write a division fact.","wrong_answer":"6 ÷ 144 = 24","correct_answer":"144 ÷ 6 = 24 or 144 ÷ 24 = 6"},"cause":"Overgeneralises 'order does not matter' from multiplication, and does not see that the product is always the dividend.","reveals":"True-or-false items with reversed facts, and fact-family completion.","help":"Use a triangle fact card with the product at the top and the rule 'the top number is always divided'.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES.M_MISSING_DIVIDEND_DIVIDES","skill":"MATH.G5.NUMBER.DIVISION.MULT_DIV_FACT_FAMILIES","error":"To find a missing dividend, the child divides the two given numbers instead of multiplying.","example":{"question":"☐ ÷ 8 = 16","wrong_answer":"2","correct_answer":"128"},"cause":"Sees the ÷ sign and divides the visible numbers, without reasoning about which operation undoes division.","reveals":"Use missing-dividend items with the quotient of the two given numbers as a distractor, and ask the child to substitute the answer back in.","help":"Have the child read it as '16 groups of 8 make what?' and check by putting the answer in the box.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.CHECK_DIVISION_BY_MULT.M_CHECK_FORGETS_REMAINDER","skill":"MATH.G5.NUMBER.DIVISION.CHECK_DIVISION_BY_MULT","error":"When checking a division with a remainder, the child multiplies quotient by divisor but does not add the remainder, then decides a correct answer is wrong.","example":{"question":"Is 395 ÷ 12 = 32 r 11 correct? Check by multiplying.","wrong_answer":"No, because 12 × 32 = 384, not 395","correct_answer":"Yes: 12 × 32 = 384 and 384 + 11 = 395"},"cause":"Knows the check only for exact divisions, and does not see the remainder as part of the dividend.","reveals":"Ask for checks of correct divisions with remainders, and see whether the child rejects them.","help":"Teach the check as a sentence frame: 'groups × size + leftover = total'.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000.M_DIV1000_DECIMAL_PLACES","skill":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000","error":"Places the decimal point after moving only two places, or ignores the missing place holder, when the number has fewer than three digits.","example":{"question":"A packet of Royco weighs 45 g. Write its mass in kg (45 ÷ 1000).","wrong_answer":"0.45 kg","correct_answer":"0.045 kg"},"cause":"Uses 'put 0. in front' as a rule instead of shifting each digit three places, so no zero place holder is inserted.","reveals":"Use 1- and 2-digit dividends with distractors 0.45 and 0.0045.","help":"Write the number on a place-value chart and slide each digit three columns to the right, filling empty columns with zeros.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000.M_SMALLER_CANNOT_DIVIDE_BIGGER","skill":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000","error":"Says a smaller number cannot be divided by a bigger one, or gives 0.","example":{"question":"Mama bought 750 g of sugar. How many kilograms is that? (750 ÷ 1000)","wrong_answer":"0 kg / 'cannot be done'","correct_answer":"0.75 kg"},"cause":"Holds the earlier rule that the dividend must be greater than the divisor, a rule reinforced by outcome (a).","reveals":"Ask the child to explain whether 750 ÷ 1000 is possible, and use a measuring context such as a 1 kg packet.","help":"Show a 1 kg packet against a 750 g packet and ask what part of a kilogram it is, then link this to decimals.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000.M_DIV1000_MULTIPLIES","skill":"MATH.G5.NUMBER.DIVISION.DIV_BY_1000","error":"Adds three zeros (multiplies) instead of dividing.","example":{"question":"125 ÷ 1000","wrong_answer":"125000","correct_answer":"0.125"},"cause":"Remembers 'three zeros' from × 1000 without the direction of the shift.","reveals":"Mix × 1000 and ÷ 1000 items, and ask 'should the answer be bigger or smaller than 125?'","help":"Before calculating, have the child say whether the answer will be bigger or smaller, then shift the digits.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.ESTIMATE_QUOTIENTS.M_ROUNDS_DIVISOR_WRONG","skill":"MATH.G5.NUMBER.DIVISION.ESTIMATE_QUOTIENTS","error":"Rounds a 2-digit divisor ending in 5 (or above) down instead of up.","example":{"question":"Estimate 598 ÷ 15 by rounding both numbers to the nearest ten.","wrong_answer":"600 ÷ 10 = 60","correct_answer":"600 ÷ 20 = 30"},"cause":"Applies rounding rules unevenly, often treating 5 as 'round down' or rounding toward a friendlier number.","reveals":"Use divisors ending in 5 to 9 and ask for the rounded numbers as well as the estimate.","help":"Have the child place the number on a number line between the two tens and recite '5 or more, round up'.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.ESTIMATE_QUOTIENTS.M_ESTIMATE_COMPUTED_EXACTLY","skill":"MATH.G5.NUMBER.DIVISION.ESTIMATE_QUOTIENTS","error":"Works out the exact quotient (or rounds only one number) instead of estimating.","example":{"question":"Estimate 598 ÷ 31 by rounding to the nearest ten.","wrong_answer":"19 r 9","correct_answer":"600 ÷ 30 = 20"},"cause":"Sees estimating as 'less correct' or does not understand its purpose, so falls back on the familiar algorithm.","reveals":"Use timed mental estimation items, or ask for the rounded division sentence explicitly.","help":"Use estimates before calculating, for example 'about how many 30-shilling mandazi can Sh 598 buy?', and praise quick sensible answers.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS.M_LEFT_TO_RIGHT_ALL","skill":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS","error":"Works every operation strictly from left to right, ignoring that × and ÷ come before + and −.","example":{"question":"20 + 30 ÷ 5","wrong_answer":"10","correct_answer":"26"},"cause":"Reads expressions like a sentence and has not learnt the order-of-operations convention.","reveals":"Put + or − before × or ÷, and offer the left-to-right result as a distractor.","help":"Have pupils circle the × and ÷ parts first and work those out before anything else.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS.M_ADD_BEFORE_SUBTRACT","skill":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS","error":"Applies BODMAS letter order literally, doing all additions before any subtraction.","example":{"question":"50 − 20 + 10","wrong_answer":"20","correct_answer":"40"},"cause":"Believes A must come before S because of the order of letters in BODMAS.","reveals":"Use expressions where − comes before +, with the 'add first' result as a distractor.","help":"Teach + and − as partners worked left to right, and check with a shilling story ('had Sh 50, spent 20, got 10').","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS.M_MULTIPLY_BEFORE_DIVIDE","skill":"MATH.G5.NUMBER.DIVISION.ORDER_OF_OPERATIONS","error":"Always multiplies before dividing, even when the division comes first.","example":{"question":"48 ÷ 6 × 2","wrong_answer":"4","correct_answer":"16"},"cause":"Thinks × ranks above ÷ (or misreads the order of letters), instead of treating them as partners worked left to right.","reveals":"Use ÷ followed by × expressions, with the 'multiply first' result as a distractor.","help":"Pair × and ÷ on one step of an 'operations ladder' and work that step left to right.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.COMBINED_OPS_PROBLEMS.M_STOPS_AFTER_ONE_STEP","skill":"MATH.G5.NUMBER.DIVISION.COMBINED_OPS_PROBLEMS","error":"Does only the first step of a multi-step problem and gives that as the answer.","example":{"question":"Wanjiku bought 3 kg of sugar at Sh 150 per kg and paid with a Sh 1000 note. How much change did she get?","wrong_answer":"Sh 450","correct_answer":"Sh 550 (1000 − 3 × 150)"},"cause":"Does not keep the final question in mind, and treats any calculated number as the answer.","reveals":"Use multi-step items whose intermediate result is offered as a distractor.","help":"Have pupils plan the steps in words first ('cost, then change') and tick each one off.","status":"draft"},{"code":"MATH.G5.NUMBER.DIVISION.COMBINED_OPS_PROBLEMS.M_EXPRESSION_ORDER_SCRAMBLED","skill":"MATH.G5.NUMBER.DIVISION.COMBINED_OPS_PROBLEMS","error":"Writes a correct expression for the story but then evaluates it left to right, or writes the operations in the order the numbers appear rather than the order of the story.","example":{"question":"Write and work out an expression: a teacher shares 120 pencils equally among 4 groups, then each group gives away 6 pencils. How many pencils does each group have now?","wrong_answer":"120 ÷ (4 − 6), or 120 ÷ 4 − 6 worked as 120 ÷ (−2), giving no answer","correct_answer":"120 ÷ 4 − 6 = 30 − 6 = 24 pencils"},"cause":"Does not connect the order of actions in the story with the order of operations in the expression.","reveals":"Ask the child to match stories to expressions, and include expressions with the operations in the wrong order.","help":"Have the child act out the story step by step with counters, writing each step as it happens before combining them into one expression.","status":"draft"}]},{"code":"MATH.G5.NUMBER.FRACTIONS","number":"1.6","strand":"Numbers","sub_strand":"Fractions","sequence":106,"lessons":8,"content_topics":["Simplifying, comparing and ordering fractions","Addition and subtraction of fraction"],"learning_experiences":["identify equivalent fractions using a fraction board or chart","represent equivalent fractions using real objects","use charts or others resources to express fractions in their simplest forms","arrange given fractions in increasing or decreasing order using different methods","add fractions with the same denominator using paper cut-outs, real objects or other resources","subtract two fractions with the same denominator using paper cutouts, number lines, real objects, or other resources","carry out addition of two fractions by renaming one fraction using equivalent fractions","carry out subtraction of two fractions by renaming one fraction using equivalent fractions"],"key_inquiry_questions":["Why can we order fractions in real life?","Where are fractions used in real life?"],"core_competences":"● Learning to learn: learner orders, compares and simplifies fractions. ● Digital Literacy: learner plays digital games involving fractions.","values":"Responsibility: learner prepares paper cut-outs and collects concrete objects for comparing fractions.","pcis":"Safety: learner observes safety precautions while collecting concrete objects for learning.","links":"The learner is able to relate the concept of fractions to mixtures in Science and Technology.","design_notes":"1) Outcome h ('appreciate the use of fractions in real life') is attitudinal and is not mapped to a skill; it can be observed through real-life tasks and the key inquiry questions. 2) Outcomes a and b give no denominator limit, and d to g give no limit at all; only c states 'not exceeding 12'. The limit of denominators not exceeding 12 across all skills is proposed, for consistency with c and with G4 1.6b. The proposed starting terms up to 50 for simplifying follow G4 1.1f (factors up to 50). 3) 'With one renaming' in f and g is interpreted (proposed) as: one denominator is a multiple of the other, so only one fraction is renamed using equivalent fractions. This matches the learning experiences, and the LCM method (both renamed) is Grade 6 (1.4a, 1.4b). 4) Whether d to g include mixed numbers is not stated. Since adding and subtracting mixed numbers appears in Grade 6 (1.4c, 1.4d), proper fractions only are proposed. Sums greater than 1 may be written as mixed numbers (G4 1.6d), and subtraction results should not be negative. 5) G5_EQUIVALENT_FRACTIONS is mapped to outcome a because the design's learning experiences for simplifying start with equivalent fractions; it is also the key prerequisite for b, c, f and g. 6) Comparing fractions whose denominators share no convenient common denominator up to 12 (e.g. 3/4 and 4/5) is proposed as out of scope for Grade 5. 7) The Grade 4 official outcomes do not mention equivalent fractions or comparing, yet HOREB's G4_FRACTIONS is labelled 'Equivalent, Compare'; HOREB should check whether that content belongs to Grade 5. Also, G5_FRACTIONS_INTRO overlaps G4 1.6a to 1.6e. G6_FRACTIONS_ADD and G6_FRACTIONS_SUB only partly overlap f and g (unlike denominators in general versus one renaming). 8) Grade 5 almost certainly has its own whole-number content on factors and multiples (HOREB G5_FACTORS, G5_MULTIPLES), but no Grade 5 codes were supplied, so prerequisites link to G4 1.1f and 1.1g instead. 9) The second key inquiry question contains the stray text 'Inquiry Question(s)', which looks like an extraction artefact from the design layout.","outcomes":[{"code":"MATH.G5.NUMBER.FRACTIONS.a","letter":"a","text":"simplify fractions in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.b","letter":"b","text":"compare fractions in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.c","letter":"c","text":"order fractions with denominators not exceeding 12 in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.d","letter":"d","text":"add two fractions with the same denominator in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.e","letter":"e","text":"subtract two fractions with the same denominator in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.f","letter":"f","text":"add two fractions with one renaming in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.g","letter":"g","text":"subtract two fractions with one renaming in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.FRACTIONS.h","letter":"h","text":"appreciate the use of fractions in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","name":"Recognise and generate equivalent fractions","outcomes":["MATH.G5.NUMBER.FRACTIONS.a"],"mastery":"Given a fraction with denominator not exceeding 12, the child produces equivalent fractions by multiplying or dividing the numerator and denominator by the same number (proposed: multipliers 2 to 10). The child can show the equivalence on a fraction board, a chart or with real objects and explain that the amount stays the same.","question_forms":["missing number (e.g. 3/4 = ?/12)","match equivalent fractions on a fraction board or chart","true or false: are these fractions equivalent?","compare and explain: same amount of a shared item"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_FRACTIONS_EQUIV","G4_FRACTIONS"],"prerequisites":[{"requires":"MATH.G4.NUMBER.FRACTIONS.b","kind":"outcome","strength":"essential","reason":"The child must see a fraction as part of a whole to see that two fractions cover the same amount.","status":"proposed"},{"requires":"MATH.G4.NUMBER.FRACTIONS.a","kind":"outcome","strength":"essential","reason":"Equivalence is built by acting on the numerator and the denominator separately.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"helpful","reason":"Fluent multiplication makes scaling the numerator and denominator quick.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","name":"Express a fraction in its simplest form","outcomes":["MATH.G5.NUMBER.FRACTIONS.a"],"mastery":"The child reduces a fraction to its simplest form by dividing the numerator and denominator by a common factor, repeating until no common factor other than 1 remains. Proposed limits: starting numerators and denominators up to 50, in line with G4 factors up to 50, and simplest forms with denominators not exceeding 12. The child also knows the simplified fraction has the same value.","question_forms":["simplify to lowest terms","is this fraction in its simplest form? explain","word problem: give the answer in simplest form (e.g. 6 of 8 mandazi eaten)","spot the error in a worked simplification"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_FRACTIONS_EQUIV"],"prerequisites":[{"requires":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","kind":"skill","strength":"essential","reason":"Simplifying is finding the equivalent fraction with the smallest terms.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.f","kind":"outcome","strength":"essential","reason":"The child must find common factors of the numerator and denominator.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.a","kind":"outcome","strength":"helpful","reason":"Dividing both terms by a common factor relies on division facts.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS","name":"Compare fractions with the same denominator or the same numerator","outcomes":["MATH.G5.NUMBER.FRACTIONS.b"],"mastery":"The child uses < , > or = to compare two fractions of the same whole that share a denominator or a numerator, including unit fractions. The child explains that a larger denominator means smaller parts. Proposed limit: denominators not exceeding 12.","question_forms":["insert <, > or =","which is bigger? (unit fractions)","word problem: who got more of the same chapati or loaf","compare and explain: same whole versus different wholes"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G4_FRACTIONS"],"prerequisites":[{"requires":"MATH.G4.NUMBER.FRACTIONS.b","kind":"outcome","strength":"essential","reason":"Comparing needs a picture of what each fraction of the same whole looks like.","status":"proposed"},{"requires":"MATH.G4.NUMBER.FRACTIONS.a","kind":"outcome","strength":"essential","reason":"The child must know what the denominator tells about the size of the parts.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.d","kind":"outcome","strength":"helpful","reason":"Comparing whole numbers and using the comparison symbols is the base for comparing numerators.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS","name":"Compare fractions with different denominators by renaming","outcomes":["MATH.G5.NUMBER.FRACTIONS.b"],"mastery":"The child compares two fractions with different numerators and denominators by renaming them to a common denominator. Proposed: this is done by renaming one fraction where one denominator is a multiple of the other, or by using a fraction board or lists of equivalent fractions where both denominators divide 12 (e.g. 2/3 and 3/4 as twelfths). The child may also use the benchmark 1/2. Proposed limit: denominators not exceeding 12; LCM methods are Grade 6.","question_forms":["insert <, > or =","word problem: which share is greater (e.g. 2/3 of a plot of sukuma wiki versus 5/6)","compare using a fraction board","compare and explain: why your method works"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G4_FRACTIONS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS","kind":"skill","strength":"essential","reason":"After renaming, the comparison becomes a same-denominator comparison.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","kind":"skill","strength":"essential","reason":"Renaming to a common denominator uses equivalent fractions.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.g","kind":"outcome","strength":"helpful","reason":"Spotting that one denominator is a multiple of the other uses knowledge of multiples.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS","name":"Order fractions with denominators not exceeding 12","outcomes":["MATH.G5.NUMBER.FRACTIONS.c"],"mastery":"The child arranges a set of fractions (proposed: three to five fractions) with denominators not exceeding 12 in increasing or decreasing order. The child uses a suitable method such as same denominator, same numerator, renaming to a common denominator, a fraction board or a number line, and writes the answer using the original fractions.","question_forms":["arrange in increasing order","arrange in decreasing order","word problem: order shares or distances (e.g. fractions of a kilometre walked to school)","place fractions on a number line","which fraction is out of order?"],"thinking":["procedure","reasoning","problem solving"],"horeb_skill_ids":["G4_FRACTIONS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS","kind":"skill","strength":"essential","reason":"Ordering a mixed set needs fractions with different denominators to be compared.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS","kind":"skill","strength":"essential","reason":"Simple sets with the same denominator or numerator are ordered by direct comparison.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.d","kind":"outcome","strength":"helpful","reason":"The child already knows 'increasing' and 'decreasing' from ordering whole numbers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR","name":"Add two fractions with the same denominator","outcomes":["MATH.G5.NUMBER.FRACTIONS.d"],"mastery":"The child adds two proper fractions with the same denominator (proposed: not exceeding 12) by adding the numerators and keeping the denominator. The answer is simplified. Proposed: where the sum exceeds 1, it is written as a mixed number using G4 skills.","question_forms":["calculate the sum","missing addend (e.g. 2/9 + ?/9 = 7/9)","word problem: combining parts of the same whole (e.g. a jug of uji, a plot of maize)","represent with paper cut-outs or a diagram"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_FRACTIONS_ADD_LIKE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.FRACTIONS.b","kind":"outcome","strength":"essential","reason":"Adding is joining parts of the same whole, so the child must picture the parts.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","kind":"skill","strength":"helpful","reason":"Answers are expected in simplest form.","status":"proposed"},{"requires":"MATH.G4.NUMBER.FRACTIONS.d","kind":"outcome","strength":"helpful","reason":"Sums greater than 1 are written as mixed numbers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR","name":"Subtract two fractions with the same denominator","outcomes":["MATH.G5.NUMBER.FRACTIONS.e"],"mastery":"The child subtracts one fraction from another with the same denominator (proposed: not exceeding 12, result not negative). This includes subtracting from a whole written as, for example, 8/8. The child subtracts the numerators, keeps the denominator and simplifies the answer.","question_forms":["calculate the difference","missing number (e.g. 7/10 - ?/10 = 3/10)","word problem: what fraction is left (e.g. of a pawpaw or of a bag of flour)","represent on a number line or with cut-outs"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_FRACTIONS_SUB_LIKE"],"prerequisites":[{"requires":"MATH.G4.NUMBER.FRACTIONS.b","kind":"outcome","strength":"essential","reason":"Taking away parts of a whole needs a clear part-whole picture.","status":"proposed"},{"requires":"MATH.G4.NUMBER.FRACTIONS.e","kind":"outcome","strength":"helpful","reason":"Writing a whole as a fraction (e.g. 1 = 8/8) is linked to converting to improper fractions.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","kind":"skill","strength":"helpful","reason":"Answers are expected in simplest form.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING","name":"Add two fractions by renaming one of them","outcomes":["MATH.G5.NUMBER.FRACTIONS.f"],"mastery":"The child adds two fractions where one denominator is a multiple of the other (proposed: denominators not exceeding 12, e.g. 1/2 + 1/4 or 2/3 + 1/6). The child renames only the fraction with the smaller denominator as an equivalent fraction, adds, and simplifies the answer.","question_forms":["calculate the sum","which fraction should be renamed, and to what?","word problem: combining (e.g. 1/2 kg of sugar and 1/4 kg of sugar)","spot the error in a worked sum"],"thinking":["procedure","reasoning","problem solving"],"horeb_skill_ids":["G6_FRACTIONS_ADD"],"prerequisites":[{"requires":"MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR","kind":"skill","strength":"essential","reason":"After renaming, the task is a same-denominator addition.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","kind":"skill","strength":"essential","reason":"Renaming one fraction is making an equivalent fraction.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.g","kind":"outcome","strength":"helpful","reason":"The child must see which denominator is a multiple of the other.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","kind":"skill","strength":"helpful","reason":"Answers are expected in simplest form.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING","name":"Subtract two fractions by renaming one of them","outcomes":["MATH.G5.NUMBER.FRACTIONS.g"],"mastery":"The child subtracts two fractions where one denominator is a multiple of the other (proposed: denominators not exceeding 12, result not negative). The child renames one fraction as an equivalent fraction, subtracts, and simplifies the answer. The child also recognises when the fraction that looks 'smaller' is actually larger after renaming.","question_forms":["calculate the difference","word problem: what is left or how much more (e.g. 1/2 litre of milk, 3/8 litre drunk)","missing number after renaming","spot the error in a worked subtraction"],"thinking":["procedure","reasoning","problem solving"],"horeb_skill_ids":["G6_FRACTIONS_SUB"],"prerequisites":[{"requires":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR","kind":"skill","strength":"essential","reason":"After renaming, the task is a same-denominator subtraction.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","kind":"skill","strength":"essential","reason":"Renaming one fraction is making an equivalent fraction.","status":"proposed"},{"requires":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS","kind":"skill","strength":"helpful","reason":"Knowing which fraction is larger prevents 'impossible' or reversed subtractions.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS.M_EQUIV_ADDITIVE","skill":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","error":"Adds the same number to the numerator and denominator instead of multiplying both by the same number.","example":{"question":"2/3 = ?/6","wrong_answer":"5 (added 3 to both: 2+3, 3+3)","correct_answer":"4"},"cause":"Believes 'doing the same thing to top and bottom' keeps a fraction the same, whatever the operation.","reveals":"Include the additive answer as a distractor in missing-number items; ask the child to shade 2/3 and 5/6 on fraction strips to check.","help":"Use a fraction board to show that 2/3 covers the same length as 4/6 but not 5/6, then link this to cutting each third into 2 pieces (multiplying by 2).","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS.M_EQUIV_ONE_TERM_ONLY","skill":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","error":"Changes only the denominator and leaves the numerator unchanged.","example":{"question":"3/4 = ?/8","wrong_answer":"3","correct_answer":"6"},"cause":"Sees the denominator as the only part that is 'converted' and does not see the fraction as a relationship between two numbers.","reveals":"Offer 3/8 as a distractor; ask 'Is 3/8 of a cake the same amount as 3/4 of the cake?' with a diagram.","help":"Fold a paper strip into quarters, shade 3, then fold again into eighths and count the shaded eighths.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS.M_EQUIV_BIGGER_NUMBERS_BIGGER","skill":"MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS","error":"Thinks a fraction with bigger numbers is a bigger amount, even when the fractions are equivalent.","example":{"question":"Wanjiku ate 1/2 of a chapati. Otieno ate 4/8 of the same-size chapati. Who ate more?","wrong_answer":"Otieno","correct_answer":"They ate the same amount"},"cause":"Applies whole-number thinking to the numerator and denominator separately.","reveals":"A compare-and-explain item with equivalent fractions written in different terms, with 'the one with bigger numbers' as a distractor.","help":"Have children cut real or paper chapatis into halves and eighths and lay the pieces on top of each other.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS.M_SIMPLIFY_SUBTRACT","skill":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","error":"Simplifies by subtracting the same number from the numerator and denominator.","example":{"question":"Simplify 6/9","wrong_answer":"3/6 (took 3 from each)","correct_answer":"2/3"},"cause":"Thinks 'making the numbers smaller' is the aim, rather than dividing by a common factor.","reveals":"Include the subtracted form as a distractor; ask whether 3/6 and 6/9 shade the same amount.","help":"Always ask 'What number divides both exactly?' and check the answer against a fraction chart.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS.M_SIMPLIFY_STOPS_EARLY","skill":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","error":"Divides once by a common factor and stops before reaching the simplest form.","example":{"question":"Simplify 12/18","wrong_answer":"6/9","correct_answer":"2/3"},"cause":"Thinks 'simplify' means 'make it a bit simpler' rather than 'until no common factor except 1 remains'.","reveals":"Use fractions needing more than one step (or one division by a larger factor) and offer the partly simplified form as a distractor.","help":"Teach a final check: 'Do the numerator and denominator still share a factor other than 1?'","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS.M_SIMPLIFY_MAKES_SMALLER","skill":"MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS","error":"Believes a simplified fraction is a smaller amount than the original.","example":{"question":"Is 2/3 of a bag of rice more than, less than or the same as 8/12 of the bag?","wrong_answer":"Less","correct_answer":"The same"},"cause":"Thinks the size of the numbers shows the size of the fraction.","reveals":"A compare item pairing a fraction with its simplest form.","help":"Show both fractions on a fraction board and stress that simplifying renames the amount without changing it.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS.M_COMPARE_BIGGER_DENOMINATOR","skill":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS","error":"Thinks the fraction with the larger denominator is larger.","example":{"question":"Which is more: 1/4 of a loaf or 1/8 of the same loaf?","wrong_answer":"1/8","correct_answer":"1/4"},"cause":"Uses whole-number ordering (8 > 4) and misses that more parts means smaller parts.","reveals":"Unit-fraction and same-numerator comparisons (e.g. 3/5 versus 3/8) where the 'bigger denominator' choice is wrong.","help":"Share one loaf among 4 children and then among 8, and ask who gets the bigger piece.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS.M_COMPARE_DIFFERENT_WHOLES","skill":"MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS","error":"Compares fractions of different-sized wholes as if the wholes were the same.","example":{"question":"Akinyi got 1/2 of a small mandazi. Baraka got 1/4 of a large cake. Akinyi says she got more because 1/2 > 1/4. Is she right?","wrong_answer":"Yes, 1/2 is always more than 1/4","correct_answer":"Not necessarily; 1/2 > 1/4 only when both are parts of the same (or equal) whole"},"cause":"Treats fractions as fixed amounts and forgets they are parts of a particular whole.","reveals":"A compare-and-explain item using two clearly different wholes.","help":"Show half of a small orange beside a quarter of a watermelon and ask which is more food.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS.M_COMPARE_GAP_THINKING","skill":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS","error":"Judges two fractions to be equal because each is 'one part short' of a whole.","example":{"question":"Compare 2/3 and 3/4 using <, > or =","wrong_answer":"2/3 = 3/4","correct_answer":"2/3 < 3/4 (8/12 < 9/12)"},"cause":"Looks at the difference between the numerator and denominator rather than at the size of the parts.","reveals":"Pairs such as 2/3 versus 3/4 or 5/6 versus 11/12, with '=' as a distractor.","help":"Compare the strips on a fraction board: the missing quarter is smaller than the missing third, so 3/4 is more.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS.M_COMPARE_BIGGER_TERMS","skill":"MATH.G5.NUMBER.FRACTIONS.COMPARE_UNLIKE_FRACTIONS","error":"Picks the fraction with the bigger numerator and denominator as the larger.","example":{"question":"Compare 5/12 and 2/3","wrong_answer":"5/12 > 2/3","correct_answer":"5/12 < 2/3 (5/12 < 8/12)"},"cause":"Whole-number bias: bigger numbers are taken to mean a bigger amount.","reveals":"Pairs where the fraction with larger terms is actually smaller.","help":"Require renaming to a common denominator, or a 'more or less than 1/2?' check, before deciding.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS.M_ORDER_BY_DENOMINATOR","skill":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS","error":"Orders unit fractions by the size of the denominator, as if they were whole numbers.","example":{"question":"Arrange 1/3, 1/6, 1/2 in increasing order","wrong_answer":"1/2, 1/3, 1/6","correct_answer":"1/6, 1/3, 1/2"},"cause":"Applies whole-number ordering to the denominators.","reveals":"Sets of unit fractions or same-numerator fractions to put in increasing order.","help":"Place the fractions on a fraction board or number line from 0 to 1 before writing the order.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS.M_ORDER_BY_NUMERATOR","skill":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS","error":"Orders fractions with different denominators by looking only at the numerators.","example":{"question":"Arrange 2/3, 3/4, 5/12 in increasing order","wrong_answer":"2/3, 3/4, 5/12","correct_answer":"5/12, 2/3, 3/4 (5/12, 8/12, 9/12)"},"cause":"Does not see that numerators can only be compared once the parts are the same size.","reveals":"Mixed-denominator sets where numerator order differs from value order.","help":"Teach 'make the parts the same size first': rename to twelfths, order, then write back the original fractions.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS.M_ORDER_DIRECTION","skill":"MATH.G5.NUMBER.FRACTIONS.ORDER_FRACTIONS","error":"Confuses increasing and decreasing order.","example":{"question":"Arrange 3/4, 1/4, 2/4 in decreasing order","wrong_answer":"1/4, 2/4, 3/4","correct_answer":"3/4, 2/4, 1/4"},"cause":"Has not linked the words 'increasing' and 'decreasing' to 'smallest first' and 'largest first'.","reveals":"Paired items asking for both orders of the same set.","help":"Link the words to a picture, such as steps going up for 'increasing', and have children say 'smallest first' or 'largest first' before writing.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR.M_ADD_DENOMINATORS","skill":"MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR","error":"Adds the denominators as well as the numerators.","example":{"question":"2/7 + 3/7","wrong_answer":"5/14","correct_answer":"5/7"},"cause":"Treats a fraction as two separate whole numbers and adds 'top with top, bottom with bottom'.","reveals":"Offer the added-denominator answer as a distractor; ask whether 5/14 is more or less than 2/7 (it is less, which is impossible after adding).","help":"Use paper cut-outs: 2 sevenths and 3 sevenths make 5 sevenths, because the size of the pieces does not change.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR.M_ADD_DROPS_DENOMINATOR","skill":"MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR","error":"Adds the numerators and writes the answer as a whole number, dropping the denominator.","example":{"question":"Mama used 2/8 of a packet of flour on Monday and 3/8 on Tuesday. What fraction did she use altogether?","wrong_answer":"5","correct_answer":"5/8 of the packet"},"cause":"Counts the pieces but loses track of what kind of pieces they are.","reveals":"Word problems where a whole-number answer is clearly unreasonable (5 packets).","help":"Have children say the unit aloud ('2 eighths plus 3 eighths is 5 eighths').","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR.M_SUB_DENOMINATORS","skill":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR","error":"Subtracts the denominators as well as the numerators.","example":{"question":"5/8 - 3/8","wrong_answer":"2/0 (or 2)","correct_answer":"2/8 = 1/4"},"cause":"Treats the numerator and denominator as separate whole numbers to operate on.","reveals":"Include '2' or '2/0' as a distractor; use a number line marked in eighths.","help":"Model on a number line in eighths: start at 5/8, jump back 3 eighths, and land on 2/8.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR.M_SUB_WHOLE_NOT_RENAMED","skill":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR","error":"Cannot subtract a fraction from a whole, or gives the fraction taken away as the answer.","example":{"question":"Juma had a whole pawpaw and ate 3/8 of it. What fraction is left?","wrong_answer":"3/8 (or 2/8)","correct_answer":"8/8 - 3/8 = 5/8"},"cause":"Does not see that 1 whole can be written as 8/8.","reveals":"'What is left?' word problems starting from a whole, with the subtracted fraction offered as a distractor.","help":"Cut a real or paper pawpaw into 8 equal pieces, name the whole as 8/8, then remove 3 pieces.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING.M_RENAME_ADD_DENOMINATORS","skill":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING","error":"Adds the numerators and the denominators of unlike fractions without renaming.","example":{"question":"1/2 + 1/4","wrong_answer":"2/6","correct_answer":"2/4 + 1/4 = 3/4"},"cause":"Has no sense that only same-size parts can be counted together.","reveals":"Include 2/6 as a distractor; ask whether the answer can be less than 1/2 when 1/2 was one of the parts.","help":"Use a fraction board: put a half and a quarter end to end and find the single strip they match.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING.M_RENAME_DENOMINATOR_ONLY","skill":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING","error":"Renames the denominator of one fraction but not its numerator, then adds.","example":{"question":"Kamau bought 1/2 kg of sugar and then 1/4 kg more. How much sugar did he buy?","wrong_answer":"1/4 + 1/4 = 2/4 kg","correct_answer":"2/4 + 1/4 = 3/4 kg"},"cause":"Sees renaming as 'making the bottoms match' rather than making an equivalent fraction.","reveals":"Ask for the renamed fraction as an intermediate step; the error shows as 1/2 = 1/4.","help":"Ask after every renaming: 'Is your new fraction the same amount as the old one?'","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING.M_RENAME_ADDITIVE","skill":"MATH.G5.NUMBER.FRACTIONS.ADD_ONE_RENAMING","error":"Renames a fraction by adding to the numerator and denominator instead of multiplying.","example":{"question":"2/3 + 1/6","wrong_answer":"3/6 + 1/6 = 4/6 (renamed 2/3 as 3/6 by adding)","correct_answer":"4/6 + 1/6 = 5/6"},"cause":"Carries over the additive idea of equivalence (see M_EQUIV_ADDITIVE).","reveals":"A 'spot the error' item showing a renaming step done by addition.","help":"Go back to fraction strips to show that each third splits into two sixths, so 2/3 becomes 4/6.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING.M_RENAME_SUB_DENOMINATORS","skill":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING","error":"Subtracts the numerators and the denominators of unlike fractions without renaming.","example":{"question":"3/4 - 1/2","wrong_answer":"2/2 = 1","correct_answer":"3/4 - 2/4 = 1/4"},"cause":"Treats each fraction as two separate whole numbers.","reveals":"The wrong method gives an answer larger than the starting fraction; offer it as a distractor and ask whether that is possible.","help":"Get children to estimate first ('the answer must be less than 3/4') and check their result against the estimate.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING.M_RENAME_SUB_DENOMINATOR_ONLY","skill":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING","error":"Renames only the denominator of one fraction, then subtracts.","example":{"question":"5/6 - 1/3","wrong_answer":"5/6 - 1/6 = 4/6","correct_answer":"5/6 - 2/6 = 3/6 = 1/2"},"cause":"Thinks renaming means changing the denominator so that the denominators match.","reveals":"Ask for the renamed fraction as a separate step.","help":"Get children to show the renamed fraction on a fraction chart before subtracting.","status":"draft"},{"code":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING.M_SUB_THINKS_IMPOSSIBLE","skill":"MATH.G5.NUMBER.FRACTIONS.SUBTRACT_ONE_RENAMING","error":"Thinks the subtraction cannot be done (or reverses it) because the second fraction has bigger numbers.","example":{"question":"Neema had 1/2 litre of milk and drank 3/8 litre. How much milk was left?","wrong_answer":"It cannot be done because 3/8 is more than 1/2","correct_answer":"4/8 - 3/8 = 1/8 litre"},"cause":"Judges fraction size by the size of the numerators and denominators.","reveals":"Subtraction items where the second fraction has the larger terms but the smaller value.","help":"Rename first, then compare: 1/2 is 4/8, which is more than 3/8.","status":"draft"}]},{"code":"MATH.G5.NUMBER.DECIMALS","number":"1.7","strand":"Numbers","sub_strand":"Decimals","sequence":107,"lessons":6,"content_topics":["Place value in decimals","Addition and subtraction of decimals"],"learning_experiences":["work out place value of decimals up to thousandths using a place value chart","order decimals up to thousandths from smallest to largest and from largest to smallest using different methods","work out addition of decimals up to thousandths using place value apparatus","subtract decimals up to thousandths using place value apparatus","collaborate with peers to find information on application of decimals in real-life situations"],"key_inquiry_questions":["Where can you use decimals in real life?","What is the importance of ordering decimals?"],"core_competences":"Creativity and Imagination: the learner orders decimals up to thousandths from smallest to largest and from largest to smallest using number cards.","values":"• Unity: learner collaborates with peers to find information on application of decimals in real-life situations • Social justice: learner shares information on the application of decimals in real-life situations.","pcis":"Social cohesion: learner collaborates with peers to find information on application of decimals.","links":"The learner is able to relate the concept of decimal numbers to reading quantities of ingredients in Agriculture.","design_notes":"Outcome f ('appreciate use of decimals in real-life situations') is attitudinal and has no skill. It is supported by the learning experience on collaborating with peers to find real-life uses of decimals. The key inquiry questions appear garbled in the source text ('Where' / 'can you use decimals in real life?' / '... Inquiry Question(s)'). They have been read as 'Where can you use decimals in real life?' and 'What is the importance of ordering decimals?'. Outcome a says only 'identify place value'. Including the value of a digit and writing decimals from words or expanded form (G5_DEC_DIGIT_VALUE) is proposed professional judgement, not KICD wording; Grade 4 1.1a pairs 'place value and total value' for whole numbers, but the decimals outcomes do not. Outcome e names only multiplication by 1000. Multiplying by 10 and 100 is not stated, though teachers will probably build up through them; it is not assessed as a separate skill here. There is no learning experience for outcome e, so the method (place value chart shift) is proposed. Unit conversions (kg to g, l to ml, km to m) are proposed 'different situations' and may overlap the Measurement strand. The outcomes give no limit on the whole-number part of decimals or on the number of addends. 'Whole-number parts up to hundreds' and 'two or three addends' are proposed limits. Subtraction is assumed to give non-negative answers, since negative numbers first appear in Grade 6 (integers). Grade 5 whole-number outcome codes were not provided, so prerequisites link to Grade 4 codes and Grade 5 skills in this sub-strand only. The scope of the HOREB skills G5_DECIMALS_INTRO, G5_DECIMALS_ADD and G5_DECIMALS_SUB is unknown; their overlap with these skills should be confirmed. G6_DECIMALS_MUL and G6_INEQUALITIES are only partial overlaps (multiplying decimals generally; using <, > and =). Six suggested lessons is tight for five assessable outcomes, so teachers may need to combine the comparing and ordering skills and the two kinds of addition and subtraction within lessons.","outcomes":[{"code":"MATH.G5.NUMBER.DECIMALS.a","letter":"a","text":"identify place value of decimals up to thousandths in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DECIMALS.b","letter":"b","text":"order decimals up to thousandths in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DECIMALS.c","letter":"c","text":"add decimals up to thousandths in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DECIMALS.d","letter":"d","text":"subtract decimals up to thousandths in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DECIMALS.e","letter":"e","text":"multiply decimal numbers of up to thousandths by 1000 in different situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.DECIMALS.f","letter":"f","text":"appreciate use of decimals in real-life situations","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","name":"Name the place of a digit in a decimal (ones to thousandths)","outcomes":["MATH.G5.NUMBER.DECIMALS.a"],"mastery":"Given a decimal with up to three decimal places (e.g. 34.708, 0.056), the child names the place of any digit (ones, tenths, hundredths, thousandths, plus whole-number places already known) and places the digits correctly on a place value chart. Proposed limit: whole-number part up to hundreds.","question_forms":["name the place of the underlined digit","fill a place value chart from a decimal","which digit is in the thousandths place?","compare place sizes (which is larger: a tenth or a thousandth?)"],"thinking":["recall","procedure"],"horeb_skill_ids":["G5_DECIMALS_INTRO"],"prerequisites":[{"requires":"MATH.G4.NUMBER.DECIMALS.c","kind":"outcome","strength":"essential","reason":"Thousandths extend the tenths and hundredths place value learnt in Grade 4.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DECIMALS.a","kind":"outcome","strength":"essential","reason":"The child must know what a tenth and a hundredth are before meeting a thousandth.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"helpful","reason":"Whole-number place value (each place ten times the next) is the pattern that continues past the decimal point.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE","name":"State the value of a digit and write decimals to thousandths from place value information (proposed)","outcomes":["MATH.G5.NUMBER.DECIMALS.a"],"mastery":"The child states what a digit is worth in a decimal with up to three decimal places (the 7 in 3.072 is 7 hundredths, or 0.07). They also write a decimal from a chart, from words or from expanded form, using zero as a placeholder (e.g. 5 ones and 4 thousandths = 5.004). Proposed: this is professional judgement about what 'identify place value' requires. The outcome does not use the words 'total value'.","question_forms":["value of the underlined digit","write the decimal shown on the chart or abacus","write from expanded form (3 + 0.4 + 0.006)","write from words (e.g. 'two and fifteen thousandths')","real-life: read a measurement such as 1.250 kg and say what each digit means"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_DECIMALS_INTRO"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","kind":"skill","strength":"essential","reason":"A digit's value depends on knowing its place.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DECIMALS.b","kind":"outcome","strength":"essential","reason":"Writing decimals in decimal notation is the basis for writing them to thousandths.","status":"proposed"},{"requires":"MATH.G4.NUMBER.FRACTIONS.b","kind":"outcome","strength":"helpful","reason":"Seeing a tenth as part of a whole supports understanding a digit's value as a fraction of one.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE","name":"Compare two decimals up to thousandths","outcomes":["MATH.G5.NUMBER.DECIMALS.b"],"mastery":"The child correctly decides which of two decimals with up to three decimal places is greater, including pairs with different numbers of decimal places (0.5 and 0.125) and trailing zeros (0.70 and 0.7). They use >, < or = and explain by comparing place by place from the left.","question_forms":["insert >, < or =","which is greater/smaller and why?","compare and explain (spot the error in a friend's comparison)","real-life: which parcel or runner is heavier or faster?"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_DECIMALS_INTRO","G6_INEQUALITIES"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","kind":"skill","strength":"essential","reason":"Comparing place by place from the left needs secure place names and sizes.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DECIMALS.d","kind":"outcome","strength":"essential","reason":"Ordering to hundredths in Grade 4 is the direct foundation.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ORDER","name":"Order a set of decimals up to thousandths","outcomes":["MATH.G5.NUMBER.DECIMALS.b"],"mastery":"The child arranges a set of three to five decimals (up to three decimal places, possibly with different whole-number parts and including whole numbers) from smallest to largest or from largest to smallest. They may use a place value chart, add zeros to give equal decimal places, or use a number line.","question_forms":["arrange smallest to largest","arrange largest to smallest","real-life: order race times, masses of produce or lengths","find the missing decimal that fits between two others"],"thinking":["procedure","reasoning","problem solving"],"horeb_skill_ids":["G5_DECIMALS_INTRO"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE","kind":"skill","strength":"essential","reason":"Ordering a set is repeated pairwise comparison.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.d","kind":"outcome","strength":"helpful","reason":"Experience ordering whole numbers both ways gives the routine of ascending and descending order.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES","name":"Add decimals with the same number of decimal places, with regrouping","outcomes":["MATH.G5.NUMBER.DECIMALS.c"],"mastery":"The child adds two or three decimals that all have the same number of decimal places (up to thousandths). They regroup across places, including from tenths into ones, and place the decimal point correctly in the answer (e.g. 2.786 + 4.457 = 7.243). Proposed limit: whole-number parts up to hundreds.","question_forms":["vertical addition","horizontal addition","addition using place value apparatus or a chart","missing digit in a sum"],"thinking":["procedure"],"horeb_skill_ids":["G5_DECIMALS_ADD"],"prerequisites":[{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"essential","reason":"Decimal addition uses the same column method with double regrouping.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","kind":"skill","strength":"essential","reason":"Regrouping 10 thousandths as 1 hundredth relies on place value.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_MIXED_PLACES","name":"Add decimals with different numbers of decimal places, including whole numbers, in context","outcomes":["MATH.G5.NUMBER.DECIMALS.c"],"mastery":"The child lines up place values, not end digits, when adding decimals with different numbers of decimal places or a whole number and a decimal (3.5 + 1.25 + 0.075; 6 + 0.25). They solve one- or two-step word problems involving shillings, kilograms, litres or kilometres.","question_forms":["vertical addition with unequal decimal places","whole number plus decimal","word problem: total mass or length","word problem: total cost in shillings","spot the error in a worked sum"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_DECIMALS_ADD"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES","kind":"skill","strength":"essential","reason":"The column procedure must be secure before handling unequal decimal places.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE","kind":"skill","strength":"essential","reason":"Aligning by place, and knowing 6 = 6.000, needs understanding of digit value and zero placeholders.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES","name":"Subtract decimals with the same number of decimal places, with regrouping","outcomes":["MATH.G5.NUMBER.DECIMALS.d"],"mastery":"The child subtracts decimals that have the same number of decimal places (up to thousandths), where the first number is the larger. They regroup correctly, including across zeros and across the decimal point (e.g. 6.003 − 2.145 = 3.858).","question_forms":["vertical subtraction","horizontal subtraction","subtraction using place value apparatus","missing digit in a difference","check by adding"],"thinking":["procedure"],"horeb_skill_ids":["G5_DECIMALS_SUB"],"prerequisites":[{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"essential","reason":"Decimal subtraction uses the same column method with regrouping.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","kind":"skill","strength":"essential","reason":"Exchanging 1 tenth for 10 hundredths relies on place value.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES","kind":"skill","strength":"helpful","reason":"Addition is used to check subtraction and shares the alignment routine.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_MIXED_PLACES","name":"Subtract decimals with different numbers of decimal places, including from whole numbers, in context","outcomes":["MATH.G5.NUMBER.DECIMALS.d"],"mastery":"The child fills empty places with zeros so both numbers have the same number of decimal places, then subtracts (4.5 − 1.237; 7 − 2.45). They solve word problems about change, difference and what remains, in shillings, kilograms, litres or metres.","question_forms":["vertical subtraction with unequal decimal places","whole number minus decimal","word problem: change from a note or coin","word problem: how much more / how much is left","compare and explain (who is taller, by how much?)"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_DECIMALS_SUB"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES","kind":"skill","strength":"essential","reason":"Regrouping must be secure before zeros are inserted and borrowed from.","status":"proposed"},{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE","kind":"skill","strength":"essential","reason":"The child must know that 4.5 = 4.500 and 7 = 7.00 to fill empty places.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000","name":"Multiply decimals (up to thousandths) by 1000","outcomes":["MATH.G5.NUMBER.DECIMALS.e"],"mastery":"The child multiplies any decimal with up to three decimal places by 1000. They understand that each digit moves three places to the left, and they insert zeros where needed (0.375 × 1000 = 375; 3.2 × 1000 = 3200; 0.04 × 1000 = 40). They apply this in real-life situations such as kg to g, km to m and litres to millilitres.","question_forms":["direct calculation × 1000","missing number (□ × 1000 = 2045)","place value chart shift","real-life: convert kg to g, l to ml, km to m","spot the error"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G6_DECIMALS_MUL"],"prerequisites":[{"requires":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","kind":"skill","strength":"essential","reason":"Multiplying by 1000 is understood as each digit moving three places to the left.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.a","kind":"outcome","strength":"helpful","reason":"Multiplying whole numbers by multiples of 10 builds the idea that digits shift place.","status":"proposed"},{"requires":"MATH.G4.NUMBER.WHOLE_NUMBERS.a","kind":"outcome","strength":"helpful","reason":"Reading answers such as 2045 needs whole-number place value up to thousands.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME.M_TENTHS_AS_TENS","skill":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","error":"Gives whole-number place names to decimal places, for example calling the first place after the point 'tens', or thinks there is a 'oneths' place.","example":{"question":"In 4.583, what is the place value of the digit 5?","wrong_answer":"tens","correct_answer":"tenths"},"cause":"Believes place value is symmetrical about the decimal point, or does not hear the '-ths' ending as meaning a part of one.","reveals":"Offer 'tens', 'tenths', 'ones' and 'hundreds' as options for the first digit after the point; choosing 'tens' or 'ones' exposes it.","help":"Use a place value chart with the ones column at the centre and stress the '-ths' ending, contrasting 10 shillings with one tenth of a shilling.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME.M_THOUSANDTH_BIGGER","skill":"MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME","error":"Thinks a thousandth is larger than a tenth because a thousand is larger than ten.","example":{"question":"Which is greater: 3 tenths or 3 thousandths?","wrong_answer":"3 thousandths","correct_answer":"3 tenths (0.3 is greater than 0.003)"},"cause":"Transfers the size of whole numbers to the names of fractional places, without seeing that more equal parts makes each part smaller.","reveals":"A 'which place is worth more?' item comparing tenths and thousandths, with no digits to distract.","help":"Cut a strip or a chapati into 10 and then into 100 pieces so learners see that more pieces means smaller pieces.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE.M_DIGIT_VALUE_AS_WHOLE","skill":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE","error":"Gives the digit itself, or a whole-number value, as the value of a digit after the decimal point.","example":{"question":"What is the value of the digit 8 in 4.583?","wrong_answer":"8 (or 80)","correct_answer":"0.08 (8 hundredths)"},"cause":"Has learnt place names as labels but does not connect them to quantities that are parts of one.","reveals":"Multiple choice with options 8, 80, 0.8 and 0.08 for the underlined digit.","help":"Ask learners to say the value aloud as '8 hundredths' and write it as both 8/100 and 0.08 before moving on.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE.M_MISSING_PLACEHOLDER_ZERO","skill":"MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE","error":"Leaves out zero placeholders when writing a decimal from words or a chart.","example":{"question":"Write 'five and twenty-four thousandths' as a decimal.","wrong_answer":"5.24","correct_answer":"5.024"},"cause":"Writes the digits heard ('twenty-four') straight after the point without checking that the last digit must be in the thousandths place.","reveals":"Dictate decimals whose words skip a place (e.g. 'three and seven hundredths') and check for 3.7 instead of 3.07.","help":"Have learners write the words into a place value chart first, filling every empty column before the last named place with 0.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE.M_LONGER_IS_LARGER","skill":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE","error":"Thinks the decimal with more digits after the point is larger.","example":{"question":"Which is greater: 0.5 or 0.125?","wrong_answer":"0.125","correct_answer":"0.5"},"cause":"Treats the digits after the point as a whole number (125 > 5).","reveals":"Pairs where the shorter decimal is larger (0.5 vs 0.125, 0.8 vs 0.75); learners who always choose the longer one are exposed.","help":"Have learners add zeros to make the same number of decimal places (0.500 vs 0.125) and compare tenths first on a chart.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE.M_SHORTER_IS_LARGER","skill":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE","error":"Thinks the decimal with fewer digits after the point is larger because thousandths are 'tiny'.","example":{"question":"Which is greater: 0.3 or 0.312?","wrong_answer":"0.3, because tenths are bigger than thousandths","correct_answer":"0.312"},"cause":"Partial understanding that later places are smaller, applied to the whole number instead of to each digit.","reveals":"Pairs where the longer decimal begins with the same digits and is larger (0.3 vs 0.312, 1.4 vs 1.45).","help":"Show both on a number line from 0.3 to 0.4 so learners see 0.312 lies just beyond 0.3.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE.M_TRAILING_ZERO_CHANGES_VALUE","skill":"MATH.G5.NUMBER.DECIMALS.DEC_COMPARE","error":"Thinks adding a zero at the end of a decimal makes it larger.","example":{"question":"Insert >, < or =: 0.70 ___ 0.7","wrong_answer":">","correct_answer":"="},"cause":"Applies the whole-number rule that adding a zero on the right multiplies by ten.","reveals":"Include '=' pairs such as 0.70 and 0.7, or 2.500 and 2.5, among comparison items.","help":"Use money: 0.70 of a shilling and 0.7 of a shilling are both 70 cents.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ORDER.M_IGNORES_WHOLE_PART","skill":"MATH.G5.NUMBER.DECIMALS.DEC_ORDER","error":"Orders decimals by the digits after the point only, ignoring the whole-number part.","example":{"question":"Arrange from smallest to largest: 2.05, 1.9, 1.875","wrong_answer":"2.05, 1.9, 1.875","correct_answer":"1.875, 1.9, 2.05"},"cause":"Focuses on the decimal digits as the 'hard part', or reads them as whole numbers (5 < 9 < 875).","reveals":"Sets where the whole-number parts differ and the decimal parts point the opposite way.","help":"Teach a fixed routine: compare whole numbers first, then tenths, then hundredths, then thousandths, using a chart.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ORDER.M_WHOLE_NUMBER_SMALLEST","skill":"MATH.G5.NUMBER.DECIMALS.DEC_ORDER","error":"Puts a whole number first when ordering from smallest because it has fewer digits.","example":{"question":"Arrange from smallest to largest: 3, 2.875, 2.95","wrong_answer":"3, 2.875, 2.95","correct_answer":"2.875, 2.95, 3"},"cause":"Judges size by how many digits are written, not by place value.","reveals":"Include a whole number in a set of decimals just below it.","help":"Rewrite the whole number with zeros (3.000) and place all numbers on a number line from 2 to 3.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES.M_ADD_PARTS_SEPARATELY","skill":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES","error":"Adds the whole parts and the decimal parts as separate whole numbers, without regrouping into the ones.","example":{"question":"2.7 + 1.5 =","wrong_answer":"3.12","correct_answer":"4.2"},"cause":"Sees the decimal point as a separator between two whole numbers, not as part of one place value system.","reveals":"Items where the tenths add to 10 or more, with 3.12 offered as a distractor.","help":"Model with place value apparatus or coins that 12 tenths must be exchanged for 1 one and 2 tenths.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES.M_POINT_DROPPED","skill":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_SAME_PLACES","error":"Leaves out or misplaces the decimal point in the answer.","example":{"question":"4.236 + 1.152 =","wrong_answer":"5388","correct_answer":"5.388"},"cause":"Treats the sum as a whole-number calculation and forgets that the point stays in line.","reveals":"Estimate-check items: 'Is the answer about 5 or about 5000?'","help":"Ask learners to write the point in the answer row first, then estimate (4 + 1 is about 5) to check.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_MIXED_PLACES.M_RIGHT_ALIGN_DIGITS","skill":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_MIXED_PLACES","error":"Lines up the last digits on the right, as with whole numbers, instead of lining up the decimal points.","example":{"question":"Wanjiru bought 3.5 kg of sukuma wiki and 1.25 kg of tomatoes. What is the total mass?","wrong_answer":"1.60 kg","correct_answer":"4.75 kg"},"cause":"Over-applies the whole-number habit of right-aligning columns.","reveals":"Addends with different numbers of decimal places, set horizontally so the learner must arrange the columns.","help":"Have learners write 3.50 so both numbers have the same decimal places, and line up the points down the page.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_MIXED_PLACES.M_WHOLE_AS_DECIMAL_DIGITS","skill":"MATH.G5.NUMBER.DECIMALS.DEC_ADD_MIXED_PLACES","error":"When adding a whole number to a decimal, places the whole number under the decimal digits.","example":{"question":"6 + 0.25 =","wrong_answer":"0.31","correct_answer":"6.25"},"cause":"Does not know that a whole number has an unwritten decimal point after its last digit.","reveals":"Whole number plus decimal items with distractors such as 0.31 or 0.85.","help":"Have learners rewrite whole numbers with a point and zeros (6 = 6.00) before adding.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES.M_SMALLER_FROM_LARGER","skill":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES","error":"In each column, subtracts the smaller digit from the larger whichever number it belongs to, so no regrouping happens.","example":{"question":"5.42 − 2.68 =","wrong_answer":"3.26","correct_answer":"2.74"},"cause":"Believes you 'cannot take a bigger number from a smaller one', carried over from whole-number subtraction.","reveals":"Items needing regrouping in several columns; checking by adding (3.26 + 2.68 ≠ 5.42) exposes the error.","help":"Use place value apparatus to exchange 1 tenth for 10 hundredths, and always check by adding back.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES.M_REGROUP_ACROSS_ZERO","skill":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES","error":"When regrouping across zeros, borrows straight from the ones but does not change the zeros in between.","example":{"question":"6.003 − 2.145 =","wrong_answer":"4.968","correct_answer":"3.858"},"cause":"Does not see that 6 ones must become 5 ones, 9 tenths, 9 hundredths and 10 thousandths.","reveals":"Items with zeros in the first number (6.003, 4.008) where regrouping must pass through them.","help":"Model exchanging one coin step by step down each column with apparatus before using the written method.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_MIXED_PLACES.M_BRING_DOWN_DIGITS","skill":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_MIXED_PLACES","error":"When the second number has more decimal places, brings its extra digits straight down into the answer instead of subtracting them from zeros.","example":{"question":"4.5 − 1.237 =","wrong_answer":"3.337","correct_answer":"3.263"},"cause":"Treats empty places as 'nothing to do', not as zeros to subtract from.","reveals":"Items where the first number has fewer decimal places than the second.","help":"Have learners fill empty places with zeros (4.500) before subtracting, then check by adding.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_MIXED_PLACES.M_WHOLE_MINUS_DECIMAL","skill":"MATH.G5.NUMBER.DECIMALS.DEC_SUB_MIXED_PLACES","error":"When subtracting a decimal from a whole number, subtracts only the whole parts and copies the decimal part.","example":{"question":"Otieno had 7 litres of milk and sold 2.45 litres. How much is left?","wrong_answer":"5.45 litres","correct_answer":"4.55 litres"},"cause":"Does not see that 7 = 7.00, so there are tenths and hundredths to take from.","reveals":"Change and 'how much is left' problems from a whole amount, with the copied-decimal distractor offered.","help":"Use a change context (Sh 7.00 minus Sh 2.45) and have learners write 7.00 first.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000.M_ANNEX_ZEROS","skill":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000","error":"Writes three zeros on the end of the decimal instead of moving the digits.","example":{"question":"2.45 × 1000 =","wrong_answer":"2.45000","correct_answer":"2450"},"cause":"Over-applies the whole-number rule 'to multiply by 1000, add three zeros'.","reveals":"Offer 2.45000 as a distractor and ask whether it is bigger than 2.45.","help":"Show on a place value chart that each digit moves three places to the left, and ask whether the answer should be bigger.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000.M_WRONG_NUMBER_OF_PLACES","skill":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000","error":"Moves the digits the wrong number of places, often two.","example":{"question":"0.375 × 1000 =","wrong_answer":"37.5","correct_answer":"375"},"cause":"Confuses multiplying by 100 with multiplying by 1000, or counts places loosely.","reveals":"Mix × 1000 items with answers from moving one, two and three places as options.","help":"Link to the three zeros in 1000 and have learners move one place per zero on the chart.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000.M_NO_ZERO_FILL","skill":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000","error":"Moves the point to the end of the digits and stops, without filling empty places with zeros.","example":{"question":"A bag holds 3.2 kg of rice. How many grams is that? (3.2 × 1000)","wrong_answer":"32 g","correct_answer":"3200 g"},"cause":"Thinks 'multiplying by 1000 removes the point' rather than shifting digits three places.","reveals":"Decimals with only one or two decimal places (3.2, 0.04) multiplied by 1000.","help":"Have learners count three jumps of the point, writing a 0 in each empty place.","status":"draft"},{"code":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000.M_MOVES_WRONG_WAY","skill":"MATH.G5.NUMBER.DECIMALS.DEC_MULT_1000","error":"Moves the digits to the right, making the number smaller.","example":{"question":"4.6 × 1000 =","wrong_answer":"0.0046","correct_answer":"4600"},"cause":"Learnt 'move the point three places' as a rule without a sense of whether the answer should grow.","reveals":"Ask learners to estimate first: should 4.6 × 1000 be more or less than 4.6?","help":"Always start with an estimate, e.g. 4.6 kg is more than 4000 g, so the answer must be in the thousands.","status":"draft"}]},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS","number":"1.8","strand":"Numbers","sub_strand":"Simple Equations","sequence":108,"lessons":6,"content_topics":["Forming and solving simple equations"],"learning_experiences":["discuss and come up with equations with one unknown from daily experiences","use real objects to form equations with one unknown","team up with peers to solve equations with one unknown","use digital devices or other resources to learn more about equations. Experiences"],"key_inquiry_questions":["Where are equations used in real life?"],"core_competences":"● Critical thinking and problem solving: learner forms and solves equations with one unknown. ● Digital literacy: learner uses digital devices or other resources to learn more about equations with one unknown.","values":"Peace: learner harmoniously teams up with peers to solve equations with one unknown.","pcis":"Safety: learner carefully collects safe concrete objects from the environment to illustrate the formation of simple equations with one unknown.","links":"The learner is able to relate the concept of equations with one unknown to the concept of marketing goods in Pre-technical Studies.","design_notes":"1) Outcome c ('appreciate use of equations in solving problems in real life') is attitudinal. It is not mapped to a skill and is best evidenced through observation, e.g. learners posing their own equations from home or market situations, which also links to the key inquiry question 'Where are equations used in real life?'. 2) The design gives no number limits, no list of equation forms and no statement about whether fractions or decimals may appear. All limits given here are proposed: whole numbers within Grade 4 operation ranges, whole-number solutions, and one-step equations as the core. 3) Whether two-step equations (ax + b = c) are in scope is unclear. With only 6 suggested lessons, the core is probably one-step. G5_EQ_TWO_STEP is offered as a proposed extension and should be confirmed against approved textbooks before it is assessed as core. 4) 'Simple equations' is not defined in the design. I have taken it to mean linear equations in one unknown with the unknown appearing once. 5) The learning experience 'use digital devices or other resources to learn more about equations' is a resource activity, not a separate assessable skill. 6) The input texts contain extraction artefacts ('... equations. Experiences' and '... real life? Inquiry Question(s)'); these words are headings, not part of the official text. 7) The Grade 6 outcomes supplied contain no equations sub-strand, only Inequalities (1.6a–c), which builds directly on this work. The HOREB skill G6_SIMPLE_EQUATIONS (x + a = b) does not match any supplied Grade 6 outcome, and its scope looks narrower than Grade 5 1.8. The mapping should be reviewed; it may belong at Grade 5. 8) G5_MISSING_NUMBER overlaps G5_EQ_MEANING and the solving skills (box notation as an early form of the unknown). 9) Grade 4 prerequisites rely on 1.8a–c (Use of letters) and the four operations. The addition–subtraction inverse relationship has no explicit Grade 4 outcome; only multiplication and division (1.5b) do.","outcomes":[{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.a","letter":"a","text":"form simple equations with one unknown involving real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.b","letter":"b","text":"solve simple equations with one unknown involving real-life situations","status":"kicd_verified"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.c","letter":"c","text":"appreciate use of equations in solving problems in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","name":"Understand what an equation is (equals sign as balance, letter as an unknown number)","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.a"],"mastery":"The child can tell an equation (e.g. x + 5 = 12) from an expression (e.g. x + 5). They read '=' as 'has the same value as', can say whether a number statement such as 8 + 4 = 7 + 5 is true, and can explain that a letter stands for an unknown number (a quantity), not an object. Proposed limit: whole numbers, one letter, one operation on each side.","question_forms":["pick the equation from a list (equation vs expression)","true or false number sentence (e.g. 8 + 4 = 7 + 5)","missing number on either side of '='","balance scale picture: say what the letter stands for","explain what the letter means in a context"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_MISSING_NUMBER","G5_SIMPLE_EQUATIONS"],"prerequisites":[{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.a","kind":"outcome","strength":"essential","reason":"Children must already accept that a letter can represent information or an unknown quantity.","status":"proposed"},{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.b","kind":"outcome","strength":"helpful","reason":"Knowing what an expression is makes it possible to see that an equation is two equal expressions.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB","name":"Form a one-step equation involving addition or subtraction from a real-life situation","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.a"],"mastery":"Given a short everyday situation (money in shillings, passengers in a matatu, eggs, ages), real objects or a picture, the child chooses a letter for the unknown and writes a correct equation of the form x + a = b, x − a = b or a − x = b. The order is right in subtraction. Proposed limit: whole numbers within the Grade 4 range (sums up to 10,000), with one unknown.","question_forms":["word problem: some, then more (x + a = b)","word problem: some, then spent or removed (x − a = b)","word problem: comparison 'more than' or 'less than'","match a story to its equation (multiple choice)","real objects or picture: write the equation shown","write a story for a given equation"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_SIMPLE_EQUATIONS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","kind":"skill","strength":"essential","reason":"Forming an equation needs a clear idea of the letter as an unknown number and of '=' as balance.","status":"proposed"},{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.b","kind":"outcome","strength":"essential","reason":"Writing x + 5 or x − 50 from a story is the Grade 4 expression skill, which the equation extends.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV","name":"Form a one-step equation involving multiplication or division from a real-life situation","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.a"],"mastery":"Given an everyday situation about equal groups, cost of several identical items, 'times as many' or equal sharing, the child writes a correct equation of the form ax = b (written as 3x or 3 × x) or x ÷ a = b. The order is right in division. Proposed limit: whole numbers, multipliers and divisors up to 2 digits (in line with G4:1.4b and 1.5a), and whole-number unknowns.","question_forms":["word problem: cost of several identical items (3p = 45)","word problem: 'times as many'","word problem: equal sharing (x ÷ 5 = 6)","match a story to its equation (multiple choice)","real objects or groups: write the equation shown","write a story for a given equation"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_SIMPLE_EQUATIONS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","kind":"skill","strength":"essential","reason":"Forming an equation needs a clear idea of the letter as an unknown number and of '=' as balance.","status":"proposed"},{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.b","kind":"outcome","strength":"essential","reason":"Expressions such as 3p for the cost of 3 items are the building blocks of these equations.","status":"proposed"},{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.c","kind":"outcome","strength":"helpful","reason":"Simplifying p + p + p to 3p supports writing 3p = 45 from a repeated-cost story.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.b","kind":"outcome","strength":"helpful","reason":"Seeing sharing and grouping as related helps the child choose between multiplication and division.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB","name":"Solve one-step equations involving addition or subtraction","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.b"],"mastery":"The child solves x + a = b, a + x = b, x − a = b and a − x = b by using the inverse operation, or by balancing (doing the same to both sides). They check the answer by putting it back into the equation. Proposed limit: whole numbers, sums up to 10,000, whole-number solutions.","question_forms":["solve: x + a = b","solve: x − a = b","solve: a − x = b (unknown subtracted)","check whether a given value is the solution","find the error in a worked solution"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_SIMPLE_EQUATIONS","G5_MISSING_NUMBER","G6_SIMPLE_EQUATIONS","G5_ADDITION","G5_SUBTRACTION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","kind":"skill","strength":"essential","reason":"Balancing or undoing only makes sense if '=' is understood as equal value on both sides.","status":"proposed"},{"requires":"MATH.G4.NUMBER.ADDITION.b","kind":"outcome","strength":"essential","reason":"Solving x − a = b requires adding, often with regrouping.","status":"proposed"},{"requires":"MATH.G4.NUMBER.SUBTRACTION.b","kind":"outcome","strength":"essential","reason":"Solving x + a = b requires subtracting, often with regrouping.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV","name":"Solve one-step equations involving multiplication or division","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.b"],"mastery":"The child solves ax = b, x ÷ a = b and a ÷ x = b by using the inverse operation or by balancing. They know that 3x means 3 × x, and they check by substitution. Proposed limit: whole numbers, divisors up to 2 digits, exact (no-remainder) whole-number solutions.","question_forms":["solve: ax = b","solve: x ÷ a = b","solve: a ÷ x = b (unknown divisor)","check whether a given value is the solution","find the error in a worked solution"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_SIMPLE_EQUATIONS","G5_MISSING_NUMBER","G5_MULTIPLICATION","G5_DIVISION"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","kind":"skill","strength":"essential","reason":"Balancing or undoing only makes sense if '=' is understood as equal value on both sides.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.b","kind":"outcome","strength":"essential","reason":"Undoing multiplication with division, and the reverse, depends on knowing they are inverse operations.","status":"proposed"},{"requires":"MATH.G4.NUMBER.MULTIPLICATION.b","kind":"outcome","strength":"essential","reason":"Solving x ÷ a = b requires multiplying, up to 2-digit by 2-digit.","status":"proposed"},{"requires":"MATH.G4.NUMBER.DIVISION.a","kind":"outcome","strength":"essential","reason":"Solving ax = b requires dividing accurately.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_IN_CONTEXT","name":"Form and solve an equation to answer a real-life problem, then interpret and check","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.a","MATH.G5.NUMBER.SIMPLE_EQUATIONS.b"],"mastery":"From a real-life word problem, the child forms the equation, solves it, states the answer in words with the correct unit (e.g. 'Each bunch of sukuma wiki costs sh 30'), and checks that the answer makes sense in the story. Proposed limit: one-step equations with whole numbers, as in the two solving skills.","question_forms":["word problem: form, solve and state the answer with units","word problem: shopping in shillings","word problem: ages or measurements","is this answer reasonable? (check against the story)","pose own problem from daily life and solve it"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G5_SIMPLE_EQUATIONS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB","kind":"skill","strength":"essential","reason":"The child must first turn the story into an equation.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV","kind":"skill","strength":"essential","reason":"Many real-life problems (shopping, sharing) give multiplication or division equations.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB","kind":"skill","strength":"essential","reason":"The equation formed must then be solved.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV","kind":"skill","strength":"essential","reason":"The equation formed must then be solved.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_TWO_STEP","name":"Form and solve two-step equations of the form ax + b = c or ax − b = c (proposed extension)","outcomes":["MATH.G5.NUMBER.SIMPLE_EQUATIONS.a","MATH.G5.NUMBER.SIMPLE_EQUATIONS.b"],"mastery":"Proposed extension, not stated in the design. The child forms and solves equations such as 2x + 6 = 20 from situations like '2 pens and a sh 6 sweet cost sh 20'. They undo the addition or subtraction first, then the multiplication. Proposed limit: small whole numbers, coefficient up to 10, whole-number solutions.","question_forms":["solve: ax + b = c","solve: ax − b = c","word problem: several identical items plus a fixed cost","find the error in a worked solution"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_SIMPLE_EQUATIONS"],"prerequisites":[{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB","kind":"skill","strength":"essential","reason":"The first step undoes an addition or subtraction.","status":"proposed"},{"requires":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV","kind":"skill","strength":"essential","reason":"The second step undoes a multiplication.","status":"proposed"},{"requires":"MATH.G4.NUMBER.USE_OF_LETTERS.c","kind":"outcome","strength":"helpful","reason":"Knowing that 2x and 6 are unlike terms prevents wrongly combining them into 8x.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING.M_EQUALS_MEANS_ANSWER","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","error":"Reads '=' as 'now write the answer' and works left to right, ignoring what comes after the sign.","example":{"question":"Fill in the box: 8 + 4 = □ + 5","wrong_answer":"12 (or 17)","correct_answer":"7"},"cause":"Years of sums of the form 'a + b = □' have taught that '=' signals the result of an operation, not equal value on both sides.","reveals":"Put the box or the operation on the right of '=', and include 12 and 17 as distractors.","help":"Use a balance scale or bundles of sticks and ask 'Is it the same on both sides?' Regularly write equations such as 12 = 7 + 5 with the operation on the right.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING.M_LETTER_AS_OBJECT","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","error":"Thinks a letter stands for an object or a word (p = pen) instead of a number such as the cost or the count.","example":{"question":"A pen costs p shillings. What does p stand for?","wrong_answer":"a pen","correct_answer":"the cost of one pen in shillings (a number)"},"cause":"Letters are used as abbreviations elsewhere (kg, m, sh), so the child treats a letter as a label rather than as an unknown number.","reveals":"Ask what the letter stands for, with options 'a pen', 'pens' and 'the number of shillings one pen costs'.","help":"Always define letters in full, e.g. 'Let p be the number of shillings one pen costs', and ask learners to say the definition aloud.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING.M_EXPRESSION_IS_EQUATION","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING","error":"Calls an expression such as x + 7 an equation, or does not see that an equation must contain '=' with two equal sides.","example":{"question":"Which is an equation? A: x + 7   B: x + 7 = 15   C: 15","wrong_answer":"A","correct_answer":"B"},"cause":"The Grade 4 work on expressions and this Grade 5 work both use letters, so any letter-and-number string is seen as 'algebra' or 'an equation'.","reveals":"A sorting task mixing expressions, equations and plain numbers.","help":"Contrast pairs side by side: 'x + 7' (a description you cannot solve) and 'x + 7 = 15' (a balance you can solve).","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB.M_SUBTRACTION_ORDER_REVERSED","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB","error":"Writes the subtraction in the order the numbers appear, not in the order of the action.","example":{"question":"Njeri had some shillings. She spent sh 50 on mandazi and was left with sh 120. Let n be the number of shillings she had. Write an equation.","wrong_answer":"50 − n = 120","correct_answer":"n − 50 = 120"},"cause":"The child treats subtraction as commutative, or copies the numbers in story order without modelling 'start amount minus amount spent'.","reveals":"A multiple-choice item with both orders offered, or asking the learner to test their equation with a sensible value.","help":"Act the story out with real coins: start with an unknown pile, take 50 away, and write the equation in the order the actions happened.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB.M_KEYWORD_MORE_MEANS_ADD","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB","error":"Sees 'more' and adds the given numbers, or writes the opposite operation, instead of modelling the comparison.","example":{"question":"Otieno has 15 eggs. That is 6 more than Akinyi has. Let a be the number of eggs Akinyi has. Write an equation.","wrong_answer":"a − 6 = 15 (or a = 15 + 6)","correct_answer":"a + 6 = 15 (so a = 9)"},"cause":"Reliance on key words ('more' means add) rather than on the relationship between the two quantities.","reveals":"Comparison stories where the key word points to the wrong operation, with a − 6 = 15 and 15 + 6 = a as distractors.","help":"Draw a bar model with Akinyi's bar plus 6 matching Otieno's 15, and ask 'Who has more?' before writing anything.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB.M_WRITES_ANSWER_NOT_EQUATION","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB","error":"Works out the answer mentally and writes only 'p = 11' when asked to form the equation.","example":{"question":"A matatu had some passengers. At Kisumu 7 more got in, making 18. Let p be the number of passengers at first. Form an equation.","wrong_answer":"p = 11","correct_answer":"p + 7 = 18"},"cause":"The child sees the equation as an extra step with no purpose and jumps to the arithmetic, so they do not separate modelling from solving.","reveals":"Ask only for the equation, or use numbers large enough that mental shortcuts fail (e.g. p + 1,375 = 4,020).","help":"Mark forming and solving as separate steps, and explain that the equation is a record of the story that anyone can check.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV.M_TIMES_AS_MANY_REVERSED","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV","error":"Puts the multiplier on the wrong quantity in a 'times as many' statement.","example":{"question":"A farmer in Nakuru has 4 times as many goats as cows. He has 24 goats. Let c be the number of cows. Write an equation.","wrong_answer":"c = 4 × 24","correct_answer":"4c = 24 (so c = 6)"},"cause":"The child translates the words in order ('4 times … goats') instead of asking which group is bigger.","reveals":"Offer c = 4 × 24 as a distractor, and ask whether the farmer then has more cows than goats.","help":"Before writing, ask 'Which is more, cows or goats?' and check that the equation makes the larger group bigger.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV.M_SHARING_ORDER_REVERSED","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV","error":"Writes the divisor first in an equal-sharing equation.","example":{"question":"Mama bought x oranges and shared them equally among 5 children. Each child got 6. Write an equation.","wrong_answer":"5 ÷ x = 6","correct_answer":"x ÷ 5 = 6 (so x = 30)"},"cause":"The child believes division can be written in any order, as with multiplication.","reveals":"Multiple choice with both orders offered; or ask the learner to share 30 counters and see which equation fits.","help":"Model with counters: the total being shared always comes first, before the ÷ sign.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV.M_REPEATED_COST_AS_ADD","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_MUL_DIV","error":"Writes 3 + b instead of 3b (3 × b) for the cost of 3 identical items.","example":{"question":"3 exercise books each cost b shillings. Together they cost sh 45. Write an equation.","wrong_answer":"3 + b = 45","correct_answer":"3b = 45 (or b + b + b = 45)"},"cause":"The child joins the numbers in the story with the most familiar operation and does not see the equal groups.","reveals":"A distractor 3 + b = 45; or ask the learner to substitute b = 15 into their equation and check against the story.","help":"Write b + b + b = 45 first, then show that this is the same as 3b, linking back to simplifying expressions in Grade 4.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB.M_SAME_OPERATION_NOT_INVERSE","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB","error":"Applies the operation that is in the equation instead of its inverse.","example":{"question":"Solve x + 15 = 40","wrong_answer":"x = 55","correct_answer":"x = 25"},"cause":"The child sees '+' and adds the two numbers, so they do not think of 'undoing'.","reveals":"The distractor 55; asking the learner to substitute shows 55 + 15 ≠ 40.","help":"Make checking by substitution a required last line, and use a balance picture: take 15 off both sides.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB.M_SUBTRACTS_FOR_X_MINUS","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB","error":"For x − a = b, subtracts the smaller number from the larger instead of adding.","example":{"question":"Solve x − 18 = 30","wrong_answer":"x = 12","correct_answer":"x = 48"},"cause":"The child sees '−' and subtracts, or always takes the smaller number from the larger.","reveals":"The distractor 12; substituting gives 12 − 18, which cannot equal 30.","help":"Tell the story aloud ('I had some, gave away 18, have 30 left; did I start with more or less than 30?') before calculating.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB.M_UNKNOWN_SUBTRACTED_TREATED_AS_X_MINUS","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_ADD_SUB","error":"Solves a − x = b by adding, as if it were x − a = b.","example":{"question":"Solve 50 − x = 20","wrong_answer":"x = 70","correct_answer":"x = 30"},"cause":"The child overgeneralises a learned rule ('minus becomes plus') without noticing where the unknown sits.","reveals":"Mix a − x = b items in with x − a = b items, and include a + b as a distractor.","help":"Read 50 − x = 20 as 'What must I take from 50 to leave 20?' and check by substitution.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV.M_MULTIPLIES_FOR_AX","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV","error":"Multiplies the two numbers when solving ax = b.","example":{"question":"Solve 4x = 28","wrong_answer":"x = 112","correct_answer":"x = 7"},"cause":"The child sees multiplication in the equation and repeats it instead of undoing it.","reveals":"The distractor 112; asking whether 4 groups of 112 make 28.","help":"Read 4x = 28 as '4 groups of what make 28?', and connect it to the multiplication–division family 4 × 7 = 28, 28 ÷ 4 = 7.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV.M_3X_AS_TWO_DIGIT_NUMBER","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV","error":"Reads 3x as a two-digit number 'thirty-something' and fills in a digit.","example":{"question":"Solve 3x = 36","wrong_answer":"x = 6","correct_answer":"x = 12"},"cause":"Place-value habits: in arithmetic, writing digits side by side means tens and ones, not multiplication.","reveals":"Items where the digit pattern gives a plausible but wrong answer (3x = 36, 2x = 24, 4x = 48).","help":"Write 3 × x alongside 3x until learners say '3 times x' automatically, and check that 3 × 6 = 18, not 36.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV.M_DIVIDES_FOR_X_DIV","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_MUL_DIV","error":"For x ÷ a = b, divides b by a (or subtracts) instead of multiplying.","example":{"question":"Solve x ÷ 5 = 8","wrong_answer":"1 remainder 3 (or 3)","correct_answer":"x = 40"},"cause":"The child applies the operation they can see, or does not understand that the total being shared must be the biggest number.","reveals":"Remainder-type or subtraction-type distractors; substitution shows that 3 ÷ 5 is not 8.","help":"Use the sharing story ('shared among 5, each got 8, so how many were there altogether?') with counters.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_IN_CONTEXT.M_NUMBERS_IN_STORY_ORDER","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_IN_CONTEXT","error":"Operates on the numbers in the order they appear, following a key word, without modelling the situation.","example":{"question":"A matatu had some passengers. At Kisumu 6 got off and 9 remained. How many were in the matatu at first?","wrong_answer":"3","correct_answer":"15 (p − 6 = 9, p = 15)"},"cause":"The child reads 'got off' as 'subtract' and subtracts the smaller number from the larger, skipping the equation.","reveals":"Stories where the key word suggests the wrong operation, with that answer as a distractor.","help":"Insist on writing the equation from the story first, then ask 'Should the starting number be more or less than 9?'","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_IN_CONTEXT.M_NO_REASONABLENESS_CHECK","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_SOLVE_IN_CONTEXT","error":"Accepts an answer that does not make sense in the story because they never check it against the context.","example":{"question":"5 bunches of sukuma wiki cost sh 150. How much does one bunch cost?","wrong_answer":"sh 750","correct_answer":"sh 30 (5s = 150, s = 30)"},"cause":"The child sees solving as symbol-pushing, separate from the real situation, and does not interpret the result.","reveals":"Ask 'Is this answer reasonable? Why?', or offer sh 750 as a distractor.","help":"End every problem with a sentence answer and the question 'Does one bunch cost less than five bunches?'","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_TWO_STEP.M_UNDOES_IN_WRONG_ORDER","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_TWO_STEP","error":"Divides first and then subtracts, undoing the operations in the wrong order.","example":{"question":"Solve 2x + 6 = 20","wrong_answer":"x = 4 (20 ÷ 2 = 10, then 10 − 6 = 4)","correct_answer":"x = 7 (2x = 14, x = 7)"},"cause":"The child divides only part of the left side, not seeing that both 2x and 6 make up the 20.","reveals":"The distractor 4; substitution gives 2 × 4 + 6 = 14, not 20.","help":"Use a balance or parcel model: first remove the loose sh 6 from both sides, then share what is left into 2 equal parts.","status":"draft"},{"code":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_TWO_STEP.M_COMBINES_UNLIKE_TERMS","skill":"MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_TWO_STEP","error":"Joins 2x + 6 into 8x before solving.","example":{"question":"Solve 2x + 6 = 20","wrong_answer":"8x = 20, so x is about 2","correct_answer":"x = 7"},"cause":"The child wants a single-term answer and does not understand that letter terms and number terms are unlike.","reveals":"A worked solution showing 8x = 20 for learners to judge; or an open item where 8x appears in working.","help":"Revisit Grade 4 simplifying with objects: 2 pens and 6 shillings cannot become 8 pens.","status":"draft"}]},{"code":"MATH.G5.MEASUR.LENGTH","number":"2.1","strand":"Measurement","sub_strand":"Length","sequence":201,"lessons":12,"content_topics":["kilometre (km) as a unit of measuring length","Conversions of Kms and metres","Operations of length"],"learning_experiences":["discuss the kilometre as a unit of measuring length real life","team up with peers to estimate distance in kilometres","work with peers to establish the relationship between the kilometre and metre","express the distance from kilometres to metres and metres to kilometres","carry out addition involving distance in kilometres and metres","carry out subtraction involving distance in kilometres and metres","carry out multiplication involving distance in kilometres and metres","carry out division involving distance in kilometres and metres","use digital devices or other resources to get more information involving length in kilometres and metres"],"key_inquiry_questions":["How can you measure distance?","Why should you measure distance?"],"core_competences":"● Creativity and Imagination: learner measures distance estimated and compare findings with peers. ● Critical thinking and problem solving: learner establishes the relationship between the kilometre and metre practically.","values":"● Integrity: learner measures and honestly records estimated distances practically using ropes and other learning materials. ● Respect: learner takes turn in measuring distance in kilometres practically using ropes.","pcis":"Safety: learner observes safety precautions while handling measuring instruments.","links":"The learner is able to relate measurement of length to construction a food preservation equipment in Agriculture.","design_notes":"Outcome i ('appreciate the use of kilometres and metres in measuring length in real life') is attitudinal, so it has no skill. It can be observed through the learning experience of using digital devices or other resources (for example map apps or road distance charts) to find distances. The outcomes give no number limits, so all limits stated under what_mastery_looks_like are proposed professional judgement, not KICD wording. The design does not say whether decimal kilometres (e.g. 2.5 km) are expected. Answers have been kept in 'km and m' form to match the outcome wording, with ½ km and ¼ km included as a proposed bridge to fractions. Outcome d covers both directions of conversion, so it is split into two skills because the errors differ. Outcomes e to h say 'in real life situations', so each skill includes word problems; choosing the correct operation is assessed within those skills, not as a separate skill. The estimation outcome (b) gives no expected accuracy; a proposed standard is 'a sensible order of magnitude, refined after checking'. In the input, the second key inquiry question contains a stray fragment ('Inquiry Question(s)'), which appears to be an extraction artefact, and the content topics use 'Kms' informally. On HOREB links, all skills map to the broad G5_LENGTH skill; G4_LENGTH is named 'km, m, cm' although the Grade 4 outcomes cover only cm and m, so that existing skill may overstate Grade 4 content. G6_UNIT_CONVERSIONS overlaps the conversion skills. Grade 6 Length moves to mm and cm with the same operations pattern, so these Grade 5 skills are the template for it.","outcomes":[{"code":"MATH.G5.MEASUR.LENGTH.a","letter":"a","text":"identify the kilometre (km) as a unit of measuring length in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.b","letter":"b","text":"estimate distance in kilometres in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.c","letter":"c","text":"identify the relationship between the kilometre (km) and the metre (m) in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.d","letter":"d","text":"convert kilometres to metres and metres to kilometres in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.e","letter":"e","text":"add metres and kilometres in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.f","letter":"f","text":"subtract metres and kilometres in real life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.g","letter":"g","text":"multiply metres and kilometres by whole numbers in real life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.h","letter":"h","text":"divide metres and kilometres by whole numbers in real life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.LENGTH.i","letter":"i","text":"appreciate the use of kilometres and metres in measuring length in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT","name":"Recognise the kilometre as the unit for long distances","outcomes":["MATH.G5.MEASUR.LENGTH.a"],"mastery":"The child names and writes the kilometre and its symbol (km). They choose km rather than m or cm for long real-life distances, such as between towns, along a road or a marathon route, and choose m or cm for short lengths. They can give at least two everyday places where km is used, such as road signs, matatu fares by distance, athletics races and maps.","question_forms":["choose the best unit (km, m or cm) for a given length","sort items into 'measured in km' and 'measured in m'","where in real life do we see km? (road signs, maps)","read and interpret a distance written on a road sign"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_LENGTH"],"prerequisites":[{"requires":"MATH.G4.MEASUR.LENGTH.c","kind":"outcome","strength":"essential","reason":"The child needs a secure sense of the metre to see why a much larger unit is needed for long distances.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.a","kind":"outcome","strength":"helpful","reason":"Experience of choosing cm for small lengths supports choosing the right unit for the size of the thing measured.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.KM_ESTIMATE_DISTANCE","name":"Estimate distances in kilometres","outcomes":["MATH.G5.MEASUR.LENGTH.b"],"mastery":"The child gives a sensible whole-number estimate in km for familiar real-life distances, such as home to school, school to the nearest market or town, or a walking route. They use benchmarks, for example that a walk of about 10 to 15 minutes covers roughly 1 km, or 2½ laps of a 400 m track. They can then check the estimate against a measured or given distance (proposed: estimates in whole km, for distances up to a few tens of km for local places).","question_forms":["estimate then check against a given distance","choose the most reasonable estimate (multiple choice with unrealistic options)","use a benchmark (walking time, track laps) to estimate","compare two estimated distances: which place is further?"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_LENGTH"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT","kind":"skill","strength":"essential","reason":"The child must know what a kilometre is before estimating in it.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"helpful","reason":"Practical measuring builds the length sense that estimation depends on.","status":"proposed"},{"requires":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP","kind":"skill","strength":"helpful","reason":"Knowing 1 km = 1 000 m lets the child build benchmarks from known metre distances such as track laps.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP","name":"Know and use 1 km = 1 000 m, including comparing distances","outcomes":["MATH.G5.MEASUR.LENGTH.c"],"mastery":"The child states that 1 km = 1 000 m and explains it from practical experience, for example 10 lengths of 100 m or 2½ laps of a 400 m track. They use the relationship to compare and order distances given in km and m, such as 2 km and 1 500 m, or 3 km 50 m and 3 500 m. They also use simple fractions of a kilometre, such as ½ km = 500 m and ¼ km = 250 m.","question_forms":["complete: 1 km = ___ m","how many 100 m (or 200 m, 250 m, 500 m) lengths make 1 km?","compare and explain: which is longer?","order distances given in mixed units","half and quarter of a kilometre in metres"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_LENGTH","G4_LENGTH"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT","kind":"skill","strength":"essential","reason":"The relationship is about a unit the child must first recognise.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.c","kind":"outcome","strength":"essential","reason":"The m–cm relationship is the model for a larger-unit/smaller-unit relationship, though the factor differs (100 versus 1 000).","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M","name":"Convert kilometres (and km with m) to metres","outcomes":["MATH.G5.MEASUR.LENGTH.d"],"mastery":"The child converts whole kilometres to metres, such as 7 km = 7 000 m. They also convert mixed measures to metres, including those needing placeholder zeros, such as 3 km 45 m = 3 045 m and 2 km 5 m = 2 005 m (proposed limit: whole numbers of km up to 3 digits, metres 0 to 999; decimal km not required).","question_forms":["convert whole km to m","convert km and m to m (including placeholder zeros)","missing number: 4 km ___ m = 4 070 m","word problem: express a journey's length in metres"],"thinking":["procedure"],"horeb_skill_ids":["G5_LENGTH","G6_UNIT_CONVERSIONS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP","kind":"skill","strength":"essential","reason":"Converting applies 1 km = 1 000 m.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"The m-to-cm conversion procedure is the same structure with a different factor.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM","name":"Convert metres to kilometres (and km with m)","outcomes":["MATH.G5.MEASUR.LENGTH.d"],"mastery":"The child converts exact thousands of metres to km, such as 6 000 m = 6 km. They also convert other metre values to km and m, such as 4 050 m = 4 km 50 m and 12 300 m = 12 km 300 m, by splitting off thousands (proposed limit: up to 5-digit metre values; answers in km and m, not decimals).","question_forms":["convert exact thousands of m to km","express m as km and m","missing number: 5 208 m = ___ km ___ m","word problem: a runner covered 3 400 m; how many km and m?"],"thinking":["procedure"],"horeb_skill_ids":["G5_LENGTH","G6_UNIT_CONVERSIONS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP","kind":"skill","strength":"essential","reason":"Splitting off thousands depends on knowing 1 000 m make 1 km.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"The cm-to-m conversion is the analogous procedure from Grade 4.","status":"proposed"},{"requires":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M","kind":"skill","strength":"helpful","reason":"Converting both ways reinforces that the two are inverse processes.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.ADD_KM_M","name":"Add distances in km and m","outcomes":["MATH.G5.MEASUR.LENGTH.e"],"mastery":"The child adds two or three distances given in km and m, set out in km and m columns, regrouping every 1 000 m as 1 km. For example, 2 km 700 m + 1 km 600 m = 4 km 300 m. They also solve real-life addition word problems, such as total journey length (proposed limit: totals up to 999 km 999 m).","question_forms":["column addition without regrouping","column addition with regrouping (m to km)","add a km measure and a m measure (e.g. 5 km + 300 m)","word problem: total distance of a journey in stages"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_LENGTH"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM","kind":"skill","strength":"essential","reason":"Regrouping 1 000 m or more into km is a metres-to-km conversion.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.f","kind":"outcome","strength":"essential","reason":"Adding m and cm in columns with regrouping is the same structure.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M","name":"Subtract distances in km and m","outcomes":["MATH.G5.MEASUR.LENGTH.f"],"mastery":"The child subtracts distances in km and m, exchanging 1 km for 1 000 m when the metres being taken away are more than those available. For example, 5 km 200 m − 2 km 650 m = 2 km 550 m. They also solve real-life problems such as 'how much further?' and 'distance remaining' (proposed limit: values up to 999 km 999 m).","question_forms":["column subtraction without exchanging","column subtraction with exchanging (1 km to 1 000 m)","subtract from a whole number of km (e.g. 10 km − 3 km 450 m)","word problem: how much further / distance left to travel"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_LENGTH"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M","kind":"skill","strength":"essential","reason":"Exchanging 1 km for 1 000 m is a km-to-m conversion.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.g","kind":"outcome","strength":"essential","reason":"Subtracting m and cm with exchange is the same structure.","status":"proposed"},{"requires":"MATH.G5.MEASUR.LENGTH.ADD_KM_M","kind":"skill","strength":"helpful","reason":"Addition lets the child check a subtraction answer.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.MULTIPLY_KM_M","name":"Multiply distances in km and m by a whole number","outcomes":["MATH.G5.MEASUR.LENGTH.g"],"mastery":"The child multiplies a distance in km and m by a whole number, multiplying both the m and the km and regrouping each 1 000 m as 1 km. For example, 2 km 400 m × 3 = 7 km 200 m. They also solve repeated-trip problems (proposed limit: multiplier a single-digit whole number; may extend to 2-digit at the teacher's discretion).","question_forms":["multiply without regrouping","multiply with regrouping (m to km)","word problem: same journey made several times","missing multiplier: ___ × 1 km 500 m = 6 km"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_LENGTH"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM","kind":"skill","strength":"essential","reason":"Products of the metres often exceed 1 000 m and must be regrouped into km.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.h","kind":"outcome","strength":"essential","reason":"Multiplying m and cm by whole numbers is the same structure.","status":"proposed"},{"requires":"MATH.G5.MEASUR.LENGTH.ADD_KM_M","kind":"skill","strength":"helpful","reason":"Repeated addition gives meaning to multiplication and a way to check.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.LENGTH.DIVIDE_KM_M","name":"Divide distances in km and m by a whole number","outcomes":["MATH.G5.MEASUR.LENGTH.h"],"mastery":"The child divides a distance in km and m by a whole number. They either convert the remaining km to 1 000 m each and carry it into the metres, or convert the whole distance to metres first. For example, 7 km 200 m ÷ 4 = 1 km 800 m. They also solve equal-sharing and equal-parts problems (proposed limit: single-digit divisor; answers in whole metres).","question_forms":["divide where km divides exactly","divide with remaining km carried into metres","word problem: share a road or route equally","word problem: equal stages of a journey"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_LENGTH"],"prerequisites":[{"requires":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M","kind":"skill","strength":"essential","reason":"Remaining km must be changed to metres to continue dividing.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.i","kind":"outcome","strength":"essential","reason":"Dividing m and cm by whole numbers is the same structure.","status":"proposed"},{"requires":"MATH.G5.MEASUR.LENGTH.MULTIPLY_KM_M","kind":"skill","strength":"helpful","reason":"Multiplication lets the child check a division answer.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT.M_UNIT_SIZE_MISMATCH","skill":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT","error":"The child picks a unit that does not suit the size of the distance, for example metres or centimetres for the distance between towns.","example":{"question":"Which unit is best for measuring the distance from Nairobi to Nakuru: cm, m or km?","wrong_answer":"m","correct_answer":"km"},"cause":"The child has not yet linked unit size to the size of the thing measured, and m is the largest unit used so far.","reveals":"A unit-choice item with cm, m and km options for a town-to-town distance; choosing m or cm exposes it.","help":"Ask how many metre sticks it would take to reach the next town, so learners feel why counting in metres is impractical.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT.M_KM_KG_CONFUSION","skill":"MATH.G5.MEASUR.LENGTH.KM_IDENTIFY_UNIT","error":"The child confuses km with kg because both start with 'kilo', and writes distances in kg or masses in km.","example":{"question":"Write the distance shown on the road sign 'Thika 12': Thika is 12 ___ away.","wrong_answer":"12 kg","correct_answer":"12 km"},"cause":"The child remembers the 'kilo' prefix but not what quantity each unit measures.","reveals":"A unit-completion item that includes kg as a distractor.","help":"Pair each unit with what it measures ('km – how far', 'kg – how heavy') on a classroom chart, and sort real examples into the two groups.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.KM_ESTIMATE_DISTANCE.M_UNREALISTIC_ESTIMATE","skill":"MATH.G5.MEASUR.LENGTH.KM_ESTIMATE_DISTANCE","error":"The child gives estimates far too large or too small because they have no sense of how long 1 km is.","example":{"question":"Amina walks to school in about 15 minutes. About how far is her school: 1 km, 50 km or 10 m?","wrong_answer":"50 km","correct_answer":"about 1 km"},"cause":"The child has no personal benchmark for a kilometre and chooses by the look of the number.","reveals":"A multiple-choice estimate with options differing by powers of ten.","help":"Walk or pace a measured 1 km (or 2½ laps of a 400 m track) with the class and time it, so learners have a felt benchmark.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.KM_ESTIMATE_DISTANCE.M_TIME_AS_DISTANCE","skill":"MATH.G5.MEASUR.LENGTH.KM_ESTIMATE_DISTANCE","error":"The child gives a time instead of a distance when asked how far a place is.","example":{"question":"Estimate how far the market is from your school.","wrong_answer":"20 minutes","correct_answer":"a distance in km, e.g. about 2 km"},"cause":"In everyday talk people answer 'how far?' with a travel time, so the child does not separate the two.","reveals":"An open estimation item that requires a unit; answers in minutes or hours expose it.","help":"Accept the time as a clue, then ask 'how many km do you walk in that time?' to turn it into a distance.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP.M_KM_EQUALS_100M","skill":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP","error":"The child says 1 km = 100 m (or 10 m), carrying over the m–cm relationship from Grade 4.","example":{"question":"1 km = ___ m","wrong_answer":"100","correct_answer":"1 000"},"cause":"The child overgeneralises '1 m = 100 cm' to every pair of units.","reveals":"A direct fill-in, or a 'how many 100 m make 1 km?' item where the answer 1 exposes it.","help":"Mark ten 100 m stretches on the school field or road and count them together to make 1 km.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP.M_BIGGER_NUMBER_LONGER","skill":"MATH.G5.MEASUR.LENGTH.KM_M_RELATIONSHIP","error":"The child compares only the numbers and ignores the units, so thinks 1 500 m is longer than 2 km.","example":{"question":"Which is longer: 2 km or 1 500 m?","wrong_answer":"1 500 m","correct_answer":"2 km (2 000 m)"},"cause":"The child focuses on the size of the numeral, not the size of the unit.","reveals":"Comparison items where the shorter distance has the larger numeral.","help":"Require both distances to be written in the same unit before comparing.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M.M_KM_TO_M_TIMES_100","skill":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M","error":"The child multiplies by 100 instead of 1 000 when changing km to m.","example":{"question":"Convert 6 km to metres.","wrong_answer":"600 m","correct_answer":"6 000 m"},"cause":"The child applies the Grade 4 m-to-cm factor.","reveals":"A distractor of 600 m in a multiple-choice conversion.","help":"Have learners say '1 km is 1 000 m, so 6 km is 6 lots of 1 000 m' before writing the answer.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M.M_MISSING_PLACEHOLDER_ZERO","skill":"MATH.G5.MEASUR.LENGTH.CONVERT_KM_TO_M","error":"The child writes the km and m digits side by side, leaving out the zeros needed in the hundreds or tens place.","example":{"question":"Convert 3 km 45 m to metres.","wrong_answer":"345 m","correct_answer":"3 045 m"},"cause":"The child joins the digits instead of adding 3 000 m + 45 m, and does not see the metres as needing three places.","reveals":"Mixed measures with fewer than 100 m (e.g. 2 km 5 m, 3 km 45 m); answers like 345 or 2 500 expose it.","help":"Use a place-value chart with the km digit in the thousands column and the metres always filling three columns.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM.M_M_TO_KM_DIVIDE_100","skill":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM","error":"The child divides by 100 (splits off two digits) instead of 1 000 when changing m to km.","example":{"question":"Write 3 400 m in km and m.","wrong_answer":"34 km","correct_answer":"3 km 400 m"},"cause":"The child applies the Grade 4 cm-to-m pattern.","reveals":"A distractor of 34 km, or 34 km 0 m, in a conversion item.","help":"Ask 'how many whole thousands of metres are there?' and circle the thousands digit as the km.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM.M_M_TO_KM_DROPS_ZERO","skill":"MATH.G5.MEASUR.LENGTH.CONVERT_M_TO_KM","error":"The child splits the number in the wrong place, or drops a zero, when the metres part has an internal zero.","example":{"question":"Write 4 050 m in km and m.","wrong_answer":"4 km 5 m","correct_answer":"4 km 50 m"},"cause":"The child reads the leftover digits as a number without keeping their place value.","reveals":"Values like 4 050 m or 7 008 m, with distractors 4 km 5 m and 40 km 50 m.","help":"Check by converting back: 4 km 5 m gives 4 005 m, which is not 4 050 m.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.ADD_KM_M.M_ADD_NO_REGROUP","skill":"MATH.G5.MEASUR.LENGTH.ADD_KM_M","error":"The child leaves 1 000 m or more in the metres column instead of regrouping it as km.","example":{"question":"2 km 700 m + 1 km 600 m","wrong_answer":"3 km 1 300 m","correct_answer":"4 km 300 m"},"cause":"The child adds the columns separately and does not see that 1 000 m must become 1 km.","reveals":"Addition items where the metres total 1 000 or more; answers with a metres part of 1 000 or more expose it.","help":"Have learners check that the metres part is always less than 1 000 and regroup if it is not.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.ADD_KM_M.M_ADD_REGROUP_AT_100","skill":"MATH.G5.MEASUR.LENGTH.ADD_KM_M","error":"The child regroups when the metres reach 100, as they did with metres and centimetres in Grade 4.","example":{"question":"2 km 70 m + 1 km 50 m","wrong_answer":"4 km 20 m","correct_answer":"3 km 120 m"},"cause":"The child applies the m–cm exchange rate (100) to km–m.","reveals":"Items where the metres total between 100 and 999, so no regrouping should happen.","help":"Write '1 000 m = 1 km' at the top of the column work and ask 'have we reached 1 000 m yet?'","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.ADD_KM_M.M_ADD_IGNORE_UNITS","skill":"MATH.G5.MEASUR.LENGTH.ADD_KM_M","error":"The child adds a km value and a m value as plain numbers, ignoring the different units.","example":{"question":"A matatu travels 5 km, then 300 m more. How far altogether?","wrong_answer":"305 m","correct_answer":"5 km 300 m (5 300 m)"},"cause":"The child does not check units before adding.","reveals":"An item mixing a pure km value with a pure m value.","help":"Have learners write both measures under km and m column headings before adding.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M.M_SUB_SMALLER_FROM_LARGER","skill":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M","error":"In the metres column the child takes the smaller number from the larger, whichever is on top, instead of exchanging 1 km.","example":{"question":"5 km 200 m − 2 km 650 m","wrong_answer":"3 km 450 m","correct_answer":"2 km 550 m"},"cause":"The child believes you always subtract the smaller digit or number from the larger.","reveals":"Items where the metres being taken away are more than the metres on top.","help":"Check by adding: 3 km 450 m + 2 km 650 m gives 6 km 100 m, not 5 km 200 m.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M.M_SUB_EXCHANGE_100","skill":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M","error":"When exchanging, the child turns 1 km into 100 m instead of 1 000 m.","example":{"question":"4 km 50 m − 1 km 80 m","wrong_answer":"2 km 70 m","correct_answer":"2 km 970 m"},"cause":"The child applies the Grade 4 exchange of 1 m = 100 cm.","reveals":"Items with small metre values needing an exchange, such as 50 m − 80 m.","help":"Have learners write the exchanged metres in full (1 000 + 50 = 1 050 m) above the column before subtracting.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M.M_SUB_FORGET_REDUCE_KM","skill":"MATH.G5.MEASUR.LENGTH.SUBTRACT_KM_M","error":"The child exchanges 1 km into the metres correctly but forgets to reduce the km by 1.","example":{"question":"5 km 200 m − 2 km 650 m","wrong_answer":"3 km 550 m","correct_answer":"2 km 550 m"},"cause":"The child sees the exchange as just 'adding 1 000' to the metres, not as moving 1 km across.","reveals":"Exchange items; an answer exactly 1 km too large exposes it.","help":"Have learners cross out the km digit and write the new value each time they exchange.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.MULTIPLY_KM_M.M_MULT_NO_REGROUP","skill":"MATH.G5.MEASUR.LENGTH.MULTIPLY_KM_M","error":"The child leaves the product of the metres as 1 000 m or more instead of regrouping it into km.","example":{"question":"A boda boda rider makes 3 trips of 2 km 400 m each. How far does he ride?","wrong_answer":"6 km 1 200 m","correct_answer":"7 km 200 m"},"cause":"The child multiplies the columns separately without applying 1 000 m = 1 km.","reveals":"Items where the metres × multiplier is 1 000 or more.","help":"Have learners multiply the metres first and regroup before multiplying the km, as in column multiplication.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.MULTIPLY_KM_M.M_MULT_ONE_PART_ONLY","skill":"MATH.G5.MEASUR.LENGTH.MULTIPLY_KM_M","error":"The child multiplies only the km (or only the metres) and copies the other part unchanged.","example":{"question":"1 km 300 m × 4","wrong_answer":"4 km 300 m","correct_answer":"5 km 200 m"},"cause":"The child treats the measure as a whole number with a label attached, not as two parts that both scale.","reveals":"Distractors with only one part multiplied.","help":"Show the multiplication as repeated addition of the whole measure (1 km 300 m four times) so learners see both parts grow.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.DIVIDE_KM_M.M_DIV_IGNORE_REMAINDER","skill":"MATH.G5.MEASUR.LENGTH.DIVIDE_KM_M","error":"The child divides the km and m separately and drops the remainder from the km.","example":{"question":"A road 7 km 200 m long is shared equally among 4 groups to clean. How much does each group clean?","wrong_answer":"1 km 50 m","correct_answer":"1 km 800 m"},"cause":"The child sees the two parts as separate numbers and does not know the leftover 3 km must be carried into the metres.","reveals":"Items where the km do not divide exactly by the divisor.","help":"Have learners check by multiplying: 1 km 50 m × 4 = 4 km 200 m, not 7 km 200 m.","status":"draft"},{"code":"MATH.G5.MEASUR.LENGTH.DIVIDE_KM_M.M_DIV_REMAINDER_AS_100","skill":"MATH.G5.MEASUR.LENGTH.DIVIDE_KM_M","error":"The child carries the remaining km into the metres as 100 m each instead of 1 000 m.","example":{"question":"7 km 200 m ÷ 4","wrong_answer":"1 km 125 m","correct_answer":"1 km 800 m"},"cause":"The child applies the Grade 4 m–cm factor when carrying the remainder (3 km taken as 300 m, so 500 m ÷ 4 = 125 m).","reveals":"Items with a km remainder, with a distractor built on the 100 m error.","help":"Offer the 'convert everything to metres first' method (7 200 m ÷ 4) as a check.","status":"draft"}]},{"code":"MATH.G5.MEASUR.AREA","number":"2.2","strand":"Measurement","sub_strand":"Area","sequence":202,"lessons":6,"content_topics":["Square centimetre (cm ) as a unit of measuring area","Area of rectangles and squares"],"learning_experiences":["discuss and measure, trace and cut out 1 cm by 1cm units, and refer the area of each as one square centimetre (1cm )","cover a given surface using 1-centimetre square cut-outs and count the number of cut-outs to get the area in 2 cm ","establish the area of rectangles and squares in cm as the product of the number 1cm 2 units in the row by the number of units in the column, area of rectangle or square = length x width","team up with peers to play games involving area using multiplication charts"],"key_inquiry_questions":["How can you determine the area of different surfaces?"],"core_competences":"● 2 Creativity and imagination: learner uses paper cut-outs in covering plane surfaces to get area in cm . ● Self-efficacy: learner measures, traces and cuts out 1 cm by 1cm units, and refer the area of each as one square centimetre (1cm ).","values":"Unity: learner teams up with peers to play games involving area using multiplication charts.","pcis":"Environmental awareness: learner covers a given surface from the environment using 1-centimetre square cut-outs and counts the number of cut-outs to get the area in cm","links":"Learner relates concept of area to planting fields in Agriculture.","design_notes":"1) Outcome (c), 'appreciate the use of cm² in working out area in real life', is attitudinal. It is not mapped to a skill and should be observed during practical and real-life tasks. 2) The design gives no number limits for side lengths or areas. All limits in 'what_mastery_looks_like' (whole-centimetre sides, mostly within 12 × 12, up to simple 2-digit × 2-digit, about 100 cm² for counting, no part-squares) are proposed professional judgement, not KICD text. 3) Finding a missing side from the area is not stated in the outcomes. It is included as a proposed extension, suggested by the learning experience on area games with multiplication charts. 4) The content topics and learning experiences in the source text have lost their superscripts ('cm )', 'in 2 cm', 'in cm as the product', '1cm 2 units'); these are read as cm². The key inquiry question also carries the stray heading text 'Inquiry Question(s)'. Both are extraction artefacts. 5) Grade 4 2.2c already covers area as rows × columns. The Grade 5 difference is the standard unit cm², measuring sides in cm and the length × width rule. Assessments should include cm² units and measured sides to separate the two grades. 6) Grade 5 has no unit larger than cm² (no m²), and the Grade 6 area outcomes also use only cm². Real-life tasks should therefore use surfaces of a sensible size (stamps, book covers, tiles) rather than floors or land. 7) Multiplication facts and multi-digit multiplication are essential prerequisites from the Number strand, but no codes for them appear in the inputs, so they are not linked. 8) HOREB's G6_AREA_RECT overlaps the Grade 5 calculation skills, because the Grade 6 design outcomes do not list rectangle area on its own; it may be revision or consolidation. G5_PERIMETER_INTRO is not a match but is a known source of the area–perimeter confusion.","outcomes":[{"code":"MATH.G5.MEASUR.AREA.a","letter":"a","text":"identify the square centimetre (cm²) as a unit of measuring area in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.AREA.b","letter":"b","text":"work out area of rectangles and squares in square centimetres (cm²) in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.AREA.c","letter":"c","text":"appreciate the use of cm² in working out area in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING","name":"Knowing what one square centimetre (cm²) is","outcomes":["MATH.G5.MEASUR.AREA.a"],"mastery":"The child can explain and show that 1 cm² is the space covered by a square with sides of 1 cm. They can read and write 'cm²' correctly and tell it apart from 'cm', which measures length. They know that a shape of 5 cm² covers the same space as five such squares, even when the squares are arranged differently.","question_forms":["draw or identify a 1 cm by 1 cm square","which unit: cm or cm²","explain what '6 cm²' means","true or false: a square with 2 cm sides has area 1 cm²"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_AREA_INTRO"],"prerequisites":[{"requires":"MATH.G4.MEASUR.LENGTH.a","kind":"outcome","strength":"essential","reason":"A child must know the centimetre as a length before building a square with 1 cm sides.","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.b","kind":"outcome","strength":"essential","reason":"Measuring area with unit squares is the idea that cm² makes standard.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT","name":"Finding area by covering with 1 cm squares and counting","outcomes":["MATH.G5.MEASUR.AREA.a","MATH.G5.MEASUR.AREA.b"],"mastery":"The child can cover a flat surface or a drawn shape with 1 cm square cut-outs, or use a 1 cm grid, leaving no gaps or overlaps. They count the squares accurately and record the area with the unit cm². Proposed limit: rectangles and squares up to about 100 cm², with whole squares only (no part-squares at Grade 5).","question_forms":["practical: cover a surface (stamp, eraser, matchbox top) and count","count squares on a cm grid","compare two shapes by counting squares","spot the mistake in someone's covering"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_AREA_INTRO","G4_AREA"],"prerequisites":[{"requires":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING","kind":"skill","strength":"essential","reason":"The child must know what each cut-out stands for before counting cut-outs as cm².","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.b","kind":"outcome","strength":"essential","reason":"Counting unit squares to find area is the same procedure, now with a standard unit.","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.a","kind":"outcome","strength":"helpful","reason":"Comparing surfaces by direct covering builds the idea that area is the space a surface covers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.AREA.CM2_REAL_LIFE","name":"Recognising real-life surfaces whose area is measured in cm²","outcomes":["MATH.G5.MEASUR.AREA.a"],"mastery":"The child can name and pick out everyday flat surfaces whose area we measure in cm², such as a postage stamp, an exercise book cover, a mobile phone screen or a mandazi tray. They can tell these apart from quantities measured in other units, such as the length of a pencil (cm), the mass of a mango (kg) or the amount of milk in a jug (litres).","question_forms":["choose the quantity measured in cm²","match quantity to unit (cm, cm², kg, litres)","list surfaces at home or school measured in cm²"],"thinking":["recall","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING","kind":"skill","strength":"essential","reason":"The child cannot pick out cm² situations without knowing what the unit measures.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"helpful","reason":"Experience of measuring in cm gives a feel for the size of everyday objects.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.AREA.AREA_ROWS_BY_COLUMNS","name":"Linking rows × columns of 1 cm² squares to length × width","outcomes":["MATH.G5.MEASUR.AREA.b"],"mastery":"The child can explain that a rectangle with 4 rows of 6 one-centimetre squares has area 4 × 6 = 24 cm². They can connect this to 'area = length × width', because the number of squares in a row equals the length in cm and the number of rows equals the width in cm. They can do this even when only part of the grid is drawn.","question_forms":["array: how many squares without counting one by one","partly drawn grid: find the area","explain why area = length × width","multiplication-chart area game"],"thinking":["reasoning","procedure"],"horeb_skill_ids":["G5_AREA_INTRO","G4_AREA"],"prerequisites":[{"requires":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT","kind":"skill","strength":"essential","reason":"Rows × columns is a shortcut for counting covered squares, so the child must trust the counting first.","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.c","kind":"outcome","strength":"essential","reason":"Grade 4 already introduced area as rows × columns; Grade 5 links this to cm² and length × width.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC","name":"Calculating area of rectangles and squares from their sides","outcomes":["MATH.G5.MEASUR.AREA.b"],"mastery":"Given, or after measuring, the whole-number sides in cm, the child works out the area of a rectangle (length × width) or a square (side × side) and writes the answer in cm². Proposed limits: whole-centimetre sides, mostly within 12 × 12 facts, extending to 2-digit × 1-digit and simple 2-digit × 2-digit (e.g. 25 cm × 14 cm).","question_forms":["labelled diagram: find the area","measure the sides with a ruler, then find the area","square given one side","compare and explain: which has the larger area"],"thinking":["procedure"],"horeb_skill_ids":["G6_AREA_RECT"],"prerequisites":[{"requires":"MATH.G5.MEASUR.AREA.AREA_ROWS_BY_COLUMNS","kind":"skill","strength":"essential","reason":"Length × width only makes sense when seen as rows and columns of 1 cm² squares.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"essential","reason":"Many tasks need the child to measure the sides in cm accurately first.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.AREA.AREA_PROBLEMS","name":"Solving real-life area problems with rectangles and squares in cm²","outcomes":["MATH.G5.MEASUR.AREA.b"],"mastery":"The child can solve word problems set in everyday situations, for example the cover of a textbook, a piece of kitenge cloth or a tile on a classroom wall. They decide that area (not perimeter) is needed, calculate it and give the answer in cm². Proposed extension: finding a missing side when the area and one side are known, using multiplication or division facts within 12 × 12.","question_forms":["word problem: covering a surface","word problem: comparing two surfaces","missing side (proposed extension)","area or perimeter: choose and solve"],"thinking":["problem solving","reasoning"],"horeb_skill_ids":["G6_AREA_RECT"],"prerequisites":[{"requires":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC","kind":"skill","strength":"essential","reason":"Word problems apply the area calculation.","status":"proposed"},{"requires":"MATH.G5.MEASUR.AREA.CM2_REAL_LIFE","kind":"skill","strength":"helpful","reason":"Recognising surfaces measured in cm² helps the child see that a problem needs area.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.e","kind":"outcome","strength":"helpful","reason":"Knowing what perimeter is helps the child decide between perimeter and area in a context.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING.M_CM_FOR_AREA","skill":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING","error":"Writes area in cm (a length unit) instead of cm².","example":{"question":"A rectangle is 4 cm long and 3 cm wide. What is its area?","wrong_answer":"12 cm","correct_answer":"12 cm²"},"cause":"The child sees the unit as a label copied from the sides, not as a description of what was counted (squares).","reveals":"Offer options 12 cm, 12 cm² and 14 cm. Alternatively, ask the child to write their own unit and say what it means.","help":"Every time an area is recorded, have the child point to one 1 cm by 1 cm square and say 'we counted twelve of these', then write cm².","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING.M_SQUARED_MEANS_DOUBLE","skill":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING","error":"Reads the small '2' in cm² as 'times 2' or '2 cm', so thinks 5 cm² means 10 cm.","example":{"question":"What does 5 cm² mean?","wrong_answer":"10 cm (5 × 2)","correct_answer":"The space covered by 5 squares, each 1 cm by 1 cm"},"cause":"The child does not yet know index notation, so the superscript is taken as an ordinary number to use.","reveals":"Ask the child to draw 5 cm² on 1 cm grid paper. A child with this error draws a 10 cm line or 10 squares.","help":"Read cm² aloud as 'square centimetres' and always pair the symbol with a picture of square tiles until the meaning is secure.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING.M_ANY_SQUARE_IS_ONE_CM2","skill":"MATH.G5.MEASUR.AREA.CM2_UNIT_MEANING","error":"Thinks any single square, whatever its size, has an area of 1 cm².","example":{"question":"A square has sides of 2 cm. What is its area?","wrong_answer":"1 cm²","correct_answer":"4 cm²"},"cause":"The child links 'one square' with 'one square centimetre', ignoring the 1 cm side length.","reveals":"Show a 2 cm square drawn as a single outline, with no grid inside, and ask for its area in cm².","help":"Have the child cover a 2 cm square with 1 cm cut-outs, so they see it takes four.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT.M_GAPS_OVERLAPS","skill":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT","error":"Leaves gaps between cut-outs or lets them overlap or hang over the edge, then counts them.","example":{"question":"Cover a postage stamp 3 cm by 2 cm with 1 cm squares. What is its area?","wrong_answer":"4 cm² (squares spaced out with gaps) or 8 cm² (overlapping)","correct_answer":"6 cm²"},"cause":"The child sees covering as 'putting squares on it' and does not understand that area means filling the space exactly.","reveals":"Show a picture of a covering with visible gaps and ask whether the count gives the area, and why.","help":"Have pupils check each other's coverings for gaps and overlaps before counting, and discuss why each one makes the count wrong.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT.M_COUNT_LINES_NOT_SQUARES","skill":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT","error":"Counts grid lines or dots along the edges instead of the squares.","example":{"question":"A rectangle on 1 cm grid paper is 5 squares long and 3 squares wide. Find its area.","wrong_answer":"24 cm² (6 lines × 4 lines)","correct_answer":"15 cm²"},"cause":"The child focuses on the marks (lines or points) rather than the spaces between them.","reveals":"Include 24 cm² as an option, or ask the child to show which things they counted.","help":"Have the child shade or put a counter in each square as they count, so the spaces are counted, not the lines.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT.M_COUNT_BORDER_ONLY","skill":"MATH.G5.MEASUR.AREA.AREA_COVER_AND_COUNT","error":"Counts only the squares around the edge of the shape and misses the inside ones.","example":{"question":"A rectangle on 1 cm grid paper is 4 squares long and 3 squares wide. Find its area.","wrong_answer":"10 cm²","correct_answer":"12 cm²"},"cause":"The child confuses the boundary with the whole surface, an early form of mixing up area and perimeter.","reveals":"Use rectangles at least 3 by 4 so that inside squares exist, and include the border count as a distractor.","help":"Have the child colour the border squares in one colour and the inside squares in another, then add both counts.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.CM2_REAL_LIFE.M_CM2_FOR_LENGTH","skill":"MATH.G5.MEASUR.AREA.CM2_REAL_LIFE","error":"Chooses cm² for things that are lengths, such as the length of a pencil or the height of a desk.","example":{"question":"Which would you measure in cm²: the length of a pencil, the top of a postage stamp, or the mass of a mango?","wrong_answer":"The length of a pencil","correct_answer":"The top of a postage stamp"},"cause":"The child knows cm² has 'cm' in it, so links it with anything measured with a ruler.","reveals":"Use matching tasks that put a length quantity next to a surface, with both cm and cm² offered.","help":"Have the child run a finger along a length but rub a palm over a surface, and say 'cm for along, cm² for covering'.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_ROWS_BY_COLUMNS.M_ADD_ROWS_COLUMNS","skill":"MATH.G5.MEASUR.AREA.AREA_ROWS_BY_COLUMNS","error":"Adds the number of rows and the number of columns instead of multiplying them.","example":{"question":"A tray of mandazi is laid out in 6 rows with 4 in each row, each taking up 1 cm² on a drawing. What is the area?","wrong_answer":"10 cm²","correct_answer":"24 cm²"},"cause":"The child sees two numbers and adds by default, without seeing the array as repeated rows.","reveals":"Include the sum as a distractor, and ask the child to check by counting one row and skip-counting.","help":"Have the child skip-count the rows aloud (4, 8, 12, …, 24) and then record this as 6 × 4.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_ROWS_BY_COLUMNS.M_PARTIAL_GRID_COUNT","skill":"MATH.G5.MEASUR.AREA.AREA_ROWS_BY_COLUMNS","error":"When only the first row and first column of squares are drawn, counts just the drawn squares.","example":{"question":"A rectangle shows 4 squares along the top and 3 squares down the side; the rest is blank. What is its area?","wrong_answer":"6 cm² or 7 cm²","correct_answer":"12 cm²"},"cause":"The child does not yet picture the rectangle as filled with equal rows, so counts only what is visible.","reveals":"Present partly drawn grids, which separate array thinking from plain counting.","help":"Have the child finish drawing the rows with a ruler, then predict the area of the next partly drawn grid before drawing it.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC.M_AREA_AS_PERIMETER","skill":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC","error":"Adds the sides (finding the perimeter, or just length + width) instead of multiplying.","example":{"question":"Find the area of a rectangle 7 cm long and 5 cm wide.","wrong_answer":"24 cm or 12 cm²","correct_answer":"35 cm²"},"cause":"Perimeter was learnt with the same diagrams, and the child links 'work out' with adding the sides.","reveals":"Give options 12, 24 and 35 with mixed units, and set area and perimeter questions on the same figure.","help":"On the same rectangle, have the child trace the edge for perimeter and shade the inside for area, saying which they are finding before calculating.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC.M_SQUARE_SIDE_DOUBLED","skill":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC","error":"For a square, multiplies the side by 2 instead of by itself.","example":{"question":"A square tile has sides of 6 cm. What is its area?","wrong_answer":"12 cm²","correct_answer":"36 cm²"},"cause":"The child may read the '²' as ×2, or forget that a square has a length and a width that are equal.","reveals":"Use square questions with side × 2 as a distractor. Sides of 2 cm do not reveal the error, because 2 × 2 = 2 + 2.","help":"Label both the length and the width of the square (6 cm and 6 cm) before multiplying, and check by drawing the array.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC.M_MULTIPLY_ALL_SIDES","skill":"MATH.G5.MEASUR.AREA.AREA_RECT_SQUARE_CALC","error":"Multiplies all four labelled side lengths together.","example":{"question":"A rectangle has its sides labelled 5 cm, 3 cm, 5 cm and 3 cm. Find its area.","wrong_answer":"225 cm²","correct_answer":"15 cm²"},"cause":"The child remembers 'multiply the sides' without understanding that length × width counts rows of squares.","reveals":"Label all four sides on the diagram, and ask whether 225 squares could fit on a 5 by 3 grid.","help":"Have the child sketch the 5 by 3 array and check whether their answer is sensible against it.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_PROBLEMS.M_CONTEXT_WRONG_MEASURE","skill":"MATH.G5.MEASUR.AREA.AREA_PROBLEMS","error":"In a word problem that needs area, works out the perimeter (or the other way round).","example":{"question":"Akinyi wants to cover the top of a box 20 cm long and 15 cm wide with kitenge cloth. How many square centimetres of cloth does she need?","wrong_answer":"70 cm","correct_answer":"300 cm²"},"cause":"The child picks out the numbers and an operation without picturing whether the context is about covering or going around.","reveals":"Set paired problems on the same box: one about ribbon around the edge and one about cloth covering the top.","help":"Have the child first say whether the task is 'covering' or 'going around' and sketch it before choosing the operation.","status":"draft"},{"code":"MATH.G5.MEASUR.AREA.AREA_PROBLEMS.M_MISSING_SIDE_SUBTRACT","skill":"MATH.G5.MEASUR.AREA.AREA_PROBLEMS","error":"To find a missing side from the area, subtracts the known side from the area instead of dividing, or writes the side in cm².","example":{"question":"Otieno's exercise book cover has an area of 48 cm² and a length of 8 cm. What is its width?","wrong_answer":"40 cm (or 6 cm²)","correct_answer":"6 cm"},"cause":"The child does not see the missing side as the missing factor in length × width = area, and mixes up length units and area units.","reveals":"Include the area minus the side and a side written in cm² as distractors.","help":"Write '8 × ? = 48' and find the missing number on a multiplication chart, then say 'a side is a length, so cm'.","status":"draft"}]},{"code":"MATH.G5.MEASUR.VOLUME","number":"2.3","strand":"Measurement","sub_strand":"Volume","sequence":203,"lessons":6,"content_topics":["Cubic centimetre (cm 3 ) as a unit of measuring volume","Volume of cubes and cuboids"],"learning_experiences":["measure the sides of a 1cm cube and identify it as a unit of measuring volume","arrange a number of cubes along the length, width and vary the number of layers","count the number of cubes used in activity above and record","establish that the total number of cubes represents the volume of the cube or cuboid formed","count the number of cubes on the length and multiply by the number in the width and the number of layers","establish the formula for volume (v) of cuboid as v = l x w x h","discuss the formula for volume of a cube v= s x s x s where, s is the side of a cube","manipulate cubes and cuboids by flipping around using digital devices or other resources","work out the volume of cubes and cuboids in cubic centimetres","use digital devices and other resources to play games involving volumes. Experiences"],"key_inquiry_questions":["Where is volume applicable in real life?"],"core_competences":"● Learning to learn: learner counts the number of cubes on the length and multiply by the number in the width and the number of layers to establish the formula for volume (v) of a cuboid. ● Creativity and imagination: learner counts the number of cubes to establish that the total number of cubes represents the volume of cuboid formed.","values":"Responsibility: learner shows responsibility as they handle the various objects in the environment.","pcis":"Safety: learner observes safety while handling the various objects in the environment.","links":"The learner is able to relate concept of volume to construction of innovative watering equipment in Agriculture.","design_notes":"1) Outcome f ('appreciate use of cubic centimetres in measuring volume in real life') is attitudinal. It is not mapped to a skill and is best observed during practical work and the key inquiry question 'Where is volume applicable in real life?'. 2) The design gives no number limits for this sub-strand. All limits stated in 'what_mastery_looks_like' (whole-centimetre dimensions, volumes up to 10 000 cm³, cube edges 1 to 10 cm) are proposed professional judgements, not KICD wording. 3) The design does not say whether learners should find a missing dimension from a given volume (for example V = 60 cm³, l = 5, w = 3, find h). This is not required by outcomes b to e and is proposed only as an extension, not a core assessed skill. 4) Outcomes b and d say 'derive ... practically'. These are best assessed by observing children building with 1 cm cubes and explaining, rather than by written items alone. 5) The design writes the formulas with a lower-case 'v' and the letter 'x' for multiplication. Teachers may wish to standardise on V and × in written materials. The design uses 'w' (width) where some textbooks use 'b' (breadth), so assessments should accept both. 6) Multiplying three whole numbers depends on multiplication skills from the Numbers strand, which were not provided. No Numbers-strand prerequisite codes are cited for that reason, but weak multiplication will affect outcomes c and e. 7) In the Grade 6 design as supplied, sub-strand 2.3 is Capacity (linking cm³, millilitres and litres), and there is no separate Grade 6 Volume sub-strand. The HOREB skill G6_VOLUME_CUBOID therefore overlaps Grade 5 outcomes c and e and does not match a listed Grade 6 outcome; this mapping should be checked. 8) The Grade 4 outcome 2.3c reads 'to form a cubes' and 2.3d reads 'pilling', which are typos in the source text, and the learning experience list ends with a stray word 'Experiences'. These appear to be text-extraction artefacts and do not affect meaning. 9) The skill G5_VOLUME_COUNT_CM3_CUBES is linked to outcomes a and b because the learning experiences place counting 1 cm cubes as the bridge between identifying the unit and deriving the formula. It is a proposed separate assessable step.","outcomes":[{"code":"MATH.G5.MEASUR.VOLUME.a","letter":"a","text":"identify the cubic centimetre (cm³) as a unit of measuring volume in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.VOLUME.b","letter":"b","text":"derive the formula for the volume of cuboid as v= l x w x h practically","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.VOLUME.c","letter":"c","text":"work out volume of cuboids in cubic centimetres (cm³) using the formula","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.VOLUME.d","letter":"d","text":"derive the formula for the volume of cube as v= s x s x s practically","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.VOLUME.e","letter":"e","text":"work out volume of cubes in cubic centimetres (cm³) using the formula","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.VOLUME.f","letter":"f","text":"appreciate use of cubic centimetres in measuring volume in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","name":"Identify the cubic centimetre (cm³) as a unit of volume","outcomes":["MATH.G5.MEASUR.VOLUME.a"],"mastery":"The child recognises a cube with every edge 1 cm as one cubic centimetre and reads and writes the symbol cm³ correctly. They can tell cm (length), cm² (area) and cm³ (volume) apart and choose cm³ for the space taken up by small everyday objects such as a sugar cube, a matchbox or a block of soap. Proposed limit: only the cm³ unit; larger units are not expected.","question_forms":["measure the edges of a 1 cm cube and name the unit","choose the correct unit (cm, cm², cm³) for a given measurement","read or write the symbol cm³","true or false: statements about what 1 cm³ means","identify real objects whose volume would be measured in cm³"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_VOLUME"],"prerequisites":[{"requires":"MATH.G4.MEASUR.LENGTH.a","kind":"outcome","strength":"essential","reason":"A cubic centimetre is defined by edges of 1 cm, so the child must know the centimetre.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"helpful","reason":"The learning experience asks children to measure the sides of a 1 cm cube.","status":"proposed"},{"requires":"MATH.G4.MEASUR.VOLUME.a","kind":"outcome","strength":"helpful","reason":"Experience of stacking cubes gives meaning to a cube as a unit of space.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES","name":"Find volume by counting 1 cm cubes (models and pictures)","outcomes":["MATH.G5.MEASUR.VOLUME.a","MATH.G5.MEASUR.VOLUME.b"],"mastery":"The child builds or examines a cuboid or cube made of 1 cm cubes and states its volume as the total number of cubes in cm³. This includes cubes hidden inside or behind a picture. They also understand that rearranging the same cubes, or turning the shape around, does not change the volume. Proposed limit: models of up to about 60 cubes, and pictures with up to 5 cubes along any edge.","question_forms":["count cubes in a built model and record the volume in cm³","count cubes in a picture of a cuboid including hidden cubes","compare volumes of two arrangements of the same cubes","build a cuboid with a given number of cubes"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_VOLUME","G4_VOLUME"],"prerequisites":[{"requires":"MATH.G4.MEASUR.VOLUME.b","kind":"outcome","strength":"essential","reason":"Finding volume by piling blocks into cuboids is the Grade 4 basis for counting cubic units.","status":"proposed"},{"requires":"MATH.G4.MEASUR.VOLUME.c","kind":"outcome","strength":"helpful","reason":"Piling blocks to form cubes gives experience of equal-edged shapes.","status":"proposed"},{"requires":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","kind":"skill","strength":"essential","reason":"The count must be recorded in cm³, so the unit must be understood.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE","name":"Derive V = l × w × h for a cuboid practically","outcomes":["MATH.G5.MEASUR.VOLUME.b"],"mastery":"Using 1 cm cubes, the child shows that the cubes along the length multiplied by the cubes along the width gives the cubes in one layer. That number multiplied by the number of layers gives the total. They then explain that this is V = l × w × h. They can explain why the answer is the same whichever face the cuboid rests on. Proposed limit: whole-number dimensions up to about 6 cm in practical work.","question_forms":["practical: arrange cubes in rows and layers and record the counts in a table","complete a table of length, width, layers and total cubes, then spot the rule","explain why multiplying gives the number of cubes","compare and explain: same cuboid placed on a different face"],"thinking":["reasoning"],"horeb_skill_ids":["G5_VOLUME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES","kind":"skill","strength":"essential","reason":"The formula is derived by noticing structure in cube counts.","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.c","kind":"outcome","strength":"essential","reason":"Rows times columns for area is exactly the base-layer step (l × w) of the volume formula.","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.b","kind":"outcome","strength":"helpful","reason":"Counting unit squares links to counting cubes in one layer.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_CALC","name":"Calculate the volume of a cuboid in cm³ using the formula","outcomes":["MATH.G5.MEASUR.VOLUME.c"],"mastery":"Given the length, width and height of a cuboid in whole centimetres, either as numbers or on a labelled diagram, the child multiplies all three and writes the answer in cm³. Proposed limit: dimensions are whole numbers of centimetres and volumes do not exceed 10 000 cm³.","question_forms":["calculate from a labelled diagram","calculate from given dimensions in a table","spot the error in a worked solution","multiple choice with area, sum-of-sides and correct-volume distractors"],"thinking":["procedure"],"horeb_skill_ids":["G5_VOLUME","G6_VOLUME_CUBOID"],"prerequisites":[{"requires":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE","kind":"skill","strength":"essential","reason":"Using the formula with meaning depends on knowing why it works.","status":"proposed"},{"requires":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","kind":"skill","strength":"essential","reason":"Answers must be given in cm³, not cm or cm².","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_PROBLEMS","name":"Solve real-life problems on the volume of cuboids in cm³","outcomes":["MATH.G5.MEASUR.VOLUME.c"],"mastery":"The child works out the volume of real cuboid-shaped objects described in words, such as a box of chalk, a brick, a bar of soap or a juice carton. They pick out only the measurements needed and change any metres to centimetres before multiplying. They give the answer in cm³. Proposed limit: whole-number dimensions and volumes not exceeding 10 000 cm³.","question_forms":["word problem: volume of a box or container","word problem: how many 1 cm cubes fill a box","word problem with extra (irrelevant) information","word problem with one measurement given in metres","compare volumes of two boxes and decide which holds more"],"thinking":["problem solving","procedure"],"horeb_skill_ids":["G5_VOLUME","G6_VOLUME_CUBOID"],"prerequisites":[{"requires":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_CALC","kind":"skill","strength":"essential","reason":"Word problems apply the formula calculation.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"Real objects are sometimes measured in metres, which must be changed to centimetres first.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"helpful","reason":"Measuring real boxes in centimetres supports practical problems.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.VOLUME.CUBE_FORMULA_DERIVE","name":"Derive V = s × s × s for a cube practically","outcomes":["MATH.G5.MEASUR.VOLUME.d"],"mastery":"The child builds cubes from 1 cm cubes, for example 2 by 2 by 2 and 3 by 3 by 3. They explain that a cube is a cuboid whose length, width and height are all equal, so V = l × w × h becomes V = s × s × s. They know that one edge measurement is enough to find a cube's volume. Proposed limit: practical cubes with edges up to 4 cm.","question_forms":["practical: build cubes of edge 1, 2, 3 cm and record cubes used","explain how the cube formula comes from the cuboid formula","true or false: a cube with edge 3 cm has volume 3 cm³","identify which of several cuboids are cubes"],"thinking":["reasoning"],"horeb_skill_ids":["G5_VOLUME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE","kind":"skill","strength":"essential","reason":"The cube formula is the cuboid formula with all three dimensions equal.","status":"proposed"},{"requires":"MATH.G4.MEASUR.VOLUME.c","kind":"outcome","strength":"helpful","reason":"Building cubes from blocks in Grade 4 prepares for the practical derivation.","status":"proposed"},{"requires":"MATH.G4.MEASUR.AREA.c","kind":"outcome","strength":"helpful","reason":"The area of a square base (s × s) is the first step of s × s × s.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.VOLUME.CUBE_VOLUME_CALC","name":"Calculate the volume of a cube in cm³ using the formula","outcomes":["MATH.G5.MEASUR.VOLUME.e"],"mastery":"Given the edge of a cube in whole centimetres, the child works out s × s × s and writes the answer in cm³. This includes simple contexts such as a dice, a cube-shaped box or a sugar cube. Proposed limit: edges from 1 cm to 10 cm, giving volumes up to 1000 cm³, with occasional extension to 20 cm.","question_forms":["calculate from a labelled diagram of a cube","calculate from the edge length given in words","word problem: cube-shaped box or container","multiple choice with s × 3 and s × s distractors"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_VOLUME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.VOLUME.CUBE_FORMULA_DERIVE","kind":"skill","strength":"essential","reason":"The calculation relies on knowing that the edge is used three times.","status":"proposed"},{"requires":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","kind":"skill","strength":"essential","reason":"Answers must be given in cm³.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY.M_CM3_WRONG_UNIT","skill":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","error":"The child writes volume in cm or cm² instead of cm³.","example":{"question":"Wanjiru builds a box shape using 24 cubes, each with edges of 1 cm. What is its volume?","wrong_answer":"24 cm²","correct_answer":"24 cm³"},"cause":"The child treats the unit as a label to copy from the last topic, such as area, rather than as the kind of quantity being measured.","reveals":"Offer multiple choice with 24 cm, 24 cm² and 24 cm³. Also ask the child to match three measurements (a stick, a page, a box) to the three units.","help":"Show a 1 cm line, a 1 cm square and a 1 cm cube side by side. Have children say which one 'fills space' before writing any unit.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY.M_CM3_MEANS_3CM","skill":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","error":"The child thinks the small ³ means 3 cm, so a 1 cm³ cube has edges of 3 cm.","example":{"question":"A cube has a volume of 1 cm³. How long is each of its edges?","wrong_answer":"3 cm","correct_answer":"1 cm"},"cause":"The child reads the raised 3 as an ordinary number in the measurement instead of meaning 'cubic' (three dimensions).","reveals":"Ask the child to draw or pick out a 1 cm³ cube from cubes of edge 1 cm, 2 cm and 3 cm.","help":"Have children measure a real 1 cm cube with a ruler in all three directions and say 'one centimetre long, one wide, one high: one cubic centimetre'.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY.M_VOLUME_IS_MASS","skill":"MATH.G5.MEASUR.VOLUME.CM3_UNIT_IDENTIFY","error":"The child thinks a heavier object must have a bigger volume.","example":{"question":"A 1 cm cube of wood and a 1 cm cube of iron are placed on a table. Which one takes up more space?","wrong_answer":"The iron cube","correct_answer":"They take up the same space: each is 1 cm³."},"cause":"The child uses everyday 'bigger' to mean heavier or more, and does not yet separate volume (space) from mass.","reveals":"Ask about two objects of equal size but different materials, and include 'the heavier one' as a distractor.","help":"Let children hold equal-sized cubes of different materials, such as wood, plasticine and stone, and check that each fits exactly into the same 1 cm space.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES.M_COUNT_FACE_SQUARES","skill":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES","error":"In a picture of a cuboid, the child counts the squares on the visible faces instead of the cubes. Edge cubes get counted more than once and hidden cubes are missed.","example":{"question":"A picture shows a cuboid made of 1 cm cubes. It is 3 cubes long, 2 cubes wide and 2 cubes high. What is its volume?","wrong_answer":"16 cm³ (6 + 6 + 4 squares on the front, top and side)","correct_answer":"12 cm³"},"cause":"The child sees the drawing as flat faces and does not picture the cubes as solid layers going back into the page.","reveals":"Use a picture-based question with the face-square total as a distractor, then ask the child to build the shape and recount.","help":"Build the pictured cuboid with real cubes, then take it apart layer by layer so children see each cube counted once.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES.M_COUNT_ONE_LAYER","skill":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES","error":"The child counts only the top or front layer of cubes and gives that as the volume.","example":{"question":"A stack of 1 cm cubes has 3 layers, and each layer is 4 cubes long and 2 cubes wide. What is its volume?","wrong_answer":"8 cm³","correct_answer":"24 cm³"},"cause":"The child counts only what they can see and does not realise that the layers below are also part of the shape.","reveals":"Give the single-layer count as a distractor. Ask 'How many layers are there?' before the total.","help":"Have children build one layer, count it, then add identical layers one at a time, saying the running total each time.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES.M_NO_CONSERVATION_VOLUME","skill":"MATH.G5.MEASUR.VOLUME.VOLUME_COUNT_CM3_CUBES","error":"The child thinks the same cubes take up more space when arranged taller or longer.","example":{"question":"Otieno uses 12 cubes to make a cuboid 6 cm long, 2 cm wide and 1 cm high. He rebuilds the same 12 cubes into one 3 cm long, 2 cm wide and 2 cm high. Which has the greater volume?","wrong_answer":"The taller one","correct_answer":"They are equal: both are 12 cm³."},"cause":"The child judges by one striking dimension (height or length) instead of the total amount of space.","reveals":"Ask the child to compare two pictured arrangements of the same number of cubes, with 'the taller one' as a distractor.","help":"Have children rebuild one set of cubes into several shapes and count each time, recording that the total stays the same.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE.M_ADD_LAYERS","skill":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE","error":"The child adds the number of layers to the cubes in one layer instead of multiplying.","example":{"question":"One layer of a cuboid has 4 rows of 3 cubes, which is 12 cubes. There are 5 such layers. How many cubes are there altogether?","wrong_answer":"17","correct_answer":"60 (12 × 5)"},"cause":"The child does not yet see the layers as equal groups, so uses addition of the two numbers given.","reveals":"Use a table task: 'cubes in one layer' and 'number of layers' columns, then a 'total' column to fill in.","help":"Stack layers one by one and write 12, 24, 36, 48, 60. Then ask how to get 60 quickly, linking it to 12 × 5.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE.M_ROTATION_CHANGES_VOLUME","skill":"MATH.G5.MEASUR.VOLUME.CUBOID_FORMULA_DERIVE","error":"The child believes a box standing on its end has a different volume from the same box lying flat.","example":{"question":"A matchbox-shaped cuboid is 6 cm long, 2 cm wide and 1 cm high when lying flat. Achieng stands it on its end so it is 6 cm high. What is its volume now?","wrong_answer":"It is bigger now because it is taller.","correct_answer":"Still 12 cm³ (6 × 2 × 1 = 1 × 2 × 6)."},"cause":"The child links 'height' with size and does not understand that the order of the three dimensions does not change the product.","reveals":"Ask the child to compare and explain using two pictures of the same cuboid in different positions.","help":"Flip a real box, or use a digital model as the design suggests, and recalculate in each position to show the same product.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_CALC.M_ADD_DIMENSIONS","skill":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_CALC","error":"The child adds the length, width and height instead of multiplying them.","example":{"question":"Find the volume of a cuboid 5 cm long, 3 cm wide and 2 cm high.","wrong_answer":"10 cm³","correct_answer":"30 cm³"},"cause":"The child confuses volume with perimeter-style adding of lengths, or remembers 'use all three numbers' without the operation.","reveals":"Include the sum of the sides as a multiple-choice distractor. Ask the child to check by building it with cubes.","help":"Have the child build the 5 by 3 by 2 cuboid and count 30 cubes, then compare with their answer of 10.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_CALC.M_TWO_DIMENSIONS_ONLY","skill":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_CALC","error":"The child multiplies only the length and width, giving the area of the base as the volume.","example":{"question":"Find the volume of a cuboid 5 cm long, 3 cm wide and 2 cm high.","wrong_answer":"15 cm³","correct_answer":"30 cm³"},"cause":"The child carries over the area rule (rows × columns) from Grade 4 and forgets the layers.","reveals":"Include the base area as a distractor, and ask 'How many layers did you use?'","help":"Have children say each step aloud: 'cubes in one layer, times the number of layers'.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_PROBLEMS.M_MIXED_UNITS","skill":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_PROBLEMS","error":"The child multiplies a measurement in metres with others in centimetres without converting first.","example":{"question":"A wooden box is 1 m long, 10 cm wide and 5 cm high. What is its volume in cm³?","wrong_answer":"50 cm³","correct_answer":"5000 cm³ (100 × 10 × 5)"},"cause":"The child uses the numbers and ignores the units, so does not notice that 1 m is 100 cm.","reveals":"Use a word problem with one dimension in metres, with the unconverted product as a distractor.","help":"Have children circle every unit in the question and rewrite all lengths in cm before using the formula.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_PROBLEMS.M_MULTIPLY_ALL_NUMBERS","skill":"MATH.G5.MEASUR.VOLUME.CUBOID_VOLUME_PROBLEMS","error":"The child multiplies every number in the word problem, including ones that are not lengths.","example":{"question":"A box of chalk costs Sh 50. It is 10 cm long, 6 cm wide and 5 cm high. Find its volume.","wrong_answer":"15 000 cm³","correct_answer":"300 cm³"},"cause":"The child grabs numbers without thinking about what each one means in the situation.","reveals":"Include irrelevant information, such as a price or a number of boxes not asked about, and the product including it as a distractor.","help":"Have children list 'length = , width = , height = ' from the story before calculating, crossing out numbers that are not lengths.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBE_FORMULA_DERIVE.M_EDGE_EQUALS_VOLUME","skill":"MATH.G5.MEASUR.VOLUME.CUBE_FORMULA_DERIVE","error":"The child thinks a cube's volume in cm³ is the same number as its edge in cm. A related error is saying the volume cannot be found because only one measurement is given.","example":{"question":"A cube has edges of 3 cm. What is its volume?","wrong_answer":"3 cm³","correct_answer":"27 cm³ (3 × 3 × 3)"},"cause":"The child does not see that a cube has length, width and height, which are all equal to the one edge given.","reveals":"Ask a true-or-false question: 'A cube with 3 cm edges has a volume of 3 cm³.' Then ask the child to build it.","help":"Have children build a 3 cm cube from 1 cm cubes and count 27. Then label its length, width and height, all 3 cm.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBE_VOLUME_CALC.M_CUBE_S_TIMES_3","skill":"MATH.G5.MEASUR.VOLUME.CUBE_VOLUME_CALC","error":"The child multiplies the edge by 3 instead of multiplying the edge by itself three times.","example":{"question":"A cube-shaped box has edges of 4 cm. Find its volume.","wrong_answer":"12 cm³","correct_answer":"64 cm³ (4 × 4 × 4)"},"cause":"The child mixes up 'use s three times' with 's times 3', made worse by seeing the ³ in cm³.","reveals":"Include s × 3 as a multiple-choice distractor.","help":"Have children write the full s × s × s with the number in every place, for example 4 × 4 × 4, before calculating.","status":"draft"},{"code":"MATH.G5.MEASUR.VOLUME.CUBE_VOLUME_CALC.M_CUBE_S_SQUARED","skill":"MATH.G5.MEASUR.VOLUME.CUBE_VOLUME_CALC","error":"The child works out s × s, the area of one face, and gives that as the volume.","example":{"question":"A cube-shaped box has edges of 4 cm. Find its volume.","wrong_answer":"16 cm³","correct_answer":"64 cm³"},"cause":"The child carries over the area of a square from earlier work and forgets the layers.","reveals":"Include s × s as a distractor, and ask how many layers a 4 cm cube has.","help":"Link it to layers: 4 × 4 = 16 cubes in one layer, and there are 4 layers, so 16 × 4 = 64.","status":"draft"}]},{"code":"MATH.G5.MEASUR.CAPACITY","number":"2.4","strand":"Measurement","sub_strand":"Capacity","sequence":204,"lessons":12,"content_topics":["Millilitre as a unit of measuring capacity","Measuring capacity in millilitres","Conversions in capacity","Addition and subtraction in capacity"],"learning_experiences":["collect safe small containers and read the unit of measurements indicated in them","use smaller containers with capacity in millilitres to fill bigger containers","identify containers with capacity of 5 millilitres and use them to fill other containers","share tasks with peers while filling small containers with water and measure the capacity in millilitres using a container graduated in millilitres","use digital device or other resources to find the relationship between millilitres and litres","use a container labelled in millilitres to fill a container labelled in litres and find the relationship","carry out operations involving addition, subtraction, multiplication and division of litres and millilitres by whole numbers"],"key_inquiry_questions":["Where are litres and millilitres used in day-today life?"],"core_competences":"Critical thinking and problem solving: learner converts units of capacity, relate units of capacity and work questions involving capacity.","values":"Responsibility: learner shares tasks with peers while filling small containers with water and measure the capacity in millilitres using a container graduated in millilitres.","pcis":"Social cohesion: learner works with peers to estimate and measure capacity of different containers using a container graduated in millilitres.","links":"The learner is able to relate concept of capacity to water conservation in Science and Technology.","design_notes":"Outcome j (appreciate use of litres and millilitres in measuring capacity in real life) is attitudinal and is not mapped to a skill.\n\nNo number limits: none of outcomes a–i gives number sizes, multipliers or divisors. All limits in 'what_mastery_looks_like' (e.g. up to 20 l, multipliers and divisors up to 9, whole-millilitre division answers) are proposed professional judgement, not KICD wording. The ½ l, ¼ l and ¾ l equivalences in G5_L_ML_RELATIONSHIP are likewise a proposed bridge from G4:2.4b; outcome d itself states only the relationship between litres and millilitres.\n\nOverlap between b and c: outcome c ('estimate and measure capacity in millilitres') repeats the measuring in b. I have split this into measuring with a scale (b, c), measuring by filling (b) and estimating (c).\n\nWording differences: outcomes a–h say 'real-life situations' but i says 'different situations'. I have treated these as equivalent.\n\nScope of division: outcome i covers dividing by whole numbers only, i.e. sharing. Quotition problems such as 'How many 250 ml cups can be filled from 2 l?' divide one capacity by another, so they are arguably outside i. They could be included as an extension (proposed).\n\nGrade 5 versus Grade 6 conversion: Grade 6 2.3b and 2.3c repeat conversion between litres and millilitres. I have therefore kept Grade 5 conversion to whole numbers and mixed l-and-ml forms, with no decimal litres (proposed). The design does not state this boundary. G6_UNIT_CONVERSIONS and G6_CAPACITY are listed only as forward overlaps.\n\nPrerequisites not codable: number prerequisites such as multiplying and dividing by 1 000, place value to thousands, and column methods with regrouping sit in the Numbers strand, whose codes were not supplied, so they cannot be cited. Many errors listed here are really place-value or regrouping errors showing up in a capacity context. A recurring source is transfer of the Grade 4 rule 1 m = 100 cm; teachers should contrast 100 and 1 000 explicitly.\n\nDesign text issues: the key inquiry question contains a text-layer artefact ('Inquiry Question(s)') and reads 'day-today', which should be 'day-to-day'. The learning experience about 'containers with capacity of 5 millilitres' most likely refers to teaspoons or medicine spoons.\n\nCapacity versus volume: the existing HOREB skill G4_MASS combines mass and capacity units, so its overlap with this sub-strand is only partial.","outcomes":[{"code":"MATH.G5.MEASUR.CAPACITY.a","letter":"a","text":"identify the millilitre as a unit of measuring capacity in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.b","letter":"b","text":"measure capacity in millilitres in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.c","letter":"c","text":"estimate and measure capacity in millilitres in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.d","letter":"d","text":"identify the relationship between litres and millilitres in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.e","letter":"e","text":"convert litres to millilitres and millilitres to litres in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.f","letter":"f","text":"add litres and millilitres in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.g","letter":"g","text":"subtract litres and millilitres in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.h","letter":"h","text":"multiply litres and millilitres by whole numbers in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.i","letter":"i","text":"divide litres and millilitres by whole numbers in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.CAPACITY.j","letter":"j","text":"appreciate use of litres and millilitres in measuring capacity in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","name":"Recognise the millilitre as a unit of capacity and where it is used","outcomes":["MATH.G5.MEASUR.CAPACITY.a"],"mastery":"The child reads and writes 'ml' and 'millilitre' on real containers such as a 5 ml medicine spoon, a 300 ml soda bottle or a 500 ml milk packet. They can tell a capacity label (ml, l) from a mass label (g, kg) or a length label (cm, m). They choose ml for small amounts (spoonfuls, cups, bottles) and l for large ones (jerrycans, buckets, drums). Proposed limit: everyday items up to a 20 l jerrycan.","question_forms":["read the label: which unit is shown","odd one out: which label shows capacity","choose the sensible unit (ml or l)","list real-life items measured in ml"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_CAPACITY","G4_MASS"],"prerequisites":[{"requires":"MATH.G4.MEASUR.CAPACITY.a","kind":"outcome","strength":"essential","reason":"The child must already know the litre to see the millilitre as a smaller unit of the same quantity.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.a","kind":"outcome","strength":"helpful","reason":"Meeting the centimetre as a small everyday unit of length is a parallel experience.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_SCALE","name":"Measure capacity in millilitres using a graduated container","outcomes":["MATH.G5.MEASUR.CAPACITY.b","MATH.G5.MEASUR.CAPACITY.c"],"mastery":"The child pours liquid into a measuring jug, cylinder, syringe or medicine cup marked in ml. They read the level at eye height and work out what each unlabelled division is worth (for example 10, 25, 50 or 100 ml). Proposed limit: scales up to 1 000 ml.","question_forms":["read the scale from a picture","practical: measure and record","work out the value of one small division","mark a given amount on a drawn scale"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","kind":"skill","strength":"essential","reason":"The child must recognise ml markings before reading them on a scale.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"helpful","reason":"Reading a ruler in centimetres builds the skill of reading a marked scale.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING","name":"Measure capacity in millilitres by filling with a smaller known container","outcomes":["MATH.G5.MEASUR.CAPACITY.b"],"mastery":"The child fills a container using a smaller container of known capacity, such as a 5 ml spoon or a 100 ml cup. They count the fills and work out the total in ml by repeated addition or multiplication. They understand that a smaller measuring container needs more fills. Proposed limit: up to 20 fills.","question_forms":["count fills and find the capacity","how many fills are needed","which measuring cup is bigger (compare the number of fills)","practical: fill and record"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","kind":"skill","strength":"essential","reason":"The child needs to know that a 5 ml spoon or a 100 ml cup is a known amount.","status":"proposed"},{"requires":"MATH.G4.MEASUR.CAPACITY.a","kind":"outcome","strength":"essential","reason":"Measuring by repeatedly filling a litre container was the Grade 4 method.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_ESTIMATE","name":"Estimate capacity in millilitres and check by measuring","outcomes":["MATH.G5.MEASUR.CAPACITY.c"],"mastery":"The child gives a sensible estimate in ml for common containers using benchmarks such as a 5 ml spoon, a 250 ml cup or a 500 ml bottle. They then measure, compare the estimate with the measurement and improve later estimates. They do not judge capacity by height alone. Proposed limit: containers up to 1 l.","question_forms":["choose the best estimate (multiple choice)","estimate then measure, and record the difference","order containers by estimated capacity","compare and explain: which holds more"],"thinking":["reasoning"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_SCALE","kind":"skill","strength":"essential","reason":"Estimates must be checked by accurate measurement.","status":"proposed"},{"requires":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING","kind":"skill","strength":"helpful","reason":"Filling with known cups and spoons builds the benchmarks used for estimating.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP","name":"Know and explain that 1 litre = 1 000 millilitres (and ½ l = 500 ml, ¼ l = 250 ml)","outcomes":["MATH.G5.MEASUR.CAPACITY.d"],"mastery":"The child states that 1 l = 1 000 ml and can show it practically. For example, they know that four 250 ml cups or two 500 ml bottles fill a 1 l container. Proposed extension linking to Grade 4: ½ l = 500 ml, ¼ l = 250 ml and ¾ l = 750 ml.","question_forms":["fill in: 1 l = ___ ml","how many 250 ml cups fill 1 l","true or false with reason","practical: fill a 1 l container with a ml container"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_CAPACITY","G4_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","kind":"skill","strength":"essential","reason":"Both units must be known before they can be related.","status":"proposed"},{"requires":"MATH.G4.MEASUR.CAPACITY.b","kind":"outcome","strength":"essential","reason":"Experience with ½ l and ¼ l containers underpins 500 ml and 250 ml.","status":"proposed"},{"requires":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING","kind":"skill","strength":"helpful","reason":"The design suggests finding the relationship by filling a litre container with ml containers.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.c","kind":"outcome","strength":"helpful","reason":"The metre–centimetre relationship is a parallel, though the multiplier differs (100, not 1 000).","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML","name":"Convert litres (and litres with millilitres) to millilitres","outcomes":["MATH.G5.MEASUR.CAPACITY.e"],"mastery":"The child converts whole litres and mixed amounts to ml, for example 4 l = 4 000 ml and 3 l 45 ml = 3 045 ml. They place zeros correctly when the ml part has fewer than three digits. Proposed limit: up to 20 l, whole numbers only (no decimal litres).","question_forms":["fill in the missing number","word problem: how many ml in a jerrycan","match equal amounts","spot the error"],"thinking":["procedure"],"horeb_skill_ids":["G5_CAPACITY","G6_UNIT_CONVERSIONS","G6_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP","kind":"skill","strength":"essential","reason":"Converting depends on knowing 1 l = 1 000 ml.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"Converting metres to centimetres follows the same procedure with a different multiplier.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MONEY.a","kind":"outcome","strength":"helpful","reason":"Converting shillings to cents is another bigger-to-smaller unit conversion.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L","name":"Convert millilitres to litres (and litres with millilitres)","outcomes":["MATH.G5.MEASUR.CAPACITY.e"],"mastery":"The child converts exact thousands of ml to l (6 000 ml = 6 l). They also write other amounts as litres and ml (3 500 ml = 3 l 500 ml; 2 040 ml = 2 l 40 ml). They recognise that amounts under 1 000 ml are less than 1 l. Proposed limit: up to 20 000 ml, no decimal litres.","question_forms":["fill in: ___ l ___ ml","word problem: how many litres","compare amounts given in different units","spot the error"],"thinking":["procedure"],"horeb_skill_ids":["G5_CAPACITY","G6_UNIT_CONVERSIONS","G6_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP","kind":"skill","strength":"essential","reason":"Grouping ml into litres depends on knowing 1 000 ml = 1 l.","status":"proposed"},{"requires":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML","kind":"skill","strength":"helpful","reason":"Conversion in the other direction lets the child check answers.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"Converting centimetres to metres is the parallel procedure.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML","name":"Add litres and millilitres","outcomes":["MATH.G5.MEASUR.CAPACITY.f"],"mastery":"The child adds amounts in l and ml in columns, with and without regrouping 1 000 ml as 1 l. They write the answer in standard form, for example 2 l 700 ml + 1 l 500 ml = 4 l 200 ml. They solve one- or two-step real-life problems. Proposed limit: totals up to 50 l.","question_forms":["column addition","word problem: total milk or water collected","missing number","spot the error"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L","kind":"skill","strength":"essential","reason":"Regrouping 1 000 ml as 1 l is needed when the ml column totals 1 000 or more.","status":"proposed"},{"requires":"MATH.G4.MEASUR.CAPACITY.c","kind":"outcome","strength":"essential","reason":"Adding whole litres in context comes first.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.f","kind":"outcome","strength":"helpful","reason":"Adding metres and centimetres uses the same two-unit column method.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML","name":"Subtract litres and millilitres","outcomes":["MATH.G5.MEASUR.CAPACITY.g"],"mastery":"The child subtracts amounts in l and ml, with and without regrouping 1 l as 1 000 ml. This includes subtracting from whole litres (5 l − 350 ml = 4 l 650 ml). They solve real-life 'how much is left' and 'difference' problems. Proposed limit: amounts up to 50 l.","question_forms":["column subtraction","word problem: how much is left","word problem: find the difference","missing number","spot the error"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML","kind":"skill","strength":"essential","reason":"Decomposing 1 l into 1 000 ml is needed when regrouping.","status":"proposed"},{"requires":"MATH.G4.MEASUR.CAPACITY.c","kind":"outcome","strength":"essential","reason":"Subtracting whole litres in context comes first.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.g","kind":"outcome","strength":"helpful","reason":"Subtracting metres and centimetres uses the same two-unit method.","status":"proposed"},{"requires":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML","kind":"skill","strength":"helpful","reason":"Addition is used to check subtraction answers.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML","name":"Multiply litres and millilitres by a whole number","outcomes":["MATH.G5.MEASUR.CAPACITY.h"],"mastery":"The child multiplies an amount in l and ml by a whole number. They multiply the ml first, regroup each 1 000 ml as 1 l, then multiply the litres and add the carried litres, for example 2 l 600 ml × 3 = 7 l 800 ml. Proposed limit: multipliers up to 9, products up to 100 l.","question_forms":["column multiplication","word problem: equal containers (e.g. 4 bottles of 1 l 250 ml)","missing number","spot the error"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L","kind":"skill","strength":"essential","reason":"The ml product usually has to be regrouped into litres.","status":"proposed"},{"requires":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML","kind":"skill","strength":"helpful","reason":"Multiplication can be understood as repeated addition of the same amount.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.h","kind":"outcome","strength":"helpful","reason":"Multiplying metres and centimetres is the parallel procedure.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML","name":"Divide litres and millilitres by a whole number","outcomes":["MATH.G5.MEASUR.CAPACITY.i"],"mastery":"The child divides an amount in l and ml by a whole number. They change any remaining litres to 1 000 ml each and add them to the ml before dividing, for example 5 l 400 ml ÷ 2 = 2 l 700 ml. They solve equal-sharing problems. Proposed limit: divisors up to 9, answers in whole millilitres.","question_forms":["long or short division","word problem: sharing equally among people or containers","check by multiplying","spot the error"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_CAPACITY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML","kind":"skill","strength":"essential","reason":"Remaining litres must be changed to 1 000 ml each before dividing the ml.","status":"proposed"},{"requires":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML","kind":"skill","strength":"helpful","reason":"Multiplication is used to check division answers.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.i","kind":"outcome","strength":"helpful","reason":"Dividing metres and centimetres is the parallel procedure.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT.M_BIGGER_NUMBER_MEANS_MORE","skill":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","error":"Compares the numbers and ignores the units, so thinks 500 ml is more than 2 l.","example":{"question":"Which holds more: a 500 ml bottle of water or a 2 l bottle of cooking oil?","wrong_answer":"The 500 ml bottle","correct_answer":"The 2 l bottle (2 l = 2 000 ml)"},"cause":"The child focuses on the size of the number and does not see the unit as part of the measurement.","reveals":"Pair a large number with a small unit against a small number with a large unit, and offer both as options.","help":"Put a real 500 ml bottle beside a 2 l bottle and pour one into the other, then always read the number and the unit together aloud.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT.M_MASS_LABEL_AS_CAPACITY","skill":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","error":"Treats any number on a package label as capacity, including grams.","example":{"question":"Which label shows capacity: '500 g' on a sugar packet, '500 ml' on a milk packet, or '50 cm' on a ruler?","wrong_answer":"500 g","correct_answer":"500 ml"},"cause":"The child mixes up the unit symbols and links 'how much' with any label.","reveals":"Use an odd-one-out or sorting task with g, kg, ml, l and cm labels from real Kenyan packaging.","help":"Sort real packets and bottles into 'how heavy' (g, kg) and 'how much liquid it holds' (ml, l) piles.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT.M_WRONG_UNIT_FOR_SMALL_AMOUNT","skill":"MATH.G5.MEASUR.CAPACITY.ML_IDENTIFY_UNIT","error":"Chooses litres for tiny amounts, or ml for very large ones.","example":{"question":"A nurse gives a child one spoon of cough syrup. Is the dose 5 ml or 5 l?","wrong_answer":"5 l","correct_answer":"5 ml"},"cause":"The child has no mental picture of how much 1 ml or 1 l actually is.","reveals":"Ask the child to choose the sensible unit for a familiar item, with one absurd option.","help":"Show a 5 ml medicine spoon next to a 1 l packet of milk and let pupils pour both.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_SCALE.M_EACH_MARK_IS_ONE","skill":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_SCALE","error":"Counts each small unlabelled mark on a scale as 1 ml.","example":{"question":"A jug is labelled 200 ml and 300 ml, with three small marks in between. The water is at the third small mark above 200 ml. How much water is there?","wrong_answer":"203 ml","correct_answer":"275 ml (each small mark is 25 ml)"},"cause":"The child carries over the habit of counting ones on a ruler and does not work out what each division is worth.","reveals":"Use a scale where divisions are worth 25 or 50 ml and include the 'counted ones' answer as a distractor.","help":"Before reading, have pupils find the difference between two labelled marks, count the spaces and divide to find each mark's value.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_SCALE.M_READS_FROM_ABOVE","skill":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_SCALE","error":"Reads the level while looking down at the jug, or with the jug tilted, and gets a reading that is too high or too low.","example":{"question":"Juma looks down into a measuring jug from above and reads 300 ml. With his eyes level with the water on a flat table, the jug shows 250 ml. What is the correct reading?","wrong_answer":"300 ml","correct_answer":"250 ml"},"cause":"The child does not know that a reading must be taken at eye level on a flat surface.","reveals":"In a practical task, the teacher watches how the child reads, then compares pupils' readings of the same jug.","help":"Teach the routine 'jug flat on the table, crouch until your eyes are level with the water, then read'.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING.M_GIVES_NUMBER_OF_FILLS","skill":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING","error":"Gives the number of fills as the capacity, instead of multiplying by the size of the measure.","example":{"question":"Akinyi fills a cup using a 5 ml medicine spoon 8 times. What is the capacity of the cup?","wrong_answer":"8 ml","correct_answer":"40 ml"},"cause":"The child counts the fills without linking each fill to its value in ml.","reveals":"Offer the number of fills as a distractor in multiple choice.","help":"Have pupils say a running total aloud as they pour: '5 ml, 10 ml, 15 ml ...'.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING.M_MORE_FILLS_BIGGER_CUP","skill":"MATH.G5.MEASUR.CAPACITY.ML_MEASURE_BY_FILLING","error":"Thinks the measuring container that needs more fills is the bigger one.","example":{"question":"Cup A fills a jug in 4 cupfuls. Cup B fills the same jug in 6 cupfuls. Which cup holds more?","wrong_answer":"Cup B","correct_answer":"Cup A"},"cause":"The child assumes 'bigger number means bigger' and does not grasp the inverse relationship between unit size and count.","reveals":"Use a compare-and-explain question where the larger count belongs to the smaller cup.","help":"Fill the same jug with a large cup and a small cup and ask why the small cup needed more pours.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_ESTIMATE.M_NO_BENCHMARKS","skill":"MATH.G5.MEASUR.CAPACITY.ML_ESTIMATE","error":"Gives estimates that are wildly unrealistic.","example":{"question":"Choose the best estimate for a cup of chai: 25 ml, 250 ml or 2 500 ml.","wrong_answer":"2 500 ml","correct_answer":"250 ml"},"cause":"The child has no remembered reference amounts (5 ml spoon, 250 ml cup, 500 ml bottle, 1 l packet).","reveals":"Offer options that differ by a factor of ten.","help":"Display a class 'benchmark shelf' of a 5 ml spoon, 250 ml cup, 500 ml bottle and 1 l packet, and refer to it before every estimate.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ML_ESTIMATE.M_TALLER_HOLDS_MORE","skill":"MATH.G5.MEASUR.CAPACITY.ML_ESTIMATE","error":"Judges capacity by height alone, so thinks a tall thin container holds more than a short wide one.","example":{"question":"A tall thin glass holds 200 ml and a short wide bowl holds 500 ml. Before measuring, which do you think holds more?","wrong_answer":"The tall glass","correct_answer":"The short wide bowl"},"cause":"The child attends to one dimension (height) and ignores width.","reveals":"Use a compare task with a tall narrow container and a short wide one, then check by pouring.","help":"Pour the full glass into the bowl so pupils see the bowl is not yet full.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP.M_LITRE_IS_100_ML","skill":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP","error":"States that 1 l = 100 ml.","example":{"question":"1 l = ___ ml","wrong_answer":"100","correct_answer":"1 000"},"cause":"The child over-generalises from Grade 4 metres and centimetres (1 m = 100 cm).","reveals":"Offer 100 as a distractor, or ask 'How many 100 ml cups fill a 1 l packet?' (answer: 10).","help":"Pour ten 100 ml cupfuls into a 1 l container together and record 10 × 100 ml = 1 000 ml.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP.M_HALF_LITRE_50","skill":"MATH.G5.MEASUR.CAPACITY.L_ML_RELATIONSHIP","error":"Gives ½ l as 50 ml and ¼ l as 25 ml.","example":{"question":"½ l = ___ ml","wrong_answer":"50","correct_answer":"500"},"cause":"The child halves 100 instead of 1 000, linked to the 1 l = 100 ml idea.","reveals":"Ask the child to match ½ l and ¼ l containers to ml amounts, with 50 and 25 among the options.","help":"Use the Grade 4 ½ l and ¼ l containers and pour them into a ml-graduated jug to read 500 ml and 250 ml.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML.M_MULTIPLY_BY_100","skill":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML","error":"Multiplies by 100 (adds two zeros) when changing litres to ml.","example":{"question":"A jerrycan holds 4 l. How many ml is that?","wrong_answer":"400 ml","correct_answer":"4 000 ml"},"cause":"The child uses the m–cm multiplier from Grade 4.","reveals":"Offer the ×100 answer as a distractor.","help":"Have pupils write '1 l = 1 000 ml' at the top of every conversion and multiply by that fact.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML.M_MIXED_UNIT_PLACEHOLDER","skill":"MATH.G5.MEASUR.CAPACITY.CONVERT_L_TO_ML","error":"Joins the digits together when converting a mixed amount, missing out the zero placeholder.","example":{"question":"2 l 50 ml = ___ ml","wrong_answer":"250 ml (or 2 500 ml)","correct_answer":"2 050 ml"},"cause":"The child writes the litres and then the ml side by side without seeing that the ml must fill three places.","reveals":"Use ml parts with one or two digits (5 ml, 50 ml) and include the joined-digit answers as distractors.","help":"Convert in two steps, 2 l = 2 000 ml, then 2 000 + 50 = 2 050 ml, using a place-value chart.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L.M_DIVIDE_BY_100","skill":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L","error":"Treats every 100 ml as a litre when changing ml to litres.","example":{"question":"Write 3 500 ml in litres and millilitres.","wrong_answer":"35 l","correct_answer":"3 l 500 ml"},"cause":"The child believes 100 ml = 1 l, carried over from cm and m.","reveals":"Use amounts like 3 500 ml or 750 ml; answers of 35 l or 7 l 50 ml expose the error.","help":"Ask 'Is this more or less than the 1 l packet?' before converting, and group in thousands.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L.M_SPLIT_DIGITS_WRONG","skill":"MATH.G5.MEASUR.CAPACITY.CONVERT_ML_TO_L","error":"Splits the number in the wrong place, for example taking the first two digits as litres.","example":{"question":"Write 2 040 ml in litres and millilitres.","wrong_answer":"20 l 40 ml","correct_answer":"2 l 40 ml"},"cause":"The child splits the number by eye rather than by place value, so does not know the ml part is the last three digits.","reveals":"Use numbers with a zero in the hundreds place (2 040, 4 006).","help":"Have pupils mark off three digits from the right for ml, then read what remains as litres.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML.M_ADD_REGROUP_AT_100","skill":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML","error":"Regroups into a litre when the ml column passes 100 rather than 1 000.","example":{"question":"Wanjiru's cow gave 2 l 70 ml of milk in the morning and 1 l 50 ml in the evening. How much milk altogether?","wrong_answer":"4 l 20 ml","correct_answer":"3 l 120 ml"},"cause":"The child applies the m–cm rule (100 cm = 1 m) to ml.","reveals":"Use an ml total between 100 and 999 so no regrouping is actually needed.","help":"Before carrying, ask 'Is the ml total 1 000 or more?' and carry only if it is. Also insist that answers such as 3 l 1 200 ml be rewritten as 4 l 200 ml.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML.M_COLUMNS_MISALIGNED","skill":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML","error":"Lines up the ml digits from the left instead of by place value.","example":{"question":"3 l 250 ml + 45 ml","wrong_answer":"3 l 700 ml","correct_answer":"3 l 295 ml"},"cause":"The child places 45 under 25 instead of under 50 because the place value of each digit is not secure.","reveals":"Add a two-digit ml amount to a three-digit one.","help":"Use a column grid headed l | hundreds | tens | ones of ml and write each digit in its place.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML.M_ADD_UNLIKE_UNITS","skill":"MATH.G5.MEASUR.CAPACITY.ADD_L_ML","error":"Adds litres and millilitres as if they were the same unit.","example":{"question":"Mama poured 2 l of water into a sufuria and then 300 ml more. How much water is in the sufuria?","wrong_answer":"302 ml","correct_answer":"2 l 300 ml (2 300 ml)"},"cause":"The child ignores the units and simply adds the numbers.","reveals":"Mix units in a word problem without lining them up in columns for the child.","help":"Have pupils rewrite each amount in l and ml columns, or all in ml, before adding.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML.M_SMALLER_FROM_LARGER","skill":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML","error":"Takes the smaller digit from the larger in each column instead of regrouping.","example":{"question":"5 l 200 ml − 2 l 650 ml","wrong_answer":"3 l 450 ml (or 3 l 550 ml)","correct_answer":"2 l 550 ml"},"cause":"The child believes you always subtract the smaller number from the larger, and avoids regrouping.","reveals":"Make the ml part being subtracted larger than the ml part it is taken from.","help":"Model exchanging 1 l for 1 000 ml with real containers, then check by adding the answer back.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML.M_BORROW_100","skill":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML","error":"Regroups 1 l as 100 ml when subtracting.","example":{"question":"4 l 30 ml − 1 l 80 ml","wrong_answer":"2 l 50 ml","correct_answer":"2 l 950 ml"},"cause":"The child uses the m–cm exchange rate.","reveals":"Choose ml values under 100 so that exchanging 100 ml happens to give a whole-number answer.","help":"Write '1 l = 1 000 ml' beside the sum and cross out 1 litre, adding 1 000 to the ml column.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML.M_SUBTRACT_IGNORING_UNITS","skill":"MATH.G5.MEASUR.CAPACITY.SUBTRACT_L_ML","error":"Subtracts the numbers without considering units when taking ml from whole litres.","example":{"question":"A 5 l jerrycan of water is full. Otieno uses 350 ml to wash his hands. How much water is left?","wrong_answer":"345 ml","correct_answer":"4 l 650 ml"},"cause":"The child sees 5 and 350 as plain numbers and reverses the subtraction to make it 'work'.","reveals":"Use a whole-litre amount minus an ml amount in a 'how much is left' problem.","help":"Have pupils first rewrite 5 l as 4 l 1 000 ml (or 5 000 ml), then subtract.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML.M_MULTIPLY_LITRES_ONLY","skill":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML","error":"Multiplies only the litres and copies the ml part unchanged.","example":{"question":"One bottle holds 2 l 400 ml of juice. How much do 3 bottles hold?","wrong_answer":"6 l 400 ml","correct_answer":"7 l 200 ml"},"cause":"The child treats the ml part as a label rather than part of the quantity being multiplied.","reveals":"Ask the child to check by repeated addition and compare the results.","help":"Write the problem as repeated addition (2 l 400 ml + 2 l 400 ml + 2 l 400 ml) before showing the short method.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML.M_MULT_REGROUP_AT_100","skill":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML","error":"Turns the ml product into litres by dividing by 100.","example":{"question":"1 l 350 ml × 4","wrong_answer":"18 l (treats 1 400 ml as 14 l)","correct_answer":"5 l 400 ml"},"cause":"The child uses the m–cm rate when regrouping.","reveals":"Choose a product in the ml column between 1 000 and 9 999.","help":"After multiplying the ml, have pupils convert the result separately (1 400 ml = 1 l 400 ml) before going on.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML.M_CARRY_BEFORE_MULTIPLY","skill":"MATH.G5.MEASUR.CAPACITY.MULTIPLY_L_ML","error":"Adds the carried litre before multiplying the litres, instead of after.","example":{"question":"2 l 600 ml × 3","wrong_answer":"9 l 800 ml","correct_answer":"7 l 800 ml"},"cause":"The child has a known whole-number multiplication error with the order of carrying.","reveals":"Use any problem where the ml product needs regrouping; the answer is too big by the multiplier minus one litres.","help":"Teach 'multiply the litres first, then add what you carried', and check with repeated addition.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML.M_DROP_REMAINDER_LITRES","skill":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML","error":"Ignores the remaining litre(s) after dividing the litres.","example":{"question":"5 l 400 ml of milk is shared equally between 2 families. How much does each family get?","wrong_answer":"2 l 200 ml","correct_answer":"2 l 700 ml"},"cause":"The child divides each unit separately and does not know what to do with the remainder.","reveals":"Use a litre amount not exactly divisible by the divisor, then ask the child to check by multiplying.","help":"Have pupils say 'remainder 1 l becomes 1 000 ml' and add it to the ml before dividing, then check: 2 l 700 ml × 2 = 5 l 400 ml.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML.M_REMAINDER_AS_100ML","skill":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML","error":"Converts the remaining litre to 100 ml instead of 1 000 ml.","example":{"question":"5 l 400 ml ÷ 2","wrong_answer":"2 l 250 ml","correct_answer":"2 l 700 ml"},"cause":"The child uses the m–cm rate.","reveals":"Use a divisor that leaves a litre remainder; checking by multiplication gives 4 l 500 ml, not 5 l 400 ml.","help":"Always check division by multiplying back and comparing with the starting amount.","status":"draft"},{"code":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML.M_DIVIDE_LITRES_ONLY","skill":"MATH.G5.MEASUR.CAPACITY.DIVIDE_L_ML","error":"Divides only the litres and leaves the ml unchanged.","example":{"question":"6 l 300 ml of water is poured equally into 3 buckets. How much is in each bucket?","wrong_answer":"2 l 300 ml","correct_answer":"2 l 100 ml"},"cause":"The child sees the ml part as a label rather than part of the quantity being shared.","reveals":"Use an amount where the litres divide exactly, so the only error is in the ml.","help":"Model sharing with real containers so pupils see the 300 ml must also be shared.","status":"draft"}]},{"code":"MATH.G5.MEASUR.MASS","number":"2.5","strand":"Measurement","sub_strand":"Mass","sequence":205,"lessons":12,"content_topics":["Gramme as a unit of measuring mass","Measuring mass in grammes","Conversions in mass","Operations in mass"],"learning_experiences":["identify different small containers with mass labelled grammes","use a spoon or bottle top scoop sand or soil which is estimated to be about 5 grammes","use the spoon or the bottle top to fill other container with soil or sand and estimate their masses","discuss with peers to establish the relationship between the kilogramme and the grammes using a beam balance or electronic weighing machine (1kg = 1000g)","express various values of mass in kilogrammes to grammes and vice versa","convert kilogrammes to grammes and grammes to kilogrammes in real life","determine mass of items in grammes and kilogrammes by addition, subtraction, multiplication and division different in different situations","play games involving mass by measuring mass of different objects or substances using improvised weighing balance. Experiences"],"key_inquiry_questions":["What is the importance of measuring mass?"],"core_competences":"Communication and collaboration: learner teams up with peers to estimate and measure mass of items in grammes using a beam balance or electronic weighing machine.","values":"Respect: learner teams up with peers to estimate and measure mass of items in grammes using a beam balance or electronic weighing machine.","pcis":"Social cohesion: learner teams up with peers to estimate and measure mass of items in grammes.","links":"Learner is able to relate concept of mass to measuring mass in grammes in Science and Technology.","design_notes":"Attitudinal outcome j ('appreciate use of kilogrammes and grammes in measuring mass in real life') has no skill. It is best observed during practical weighing and market or shop role-play, guided by the key inquiry question 'What is the importance of measuring mass?'.\n\nThe outcomes set no number limits, so every size limit in the skills is marked 'proposed': masses up to 1000 g for measuring and estimating, up to 10 kg for conversions, up to 100 kg for operations, small whole-number multipliers and divisors, and exact division. The design does not say whether decimal kilogrammes (e.g. 2.5 kg) are expected; the proposed skills use the 'kg and g' form only, so check this against the teacher's guide before assessing decimals.\n\nOutcomes b ('measure mass in grammes') and c ('estimate and measure mass in grammes') overlap. They have been separated as measuring skills (b) and estimating with checking (c).\n\nReading dial or spring scales (G5_MASS_READ_SCALE) is proposed. The learning experiences name beam balances, electronic weighing machines and improvised balances, but scale pictures are the usual way to assess measuring on paper.\n\nThe 5 g bottle-top or spoon benchmark comes from the design. It is approximate, and real fills vary, so it suits estimation, not exact work.\n\nOutcome h reads 'kilogramme' (singular); this is taken as kilogrammes. Grade 4 uses the spelling 'kilogram' while Grade 5 uses 'kilogramme'; this map uses Grade 5's spelling.\n\nGrade 4 whole-number skills (column addition with regrouping, multiplication, division with remainders) are essential to f to i, but no Number strand codes were supplied, so they are not cited. The Grade 4 length outcomes (2.1c to 2.1i) are linked as helpful parallels. They are also the main source of the '100 instead of 1000' errors listed above.\n\nThe existing HOREB skill G5_MASS covers this whole sub-strand at a coarse level. G6_UNIT_CONVERSIONS overlaps the relationship and conversion skills, and G6_MASS (tonnes) builds directly on them.","outcomes":[{"code":"MATH.G5.MEASUR.MASS.a","letter":"a","text":"identify the gramme as a unit of measuring mass in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.b","letter":"b","text":"measure mass in grammes in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.c","letter":"c","text":"estimate and measure mass in grammes in different situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.d","letter":"d","text":"identify the relationship between the kilogramme and the gramme in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.e","letter":"e","text":"convert kilogrammes to grammes and grammes to kilogrammes in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.f","letter":"f","text":"add grammes and kilogrammes in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.g","letter":"g","text":"subtract grammes and kilogrammes in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.h","letter":"h","text":"multiply grammes and kilogramme by whole numbers in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.i","letter":"i","text":"divide grammes and kilogrammes by whole numbers in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MASS.j","letter":"j","text":"appreciate use of kilogrammes and grammes in measuring mass in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE","name":"Recognise the gramme and read mass labels","outcomes":["MATH.G5.MEASUR.MASS.a"],"mastery":"The child names the gramme and its symbol g, tells it apart from kg, and reads mass labels on everyday packets (for example 500 g salt, 250 g tea leaves, 2 kg maize flour). Proposed: labels up to 1000 g and whole kilogrammes.","question_forms":["read the label: what is the mass of this packet?","match symbol to unit name","sort labels into g and kg","spot the label that is not a mass (ml, l)"],"thinking":["recall"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G4.MEASUR.MASS.a","kind":"outcome","strength":"essential","reason":"Knowing the kilogramme as a unit is the basis for meeting a smaller unit.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_CHOOSE_UNIT","name":"Choose grammes or kilogrammes for a real object","outcomes":["MATH.G5.MEASUR.MASS.a"],"mastery":"The child decides sensibly whether an object's mass is better measured in grammes (an egg, a pencil, a packet of chewing gum) or in kilogrammes (a sack of potatoes, a child). They explain the choice by how heavy the object is, not by how big it looks.","question_forms":["choose the best unit","complete the sentence with g or kg","odd one out","explain your choice"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE","kind":"skill","strength":"essential","reason":"The child must know both units before choosing between them.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MASS.a","kind":"outcome","strength":"helpful","reason":"Having handled a 1 kg mass gives a feel for what counts as heavy.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE","name":"Measure mass in grammes with a beam balance or improvised balance","outcomes":["MATH.G5.MEASUR.MASS.b"],"mastery":"Using a beam balance or an improvised balance with gramme masses (for example 10 g, 20 g, 50 g, 100 g, 200 g, 500 g), the child balances an object and finds its mass by adding the values of the masses used. They also read the display of an electronic scale in grammes. Proposed: objects up to 1000 g.","question_forms":["practical: weigh and record","picture of a balanced beam: find the mass","which side is heavier?","which masses would balance 350 g?"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G4.MEASUR.MASS.a","kind":"outcome","strength":"essential","reason":"Grade 4 children already balanced objects against a kilogramme mass.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MASS.b","kind":"outcome","strength":"helpful","reason":"Using ½ kg and ¼ kg masses builds the idea of combining smaller masses.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE","kind":"skill","strength":"essential","reason":"Measurements must be recorded with the correct unit.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_READ_SCALE","name":"Read a weighing scale marked in grammes","outcomes":["MATH.G5.MEASUR.MASS.b"],"mastery":"The child reads the pointer on a dial or spring scale marked in grammes. Proposed: scales up to 1000 g, with labelled divisions of 100 g and unlabelled marks worth 10 g, 20 g, 25 g or 50 g. They work out the value of one small mark before reading. Proposed skill: the design names beam balances and electronic machines, so dial reading is professional judgement.","question_forms":["read the pointer","what is each small mark worth?","draw the pointer at a given mass","difference between two readings"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G4.MEASUR.LENGTH.b","kind":"outcome","strength":"helpful","reason":"Reading a ruler between labelled marks is the same scale-reading skill.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE","kind":"skill","strength":"essential","reason":"Scale readings are in grammes.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES","name":"Estimate mass in grammes using benchmarks, then check by measuring","outcomes":["MATH.G5.MEASUR.MASS.c"],"mastery":"The child uses a benchmark to give a sensible estimate in grammes and then measures to check. Benchmarks include a spoon or bottle top of sand at about 5 g, or a 500 g packet. Proposed: up to 1000 g. The child judges whether a stated mass is reasonable and keeps the estimate as recorded when the measurement differs.","question_forms":["estimate then measure (record table)","is this mass reasonable?","benchmark scaling: 20 bottle tops of sand is about ...","order objects by estimated mass"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE","kind":"skill","strength":"essential","reason":"Estimates are checked by measuring, and benchmarks come from measured experience.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MASS.MASS_CHOOSE_UNIT","kind":"skill","strength":"helpful","reason":"A sense of light against heavy supports reasonable estimates.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP","name":"Know that 1 kg = 1000 g, including half and quarter kilogrammes","outcomes":["MATH.G5.MEASUR.MASS.d"],"mastery":"The child states that 1 kg = 1000 g and shows it on a balance, for example 1 kg balancing ten 100 g masses. They know that ½ kg = 500 g and ¼ kg = 250 g. They compare masses given in different units, such as 750 g against 1 kg.","question_forms":["fill in: 1 kg = ___ g","how many 250 g packets make 1 kg?","compare masses in different units","true or false with reason"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_MASS","G6_UNIT_CONVERSIONS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE","kind":"skill","strength":"essential","reason":"The design has learners establish 1 kg = 1000 g practically on a balance.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MASS.b","kind":"outcome","strength":"helpful","reason":"½ kg and ¼ kg link directly to 500 g and 250 g.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.c","kind":"outcome","strength":"helpful","reason":"The metre–centimetre relationship is a parallel, though it uses 100, not 1000.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G","name":"Convert kilogrammes (and kilogrammes with grammes) to grammes","outcomes":["MATH.G5.MEASUR.MASS.e"],"mastery":"The child converts whole kilogrammes and mixed amounts to grammes, for example 4 kg = 4000 g, 3 kg 450 g = 3450 g and 2 kg 45 g = 2045 g, keeping place-holder zeros. Proposed: up to 10 kg, without decimal kilogrammes.","question_forms":["convert","missing number","word problem: packet sizes","spot the error"],"thinking":["procedure"],"horeb_skill_ids":["G5_MASS","G6_UNIT_CONVERSIONS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP","kind":"skill","strength":"essential","reason":"Conversion applies 1 kg = 1000 g.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"Converting metres to centimetres is the same procedure with a different factor.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG","name":"Convert grammes to kilogrammes (and kilogrammes with grammes)","outcomes":["MATH.G5.MEASUR.MASS.e"],"mastery":"The child converts grammes to kilogrammes, or to kilogrammes and grammes. Examples: 6000 g = 6 kg, 4250 g = 4 kg 250 g, 3050 g = 3 kg 50 g. Proposed: up to 10 000 g, without decimal kilogrammes.","question_forms":["convert","missing number","word problem: total grammes to kg","compare and explain"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_MASS","G6_UNIT_CONVERSIONS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP","kind":"skill","strength":"essential","reason":"Conversion applies 1000 g = 1 kg.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G","kind":"skill","strength":"helpful","reason":"Converting back is easier once the forward direction is secure.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G","name":"Add masses in kilogrammes and grammes","outcomes":["MATH.G5.MEASUR.MASS.f"],"mastery":"The child adds masses written in kg and g, with and without regrouping 1000 g as 1 kg. For example, 2 kg 700 g + 1 kg 600 g = 4 kg 300 g. They solve shopping and market word problems. Proposed: totals up to 100 kg, up to three addends.","question_forms":["column addition in kg and g","word problem: total mass of shopping","mixed units (kg + g)","missing addend"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG","kind":"skill","strength":"essential","reason":"Regrouping 1000 g or more into kilogrammes is a grammes-to-kilogrammes conversion.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MASS.c","kind":"outcome","strength":"essential","reason":"Adding whole kilogrammes comes before adding mixed units.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.f","kind":"outcome","strength":"helpful","reason":"Adding metres and centimetres uses the same two-unit column layout.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G","name":"Subtract masses in kilogrammes and grammes","outcomes":["MATH.G5.MEASUR.MASS.g"],"mastery":"The child subtracts masses in kg and g, exchanging 1 kg for 1000 g when needed. Examples: 5 kg 200 g − 2 kg 700 g = 2 kg 500 g, and 3 kg − 400 g = 2 kg 600 g. They solve 'how much is left' and 'how much heavier' problems. Proposed: up to 100 kg.","question_forms":["column subtraction in kg and g","word problem: amount remaining","word problem: difference / how much heavier","subtract from whole kg"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G","kind":"skill","strength":"essential","reason":"Exchanging 1 kg for 1000 g is a kilogrammes-to-grammes conversion.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MASS.d","kind":"outcome","strength":"essential","reason":"Subtracting whole kilogrammes comes first.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.g","kind":"outcome","strength":"helpful","reason":"Subtracting metres and centimetres uses the same exchange structure.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_MULTIPLY_KG_G","name":"Multiply masses in kilogrammes and grammes by a whole number","outcomes":["MATH.G5.MEASUR.MASS.h"],"mastery":"The child multiplies a mass in kg and g by a whole number and regroups grammes into kilogrammes. For example, 2 kg 350 g × 4 = 9 kg 400 g. They solve 'several identical packets' problems. Proposed: multipliers up to 10 (two-digit at most), products up to 100 kg.","question_forms":["multiply kg and g","word problem: equal packets/bags","multiply grammes and give answer in kg and g","missing multiplier"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G","kind":"skill","strength":"essential","reason":"Multiplication is repeated addition with the same regrouping.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.h","kind":"outcome","strength":"helpful","reason":"Multiplying metres and centimetres is the parallel procedure.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G","name":"Divide masses in kilogrammes and grammes by a whole number","outcomes":["MATH.G5.MEASUR.MASS.i"],"mastery":"The child divides a mass in kg and g by a whole number. Any remaining kilogrammes are changed to grammes and carried on, for example 7 kg 200 g ÷ 4 = 1 kg 800 g. They solve equal-sharing and packing problems. Proposed: single-digit divisors (up to 10), exact answers to the nearest whole gramme.","question_forms":["divide kg and g","word problem: equal sharing","word problem: mass of one item from total","check by multiplying"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_MASS"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G","kind":"skill","strength":"essential","reason":"Leftover kilogrammes must be changed into grammes to continue dividing.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MASS.MASS_MULTIPLY_KG_G","kind":"skill","strength":"helpful","reason":"Multiplying back is the natural check on a division.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.i","kind":"outcome","strength":"helpful","reason":"Dividing metres and centimetres is the parallel procedure.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE.M_G_KG_SYMBOL_SWAP","skill":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE","error":"Reads or writes g as kg (or ignores the unit), so a small packet is given a huge mass.","example":{"question":"A packet of tea leaves is labelled 250 g. What is its mass?","wrong_answer":"250 kg","correct_answer":"250 g (two hundred and fifty grammes)"},"cause":"In Grade 4 the child only met kilogrammes, so every mass is read as kilogrammes.","reveals":"Offer 250 kg as a distractor beside 250 g, with a picture of a small packet.","help":"Have children hold real labelled packets and say the full unit name aloud, asking 'could a child lift 250 kg?'","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE.M_MASS_CAPACITY_UNITS","skill":"MATH.G5.MEASUR.MASS.MASS_GRAMME_RECOGNISE","error":"Uses capacity units (litres, millilitres) for the mass of solids, or reads a ml label as a mass.","example":{"question":"Which label shows the mass of a packet of sugar: 1 kg, 1 l or 500 ml?","wrong_answer":"1 l","correct_answer":"1 kg"},"cause":"Both appear on shop packaging and the child has not separated 'how heavy' from 'how much it holds'.","reveals":"Sorting labels from a duka (cooking oil, milk, sugar, salt) into mass and capacity.","help":"Sort real empty packets into a 'weighed' pile and a 'poured' pile and name the units each uses.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CHOOSE_UNIT.M_SIZE_DECIDES_UNIT","skill":"MATH.G5.MEASUR.MASS.MASS_CHOOSE_UNIT","error":"Chooses kilogrammes for any large-looking object and grammes for any small one, regardless of how heavy it is.","example":{"question":"Would you measure a large empty cardboard carton in g or kg?","wrong_answer":"kg, because it is big","correct_answer":"g, because it is light"},"cause":"Confuses size (how much space) with mass (how heavy).","reveals":"Include large light objects (empty carton, foam mattress offcut) and small heavy objects (a stone, a padlock) in the choose-a-unit item.","help":"Let children lift a big light object and a small heavy one before choosing, and ask 'does it feel heavy?' not 'does it look big?'","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CHOOSE_UNIT.M_UNIT_UNREASONABLE_MAGNITUDE","skill":"MATH.G5.MEASUR.MASS.MASS_CHOOSE_UNIT","error":"Attaches a unit without checking whether the number and unit together make sense.","example":{"question":"Complete: An egg has a mass of about 60 ___","wrong_answer":"kg","correct_answer":"g"},"cause":"Picks the more familiar unit (kg) rather than reasoning about the object.","reveals":"'Is this sensible?' items such as 'A girl has a mass of 30 g'.","help":"Compare against known benchmarks: a 1 kg packet of sugar, a 2 kg packet of maize flour, a 5 g bottle top of sand.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE.M_HEAVIER_SIDE_UP","skill":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE","error":"Thinks the pan that rises on a beam balance holds the heavier object.","example":{"question":"On a beam balance the pan with the avocado goes down and the pan with the orange goes up. Which is heavier?","wrong_answer":"The orange","correct_answer":"The avocado"},"cause":"Associates 'higher' with 'more', as on a bar graph.","reveals":"Picture items of an unbalanced beam asking which side is heavier.","help":"Let children press down on each pan with their hands so they feel that the heavier side is pulled down.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE.M_COUNT_MASSES_NOT_VALUES","skill":"MATH.G5.MEASUR.MASS.MASS_MEASURE_BALANCE","error":"Counts how many gramme masses were used instead of adding their values.","example":{"question":"A tomato balances a 100 g, a 50 g and a 20 g mass. What is its mass?","wrong_answer":"3 g","correct_answer":"170 g"},"cause":"Treats each mass piece like a non-standard unit (one bottle top = one unit), as in earlier measuring.","reveals":"A balance picture using masses of different values, with the number of pieces as a distractor.","help":"Have children write the value of each mass used and add them before recording the result.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_READ_SCALE.M_EACH_MARK_ONE_UNIT","skill":"MATH.G5.MEASUR.MASS.MASS_READ_SCALE","error":"Assumes every small mark on a scale is worth 1 g and counts on in ones.","example":{"question":"A dial is labelled 0, 100, 200, 300 g with 4 small marks between each label. The pointer is on the 3rd small mark after 200. What is the reading?","wrong_answer":"203 g","correct_answer":"260 g (each small mark is 20 g)"},"cause":"Ruler experience, where small marks often go up in ones.","reveals":"Scales whose divisions are not 1, with the 'count in ones' value as a distractor.","help":"Before every reading, ask 'how many spaces are there between two labels, and what is each space worth?'","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_READ_SCALE.M_READ_NEAREST_LABEL","skill":"MATH.G5.MEASUR.MASS.MASS_READ_SCALE","error":"Reads the nearest labelled number and ignores the unlabelled marks.","example":{"question":"The pointer of a kitchen scale is halfway between 400 g and 500 g. What is the mass?","wrong_answer":"400 g","correct_answer":"450 g"},"cause":"Believes only numbered marks can be read.","reveals":"Pointers placed between labels, with the labelled values as distractors.","help":"Have children write in the missing numbers on a drawn scale before reading it.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES.M_SIZE_EQUALS_MASS","skill":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES","error":"Estimates that the bigger object must have the greater mass.","example":{"question":"Estimate which is heavier: a large bag of cotton wool or a small stone the size of a matchbox.","wrong_answer":"The bag of cotton wool","correct_answer":"The stone (check on a balance)"},"cause":"Uses volume as a stand-in for mass.","reveals":"Estimate-and-order tasks that include big light and small heavy objects.","help":"Estimate by lifting in each hand, then check on the improvised balance and discuss surprises.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES.M_BENCHMARK_ADD_NOT_REPEAT","skill":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES","error":"When scaling a benchmark, adds the count to the benchmark instead of repeating it.","example":{"question":"One bottle top of sand is about 5 g. A cup holds 20 bottle tops of sand. About what is the mass of the sand?","wrong_answer":"25 g","correct_answer":"about 100 g"},"cause":"Does not see that each bottle top adds another 5 g, so the estimate is 20 lots of 5 g.","reveals":"Benchmark-scaling items with the sum as a distractor.","help":"Fill the cup one scoop at a time while the class counts in fives, then record the product.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES.M_CHANGE_ESTIMATE","skill":"MATH.G5.MEASUR.MASS.MASS_ESTIMATE_GRAMMES","error":"Rubs out the estimate after measuring so it matches, believing an estimate is 'wrong' unless exact.","example":{"question":"Kamau estimated a bar of soap at 200 g and measured 180 g. What should he record?","wrong_answer":"Estimate 180 g, measured 180 g","correct_answer":"Estimate 200 g, measured 180 g (a good estimate, 20 g off)"},"cause":"Sees estimating as guessing the exact answer rather than getting close.","reveals":"'Was this a good estimate?' items, and observing record tables in practical work.","help":"Praise close estimates, record estimate and measurement in separate columns, and talk about 'how close' rather than 'right or wrong'.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP.M_KG_IS_100G","skill":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP","error":"Says 1 kg = 100 g.","example":{"question":"1 kg = ___ g","wrong_answer":"100","correct_answer":"1000"},"cause":"Carries over 1 m = 100 cm from Grade 4 length work.","reveals":"Fill-in items with 100 as a distractor; also '½ kg = ___ g' with 50 as a distractor.","help":"Balance a 1 kg mass against ten 100 g masses, and contrast 'kilo means thousand' with 'centi means hundredth'.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP.M_HALF_QUARTER_MIXUP","skill":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP","error":"Confuses ½ kg and ¼ kg in grammes, for example thinking 250 g is half a kilogramme.","example":{"question":"How many 250 g packets of tea leaves make 1 kg?","wrong_answer":"2","correct_answer":"4"},"cause":"Weak link between the fraction words and 500 g and 250 g; thinks a smaller fraction gives fewer parts.","reveals":"Packet-counting items using 250 g and 500 g packs.","help":"Put 250 g packs one at a time on a balance against 1 kg, counting until it balances.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP.M_COMPARE_IGNORE_UNITS","skill":"MATH.G5.MEASUR.MASS.MASS_KG_G_RELATIONSHIP","error":"Compares masses by the numbers alone and ignores the units.","example":{"question":"Which is heavier: 500 g of beans or 2 kg of rice?","wrong_answer":"500 g of beans, because 500 is bigger than 2","correct_answer":"2 kg of rice (2 kg = 2000 g)"},"cause":"Focuses on the digits and does not change to a common unit.","reveals":"Compare items where the larger number has the smaller unit.","help":"Require both masses to be written in grammes before comparing.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G.M_KG_TO_G_TIMES_100","skill":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G","error":"Multiplies by 100 when converting kilogrammes to grammes.","example":{"question":"Mama Wanjiru bought 4 kg of sukuma wiki. How many grammes is that?","wrong_answer":"400 g","correct_answer":"4000 g"},"cause":"Uses the length factor (1 m = 100 cm) for mass.","reveals":"Conversion items with the ×100 result as a distractor.","help":"Have children write '1 kg = 1000 g' at the top of the work and build each conversion from it.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G.M_MISSING_PLACEHOLDER_ZERO","skill":"MATH.G5.MEASUR.MASS.MASS_CONVERT_KG_TO_G","error":"Joins the kilogrammes and grammes digits together without place-holder zeros.","example":{"question":"Convert 3 kg 45 g to grammes.","wrong_answer":"345 g","correct_answer":"3045 g"},"cause":"Treats conversion as writing the numbers side by side, which happens to work for 3 kg 450 g.","reveals":"Items whose gramme part has fewer than three digits (45 g, 5 g).","help":"Convert in two steps, 3 kg = 3000 g and then 3000 g + 45 g, using a place-value chart.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG.M_G_TO_KG_SPLIT_AT_HUNDREDS","skill":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG","error":"Splits the grammes into kilogrammes after the hundreds digit, as with centimetres to metres.","example":{"question":"A sack of potatoes from Nyandarua is 4250 g. Write this in kg and g.","wrong_answer":"42 kg 50 g","correct_answer":"4 kg 250 g"},"cause":"Uses 100 as the exchange number, carried over from length.","reveals":"Four-digit gramme values with the 'split by 100' answer as a distractor.","help":"Ask 'how many full thousands are in 4250?' using bundles or a place-value chart.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG.M_DROP_ZERO_IN_GRAMMES","skill":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG","error":"Loses or misplaces a zero in the gramme part when converting.","example":{"question":"Write 3050 g in kg and g.","wrong_answer":"3 kg 5 g","correct_answer":"3 kg 50 g"},"cause":"Reads digits off one by one instead of taking the remainder after 3000 as a whole number.","reveals":"Values with internal zeros (3050 g, 5005 g), and check-back items.","help":"Have children subtract the whole kilogrammes (3050 − 3000 = 50) and convert back to check.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG.M_CONVERT_WRONG_DIRECTION","skill":"MATH.G5.MEASUR.MASS.MASS_CONVERT_G_TO_KG","error":"Multiplies by 1000 when converting grammes to kilogrammes.","example":{"question":"6000 g = ___ kg","wrong_answer":"6 000 000","correct_answer":"6"},"cause":"Has memorised '1000' but not which way to use it; does not see that the bigger unit gives the smaller number.","reveals":"Mixed-direction conversion sets with the multiplied answer as a distractor.","help":"Ask 'is a kilogramme bigger or smaller than a gramme, so will I need more or fewer of them?' before calculating.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G.M_ADD_DROP_CARRY","skill":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G","error":"Writes only part of a gramme total of 1000 g or more and loses the extra kilogramme.","example":{"question":"A basket has 2 kg 700 g of tomatoes and another has 1 kg 600 g. Find the total mass.","wrong_answer":"3 kg 300 g","correct_answer":"4 kg 300 g"},"cause":"Does not see 1300 g as 1 kg 300 g.","reveals":"Addition items whose gramme column totals more than 1000, with the no-carry answer as a distractor.","help":"Have children write the full gramme total (1300 g) and convert it before combining with the kilogrammes.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G.M_ADD_REGROUP_AT_100","skill":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G","error":"Regroups into a kilogramme as soon as the grammes pass 100.","example":{"question":"2 kg 70 g + 1 kg 50 g","wrong_answer":"4 kg 20 g","correct_answer":"3 kg 120 g"},"cause":"Uses the metre–centimetre rule (100 cm = 1 m).","reveals":"Items where the grammes total between 100 and 999.","help":"Before carrying, ask 'have I got 1000 g or more?'","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G.M_ADD_UNLIKE_UNITS","skill":"MATH.G5.MEASUR.MASS.MASS_ADD_KG_G","error":"Adds the numbers of kilogrammes and grammes directly as if they were the same unit.","example":{"question":"Akinyi bought 3 kg of rice and 250 g of salt. What is the total mass?","wrong_answer":"253 kg","correct_answer":"3 kg 250 g (3250 g)"},"cause":"Ignores units and adds the visible numbers.","reveals":"Word problems mixing a whole-kilogramme amount with a gramme amount.","help":"Have children set out kg and g in labelled columns before adding.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G.M_SUB_SMALLER_FROM_LARGER","skill":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G","error":"In the grammes column, takes the smaller number from the larger whichever is on top.","example":{"question":"A bag had 5 kg 200 g of beans. 2 kg 700 g was cooked. How much is left?","wrong_answer":"3 kg 500 g","correct_answer":"2 kg 500 g"},"cause":"Sees subtraction as 'always big minus small' within a column, as in early whole-number errors.","reveals":"Items where the top gramme value is smaller, with the reversed-difference answer as a distractor.","help":"Have children check by adding the answer to the amount taken away, which should give back 5 kg 200 g.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G.M_SUB_BORROW_100","skill":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G","error":"Exchanges 1 kg for 100 g instead of 1000 g.","example":{"question":"4 kg 50 g − 1 kg 80 g","wrong_answer":"2 kg 70 g","correct_answer":"2 kg 970 g"},"cause":"Uses the length exchange (1 m = 100 cm) or the base-ten 'borrow ten' habit.","reveals":"Items needing an exchange where the gramme values are under 100.","help":"Have children write the exchange explicitly ('1 kg → 1000 g, so 50 g becomes 1050 g') before subtracting.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G.M_SUB_EXCHANGE_NOT_REDUCED","skill":"MATH.G5.MEASUR.MASS.MASS_SUBTRACT_KG_G","error":"Takes grammes from a whole kilogramme but does not reduce the number of kilogrammes.","example":{"question":"Juma had 3 kg of sugar and used 400 g. How much remains?","wrong_answer":"3 kg 600 g","correct_answer":"2 kg 600 g"},"cause":"Finds 1000 − 400 correctly but forgets that a kilogramme was used up in the exchange.","reveals":"Subtract-from-whole-kilogramme items; ask whether the answer can be more than 3 kg.","help":"Have children cross out one kilogramme and write 1000 g beside it, or convert everything to grammes first.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_MULTIPLY_KG_G.M_MULT_ONE_PART","skill":"MATH.G5.MEASUR.MASS.MASS_MULTIPLY_KG_G","error":"Multiplies only the kilogrammes (or only the grammes) and copies the other part unchanged.","example":{"question":"One bag of rice has a mass of 2 kg 350 g. What is the mass of 4 bags?","wrong_answer":"8 kg 350 g","correct_answer":"9 kg 400 g"},"cause":"Does not see that both parts of the mass are repeated 4 times.","reveals":"Multiplication items with a partly multiplied distractor.","help":"Have children write the problem as repeated addition once to see that every part is repeated.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_MULTIPLY_KG_G.M_MULT_NO_REGROUP","skill":"MATH.G5.MEASUR.MASS.MASS_MULTIPLY_KG_G","error":"Multiplies both parts but loses the kilogrammes made from the gramme product.","example":{"question":"2 kg 350 g × 4","wrong_answer":"8 kg 400 g","correct_answer":"9 kg 400 g (1400 g = 1 kg 400 g)"},"cause":"Writes the last three digits of 1400 and drops the thousand.","reveals":"Items whose gramme product reaches 1000 g or more.","help":"Have children record the full gramme product (1400 g) and convert it before adding it to the kilogrammes.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G.M_DIV_IGNORE_KG_REMAINDER","skill":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G","error":"Divides the kilogrammes and grammes separately and throws away the remainder from the kilogrammes.","example":{"question":"7 kg 200 g of maize flour is shared equally among 4 families. How much does each family get?","wrong_answer":"1 kg 50 g","correct_answer":"1 kg 800 g"},"cause":"Does not see that the leftover 3 kg is still flour that must be shared.","reveals":"Division items where the kilogrammes do not divide exactly; multiplying back reveals the shortfall.","help":"Convert the whole mass to grammes (7200 g ÷ 4) or change the leftover kilogrammes to grammes, and always check by multiplying.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G.M_DIV_REMAINDER_AS_100","skill":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G","error":"Changes the leftover kilogrammes into hundreds of grammes instead of thousands.","example":{"question":"7 kg 200 g ÷ 4","wrong_answer":"1 kg 125 g","correct_answer":"1 kg 800 g"},"cause":"Treats 3 kg left over as 300 g (the length factor 100), then 500 g ÷ 4 = 125 g.","reveals":"The same items as above; the ×100 remainder gives a distinctive wrong answer.","help":"Have children say aloud '3 kg left is 3000 g' and check the answer by multiplying back.","status":"draft"},{"code":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G.M_DIV_WRONG_WAY","skill":"MATH.G5.MEASUR.MASS.MASS_DIVIDE_KG_G","error":"Divides the number of people or items by the mass instead of the mass by the number of people or items.","example":{"question":"2 kg of groundnuts are shared equally among 8 children in Kisumu. What mass does each child get?","wrong_answer":"4 kg","correct_answer":"250 g"},"cause":"Believes you always divide the bigger number by the smaller one.","reveals":"Sharing problems where the divisor is larger than the number of kilogrammes.","help":"Ask 'should each child get more or less than the whole 2 kg?' and convert to 2000 g before dividing.","status":"draft"}]},{"code":"MATH.G5.MEASUR.TIME","number":"2.6","strand":"Measurement","sub_strand":"Time","sequence":206,"lessons":8,"content_topics":["Second as a unit of measuring time","Conversions in time","Operations in time"],"learning_experiences":["work with peers to identify second hand from a clock","carry out activities taking 10 seconds","use digital devices and other resources to tell time from clocks","relate the activities to what can be done in one tenth of the time taken to do the activity; the time taken is 1 second","measure time taken to do various activities in seconds","establish the relationship between seconds and minute using a clock or stop watch, watches","team up with peers to determine time durations in minutes and seconds using different operations in real-life situations","Experiences"],"key_inquiry_questions":["How can we read and tell time?"],"core_competences":"Learning to learn: learner establishes the relationship between seconds and minute using a clock or stop watch, watches.","values":"Responsibility: learner carefully handles a clock or stopwatch watches while establishing the relationship between seconds and minute.","pcis":"Social cohesion: learner teams up with peers to determine time durations in minutes and seconds using different operations in real-life situations.","links":"The learner is able to relate concept of time to c hange of state of matter due to heating or freezing over time in Science and Technology.","design_notes":"Outcome (i) 'appreciate use of minutes and seconds as units of measuring time in real-life situations' is attitudinal, so no skill covers it. It is best evidenced through observation during timed class activities. The design sets no number limits for any outcome. All limits given here are proposed professional judgement, not KICD wording: under 100 minutes, no hours, multipliers and divisors up to 10, and division giving whole seconds. G5_SECOND_DURATION_SENSE is a proposed skill drawn from the learning experiences ('carry out activities taking 10 seconds', 'measure time taken to do various activities in seconds'). It is not stated in an outcome, and it is linked to outcome (a) by judgement. The learning experience 'relate the activities to what can be done in one tenth of the time taken to do the activity; the time taken is 1 second' is garbled in the source text, and its intended meaning is unclear. It may mean relating a 10-second activity to what can be done in 1 second (one tenth of it). The key inquiry question text includes a stray 'Inquiry Question(s)', and there is a stray 'Experiences' item; both appear to be extraction artefacts. Outcome (b) says 'analogues clocks' (sic). Outcome (d) covers both directions, so it is split into two skills. Outcomes (e)-(h) imply regrouping. Only (e) and (f) say 'with conversion', but multiplication and division also need regrouping in practice, so it is assumed for (g) and (h). Prerequisite links use only Grade 4 codes given in the inputs. Whole-number multiplication and division facts, especially multiples of 60, are also needed but cannot be cited because the Numbers strand is not in the inputs. Several common errors come from transferring base-ten habits from Grade 4 metres and centimetres (100 cm = 1 m) to seconds (60 s = 1 min). Teachers may want to contrast the two explicitly. The HOREB skill G5_TIME ('Telling Time & Duration') overlaps with all the skills here, but its scope is broader. No existing HOREB id covers seconds specifically, and G6_UNIT_CONVERSIONS does not include time.","outcomes":[{"code":"MATH.G5.MEASUR.TIME.a","letter":"a","text":"identify the second as a unit of measuring time from a clock","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.b","letter":"b","text":"use digital or analogues clocks to read time in seconds","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.c","letter":"c","text":"identify the relationship between the minute and the second in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.d","letter":"d","text":"convert minutes to seconds and seconds to minutes in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.e","letter":"e","text":"add minutes and seconds with conversion in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.f","letter":"f","text":"subtract minutes and seconds with conversion in real life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.g","letter":"g","text":"multiply minutes and seconds by whole numbers in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.h","letter":"h","text":"divide minutes and seconds by whole numbers in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.TIME.i","letter":"i","text":"appreciate use of minutes and seconds as units of measuring time in real-life situations","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY","name":"Identify the second and the second hand on a clock","outcomes":["MATH.G5.MEASUR.TIME.a"],"mastery":"The child points out the second hand on an analogue clock (the thin hand that moves fastest, or ticks once each second) and the seconds digits on a digital clock or stopwatch. The child names the second as the unit it measures. Proposed: the child also tells the second hand apart from the minute and hour hands on any ordinary wall clock or wristwatch.","question_forms":["label the hands of a clock","which hand shows seconds (multiple choice)","point to the seconds digits on a digital display","true or false about clock hands"],"thinking":["recall"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G4.MEASUR.TIME.a","kind":"outcome","strength":"essential","reason":"The child must already know the hour and minute hands before telling the second hand apart from them.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.SECOND_DURATION_SENSE","name":"Estimate and measure short durations in seconds (proposed, from learning experiences)","outcomes":["MATH.G5.MEASUR.TIME.a"],"mastery":"Proposed: the child judges which everyday actions take about 1 second, about 10 seconds or about 1 minute. The child times short activities (for example clapping 10 times or running across the school field) with a stopwatch or clock, to the nearest second, for durations up to 60 seconds.","question_forms":["which activity takes about 10 seconds (multiple choice)","estimate then measure","order activities by duration","record a measured time in seconds"],"thinking":["reasoning","procedure"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY","kind":"skill","strength":"essential","reason":"Measuring in seconds needs the child to know which hand or digits show seconds.","status":"proposed"},{"requires":"MATH.G4.MEASUR.TIME.b","kind":"outcome","strength":"helpful","reason":"Estimating time in Grade 4 builds the habit of judging durations before measuring.","status":"proposed"},{"requires":"MATH.G5.MEASUR.TIME.READ_SECONDS_DIGITAL","kind":"skill","strength":"helpful","reason":"Most timed activities are read off a stopwatch or phone timer.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.READ_SECONDS_ANALOGUE","name":"Read time including seconds on an analogue clock","outcomes":["MATH.G5.MEASUR.TIME.b"],"mastery":"The child reads hours, minutes and seconds from an analogue clock that has a second hand, including when the second hand is between numerals. The child counts in fives from 12 and then adds the small marks, for example 'twenty past three and 37 seconds', or 3:20:37.","question_forms":["read the clock face (hours, minutes, seconds)","how many seconds does the second hand show","draw the second hand to show a given number of seconds","match clock face to written time"],"thinking":["procedure"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY","kind":"skill","strength":"essential","reason":"The child cannot read seconds without picking out the second hand.","status":"proposed"},{"requires":"MATH.G4.MEASUR.TIME.a","kind":"outcome","strength":"essential","reason":"Reading hours and minutes, including counting in fives round the face, is the base for reading seconds.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.READ_SECONDS_DIGITAL","name":"Read time and durations including seconds on digital clocks and stopwatches","outcomes":["MATH.G5.MEASUR.TIME.b"],"mastery":"The child reads a digital clock in the form hh:mm:ss, for example 08:15:42, as 8 hours 15 minutes 42 seconds. The child reads a stopwatch in the form mm:ss, for example 02:35, as 2 minutes 35 seconds, and can say which digits stand for which unit.","question_forms":["read the digital display","which digits show the seconds","stopwatch reading to words","match digital and analogue displays"],"thinking":["procedure"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G4.MEASUR.TIME.f","kind":"outcome","strength":"essential","reason":"Reading hh:mm on a digital clock comes before reading the extra :ss digits.","status":"proposed"},{"requires":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY","kind":"skill","strength":"helpful","reason":"Knowing what a second is helps the child make sense of the fast-changing digits.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION","name":"Know that 1 minute = 60 seconds","outcomes":["MATH.G5.MEASUR.TIME.c"],"mastery":"The child states that 60 seconds make 1 minute. The child explains this using the clock: one full turn of the second hand is 60 seconds, during which the minute hand moves on by one small mark. The child uses the fact in real-life talk, for example 'one minute of silence is 60 seconds'.","question_forms":["fill in: 1 minute = __ seconds","what happens to the minute hand when the second hand goes round once","explain using a clock or stopwatch","true or false about minutes and seconds"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY","kind":"skill","strength":"essential","reason":"The 60 s = 1 min fact is built by watching the second hand go round once.","status":"proposed"},{"requires":"MATH.G4.MEASUR.TIME.c","kind":"outcome","strength":"helpful","reason":"Grade 4 conversions such as 1 hour = 60 minutes introduce the idea of grouping in sixties.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC","name":"Convert minutes (and minutes and seconds) to seconds","outcomes":["MATH.G5.MEASUR.TIME.d"],"mastery":"The child converts whole minutes to seconds by multiplying by 60, and converts mixed amounts such as 4 min 15 s to seconds (255 s). Proposed limit: up to 2-digit minutes (under 100 minutes), no hours.","question_forms":["convert: __ min = __ s","convert mixed: __ min __ s = __ s","word problem: duration of a song or race in seconds","missing number"],"thinking":["procedure"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION","kind":"skill","strength":"essential","reason":"Converting depends on knowing that 1 minute = 60 seconds.","status":"proposed"},{"requires":"MATH.G4.MEASUR.TIME.c","kind":"outcome","strength":"helpful","reason":"Converting hours to minutes uses the same multiply-by-60 procedure.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.d","kind":"outcome","strength":"helpful","reason":"Metre and centimetre conversion gives a familiar model of converting a larger unit to a smaller one.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","name":"Convert seconds to minutes and seconds","outcomes":["MATH.G5.MEASUR.TIME.d"],"mastery":"The child converts a number of seconds to whole minutes and leftover seconds by grouping in sixties or dividing by 60, for example 150 s = 2 min 30 s and 240 s = 4 min. The answer is always given in minutes and seconds, not as a decimal. Proposed limit: up to about 4-digit seconds, giving answers under 100 minutes.","question_forms":["convert: __ s = __ min __ s","word problem: a stopwatch shows seconds, give in minutes and seconds","compare two durations given in different units","missing number"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION","kind":"skill","strength":"essential","reason":"Grouping seconds into minutes depends on the 60 s = 1 min fact.","status":"proposed"},{"requires":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC","kind":"skill","strength":"helpful","reason":"Knowing the multiples of 60 (120, 180, 240 ...) makes grouping into minutes quicker.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC","name":"Add minutes and seconds with regrouping","outcomes":["MATH.G5.MEASUR.TIME.e"],"mastery":"The child adds two or three durations in minutes and seconds. When the seconds come to 60 or more, the child changes 60 s into 1 min and adds it to the minutes, for example 3 min 45 s + 2 min 30 s = 6 min 15 s. Proposed limit: answers under 100 minutes.","question_forms":["column addition (min | s)","word problem: total time of two activities","missing number in an addition","find the error in a worked example"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","kind":"skill","strength":"essential","reason":"Regrouping 60 s or more into minutes is the key step in addition.","status":"proposed"},{"requires":"MATH.G4.MEASUR.TIME.e","kind":"outcome","strength":"helpful","reason":"Working out durations in hours and minutes gives practice with base-60 regrouping.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.f","kind":"outcome","strength":"helpful","reason":"Adding metres and centimetres gives the same two-unit column layout.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC","name":"Subtract minutes and seconds with regrouping","outcomes":["MATH.G5.MEASUR.TIME.f"],"mastery":"The child subtracts durations in minutes and seconds. When there are not enough seconds, the child changes 1 minute into 60 seconds, for example 5 min 20 s − 2 min 45 s = 2 min 35 s. The child uses subtraction for 'how much longer' and 'how much time is left' problems.","question_forms":["column subtraction (min | s)","word problem: difference between two race times","word problem: time remaining","find the error in a worked example"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC","kind":"skill","strength":"essential","reason":"Borrowing means changing 1 minute into 60 seconds.","status":"proposed"},{"requires":"MATH.G4.MEASUR.TIME.e","kind":"outcome","strength":"helpful","reason":"Finding durations involves the same 'how much longer' reasoning.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.g","kind":"outcome","strength":"helpful","reason":"Subtracting metres and centimetres gives a model of borrowing across two units.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC","name":"Multiply minutes and seconds by a whole number","outcomes":["MATH.G5.MEASUR.TIME.g"],"mastery":"The child multiplies a duration in minutes and seconds by a whole number and regroups seconds into minutes, for example 2 min 25 s × 3 = 7 min 15 s. Proposed limit: multipliers up to 10.","question_forms":["column multiplication (min | s)","word problem: repeated activity (e.g. same song played several times)","missing number","compare with repeated addition"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","kind":"skill","strength":"essential","reason":"The product of the seconds usually needs regrouping into minutes.","status":"proposed"},{"requires":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC","kind":"skill","strength":"helpful","reason":"Multiplication can be checked as repeated addition of durations.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.h","kind":"outcome","strength":"helpful","reason":"Multiplying metres and centimetres uses the same two-unit method.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC","name":"Divide minutes and seconds by a whole number","outcomes":["MATH.G5.MEASUR.TIME.h"],"mastery":"The child divides a duration in minutes and seconds by a whole number. Leftover minutes are changed into 60 s each before dividing the seconds, for example 7 min 30 s ÷ 2 = 3 min 45 s. The child may instead convert everything to seconds first. Proposed limits: divisors up to 10, and answers that come out in whole seconds.","question_forms":["division of min and s by a whole number","word problem: sharing time equally","word problem: time for one lap or one item","check answer by multiplying"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_TIME"],"prerequisites":[{"requires":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC","kind":"skill","strength":"essential","reason":"Leftover minutes must be changed into seconds before dividing the seconds.","status":"proposed"},{"requires":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","kind":"skill","strength":"essential","reason":"If the child divides in seconds only, the answer must be changed back into minutes and seconds.","status":"proposed"},{"requires":"MATH.G4.MEASUR.LENGTH.i","kind":"outcome","strength":"helpful","reason":"Dividing metres and centimetres gives a model of carrying a remainder into the smaller unit.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY.M_SECOND_MINUTE_HAND_SWAP","skill":"MATH.G5.MEASUR.TIME.SECOND_IDENTIFY","error":"The child treats the long thin second hand as the minute hand, because both are long.","example":{"question":"On the classroom clock the hour hand is just past 3, the thicker long hand points to 2 and the thin long hand points to 9. What time is it?","wrong_answer":"3:45","correct_answer":"10 minutes past 3 and 45 seconds (3:10:45)"},"cause":"Grade 4 clocks often had only two hands, so the child believes 'long hand = minutes' and does not know the third hand exists.","reveals":"Show a three-hand clock where the minute and second hands point to very different numerals, and include the swapped reading as a distractor.","help":"Let pupils watch a real clock for one minute so they see the thin hand sweep right round while the minute hand barely moves, then name each hand by its speed.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.SECOND_DURATION_SENSE.M_SECOND_SIZE_MISJUDGED","skill":"MATH.G5.MEASUR.TIME.SECOND_DURATION_SENSE","error":"The child has no feel for how long a second is. Counting '1, 2, 3 ...' goes much too fast, and long activities get matched to a few seconds.","example":{"question":"Which takes about 10 seconds: (A) cooking ugali for the family, (B) writing your first name, (C) walking from Nairobi to Thika?","wrong_answer":"A","correct_answer":"B"},"cause":"Seconds have never been experienced as a measured unit, so the word 'seconds' just means 'a short time' in daily speech ('wait a second').","reveals":"Ask pupils to estimate how long an activity takes, then time it with a stopwatch and compare their estimate with the measured time.","help":"Practise counting 'one-thousand-and-one, one-thousand-and-two ...' against a stopwatch until ten counts match ten seconds.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.READ_SECONDS_ANALOGUE.M_NUMERAL_AS_SECONDS","skill":"MATH.G5.MEASUR.TIME.READ_SECONDS_ANALOGUE","error":"The child reads the numeral the second hand points to as the number of seconds.","example":{"question":"The second hand points exactly at the 4. How many seconds does it show?","wrong_answer":"4 seconds","correct_answer":"20 seconds"},"cause":"The child copies the hour-hand rule (read the numeral directly) instead of counting in fives as for minutes.","reveals":"Use a question with the second hand on a numeral, and include the numeral itself as a distractor.","help":"Have pupils write 5, 10, 15 ... 55 beside the numerals on a paper clock face and count round in fives aloud.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.READ_SECONDS_ANALOGUE.M_SMALL_MARKS_ADDED_TO_NUMERAL","skill":"MATH.G5.MEASUR.TIME.READ_SECONDS_ANALOGUE","error":"When the second hand is between numerals, the child adds the small marks to the numeral itself instead of to its five-times value.","example":{"question":"The second hand is two small marks past the 7. How many seconds does it show?","wrong_answer":"9 seconds","correct_answer":"37 seconds"},"cause":"The child knows each small mark is 1 second but has not linked each numeral to a multiple of 5.","reveals":"Place the second hand between numerals and offer 'numeral + marks' as a distractor.","help":"Ask 'What is the 7 worth in seconds?' first, then 'How many more marks?', and record both steps (35 + 2 = 37).","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.READ_SECONDS_DIGITAL.M_STOPWATCH_AS_HOURS","skill":"MATH.G5.MEASUR.TIME.READ_SECONDS_DIGITAL","error":"The child reads a stopwatch display mm:ss as hours and minutes.","example":{"question":"A stopwatch shows 02:35 after Achieng runs round the school field. How long did she take?","wrong_answer":"2 hours 35 minutes","correct_answer":"2 minutes 35 seconds"},"cause":"In Grade 4 every 'number:number' display was hours:minutes, so the child applies that pattern everywhere.","reveals":"Give a stopwatch reading in a context where hours are clearly unreasonable, with the hours/minutes reading as a distractor.","help":"Show a clock and a stopwatch side by side, label each pair of digits, and ask 'Is that a sensible time for running round a field?'","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.READ_SECONDS_DIGITAL.M_DIGITAL_SECONDS_IGNORED","skill":"MATH.G5.MEASUR.TIME.READ_SECONDS_DIGITAL","error":"On an hh:mm:ss clock the child reads only the first two parts, or reads the middle pair as seconds.","example":{"question":"A digital clock shows 08:15:42. Write the time in words.","wrong_answer":"8 hours 15 seconds (or: 15 minutes past 8, with the 42 left out)","correct_answer":"15 minutes and 42 seconds past 8 (8 hours 15 minutes 42 seconds)"},"cause":"The child is not yet sure which digit pair goes with which unit when there are three pairs.","reveals":"Ask 'How many seconds does the clock show?' about an hh:mm:ss display, and include 15 and 08 as distractors.","help":"Write 'h : min : s' above each digital display until pupils can label the pairs without help.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION.M_100_SECONDS_IN_MINUTE","skill":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION","error":"The child believes 1 minute is 100 seconds.","example":{"question":"How many seconds are there in 1 minute?","wrong_answer":"100","correct_answer":"60"},"cause":"The child over-generalises base-ten patterns from number work and from length (1 m = 100 cm, learnt in Grade 4).","reveals":"Offer 100 as a distractor. In later items, this shows up as regrouping or borrowing at 100.","help":"Time one full turn of the second hand with the class counting aloud, and compare explicitly: 'Centimetres group in hundreds, seconds group in sixties.'","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION.M_REVOLUTION_IS_12","skill":"MATH.G5.MEASUR.TIME.MINUTE_SECOND_RELATION","error":"The child thinks one full turn of the second hand is 12 seconds because there are 12 numerals.","example":{"question":"The second hand starts at 12 and goes all the way round back to 12. How much time has passed?","wrong_answer":"12 seconds","correct_answer":"60 seconds (1 minute)"},"cause":"The child counts the numerals instead of the 60 small marks.","reveals":"Ask about a full turn or a half turn (correct: 30 s) and include 12 or 6 as distractors.","help":"Have pupils count the small marks on a clock face themselves and connect the total to the class's counted minute.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC.M_MIN_TO_SEC_TIMES_100","skill":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC","error":"The child multiplies by 100 instead of 60.","example":{"question":"A song on the radio lasts 3 minutes. How many seconds is that?","wrong_answer":"300 seconds","correct_answer":"180 seconds"},"cause":"The child uses the 100-based conversion from length (m to cm), or 'adds two zeros' as a rule.","reveals":"Include the ×100 answer as a distractor in a whole-minute conversion.","help":"Build a table of 1 min = 60 s, 2 min = 120 s, 3 min = 180 s by repeated adding of 60 before using any shortcut.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC.M_MIXED_CONCATENATE","skill":"MATH.G5.MEASUR.TIME.CONVERT_MIN_TO_SEC","error":"The child writes the minutes and seconds digits side by side, or forgets to add the extra seconds.","example":{"question":"Kamau boiled water for chai in 4 min 15 s. How many seconds is that?","wrong_answer":"415 seconds (or 240 seconds)","correct_answer":"255 seconds (240 + 15)"},"cause":"The child sees '4 min 15 s' as one number, or converts the minutes and then stops.","reveals":"Give mixed-unit conversions with both the joined-digit answer and the minutes-only answer as distractors.","help":"Require a two-line layout: '4 min = 240 s; 240 s + 15 s = 255 s'.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN.M_DECIMAL_REMAINDER","skill":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","error":"The child divides by 60 on a calculator or by long division, gets a decimal, and reads the decimal digits as seconds.","example":{"question":"A matatu waited 150 seconds at the stage. Write this in minutes and seconds.","wrong_answer":"2 min 5 s (or 2 min 50 s), from 2.5","correct_answer":"2 min 30 s"},"cause":"The child treats the decimal part of a minute as a count of seconds, not as a fraction of 60.","reveals":"Use totals that give .5 or .25 minutes and offer the decimal-digit readings as distractors.","help":"Teach 'take away sixties': 150 − 60 − 60 = 30, so 2 min 30 s, and keep remainders in seconds.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN.M_SEC_TO_MIN_BY_100","skill":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","error":"The child splits the seconds at the hundreds digit, as if 100 s were 1 minute.","example":{"question":"Write 150 seconds in minutes and seconds.","wrong_answer":"1 min 50 s","correct_answer":"2 min 30 s"},"cause":"This comes from the belief that 1 minute = 100 seconds, combined with place-value habits.","reveals":"Use a 3-digit number of seconds and include the 'split at hundreds' answer as a distractor.","help":"Ask pupils to check by converting back: 1 min 50 s = 110 s, not 150 s.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN.M_CONVERT_WRONG_DIRECTION","skill":"MATH.G5.MEASUR.TIME.CONVERT_SEC_TO_MIN","error":"The child multiplies by 60 when converting seconds to minutes.","example":{"question":"Convert 120 seconds to minutes.","wrong_answer":"7200 minutes","correct_answer":"2 minutes"},"cause":"The child has memorised '×60' as the conversion rule without thinking about whether the unit is getting bigger or smaller.","reveals":"Mix both directions of conversion in one set and include the multiplied answer as a distractor.","help":"Ask 'Will there be more minutes or fewer minutes than seconds?' before any calculation.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC.M_ADD_NO_REGROUP","skill":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC","error":"The child leaves 60 or more seconds in the seconds column.","example":{"question":"Njeri swept the classroom in 3 min 45 s and the verandah in 2 min 30 s. What was the total time?","wrong_answer":"5 min 75 s","correct_answer":"6 min 15 s"},"cause":"The child adds each column separately and does not know that the seconds must stay below 60.","reveals":"Use seconds that add to between 60 and 99, so that a base-ten 'carry' is never triggered.","help":"Add a final check to every answer: 'Is the seconds number less than 60? If not, change 60 s into 1 min.'","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC.M_ADD_REGROUP_AT_100","skill":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC","error":"The child regroups only when the seconds reach 100.","example":{"question":"2 min 50 s + 1 min 40 s = ?","wrong_answer":"3 min 90 s","correct_answer":"4 min 30 s"},"cause":"This comes from the belief that 1 minute = 100 seconds, carried over from base-ten column addition.","reveals":"Use seconds totals between 60 and 99, and also totals of 100 or more, to see where the child regroups.","help":"Use a number line marked at 60 s = 1 min to show where the next minute starts.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC.M_ADD_CARRY_LOST","skill":"MATH.G5.MEASUR.TIME.ADD_MIN_SEC","error":"The child changes the extra seconds correctly but forgets to add the carried minute to the minutes.","example":{"question":"3 min 45 s + 2 min 30 s = ?","wrong_answer":"5 min 15 s","correct_answer":"6 min 15 s"},"cause":"The child sees regrouping as 'take away 60' rather than as an exchange of 60 s for 1 min.","reveals":"Include the answer that is one minute short as a distractor.","help":"Have pupils write the carried 1 above the minutes column, just as in whole-number column addition.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC.M_SUB_SMALLER_FROM_LARGER","skill":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC","error":"In the seconds column, the child subtracts the smaller number from the larger, whichever row it is in.","example":{"question":"Wanjiru ran the race in 5 min 20 s and Otieno in 2 min 45 s. How much longer did Wanjiru take?","wrong_answer":"3 min 25 s","correct_answer":"2 min 35 s"},"cause":"The child believes subtraction is always 'big minus small' and avoids borrowing.","reveals":"Use questions where the top seconds are smaller than the bottom seconds.","help":"Have pupils check by adding the answer to the smaller time to see whether they get back the larger time.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC.M_SUB_BORROW_100","skill":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC","error":"When borrowing, the child turns 1 minute into 100 seconds.","example":{"question":"5 min 20 s − 2 min 45 s = ?","wrong_answer":"2 min 75 s","correct_answer":"2 min 35 s"},"cause":"The child applies the base-ten exchange from whole-number subtraction, or from metres and centimetres.","reveals":"Seconds of 60 or more in an answer, or the specific distractor 2 min 75 s, show this error.","help":"Model the exchange with a stopwatch: '1 minute opened up gives 60 seconds, so 20 + 60 = 80 seconds.'","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC.M_SUB_BORROW_NOT_REDUCED","skill":"MATH.G5.MEASUR.TIME.SUBTRACT_MIN_SEC","error":"The child adds 60 to the seconds but does not reduce the minutes by 1.","example":{"question":"5 min 20 s − 2 min 45 s = ?","wrong_answer":"3 min 35 s","correct_answer":"2 min 35 s"},"cause":"The child treats borrowing as 'adding 60' rather than as an exchange.","reveals":"Include the answer that is one minute too many as a distractor.","help":"Have pupils cross out the 5 and write 4 above it before touching the seconds column.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC.M_MULT_NO_REGROUP","skill":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC","error":"The child multiplies each part but leaves 60 or more seconds unregrouped.","example":{"question":"It takes 2 min 25 s to fry one batch of mandazi. How long do 3 batches take?","wrong_answer":"6 min 75 s","correct_answer":"7 min 15 s"},"cause":"The child treats the minutes and seconds as unrelated columns.","reveals":"Choose numbers where the product of the seconds is between 60 and 99.","help":"Use the same 'seconds must be under 60' check as in addition, and link it to repeated addition.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC.M_MULT_MINUTES_ONLY","skill":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC","error":"The child multiplies only the minutes and copies the seconds unchanged.","example":{"question":"2 min 25 s × 3 = ?","wrong_answer":"6 min 25 s","correct_answer":"7 min 15 s"},"cause":"The child sees the seconds as a label or a small add-on, not as part of the quantity.","reveals":"Include the answer with unchanged seconds as a distractor.","help":"Have pupils write the problem as repeated addition (2 min 25 s + 2 min 25 s + 2 min 25 s) to see the seconds grow.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC.M_MULT_REGROUP_100","skill":"MATH.G5.MEASUR.TIME.MULTIPLY_MIN_SEC","error":"The child regroups the product of the seconds as if 100 s = 1 min.","example":{"question":"2 min 40 s × 3 = ?","wrong_answer":"7 min 20 s","correct_answer":"8 min"},"cause":"This is the 100-seconds-in-a-minute belief appearing during multiplication (120 s treated as 1 min 20 s).","reveals":"Use a product of the seconds of 100 or more, and include the 100-based regrouped answer as a distractor.","help":"Have pupils convert the product of the seconds separately first (120 s = 2 min) before combining.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC.M_DIV_REMAINDER_DROPPED","skill":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC","error":"The child divides the minutes, throws away the remainder, then divides the seconds.","example":{"question":"Mwalimu shares 7 min 30 s of reading time equally between 2 pupils. How long does each pupil read?","wrong_answer":"3 min 15 s","correct_answer":"3 min 45 s"},"cause":"The child does not see that the leftover minute is still time that must be shared.","reveals":"Use an odd number of minutes with divisor 2, and include the answer with the remainder dropped.","help":"Have pupils check by multiplying the answer by the divisor (3 min 15 s × 2 = 6 min 30 s, not 7 min 30 s).","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC.M_DIV_REMAINDER_AS_TEN","skill":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC","error":"The child carries a remaining minute into the seconds as 10 (or 100) instead of 60.","example":{"question":"7 min 30 s ÷ 2 = ?","wrong_answer":"3 min 20 s (from 10 + 30 = 40, then 40 ÷ 2)","correct_answer":"3 min 45 s (60 + 30 = 90, then 90 ÷ 2 = 45)"},"cause":"The child uses the base-ten carrying from whole-number short division.","reveals":"Choose a remainder of 1 minute, and include the answers that come from 10-based and 100-based carrying as distractors.","help":"Have pupils say aloud 'one minute left over is 60 seconds' and write 60 + 30 before dividing.","status":"draft"},{"code":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC.M_DIV_ONE_PART_ONLY","skill":"MATH.G5.MEASUR.TIME.DIVIDE_MIN_SEC","error":"The child divides only the minutes, or only the seconds, and leaves the other part unchanged.","example":{"question":"A runner at Kasarani completes 2 laps in 6 min 40 s at a steady pace. How long is one lap?","wrong_answer":"3 min 40 s","correct_answer":"3 min 20 s"},"cause":"The child does not treat '6 min 40 s' as a single quantity.","reveals":"Include answers where only one part has been halved.","help":"Show the method of converting to seconds first (400 s ÷ 2 = 200 s = 3 min 20 s) so that the duration is seen as one amount.","status":"draft"}]},{"code":"MATH.G5.MEASUR.MONEY","number":"2.7","strand":"Measurement","sub_strand":"Money","sequence":207,"lessons":8,"content_topics":["Budget","Tax","Services by provided banks"],"learning_experiences":["discuss meaning and importance of a budget","prepare a budget of about 5 items that can be found in the classroom model shop","discuss meaning and importance of taxes to the governments, and study receipts from sales to identify amount of taxes paid","discuss provision of loans, safe custody of items, money deposits and withdrawals, savings as services provided by banks","brainstorm on factors to consider when saving money and share with others","use digital devices to learn how to transfer money from one person to another as part of bank services"],"key_inquiry_questions":["How do you spend your money?","What is the importance of paying taxes?"],"core_competences":"● Communication and collaboration: leaner discuss and shares information about preparation of a shopping budget. ● Learning to learn: learner discusses matters on budgeting, savings, and electronic banking.","values":"Patriotism: learner appreciates importance of taxes to the government of Kenya.","pcis":"Financial literacy: learner appreciates the importance of budgeting, personal savings and banking services.","links":"The learner is able to relate concept of money to resources and economic activities in Kenya in Social Studies.","design_notes":"Attitudinal outcome:\n- Outcome g ('appreciate use of budgeting, bank services and payment of taxes in real life') is attitudinal. It is not mapped to a skill and should be observed through class discussion and projects.\n\nAmbiguities in the outcomes:\n- Outcome c says 'up to 5 items' while the learning experience says 'about 5 items'. The skills follow the outcome (no more than 5).\n- Outcome c gives no limit on money values. The proposed limit of 10,000 shillings follows G4 3.7c. Whole shillings are proposed for budget prices.\n- Outcome d covers the meaning and importance of tax. The receipt-reading skill (G5_TAX_ON_RECEIPT) comes from the learning experiences, not a separate outcome. It is limited to reading the tax amount; working out VAT percentages is not expected at Grade 5. Naming types of tax is Grade 6 (2.6e) and should not be assessed here.\n- Outcome e covers bank services. Money transfer by digital device appears only in the learning experiences, so G5_MONEY_TRANSFER_DIGITAL is a proposed separate skill. Many Kenyan children know M-Pesa, which is mobile money run by a mobile network operator, not a bank. Teachers may want to say that banks also offer transfers through apps and mobile banking. Transfer charges belong to Grade 6 bank charges.\n- The lists of saving factors and budget reasons in the skills are proposed professional judgement, not KICD text.\n\nErrors in the source text:\n- The content topic 'Services by provided banks' appears to be a word-order error in the design for 'Services provided by banks'.\n- The second key inquiry question contains stray text: 'Inquiry Question(s)'.\n- The outcomes are marked as verified from the text layer only.\n\nProgression:\n- Grade 6 2.6a ('prepare simple budget') revisits budgeting, so the Grade 5 work leads straight into it.\n- Profit and loss are Grade 6 outcomes (2.6b–d).\n\nHOREB mapping:\n- The existing HOREB id G5_MONEY is titled 'Money (Profit & Loss)'. This does not match the Grade 5 design, which has no profit or loss, so it is not linked. Its content fits Grade 6. This should be reviewed.\n- G4_MONEY is titled 'Budgets, Spending & Saving', but the Grade 4 outcomes only cover cents and shillings, a shopping list of 3 items and total cost. Its overlap with the Grade 5 budget and saving skills is therefore partial.\n- G6_MONEY (bank charges) is linked as a forward overlap for the bank services skills only.\n\nPrerequisites outside the inputs:\n- Whole-number addition, subtraction and multiplication come from the Numbers strand, which is not given in the inputs. These are true prerequisites for G5_BUDGET_ITEM_COSTS and G5_BUDGET_TOTAL_BALANCE but cannot be coded here.","outcomes":[{"code":"MATH.G5.MEASUR.MONEY.a","letter":"a","text":"explain the term budget in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MONEY.b","letter":"b","text":"identify the importance of a budget in real life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MONEY.c","letter":"c","text":"prepare a budget of up to 5 items used in daily life","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MONEY.d","letter":"d","text":"explain meaning of tax and its importance to the government","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MONEY.e","letter":"e","text":"identify services provided by banks in real-life situations","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MONEY.f","letter":"f","text":"identify factors to consider in order to save money wisely","status":"kicd_verified"},{"code":"MATH.G5.MEASUR.MONEY.g","letter":"g","text":"appreciate use of budgeting, bank services and payment of taxes in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING","name":"Explain what a budget is","outcomes":["MATH.G5.MEASUR.MONEY.a"],"mastery":"The child explains in their own words that a budget is a plan, made before spending, of how a known amount of money will be used. They can tell a budget apart from a plain shopping list (no costs or money available) and from a receipt (a record made after buying). Contexts are home, school and the classroom model shop.","question_forms":["explain in own words","pick the budget: budget vs shopping list vs receipt","true or false about budgets","give a real-life example of when a budget is made"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G4_MONEY"],"prerequisites":[{"requires":"MATH.G4.MEASUR.MONEY.b","kind":"outcome","strength":"helpful","reason":"A budget builds on the Grade 4 shopping list by adding costs and money available.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE","name":"Identify why a budget is important","outcomes":["MATH.G5.MEASUR.MONEY.b"],"mastery":"The child gives at least three reasons for budgeting, for example avoiding overspending, putting needs before wants, leaving money to save, and avoiding debt. They can say which item a family should drop first when money is short. The needs-before-wants reasoning is a proposed part of this skill.","question_forms":["list reasons","scenario: what went wrong without a budget","needs vs wants sorting","which item to drop first and why"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G4_MONEY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING","kind":"skill","strength":"essential","reason":"A child must know what a budget is before explaining why it matters.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS","name":"Work out the cost of each line in a budget (quantity × unit price)","outcomes":["MATH.G5.MEASUR.MONEY.c"],"mastery":"For each of up to 5 everyday items, the child finds the line cost from a quantity and a unit price, e.g. 3 kg of sugar at 180 shillings per kg. Proposed limits: whole shillings, whole-number quantities up to about 10, plus halves (e.g. ½ kg), and line costs within 10,000 shillings.","question_forms":["complete the cost column of a budget table","word problem: cost of several of one item","missing unit price or quantity","spot the error in a budget line"],"thinking":["procedure"],"horeb_skill_ids":["G4_MONEY"],"prerequisites":[{"requires":"MATH.G4.MEASUR.MONEY.c","kind":"outcome","strength":"essential","reason":"Working out the cost of items on a list, up to 10,000 shillings, is the core arithmetic of a budget line.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MONEY.b","kind":"outcome","strength":"helpful","reason":"Familiarity with listing items and quantities makes the budget table easier to set out.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE","name":"Prepare a full budget of up to 5 items: total, compare with money available, balance or adjust","outcomes":["MATH.G5.MEASUR.MONEY.c"],"mastery":"The child sets out a budget of up to 5 items with columns for item, quantity, unit price and cost. They add the line costs and compare the total with the money available, then either state the balance or, if there is a shortfall, adjust the budget by dropping or reducing wants. Proposed limits: money available and totals up to 10,000 shillings, matching G4 3.7c.","question_forms":["prepare a budget from a price list (model shop)","find the total of a budget","find the balance left","can she afford it? shortfall and adjust","open task: plan a budget for a given amount"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G4_MONEY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS","kind":"skill","strength":"essential","reason":"The total must be built from correct line costs, not unit prices.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MONEY.c","kind":"outcome","strength":"essential","reason":"Totalling costs within 10,000 shillings is carried straight over from Grade 4.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING","kind":"skill","strength":"helpful","reason":"Knowing a budget is limited by the money available explains why the balance is checked.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE","kind":"skill","strength":"helpful","reason":"Putting needs before wants guides which item to drop when there is a shortfall.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.TAX_MEANING","name":"Explain what tax is and why the government needs it","outcomes":["MATH.G5.MEASUR.MONEY.d"],"mastery":"The child explains that tax is money people and businesses must pay to the government, which collects it through KRA. They name public services paid for with taxes, such as roads, public schools, hospitals, security and water. They do not need to name types of tax, which is Grade 6 outcome 2.6e.","question_forms":["explain in own words","who receives the tax?","match tax to services it pays for","true or false about tax","why should people pay tax?"],"thinking":["recall","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G4.MEASUR.MONEY.d","kind":"outcome","strength":"helpful","reason":"General awareness of how money is used in daily life supports the idea of paying money for public services.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.TAX_ON_RECEIPT","name":"Identify the amount of tax paid on a sales receipt","outcomes":["MATH.G5.MEASUR.MONEY.d"],"mastery":"From a real or model Kenyan receipt, the child finds the line that shows tax (e.g. 'VAT 16%') and reads the tax amount in shillings and cents. They understand that the total already includes this tax. Proposed limit: read and identify only; working out VAT as a percentage is not required at Grade 5. This skill comes from the learning experiences, not a separate outcome.","question_forms":["read the receipt: how much tax?","how much did the customer pay in total?","which line shows the tax?","price before tax (total − tax)"],"thinking":["procedure","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G5.MEASUR.MONEY.TAX_MEANING","kind":"skill","strength":"essential","reason":"A child must know what tax is to recognise the tax line on a receipt.","status":"proposed"},{"requires":"MATH.G4.MEASUR.MONEY.a","kind":"outcome","strength":"helpful","reason":"Receipt amounts are written in shillings and cents (e.g. 137.93).","status":"proposed"},{"requires":"MATH.G4.MEASUR.MONEY.c","kind":"outcome","strength":"helpful","reason":"Reading item costs and totals on a receipt draws on Grade 4 total-cost work.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.BANK_SERVICES","name":"Identify services provided by banks in real-life situations","outcomes":["MATH.G5.MEASUR.MONEY.e"],"mastery":"The child names and describes bank services: deposits, withdrawals, savings accounts, loans (paid back with interest), safe custody of valuables and documents, and money transfer. Given a short real-life situation, they say which service is being used.","question_forms":["name the services","match situation to bank service","true or false (e.g. loans are paid back)","vocabulary: deposit vs withdrawal"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G6_MONEY"],"prerequisites":[{"requires":"MATH.G4.MEASUR.MONEY.d","kind":"outcome","strength":"helpful","reason":"Awareness of how money is used and kept in real life supports talking about banks.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.MONEY_TRANSFER_DIGITAL","name":"Describe how money is transferred from one person to another using digital devices, and how to stay safe","outcomes":["MATH.G5.MEASUR.MONEY.e"],"mastery":"The child describes the steps of sending money with a phone or banking app: choose 'send money', enter the recipient's number or account, enter the amount, check the recipient's name, then enter the PIN and confirm. They explain the safety rules: never share the PIN and always check the name before sending. Proposed limit: describing the steps only; working out transfer charges is Grade 6 (bank charges).","question_forms":["put the transfer steps in order","what should you check before pressing send?","safety scenario: someone asks for your PIN","role play with a model phone"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G6_MONEY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MONEY.BANK_SERVICES","kind":"skill","strength":"essential","reason":"Transfer is one bank service and relies on understanding accounts, deposits and withdrawals.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS","name":"Identify factors to consider in order to save money wisely","outcomes":["MATH.G5.MEASUR.MONEY.f"],"mastery":"The child names and explains factors in wise saving, and applies them to choose the wiser plan in a short scenario. The factors (a proposed list) are:\n- how much money comes in\n- needs before wants\n- setting a saving goal and a time to reach it\n- deciding the amount to save before spending\n- choosing a safe place to save (bank, SACCO, children's account rather than at home)\n- saving regularly, even in small amounts\n- interest earned","question_forms":["brainstorm or list factors","which is the wiser saving plan?","where is the safest place to save and why?","advise a character on saving"],"thinking":["recall","reasoning","problem solving"],"horeb_skill_ids":["G4_MONEY"],"prerequisites":[{"requires":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE","kind":"skill","strength":"helpful","reason":"Planning to save is part of budgeting and of putting needs before wants.","status":"proposed"},{"requires":"MATH.G5.MEASUR.MONEY.BANK_SERVICES","kind":"skill","strength":"helpful","reason":"Choosing a safe place to save relies on knowing that banks offer savings accounts.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING.M_BUDGET_IS_RECEIPT","skill":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING","error":"Thinks a budget is the record of what was already bought, such as a receipt, rather than a plan made before spending.","example":{"question":"Which one is a budget? A: Wanjiru's list, written before going to Marikiti market, showing items and the money planned for each. B: The receipt Wanjiru got after paying.","wrong_answer":"B","correct_answer":"A, because a budget is a plan made before spending."},"cause":"Both documents list items and prices, and the child has seen receipts far more often than budgets.","reveals":"A 'choose the budget' item that places a receipt beside a planned list with costs and money available.","help":"Show a budget and the matching receipt side by side and ask 'Which was written before shopping, and which after?'","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING.M_BUDGET_NO_MONEY_LIMIT","skill":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING","error":"Treats a list of wanted items, with no costs and no money available, as a complete budget.","example":{"question":"Otieno has 500 shillings. He writes: sugar, bread, milk. Is this a complete budget?","wrong_answer":"Yes","correct_answer":"No. It needs the cost of each item, the total, and the money available (500 shillings) to compare with."},"cause":"The child carries over the Grade 4 shopping list idea without adding the money side.","reveals":"A 'Is this a budget? What is missing?' item using a bare list of items.","help":"Have learners turn a shopping list into a budget by adding three things: cost, total, and money available.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING.M_BUDGET_ONLY_FOR_GOVERNMENT","skill":"MATH.G5.MEASUR.MONEY.BUDGET_MEANING","error":"Believes budgets are only for governments, businesses or adults with a lot of money.","example":{"question":"Does a child with 100 shillings pocket money need a budget?","wrong_answer":"No, budgets are only for the government and big businesses.","correct_answer":"Yes. Anyone with money to spend can plan how to use it, even 100 shillings."},"cause":"The child hears 'budget' mostly in news about the national budget reading.","reveals":"A true or false statement such as 'Only the government makes budgets', or a scenario about a child's pocket money.","help":"Let each learner budget a small amount, such as 100 shillings at the school canteen, so the idea feels personal.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE.M_BUDGET_MEANS_SPEND_ALL","skill":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE","error":"Thinks the aim of a budget is to spend all the money, so money left over means the budget failed.","example":{"question":"Akinyi budgeted 1,000 shillings for the week's shopping and spent 850 shillings. Did her budget fail?","wrong_answer":"Yes, because she did not use all the money.","correct_answer":"No. She spent within her budget and has 150 shillings left to save."},"cause":"The child sees the money available as a target to reach rather than a limit not to pass.","reveals":"A scenario where spending is under budget, asking whether the budget worked.","help":"Describe the money available as a ceiling, and praise plans that leave something to save.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE.M_DROP_MOST_EXPENSIVE","skill":"MATH.G5.MEASUR.MONEY.BUDGET_IMPORTANCE","error":"When money is short, removes the most expensive item even if it is a need, instead of removing a want.","example":{"question":"Mama Achieng's budget is too high. Her items are maize flour (230 shillings), soap (120 shillings) and sweets (50 shillings). Which item should she remove first?","wrong_answer":"Maize flour, because it costs the most.","correct_answer":"Sweets, because they are a want. Maize flour and soap are needs."},"cause":"The child focuses only on the numbers and does not judge needs against wants.","reveals":"A 'which item to drop' item where the most expensive item is clearly a need.","help":"Before any cutting, have learners label each budget item 'N' (need) or 'W' (want).","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS.M_UNIT_PRICE_AS_COST","skill":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS","error":"Writes the unit price as the cost of the line, ignoring the quantity.","example":{"question":"Sugar costs 180 shillings per kg. What is the cost of 3 kg?","wrong_answer":"180 shillings","correct_answer":"3 × 180 = 540 shillings"},"cause":"The child copies the price straight from the price list and does not link quantity to cost.","reveals":"A budget table with quantities greater than 1; the unit price appears as a distractor.","help":"Have learners say each line aloud ('3 kilograms at 180 shillings each') and act it out with model shop items.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS.M_ADD_QTY_AND_PRICE","skill":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS","error":"Adds the quantity to the unit price instead of multiplying.","example":{"question":"Kamau buys 4 packets of milk at 65 shillings each. What is the cost?","wrong_answer":"69 shillings","correct_answer":"4 × 65 = 260 shillings"},"cause":"The child grabs the two numbers and uses the operation they find most familiar.","reveals":"A multiple-choice item that includes the sum (69) as a distractor.","help":"Have learners check by repeated addition (65 + 65 + 65 + 65) to see why the answer must be much larger than 65.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS.M_FORGET_CARRY","skill":"MATH.G5.MEASUR.MONEY.BUDGET_ITEM_COSTS","error":"Forgets to add the carried ten when multiplying a 2-digit price by a 1-digit quantity.","example":{"question":"5 exercise books cost 45 shillings each. What is the total cost?","wrong_answer":"205 shillings","correct_answer":"225 shillings, because 5 × 45 = 200 + 25."},"cause":"The child writes down 5 and carries 2 from 5 × 5 = 25, then works out 5 × 4 = 20 but does not add the 2.","reveals":"Questions where the ones digit times the quantity is 10 or more, with the 'no-carry' answer offered as a distractor.","help":"Teach a quick estimate (5 × 45 is about 5 × 50 = 250) so learners notice that 205 is too low.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE.M_TOTAL_OF_UNIT_PRICES","skill":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE","error":"Adds the unit prices instead of the line costs to get the budget total.","example":{"question":"Budget: rice, 2 kg at 150 shillings per kg, cost 300 shillings. Cooking oil, 1 litre at 320 shillings, cost 320 shillings. What is the total?","wrong_answer":"470 shillings","correct_answer":"300 + 320 = 620 shillings"},"cause":"The child adds the wrong column, not seeing that the cost column is the one that matters.","reveals":"A full budget table with quantities greater than 1; the sum of unit prices is a distractor.","help":"Have learners shade the cost column and add only the shaded numbers.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE.M_BALANCE_ADDED","skill":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE","error":"Adds the total to the money available instead of subtracting to find the balance.","example":{"question":"Njeri has 1,000 shillings. Her budget total is 870 shillings. How much will be left?","wrong_answer":"1,870 shillings","correct_answer":"1,000 − 870 = 130 shillings"},"cause":"The child has just added the costs and keeps adding; 'balance' is not linked to 'left over'.","reveals":"A balance item with the sum offered as a distractor; the answer is larger than the money she had.","help":"Ask 'Can you have more left than you started with?' and model the balance as change from a model-shop sale.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE.M_SMALLER_FROM_LARGER","skill":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE","error":"In column subtraction, takes the smaller digit from the larger in each column instead of exchanging, especially across zeros.","example":{"question":"Money available: 1,500 shillings. Total: 1,265 shillings. Find the balance.","wrong_answer":"365 shillings","correct_answer":"235 shillings"},"cause":"The child believes you 'always take the small number from the big number' in each column.","reveals":"Balance questions where the money available has zeros in the ones or tens place.","help":"Check by adding back (235 + 1,265 = 1,500) and practise exchanging with play-money notes and coins.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE.M_SHORTFALL_IGNORED","skill":"MATH.G5.MEASUR.MONEY.BUDGET_TOTAL_BALANCE","error":"When the total is more than the money available, reverses the subtraction and reports a 'balance' instead of noticing the shortfall.","example":{"question":"Halima has 500 shillings. Her budget total is 560 shillings. Can she buy everything?","wrong_answer":"Yes, her balance is 60 shillings.","correct_answer":"No. She is short by 560 − 500 = 60 shillings, so she must remove or reduce an item, starting with wants."},"cause":"The child subtracts mechanically and does not compare the two amounts first.","reveals":"An 'Can she afford it?' item where the total is greater than the money available.","help":"Always start with the question 'Is the total more or less than the money available?' before calculating.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.TAX_MEANING.M_TAX_IS_FINE","skill":"MATH.G5.MEASUR.MONEY.TAX_MEANING","error":"Thinks tax is a fine or punishment paid for doing something wrong.","example":{"question":"What is tax?","wrong_answer":"Money you pay as a punishment when you break a rule.","correct_answer":"Money that people and businesses must pay to the government so it can provide services such as roads, schools and hospitals."},"cause":"Both tax and fines are compulsory payments to authorities, and children hear about fines such as traffic fines.","reveals":"A multiple-choice definition item with 'a punishment for breaking rules' as a distractor.","help":"Contrast the two directly: a fine is paid only when you break a rule; tax is paid by everyone who earns or buys.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.TAX_MEANING.M_TAX_KEPT_BY_SHOP","skill":"MATH.G5.MEASUR.MONEY.TAX_MEANING","error":"Believes the tax shown on a receipt is kept by the shop as extra profit.","example":{"question":"A supermarket receipt shows 'VAT 80.00'. Who gets this money in the end?","wrong_answer":"The supermarket","correct_answer":"The government. The shop collects it from the customer and pays it to KRA."},"cause":"The child sees the customer paying the shop and cannot picture the money being passed on.","reveals":"A 'who receives the tax?' item with the shop as a distractor.","help":"Draw the path of the money: customer → shop → KRA → government → road, school or hospital.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.TAX_MEANING.M_GOVT_PRINTS_MONEY","skill":"MATH.G5.MEASUR.MONEY.TAX_MEANING","error":"Thinks the government does not need taxes because it can simply print or already has money.","example":{"question":"Why does the government collect taxes?","wrong_answer":"It does not need to, because it can print as much money as it wants.","correct_answer":"To pay for public services such as roads, public schools, hospitals, security and the salaries of teachers and nurses."},"cause":"The child knows the Central Bank makes money and has no idea where government spending comes from.","reveals":"A 'why collect tax?' item, or a true or false item stating 'The government does not need taxes'.","help":"Walk through a local example, such as a new classroom or road, and ask who paid the builders.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.TAX_ON_RECEIPT.M_ADD_TAX_AGAIN","skill":"MATH.G5.MEASUR.MONEY.TAX_ON_RECEIPT","error":"Adds the VAT line to the receipt total, not realising the total already includes the tax.","example":{"question":"A receipt shows 'TOTAL 580.00' and below it 'VAT 16% included: 80.00'. How much did the customer pay?","wrong_answer":"660.00 shillings","correct_answer":"580.00 shillings, because the 80.00 tax is already inside the total."},"cause":"The child treats every amount on a receipt as something to add.","reveals":"A 'how much was paid?' item on a real receipt layout, with total + VAT as a distractor.","help":"Compare the receipt total with the cash and change lines to show that the customer paid exactly the total.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.TAX_ON_RECEIPT.M_TAX_RATE_AS_AMOUNT","skill":"MATH.G5.MEASUR.MONEY.TAX_ON_RECEIPT","error":"Reads the tax rate (16%) or another line, such as change, as the amount of tax paid.","example":{"question":"Receipt: TOTAL 1,160.00; VAT 16%: 160.00; CASH 1,200.00; CHANGE 40.00. How much tax was paid?","wrong_answer":"16 shillings","correct_answer":"160.00 shillings"},"cause":"The child picks the first number next to the word 'VAT' and does not understand the % sign.","reveals":"A receipt-reading item with the rate (16) and the change (40) both offered as distractors.","help":"Teach learners to find the money amount at the right-hand end of the VAT line, and read real receipts brought from home.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BANK_SERVICES.M_BANK_KEEPS_SAME_NOTES","skill":"MATH.G5.MEASUR.MONEY.BANK_SERVICES","error":"Believes the bank keeps each customer's exact notes in a box with their name, to be given back later.","example":{"question":"Mwangi deposits one 1,000-shilling note. When he withdraws 1,000 shillings, must he get the same note back?","wrong_answer":"Yes, the bank keeps his note in a box with his name on it.","correct_answer":"No. The bank records 1,000 shillings in his account; he can be given any notes or coins worth 1,000 shillings."},"cause":"The child confuses a deposit with safe custody of a particular item.","reveals":"A true or false item about getting the 'same money' back, or a 'deposit vs safe custody' matching item.","help":"Run a class 'bank' with a record book, so learners see that balances are recorded and the notes are mixed together.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BANK_SERVICES.M_LOAN_IS_GIFT","skill":"MATH.G5.MEASUR.MONEY.BANK_SERVICES","error":"Thinks a bank loan is free money that does not have to be paid back.","example":{"question":"Mama Njeri borrows 20,000 shillings from a bank to buy a posho mill. Does she have to pay it back?","wrong_answer":"No, the bank gave her the money.","correct_answer":"Yes. She must repay the 20,000 shillings plus interest within the agreed time."},"cause":"The child has seen people receive money from banks but has not seen the repayments.","reveals":"A scenario or true or false item about repaying a loan.","help":"Compare a loan to borrowing a classmate's pencil: it must be returned, and the bank charges extra (interest) for lending.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.BANK_SERVICES.M_DEPOSIT_WITHDRAW_SWAP","skill":"MATH.G5.MEASUR.MONEY.BANK_SERVICES","error":"Confuses the words 'deposit' and 'withdrawal'.","example":{"question":"Putting money into your bank account is called a ______.","wrong_answer":"withdrawal","correct_answer":"deposit"},"cause":"Both are unfamiliar banking words used together, and the child has no memory hook for either.","reveals":"A fill-in or match-the-picture item showing money going into or out of an account.","help":"Use arrows on the board: deposit = money IN to the account; withdraw = money OUT ('draw out').","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.MONEY_TRANSFER_DIGITAL.M_SHARE_PIN","skill":"MATH.G5.MEASUR.MONEY.MONEY_TRANSFER_DIGITAL","error":"Thinks it is fine to tell a PIN to someone who says they are from the bank, or to a friend or agent.","example":{"question":"A caller says he is from the bank and asks for your PIN to 'fix your account'. What should you do?","wrong_answer":"Tell him the PIN so he can fix it.","correct_answer":"Never share your PIN. Hang up and tell a parent or the bank, because the bank never asks for your PIN."},"cause":"The child trusts anyone who claims authority and does not understand that the PIN protects the money.","reveals":"A safety scenario item asking what the person should do.","help":"Role-play common fraud calls and repeat the rule: 'My PIN is mine alone.'","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.MONEY_TRANSFER_DIGITAL.M_NO_CHECK_RECIPIENT","skill":"MATH.G5.MEASUR.MONEY.MONEY_TRANSFER_DIGITAL","error":"Skips checking the recipient's name on the confirmation screen, believing wrongly sent money always comes back.","example":{"question":"Mum wants to send 500 shillings to Jane Achieng. The screen says 'Send 500 to JOHN OCHIENG?' What should she do?","wrong_answer":"Press send; the money will find the right person.","correct_answer":"Cancel, check the number and enter it correctly, then confirm the name says Jane Achieng before sending."},"cause":"The child sees the confirmation screen as a formality and thinks transfers can always be undone.","reveals":"A 'what should you check before pressing send?' item, or ordering steps where the check step is left out.","help":"Practise on a paper model phone in which one card shows a wrong name, and make 'read the name' a required step.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS.M_SAVE_WHATS_LEFT","skill":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS","error":"Plans to save only whatever is left after spending, instead of setting aside a saving amount first.","example":{"question":"Baraka gets 200 shillings pocket money each week. Which is the wiser plan? A: Spend on what he wants and save whatever is left. B: Put aside 50 shillings first, then spend the rest on needs.","wrong_answer":"A","correct_answer":"B, because deciding the saving amount first means he will really save."},"cause":"The child sees saving as leftover money, not as a planned part of the budget.","reveals":"A 'which is the wiser plan?' item comparing 'save first' with 'save leftovers'.","help":"Have learners write the saving amount as the first line of their budget.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS.M_HOME_AS_SAFE_AS_BANK","skill":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS","error":"Thinks keeping savings at home, such as in a tin or under a mattress, is as safe as a bank or SACCO.","example":{"question":"Where is the safest place to keep 5,000 shillings saved for school fees?","wrong_answer":"In a tin under the bed","correct_answer":"In a bank or SACCO account, because it is protected from theft, fire and spending on impulse, and may earn interest."},"cause":"The child has seen family members keep money at home and can see it there.","reveals":"A 'safest place to save and why' item with home options as distractors.","help":"Discuss what could happen to money kept at home (theft, fire, rats, being tempted to spend it) and compare with an account.","status":"draft"},{"code":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS.M_SAVING_ONLY_FOR_RICH","skill":"MATH.G5.MEASUR.MONEY.SAVING_FACTORS","error":"Believes saving is only possible for people with a lot of money.","example":{"question":"Wafula gets 20 shillings a day. Can he save?","wrong_answer":"No, saving is only for people with a lot of money.","correct_answer":"Yes. If he saves 10 shillings a day, he has 10 × 7 = 70 shillings after one week."},"cause":"The child thinks small amounts do not matter and has not seen regular saving add up.","reveals":"A true or false or scenario item about saving small amounts regularly.","help":"Keep a class chart showing how a small daily saving grows week by week.","status":"draft"}]},{"code":"MATH.G5.GEOMET.LINES","number":"3.1","strand":"Geometry","sub_strand":"Lines","sequence":301,"lessons":4,"content_topics":["horizontal and vertical lines","perpendicular and parallel lines"],"learning_experiences":["work with peers to identify lines in the classroom and within the environment","describe lines in the environment and identify them as horizontal and vertical lines, parallel and perpendicular lines","work with peers to draw and model horizontal and vertical lines, parallel and perpendicular lines","use digital devices and other resources to draw more lines"],"key_inquiry_questions":["Where are perpendicular lines used?"],"core_competences":"● Learning to learn: learner draws different horizontal, vertical, parallel and perpendicular lines. ● Digital literacy: learner uses digital devices to learn more about lines.","values":"Unity: learner works with peers to draw and model horizontal and vertical lines, parallel and perpendicular lines.","pcis":"Environmental awareness: learner teams up with peers to identify lines in the classroom and within the environment.","links":"The learner is able to relate line to sketching and drawing in Creative Arts.","design_notes":"1) Outcomes b, d and f read 'in different salutations'. This is clearly a typing error in the design for 'situations' (as in a, c and e), and the wording is kept as given. All outcomes are marked 'verified: text layer' only. 2) Outcome g ('appreciate use of various types of lines in real life') is attitudinal and is not mapped to a skill. It can be observed through the learning experiences (finding lines in the classroom and environment, and the key inquiry question 'Where are perpendicular lines used?'). The key inquiry question text in the input ends with the stray words 'Inquiry Question(s)', which look like a layout artefact. 3) The design does not name drawing tools. The use of ruler, set square, square grid and folded-paper right angles is proposed. Grade 6 outcome 3.1c 'construct perpendicular lines' is taken to mean compass construction, so Grade 5 drawing of perpendiculars is proposed to be by set square, grid or folding, through a point on the line only. Grade 6 outcome 3.1a repeats 'draw parallel lines', so the Grade 5 and Grade 6 limits between them are unclear. The proposed split is that Grade 5 draws parallels with set square or grid, possibly at a given distance, and Grade 6 extends this. 4) On paper, 'horizontal' and 'vertical' are taken (proposed convention) to mean parallel to the bottom and side edges of the page. In the environment they mean level and upright (plumb). Assessment items should make clear which is meant. 5) The design says 'lines' throughout. In practice children draw and judge line segments, and items should not depend on the distinction beyond the idea that parallel lines never meet when extended. 6) There are six assessable outcomes in four suggested lessons. Identifying and drawing are likely to be taught together for each pair of line types. 7) HOREB G5_LINES covers parallel and perpendicular lines only. No existing HOREB skill covers horizontal and vertical lines, so those two skills have no linked id. G5_ANGLES_INTRO is linked to perpendicular identification because it depends on recognising a right angle. Its exact content was not given, so the overlap is proposed. 8) The numeric limits in what_mastery_looks_like (lengths up to 15 cm, gaps up to 10 cm, accuracy about 2 mm) are proposed. The design gives no measurement limits for this sub-strand.","outcomes":[{"code":"MATH.G5.GEOMET.LINES.a","letter":"a","text":"identify horizontal and vertical lines in different situations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.LINES.b","letter":"b","text":"draw horizontal and vertical lines in different salutations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.LINES.c","letter":"c","text":"identify perpendicular lines in different situations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.LINES.d","letter":"d","text":"draw perpendicular lines in different salutations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.LINES.e","letter":"e","text":"identify parallel lines in different situations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.LINES.f","letter":"f","text":"draw parallel lines in different salutations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.LINES.g","letter":"g","text":"appreciate use of various types of lines in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","name":"Identify horizontal and vertical lines","outcomes":["MATH.G5.GEOMET.LINES.a"],"mastery":"The child correctly names lines in the environment (table tops, door frames, flag poles, window bars, a plumb line) and in drawings as horizontal (level, like the horizon or the bottom edge of the page), vertical (upright, like a hanging plumb line or the side edge of the page) or neither (slanting). The child does this however long the lines are and wherever they sit on the page, and does not call steep or shallow slanting lines vertical or horizontal (proposed limits: pictures and line drawings; no measurement needed).","question_forms":["classify: horizontal / vertical / neither","pick the object or picture (multiple choice)","count horizontal or vertical lines in a figure or letter","spot the odd one out and explain","true/false with reason"],"thinking":["recall","reasoning"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.a","kind":"outcome","strength":"helpful","reason":"Spotting rectangles and squares in the environment draws attention to their level and upright edges.","status":"proposed"},{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.e","kind":"outcome","strength":"helpful","reason":"Describing the sides of plane figures gives the habit of looking at individual straight lines.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.LINES.DRAW_HORIZONTAL_VERTICAL","name":"Draw horizontal and vertical lines","outcomes":["MATH.G5.GEOMET.LINES.b"],"mastery":"Using a ruler, and the page edge, a square grid or a set square as a guide, the child draws horizontal and vertical lines of a given length that are truly level or upright on the page. Lengths are measured from the 0 mark and are accurate to about 2 mm (proposed limits: whole-centimetre lengths up to 15 cm; drawing on plain or squared paper).","question_forms":["draw a horizontal or vertical line of a given length","draw on a grid from a given dot","complete a figure with horizontal or vertical lines","check a classmate's drawing and correct it"],"thinking":["procedure"],"horeb_skill_ids":[],"prerequisites":[{"requires":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","kind":"skill","strength":"essential","reason":"A child must know what horizontal and vertical mean before drawing them.","status":"proposed"},{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.b","kind":"outcome","strength":"helpful","reason":"Drawing rectangles and squares gives practice in using a ruler to draw straight sides.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR","name":"Identify perpendicular lines","outcomes":["MATH.G5.GEOMET.LINES.c"],"mastery":"The child recognises perpendicular lines as lines that meet or cross at a right angle. This includes pairs that form an L, a T or a + shape, and pairs that are tilted (neither line horizontal or vertical). The child checks doubtful cases with a set square or a folded-paper right-angle tester instead of judging by eye, and finds perpendicular sides in squares, rectangles and right-angled triangles and in the environment (corners of books, window frames, crossroads).","question_forms":["yes/no: are these lines perpendicular?","pick the perpendicular pair (multiple choice with tilted and near-right distractors)","name the perpendicular sides in a shape","find examples in the environment","explain why a pair is or is not perpendicular"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_LINES","G5_ANGLES_INTRO"],"prerequisites":[{"requires":"MATH.G4.GEOMET.ANGLES.a","kind":"outcome","strength":"essential","reason":"Perpendicular is defined by the angle where two lines meet, so the child must see an angle at a point.","status":"proposed"},{"requires":"MATH.G4.GEOMET.ANGLES.c","kind":"outcome","strength":"essential","reason":"Relating a quarter turn to an angle is how the right angle is understood.","status":"proposed"},{"requires":"MATH.G4.GEOMET.POSITION_AND_DIRECTION.c","kind":"outcome","strength":"helpful","reason":"A quarter turn is the movement that makes a right angle.","status":"proposed"},{"requires":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","kind":"skill","strength":"helpful","reason":"A horizontal line and a vertical line are the most familiar perpendicular pair and a natural starting example.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR","name":"Draw perpendicular lines","outcomes":["MATH.G5.GEOMET.LINES.d"],"mastery":"Given a line in any orientation (horizontal, vertical or slanting) and a point on it, the child draws a line through that point at a right angle to it. The child uses a ruler with a set square, a square grid or a folded-paper right angle, and checks the right angle afterwards (proposed limits: point on the line only; construction with pair of compasses is left to Grade 6, outcome 3.1c).","question_forms":["draw a perpendicular through a marked point on a line","draw a perpendicular to a slanting line","complete a right-angled corner or rectangle","check and correct a drawn 'perpendicular'"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_LINES"],"prerequisites":[{"requires":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR","kind":"skill","strength":"essential","reason":"The child must recognise a right angle to draw and check one.","status":"proposed"},{"requires":"MATH.G5.GEOMET.LINES.DRAW_HORIZONTAL_VERTICAL","kind":"skill","strength":"helpful","reason":"Accurate ruler use and line drawing are carried over directly.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL","name":"Identify parallel lines","outcomes":["MATH.G5.GEOMET.LINES.e"],"mastery":"The child recognises parallel lines as lines that stay the same distance apart all along and never meet however far they are extended. This holds whatever their length, position or slant. The child rejects lines that are slowly getting closer, and finds parallel lines in shapes (opposite sides of a rectangle) and the environment (railway lines, ruled lines in an exercise book, rungs of a ladder, iron sheet ridges).","question_forms":["yes/no: are these lines parallel?","pick the parallel pair (multiple choice with unequal-length and converging distractors)","name the parallel sides in a shape","find examples in the environment","sort pairs into parallel / perpendicular / neither"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_LINES"],"prerequisites":[{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.e","kind":"outcome","strength":"helpful","reason":"Opposite sides of rectangles and squares are the first parallel lines children meet as a property of a shape.","status":"proposed"},{"requires":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","kind":"skill","strength":"helpful","reason":"Pairs of horizontal lines and pairs of vertical lines are easy first examples of parallel lines.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL","name":"Draw parallel lines","outcomes":["MATH.G5.GEOMET.LINES.f"],"mastery":"Given a line in any orientation, the child draws a line parallel to it. Where asked, the new line is a given distance away, measured at right angles to the given line at two places or made by sliding a set square along a ruler. A square grid can also be used. The child checks the gap is equal at both ends (proposed limits: whole-centimetre gaps up to 10 cm).","question_forms":["draw a line parallel to a given line","draw a parallel line a given distance away","draw parallel lines on a grid","complete a rectangle or a pattern of parallel lines","check and correct a drawn 'parallel'"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_LINES","G6_LINES"],"prerequisites":[{"requires":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL","kind":"skill","strength":"essential","reason":"The child must know what makes lines parallel to draw and check them.","status":"proposed"},{"requires":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR","kind":"skill","strength":"helpful","reason":"The distance between parallel lines is measured along a perpendicular, and the set-square method relies on a right angle.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL.M_HV_SWAP_NAMES","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","error":"Mixes up the words, calling level lines vertical and upright lines horizontal.","example":{"question":"Is the top edge of the teacher's table a horizontal or a vertical line?","wrong_answer":"Vertical","correct_answer":"Horizontal"},"cause":"The two words are new and similar-sounding, and the child has no picture attached to each one.","reveals":"Paired items with one level and one upright object; a child with this error gets both wrong in a consistent pattern.","help":"Link 'horizontal' to the horizon (the flat line where land meets sky, as across Lake Victoria) and 'vertical' to a stone hanging on a string, and have children act both with their arms.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL.M_HV_SLANT_COUNTS","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","error":"Calls a steep slanting line vertical or a gently slanting line horizontal, not seeing 'neither' as an option.","example":{"question":"A ladder leans against the wall of a classroom. Is the ladder horizontal, vertical or neither?","wrong_answer":"Vertical","correct_answer":"Neither, it is slanting"},"cause":"The child sorts lines into 'mostly up' and 'mostly across' instead of exactly upright and exactly level.","reveals":"Include a slanting option and a 'neither' choice. A child who picks vertical for a steep slant shows the error.","help":"Hold a plumb line (stone on a string) next to slanting objects so children see the gap, and always offer 'neither' as a category.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL.M_HV_TILTED_SHAPE","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_HORIZONTAL_VERTICAL","error":"Thinks the sides of a square or rectangle are always horizontal and vertical, even when the shape is drawn tilted.","example":{"question":"A square is drawn turned so it stands on one corner (like a diamond). How many of its sides are horizontal?","wrong_answer":"2","correct_answer":"0, all four sides are slanting"},"cause":"Shapes in textbooks are almost always drawn upright, so 'square' and 'horizontal and vertical sides' have been learnt together.","reveals":"Show a rotated square and ask for the count of horizontal or vertical sides; answering 2 reveals the error.","help":"Turn a cut-out square on the desk and ask children to say whether each side is horizontal, vertical or slanting as it turns.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_HORIZONTAL_VERTICAL.M_DRAW_HV_DRIFT","skill":"MATH.G5.GEOMET.LINES.DRAW_HORIZONTAL_VERTICAL","error":"Draws a 'vertical' or 'horizontal' line by eye that slopes noticeably, often with the book turned at an angle.","example":{"question":"Draw a vertical line 6 cm long on plain paper.","wrong_answer":"A 6 cm line that leans to the right, about 1 cm further across at the top than at the bottom","correct_answer":"A 6 cm line parallel to the side edge of the page, running straight up and down"},"cause":"The child does not use the page edge, grid or set square as a reference and trusts the hand alone.","reveals":"A drawing task checked by measuring the distance from the page edge at both ends of the line. Unequal distances expose the drift.","help":"Teach children to line the set square or ruler up with the page edge or a grid line before drawing, and to check by measuring from the edge at both ends.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_HORIZONTAL_VERTICAL.M_RULER_FROM_ONE","skill":"MATH.G5.GEOMET.LINES.DRAW_HORIZONTAL_VERTICAL","error":"Starts measuring from the 1 cm mark or the end of the ruler, not from 0, so the line is the wrong length.","example":{"question":"Draw a horizontal line 8 cm long.","wrong_answer":"A line drawn from the 1 mark to the 8 mark, which is only 7 cm long","correct_answer":"A line drawn from the 0 mark to the 8 mark, 8 cm long"},"cause":"The child counts the numbers on the ruler like counting objects, starting at 1.","reveals":"A length-specified drawing measured by the teacher. A line that is consistently 1 cm short points to this error.","help":"Have children put a finger on the 0 mark before every drawing and count the centimetre spaces, not the numbers.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR.M_PERP_MUST_BE_UPRIGHT","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR","error":"Only accepts perpendicular lines when one is horizontal and the other vertical, and rejects tilted pairs that meet at a right angle.","example":{"question":"Two straight paths cross like a letter X, and a set square fits exactly into each corner. Are the paths perpendicular?","wrong_answer":"No, because neither path is straight up or across","correct_answer":"Yes, they meet at right angles"},"cause":"Every early example was a + or an L drawn upright, so 'perpendicular' has become 'horizontal meets vertical'.","reveals":"Include a tilted right-angle pair among the options. A child who skips it while choosing the upright pair shows the error.","help":"Draw an upright + on paper, then turn the paper and ask whether the lines are still perpendicular, testing the corner with a set square each time.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR.M_PERP_ANY_CROSSING","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR","error":"Thinks any two lines that cross or meet are perpendicular.","example":{"question":"Are the two lines in the letter V perpendicular?","wrong_answer":"Yes, because they meet","correct_answer":"No, they meet at an angle smaller than a right angle"},"cause":"The child has linked the word to 'meeting' or 'crossing' and not to the right angle.","reveals":"Distractors that cross at clearly acute or obtuse angles, such as the letters X (narrow), V and K.","help":"Make children test every meeting point with a folded-paper right angle before saying 'perpendicular'.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR.M_PERP_MUST_CROSS","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR","error":"Thinks perpendicular lines must cross through each other, so rejects an L or T shape.","example":{"question":"Are two edges meeting at the corner of an exercise book perpendicular?","wrong_answer":"No, they only touch at the end, they do not cross","correct_answer":"Yes, they meet at a right angle"},"cause":"The first picture learnt was a + sign, so crossing has become part of the definition.","reveals":"Offer an L shape and a + shape and ask which are perpendicular. A child who chooses only the + reveals it.","help":"Show + , T and L shapes side by side and stress that what matters is the right angle where they meet, not whether they cross.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR.M_PERP_BY_EYE","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PERPENDICULAR","error":"Judges by eye and accepts angles that are near but not equal to a right angle.","example":{"question":"Two lines meet at an angle slightly less than a right angle (a set square corner does not fit; there is a gap). Are they perpendicular?","wrong_answer":"Yes","correct_answer":"No, the angle is not a right angle"},"cause":"The child thinks 'looks square' is good enough and does not know a check can be made.","reveals":"A near-right-angle distractor (about 80°) beside a true right angle, asking the child to check with a set square.","help":"Require a set-square or paper-corner check for every answer until the habit is fixed.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR.M_DRAWPERP_ALWAYS_VERTICAL","skill":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR","error":"Draws a vertical line through the point even when the given line is slanting.","example":{"question":"Line AB slopes upwards from left to right. Draw a line through point P on AB that is perpendicular to AB.","wrong_answer":"A line straight up and down the page through P","correct_answer":"A line through P that makes a right angle with AB, so it slopes upwards from right to left"},"cause":"The child thinks 'perpendicular' means 'vertical' (see M_PERP_MUST_BE_UPRIGHT).","reveals":"Give the drawing task with a slanting line, then check the corner with a set square. A vertical answer fails the check.","help":"Teach the method of placing one edge of the set square along the given line, whatever its direction, and drawing along the other edge.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR.M_SETSQUARE_WRONG_EDGE","skill":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR","error":"Places the long sloping edge of the set square on the line, so the drawn line makes a 45° or 60° angle, not a right angle.","example":{"question":"Using a set square, draw a line perpendicular to the horizontal line XY at point M.","wrong_answer":"A line through M slanting at about 45° to XY","correct_answer":"A line through M at a right angle to XY, drawn along the edge next to the square corner"},"cause":"The child does not know which corner of the set square is the right angle.","reveals":"Ask the child to point to the right-angle corner of the set square, or check the drawn angle with a paper corner.","help":"Mark the right-angle corner of each set square with a small square symbol and have children find it before every drawing.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR.M_DRAWPERP_MISSES_POINT","skill":"MATH.G5.GEOMET.LINES.DRAW_PERPENDICULAR","error":"Draws a line at a right angle to the given line but not through the marked point.","example":{"question":"Draw a line perpendicular to line CD through point Q, which is 3 cm from C on CD.","wrong_answer":"A perpendicular line meeting CD 1 cm away from Q","correct_answer":"A perpendicular line passing exactly through Q"},"cause":"The child concentrates on the right angle and forgets that the point fixes the position.","reveals":"Measure from C to where the drawn line meets CD. A distance other than 3 cm shows the point was ignored.","help":"Have children slide the set square along the line until its corner touches the point before drawing.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL.M_PAR_SAME_LENGTH","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL","error":"Thinks parallel lines must be the same length and lined up exactly opposite each other.","example":{"question":"One horizontal line is 3 cm long. Another horizontal line 2 cm below it is 7 cm long and starts further to the right. Are they parallel?","wrong_answer":"No, because they are not the same length","correct_answer":"Yes, they stay the same distance apart and would never meet"},"cause":"Early examples such as railway lines and opposite sides of a rectangle always show equal, matched lines.","reveals":"A distractor pair that is parallel but of very different lengths and offset. A child who rejects it shows the error.","help":"Ask children to imagine extending both lines with a ruler to show they still never meet, and remind them lines go on in both directions.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL.M_PAR_NOT_MEETING_YET","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL","error":"Calls two lines parallel just because they do not touch on the page, even when they are getting closer together.","example":{"question":"Two lines are 4 cm apart at the left end and 2 cm apart at the right end. Are they parallel?","wrong_answer":"Yes, they do not meet","correct_answer":"No, the gap is getting smaller, so they would meet if extended"},"cause":"The child uses 'do not meet on the page' in place of 'same distance apart all along'.","reveals":"A pair of short, gently converging lines that do not touch. Choosing it as parallel exposes the error.","help":"Have children measure the gap at both ends and extend the lines with a ruler to see whether they meet.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL.M_PAR_ONLY_HORIZONTAL","skill":"MATH.G5.GEOMET.LINES.IDENTIFY_PARALLEL","error":"Recognises only pairs of horizontal lines as parallel and rejects vertical or slanting pairs.","example":{"question":"Are the two slanting edges of a ruler laid diagonally across a desk parallel?","wrong_answer":"No, they are not lying flat across the page","correct_answer":"Yes, the two long edges of a ruler are always the same distance apart"},"cause":"Over-reliance on the railway-line and ruled-exercise-book images, which are horizontal.","reveals":"Include vertical and slanting parallel pairs among the options and see whether they are skipped.","help":"Turn a ruler or a ladder picture to different positions and ask each time whether the edges or rails are still parallel.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL.M_DRAWPAR_ONE_MEASURE","skill":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL","error":"Measures the required distance at only one point, then draws the new line by eye, so the lines are not parallel.","example":{"question":"Draw a line parallel to line AB and 3 cm away from it.","wrong_answer":"A line 3 cm from AB at one end but 4 cm away at the other end","correct_answer":"A line exactly 3 cm from AB at every point, found by marking 3 cm at two places or sliding a set square along a ruler"},"cause":"The child thinks one measurement fixes the line and does not realise that two points are needed.","reveals":"Measure the gap at both ends of the child's drawing. Unequal gaps reveal the error.","help":"Teach children to mark the distance at two places far apart, join the marks, and then check the gap at a third place.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL.M_DRAWPAR_SLANT_MEASURE","skill":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL","error":"Measures the distance between the lines along a slant instead of at right angles, so the gap is smaller than asked.","example":{"question":"Draw a line parallel to the horizontal line PQ and 4 cm from it.","wrong_answer":"The ruler is held slanting and 4 cm is marked along it, giving lines only about 3 cm apart","correct_answer":"Distance measured straight up from PQ at a right angle, so the lines are 4 cm apart"},"cause":"The child has not understood that the distance between lines is the shortest, perpendicular distance.","reveals":"Check the drawn gap with a set square held perpendicular. A gap smaller than asked points to slant measuring.","help":"Have children first draw a short perpendicular with the set square and measure along that.","status":"draft"},{"code":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL.M_DRAWPAR_IGNORES_DIRECTION","skill":"MATH.G5.GEOMET.LINES.DRAW_PARALLEL","error":"Draws a horizontal line under a slanting given line instead of a line that follows the same slant.","example":{"question":"Line MN slopes downwards from left to right. Draw a line parallel to MN.","wrong_answer":"A horizontal line below MN","correct_answer":"A line below or above MN with exactly the same downward slope"},"cause":"The child links 'parallel' with 'one line under another', as in the ruled lines of an exercise book.","reveals":"A drawing task with a slanting line. Measure the gap at both ends; a horizontal answer gives unequal gaps.","help":"Use the sliding set-square method so the new line copies the direction of the given line exactly.","status":"draft"}]},{"code":"MATH.G5.GEOMET.ANGLES","number":"3.2","strand":"Geometry","sub_strand":"Angles","sequence":302,"lessons":6,"content_topics":["Turns as angles","Measuring angles using a protractor"],"learning_experiences":["make clockwise, quarter and half turn, and relate them to angles in the environment","discuss the use of angles in the environment","team up with peers to make a unit angle and use it to measure angles in the environment","o divide a 10 angle into 10 equal parts and identify each part as equal to 1 degree","measure angles in degrees using a protractor","work with peers to measure angles in degrees using a protractor and share results with others","use digital devices and other resources to draw plane figures and learn about angles"],"key_inquiry_questions":["Where are angles used in the environment?"],"core_competences":"● Communication and collaboration: learner teams up with peers to make a unit angle and use it to measure angles in the environment. ● Learning to learn: learner measures angles in degrees using a protractor and shares results with others.","values":"Responsibility: learner teams up with peers to make a unit angle and uses it to measure angles in the environment.","pcis":"Social cohesion: learner works with peers to measure angles in degrees using a protractor and shares results with others.","links":"The learner is able to relate line to sketching and drawing in Creative Arts.","design_notes":"Outcome f ('appreciate the use of angles in our day-to-day life') is attitudinal and is not mapped to a skill. 1) Outcomes c and d overlap heavily. I have split them, as a proposal, into the protractor procedure (c) and the degree unit plus measuring and recording in context (c, d). 2) The design gives no size limit. Proposed: angles from 0° to 180° only, because angles on a straight line and at a point appear in Grade 6 (3.2a–c), and reflex angles and 270° are used only as turn sizes, not measured. Also proposed: a measuring tolerance of about ±2°. 3) The learning experience 'o divide a 10 angle into 10 equal parts and identify each part as equal to 1 degree' appears garbled in the source. It probably means dividing a 10° angle (or a unit angle) into 10 equal parts; check it against the printed design. 4) Outcome b 'read angles from protractor in both directions' is interpreted as using the inner and outer scales for angles opening clockwise and anticlockwise. 5) Drawing or constructing angles of a given size is not in these outcomes, despite the learning experience on drawing plane figures digitally, so no drawing skill is included. 6) The terms acute, obtuse and reflex do not appear in these outcomes. HOREB's G5_ANGLES_INTRO ('Types of Angles') may go beyond the design; I have used 'less than, equal to or greater than a right angle' instead. 7) Placement mismatch: HOREB places protractor measurement at Grade 6 (G6_ANGLE_MEASURE), but the KICD Grade 5 design already requires it. Consider a Grade 5 node or re-tagging. 8) The key inquiry question text contains a stray 'Inquiry Question(s)' fragment from extraction. 9) Six suggested lessons is tight for both turns and protractor work; the assessment engine should weight protractor reading (b, c) most heavily.","outcomes":[{"code":"MATH.G5.GEOMET.ANGLES.a","letter":"a","text":"relate a turn to angles in real life","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.ANGLES.b","letter":"b","text":"read angles from protractor in both directions","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.ANGLES.c","letter":"c","text":"use protractor to measure angles in different situations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.ANGLES.d","letter":"d","text":"measure angles in degrees in different situations","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.ANGLES.e","letter":"e","text":"identify the use of angles in the environment","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.ANGLES.f","letter":"f","text":"appreciate the use of angles in our day-to-day life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","name":"Relating quarter, half, three-quarter and full turns to angles","outcomes":["MATH.G5.GEOMET.ANGLES.a"],"mastery":"The child states the angle made by a quarter turn (90°, a right angle), half turn (180°), three-quarter turn (270°) and full turn (360°), in either direction. They can work out the turn between a start and an end position on a clock face, a compass or their own body. Proposed limit: whole quarter turns only; no other turn fractions.","question_forms":["practical: make a turn and name the angle","clock hands: how much has the minute hand turned","compass: facing X, turn a quarter clockwise, which way now and what angle","turn to degrees and degrees to turn conversion","compare and explain: same end position, different turn"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G4_POSITION","G4_ANGLES"],"prerequisites":[{"requires":"MATH.G4.GEOMET.POSITION_AND_DIRECTION.c","kind":"outcome","strength":"essential","reason":"The child must already recognise quarter, half and full turns before attaching angle sizes to them.","status":"proposed"},{"requires":"MATH.G4.GEOMET.POSITION_AND_DIRECTION.a","kind":"outcome","strength":"essential","reason":"Turns are described clockwise or anticlockwise, so the child needs secure direction language.","status":"proposed"},{"requires":"MATH.G4.GEOMET.ANGLES.c","kind":"outcome","strength":"essential","reason":"Grade 4 begins linking turns to angles; Grade 5 extends this to degree values.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.ANGLES.DEGREE_AS_UNIT","name":"Understanding the degree as the unit for measuring the size of an angle","outcomes":["MATH.G5.GEOMET.ANGLES.d"],"mastery":"The child explains that angle size is the amount of turn between two arms, not the length of the arms. They compare angles using a non-standard unit angle (for example a paper wedge) and know that a degree is a very small, fixed unit: 90 in a right angle and 360 in a full turn.","question_forms":["practical: measure an angle with a paper unit angle","compare two angles with different arm lengths","how many degrees in a right angle, half turn or full turn","true or false and explain"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G4_ANGLES"],"prerequisites":[{"requires":"MATH.G4.GEOMET.ANGLES.a","kind":"outcome","strength":"essential","reason":"The child must identify an angle as two arms meeting at a point before measuring its size.","status":"proposed"},{"requires":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","kind":"skill","strength":"essential","reason":"The degree is defined from the full turn (360°) and the quarter turn (90°).","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES","name":"Reading a protractor's inner and outer scales in both directions","outcomes":["MATH.G5.GEOMET.ANGLES.b"],"mastery":"Given a protractor already placed on an angle of 0° to 180°, the child chooses the scale that starts at 0 on the baseline arm. They read to the nearest degree whether the angle opens clockwise or anticlockwise, and they check the reading against a right angle.","question_forms":["read the angle from a picture of a placed protractor","which scale should you use and why","read between labelled marks (nearest degree)","spot the error in a classmate's reading"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G6_ANGLE_MEASURE"],"prerequisites":[{"requires":"MATH.G5.GEOMET.ANGLES.DEGREE_AS_UNIT","kind":"skill","strength":"essential","reason":"Reading the scale only makes sense once the child knows what one degree is.","status":"proposed"},{"requires":"MATH.G4.GEOMET.POSITION_AND_DIRECTION.a","kind":"outcome","strength":"helpful","reason":"Choosing the scale depends on whether the angle opens clockwise or anticlockwise.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR","name":"Positioning a protractor and measuring a given angle","outcomes":["MATH.G5.GEOMET.ANGLES.c"],"mastery":"The child places the centre point on the vertex and the baseline (0° line) along one arm, then reads the angle to within about 2° (proposed tolerance). This applies to angles of 0° to 180° in any orientation, including angles whose arms must first be extended with a ruler.","question_forms":["practical: measure a drawn angle","measure angles in different orientations (neither arm horizontal)","measure an angle with short arms","spot the error in protractor placement"],"thinking":["procedure"],"horeb_skill_ids":["G6_ANGLE_MEASURE"],"prerequisites":[{"requires":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES","kind":"skill","strength":"essential","reason":"Positioning is pointless if the child cannot then read the correct scale.","status":"proposed"},{"requires":"MATH.G4.GEOMET.ANGLES.a","kind":"outcome","strength":"essential","reason":"The child must locate the vertex and arms in order to place the protractor.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT","name":"Measuring and recording angles in degrees in shapes, diagrams and objects","outcomes":["MATH.G5.GEOMET.ANGLES.c","MATH.G5.GEOMET.ANGLES.d"],"mastery":"The child measures angles of 0° to 180° in plane figures (triangles, rectangles, other polygons) and in drawings or models of real objects, such as a roof truss, a ladder against a wall or opened scissors. They estimate first using a right angle as a benchmark and record the answer with the ° symbol.","question_forms":["measure the angles of a drawn shape","estimate then measure","measure an angle in a picture of a real object","reasonableness check: is this measurement sensible","group task: measure and compare results"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G6_ANGLE_MEASURE","G4_PLANE_FIGURES"],"prerequisites":[{"requires":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR","kind":"skill","strength":"essential","reason":"Measuring in shapes and objects applies the basic protractor procedure.","status":"proposed"},{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.e","kind":"outcome","strength":"helpful","reason":"Knowing the corners of plane figures helps the child find each angle to measure.","status":"proposed"},{"requires":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","kind":"skill","strength":"helpful","reason":"The right angle (quarter turn) is the benchmark for estimating and checking.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT","name":"Identifying angles and their uses in the environment","outcomes":["MATH.G5.GEOMET.ANGLES.e","MATH.G5.GEOMET.ANGLES.a"],"mastery":"The child finds angles in fixed objects (roof, window frame, road junction, signboard) and in turning objects (door, clock hands, scissors, a matatu turning at a junction). They describe each angle as less than, equal to or greater than a right angle in any orientation, and say why the angle matters for its use.","question_forms":["name objects in the classroom or home that show angles","picture: point to the angle","right angle, smaller or bigger (tilted pictures)","explain why this angle is used (e.g. roof slope, ladder)"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G4_ANGLES","G5_ANGLES_INTRO"],"prerequisites":[{"requires":"MATH.G4.GEOMET.ANGLES.b","kind":"outcome","strength":"essential","reason":"Grade 4 identification of angles in objects is the base for describing their size and use.","status":"proposed"},{"requires":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","kind":"skill","strength":"helpful","reason":"Turning objects such as doors and clock hands are understood through turns.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES.M_FULL_TURN_100","skill":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","error":"Assumes a full turn is 100 degrees, so a quarter turn is 25° and a half turn is 50°.","example":{"question":"How many degrees does a half turn make?","wrong_answer":"50°","correct_answer":"180°"},"cause":"Carries over the idea from money, metres and percentages that 'whole' units come in hundreds.","reveals":"Include 25°, 50° and 100° as distractors for quarter, half and full turn items.","help":"Have children stand and make four quarter turns, saying 90, 180, 270, 360 aloud, and link this to the right-angle corner of a book.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES.M_TURN_FROM_TOP","skill":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","error":"Judges the turn by where the hand ends up on the clock face rather than how far it moved from its start.","example":{"question":"The minute hand moves from 3 to 6. What fraction of a turn is that, and what angle?","wrong_answer":"A half turn, 180°","correct_answer":"A quarter turn, 90°"},"cause":"Thinks every turn is measured from 12 (or from north), because 6 is 'halfway round' the clock.","reveals":"Use turns that do not start at 12 or north; the wrong answer gives the position of the end point, not the size of the turn.","help":"Ask the child to trace the path of the hand from its starting number with a finger and count the quarter sections passed.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES.M_SAME_END_SAME_ANGLE","skill":"MATH.G5.GEOMET.ANGLES.TURNS_AS_ANGLES","error":"Believes a quarter turn anticlockwise and a three-quarter turn clockwise are the same angle because the child ends facing the same way.","example":{"question":"Otieno faces north and makes a three-quarter turn clockwise. Akinyi faces north and makes a quarter turn anticlockwise. Did they turn through the same angle?","wrong_answer":"Yes, both turned 90°.","correct_answer":"No. Both end facing west, but Otieno turned 270° and Akinyi turned 90°."},"cause":"Confuses final direction (position) with amount of turning (angle).","reveals":"A compare-and-explain item where the end positions match but the turns differ.","help":"Let pairs act out both turns while a third child counts the quarter turns each one makes.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.DEGREE_AS_UNIT.M_LONGER_ARMS_BIGGER","skill":"MATH.G5.GEOMET.ANGLES.DEGREE_AS_UNIT","error":"Thinks an angle with longer arms is a bigger angle.","example":{"question":"Angle P is 40° with arms 8 cm long. Angle Q is 40° with arms 2 cm long. Which angle is bigger?","wrong_answer":"Angle P","correct_answer":"They are equal; both are 40°."},"cause":"Treats angle size as a length, like the other measures the child knows (ruler, tape).","reveals":"Present equal angles with very different arm lengths, and a smaller angle drawn with longer arms.","help":"Cover equal angles with the same paper unit wedge to show the arms can be extended without changing the opening.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.DEGREE_AS_UNIT.M_GAP_BETWEEN_ENDS","skill":"MATH.G5.GEOMET.ANGLES.DEGREE_AS_UNIT","error":"Judges angle size by the distance between the tips of the arms.","example":{"question":"Angle A is 60° with arms 5 cm long; angle B is 80° with arms 1 cm long. Which is bigger?","wrong_answer":"Angle A, because its arm ends are further apart","correct_answer":"Angle B (80° is greater than 60°)"},"cause":"Looks at the 'space' between the ends of the lines instead of the turn at the vertex.","reveals":"A pair where the smaller angle has the wider gap between arm ends.","help":"Model angles with a pair of strips joined at one end (or opened scissors) and ask how far one arm has turned, not how far apart the tips are.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES.M_WRONG_SCALE","skill":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES","error":"Reads the scale that does not start at 0 on the baseline arm, giving 180° minus the true angle.","example":{"question":"One arm lies along the baseline through the 0 on the right. The other arm passes the marks labelled 60 and 120. What is the angle?","wrong_answer":"120°","correct_answer":"60°"},"cause":"Reads whichever number is outermost or most visible, without tracing from 0.","reveals":"Make 180° minus the true angle a distractor in every reading item, using acute angles that are clearly smaller than a right angle.","help":"Have the child put a finger on the 0 where the arm lies, follow that same scale round to the other arm, and then ask 'is it bigger or smaller than a right angle?'","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES.M_COUNT_MARKS_BACKWARDS","skill":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES","error":"Counts the small degree marks in the wrong direction from a labelled number.","example":{"question":"Using the scale that starts at 0 on the baseline arm, the other arm is 3 small marks past 40, on the way to 50. What is the angle?","wrong_answer":"37°","correct_answer":"43°"},"cause":"On a two-direction scale the child counts down from 40, following the other scale's numbers or reading right to left by habit.","reveals":"Use readings that fall between labelled tens and include the 'counted back' value as a distractor.","help":"Ask the child to name the labelled numbers on either side of the arm first (40 and 50), so the answer must lie between them.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES.M_SMALL_MARK_AS_TEN","skill":"MATH.G5.GEOMET.ANGLES.READ_PROTRACTOR_BOTH_SCALES","error":"Treats each small mark as more than 1°, for example as 10° or as 5°.","example":{"question":"On the correct scale the arm is 2 small marks past 70, on the way to 80. What is the angle?","wrong_answer":"90°","correct_answer":"72°"},"cause":"Does not know that the space between two labelled numbers is split into 10 one-degree parts.","reveals":"Include readings just past a labelled ten, with a distractor that counts each mark as 10.","help":"Get the child to count the small spaces between 0 and 10 on a protractor and conclude that each one is 1°.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR.M_EDGE_NOT_BASELINE","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR","error":"Lines the bottom edge of the protractor up with the arm instead of the 0° baseline, which on many protractors sits above the edge.","example":{"question":"Measure angle ABC, which is 70°.","wrong_answer":"A reading a few degrees out, e.g. 66°","correct_answer":"70°"},"cause":"Treats the protractor like a ruler and uses its straight edge.","reveals":"A spot-the-error picture with the edge, not the baseline, on the arm; or practical results that are consistently a few degrees out.","help":"Have children trace the baseline on their own protractor with a finger before every measurement and check that the arm runs exactly along it.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR.M_CENTRE_OFF_VERTEX","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR","error":"Places the protractor's centre point somewhere along an arm rather than exactly on the vertex.","example":{"question":"Measure angle PQR, which is 50°.","wrong_answer":"An inaccurate reading, e.g. 45° or 56°","correct_answer":"50°"},"cause":"Does not understand that the angle is the turn about the vertex, so the centre of the protractor must sit at that point.","reveals":"A spot-the-error image with the centre slid along one arm.","help":"Mark the vertex with a dot and insist the small centre mark or hole covers the dot before anything else is done.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR.M_READ_SECOND_ARM_ONLY","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR","error":"When neither arm is horizontal, keeps the protractor straight and reads only where the upper arm crosses the scale.","example":{"question":"With the protractor held level, one arm crosses the scale at 20 and the other at 80 (same scale). What is the angle?","wrong_answer":"80°","correct_answer":"60°"},"cause":"Has learnt the procedure only for angles drawn with one arm horizontal, and does not see the angle as a gap between two readings.","reveals":"Tilted angles where the protractor cannot be put on 0 without turning it or the page.","help":"Show that the protractor (or page) may be rotated to put one arm on 0, and as a check, subtract the two readings.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR.M_SHORT_ARMS_GUESS","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_WITH_PROTRACTOR","error":"When the arms are too short to reach the scale, guesses the reading instead of extending the arms.","example":{"question":"Measure the 35° angle drawn with arms only 1 cm long.","wrong_answer":"About 50° (a guess)","correct_answer":"35°, after extending the arms with a ruler"},"cause":"Believes extending the arms would change the angle (linked to M_LONGER_ARMS_BIGGER).","reveals":"Include short-armed angles in measuring tasks; a wide spread of answers shows guessing.","help":"Demonstrate extending the arms lightly in pencil, measuring before and after to show the angle stays the same.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT.M_NO_DEGREE_UNIT","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT","error":"Records an angle as a bare number or in centimetres.","example":{"question":"Measure the angle between the ladder and the ground in the drawing.","wrong_answer":"65 cm","correct_answer":"65°"},"cause":"Associates measuring with a ruler and length units.","reveals":"Open-response items that require the child to write the unit themselves.","help":"Have the child say 'degrees' aloud with every reading and write the ° symbol as part of the answer.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT.M_BIGGER_SHAPE_BIGGER_ANGLES","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT","error":"Thinks that drawing a shape larger, or showing a bigger picture of a roof, makes its angles bigger.","example":{"question":"A small drawing of a roof has a top angle of 100°. A larger drawing of the same roof is twice as big. What is its top angle?","wrong_answer":"200°","correct_answer":"100°"},"cause":"Applies the idea of scaling lengths to angles.","reveals":"Ask for angles in an enlarged copy of a shape; doubled values expose the error.","help":"Let children measure the same corner on a small and a large copy of a triangle and compare their results.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT.M_NO_REASONABLENESS_CHECK","skill":"MATH.G5.GEOMET.ANGLES.MEASURE_ANGLES_IN_CONTEXT","error":"Accepts a measurement that contradicts what the angle obviously looks like, for example recording an obtuse value for a sharp corner.","example":{"question":"Measure the sharp corner of a triangular scarf drawing (true size 30°).","wrong_answer":"150°","correct_answer":"30°"},"cause":"Treats measuring as reading a number off a tool, with no prior estimate.","reveals":"Estimate-then-measure items; ask 'Is it more or less than a right angle?' before measuring.","help":"Make 'estimate first, using the corner of a book as a right angle' a fixed step in every measuring task.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT.M_RIGHT_ANGLE_ONLY_UPRIGHT","skill":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT","error":"Recognises a right angle only when its arms are horizontal and vertical.","example":{"question":"A square signboard at a Nairobi bus stop hangs tilted. Is the angle at its corner a right angle?","wrong_answer":"No, it is slanting.","correct_answer":"Yes, it is still a right angle (90°)."},"cause":"Has mostly seen right angles drawn in the standard 'L' position.","reveals":"Pictures of right angles in rotated positions mixed with angles that are nearly, but not exactly, right angles.","help":"Have children test tilted corners with a folded paper right angle rather than judging by eye.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT.M_ANGLE_IS_THE_CORNER_POINT","skill":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT","error":"Thinks the angle is the corner point itself rather than the amount of opening between two arms.","example":{"question":"Show the angle made by an opened pair of scissors.","wrong_answer":"Points only to the screw where the blades join.","correct_answer":"Shows the opening between the two blades, which meet at the screw (the vertex)."},"cause":"Confuses 'angle' with the everyday word 'corner' and with the vertex.","reveals":"Ask the child to mark an angle with an arc on a picture; marking a dot at the vertex reveals the error.","help":"Always mark angles with an arc between the arms and use the word 'vertex' for the meeting point.","status":"draft"},{"code":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT.M_NO_ANGLE_IN_MOVEMENT","skill":"MATH.G5.GEOMET.ANGLES.ANGLES_IN_ENVIRONMENT","error":"Does not see that a turning object, such as a door or a clock hand, makes an angle, because no lines are drawn.","example":{"question":"A classroom door opens a quarter turn. What angle does it make with the closed position?","wrong_answer":"There is no angle.","correct_answer":"90°, a right angle"},"cause":"Associates angles only with drawn shapes and fixed corners, not with turning.","reveals":"Environment items about doors, gates, clock hands or a goat tethered and turning, rather than drawn figures.","help":"Open the classroom door slowly and ask children to say when it has made a right angle, then show the two 'arms' (frame and door).","status":"draft"}]},{"code":"MATH.G5.GEOMET.3_D_OBJECTS","number":"3.3","strand":"Geometry","sub_strand":"Three-Dimension (3-D) Objects","sequence":303,"lessons":6,"content_topics":["2-D shapes in 3- D objects"],"learning_experiences":["share tasks with peers to identify, collect objects and discuss cubes, cuboids, cylinders, spheres and pyramids as 3-D objects in the environment","watch a video on 3-D objects","describe 2-D shapes found in 3-D objects and share with other groups","use digital devices and other resources to draw and learn more about 3-D objects"],"key_inquiry_questions":["Where are 3-D objects used in the environment?"],"core_competences":"Critical thinking and imagination: learner identifies 2-D shapes in 3-D objects in the environment.","values":"Responsibility: learner shares tasks with peers while identifying and collecting 3-D objects in the environment.","pcis":"Environmental awareness: learner identifies and collects 3-D objects in the environment.","links":"The learner is able to relate the concept of 3-D objects and 2-D shapes to modelling in Creative Arts.","design_notes":"1. Outcome c ('appreciate the use of 3-D objects in the environment') is attitudinal and is not mapped to a skill. It can be observed through the key inquiry question 'Where are 3-D objects used in the environment?' and discussion of why objects have their shapes. Proposed: the 'explain why an object is shaped as it is' question form under G5_DESCRIBE_3D_FEATURES supports this informally.\n\n2. The outcomes do not list which 3-D objects are covered. The list used here (cubes, cuboids, cylinders, spheres, pyramids) comes from the learning experiences, not the outcome text. Cones are not mentioned, so they appear only as a distractor in M_POINTED_MEANS_PYRAMID. The restriction to square-based and triangular-based pyramids is proposed.\n\n3. 'Describe' is not defined in the outcomes. Grade 6 (3.3a, 3.3b) explicitly introduces identifying vertices, faces and edges. The proposed position is that Grade 5 description stays informal: flat or curved surfaces, corners, rolling and stacking, and naming the shapes of faces. Formal counting of edges and vertices belongs to Grade 6. The 'how many squares does he trace' and 'how many corners' items are borderline and should be treated as informal.\n\n4. Grade 6 outcome 3.3c ('describe plane figures in 3-D objects in the environment') is almost identical to Grade 5 outcome b. The design does not say how depth should differ. A proposed reading is that Grade 5 covers recognising and naming face shapes, and Grade 6 adds systematic counting and properties.\n\n5. Terminology is unclear in the design. Whether the curved surface of a cylinder counts as a 'face' is not stated, and textbooks differ. This map uses 'face' for flat surfaces and 'curved surface' otherwise; confirm with the class textbook in use.\n\n6. The design does not state whether a cube should be treated as a special cuboid. This map keeps them as separate names at Grade 5, which is common classroom practice, but a teacher should not mark wrong a child who says a cube is a kind of cuboid.\n\n7. The learning experience 'use digital devices and other resources to draw ... 3-D objects' implies drawing. No outcome requires it, so drawing is not assessed as a separate skill here.\n\n8. HOREB's existing G5_3D_OBJECTS label mentions only cubes, cuboids and cylinders. It may need widening to include spheres and pyramids to match the learning experiences.","outcomes":[{"code":"MATH.G5.GEOMET.3_D_OBJECTS.a","letter":"a","text":"describe 3-D objects in the environment","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.b","letter":"b","text":"describe 2-D shapes in 3-D objects in the environment","status":"kicd_verified"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.c","letter":"c","text":"appreciate the use of 3-D objects in the environment","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","name":"Recognise and name cubes, cuboids, cylinders, spheres and pyramids in the environment","outcomes":["MATH.G5.GEOMET.3_D_OBJECTS.a"],"mastery":"Given real objects, models or pictures from daily life (e.g. a dice, a matchbox, a tin of Kimbo, a football, a model pyramid), the child names each as a cube, cuboid, cylinder, sphere or pyramid. The child does this whatever the object's size, colour, material or orientation. Proposed limit: only these five objects, with pyramids limited to square-based and triangular-based ones.","question_forms":["name the object (real item or picture)","sort a collection into groups","odd one out and explain","give an example from home or school","match object to name"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_3D_OBJECTS"],"prerequisites":[{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.a","kind":"outcome","strength":"helpful","reason":"Looking for shapes in environment objects in Grade 4 builds the habit of seeing geometry in everyday items.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES","name":"Describe 3-D objects by their surfaces, corners and behaviour","outcomes":["MATH.G5.GEOMET.3_D_OBJECTS.a"],"mastery":"The child describes an object in everyday mathematical language. For example, they say whether its surfaces are flat, curved or both, and whether it has corners and straight edges. They also say whether it can roll, slide or stack, and link this to its use (e.g. tins roll, bricks stack). Proposed limit: informal description only. Formal counting of vertices, faces and edges is left to Grade 6 (G6:3.3a, 3.3b).","question_forms":["describe the object","which objects can roll / stack / slide","guess the object from a description","explain why an object is shaped as it is (e.g. why bricks are cuboids)","compare two objects: same and different"],"thinking":["recall","reasoning","problem solving"],"horeb_skill_ids":["G5_3D_OBJECTS"],"prerequisites":[{"requires":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","kind":"skill","strength":"essential","reason":"A child must know which object is which before describing and comparing their features.","status":"proposed"},{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.e","kind":"outcome","strength":"helpful","reason":"Talking about properties of plane figures (sides, corners) gives the vocabulary used to describe solids.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_VS_3D","name":"Distinguish 2-D shapes from 3-D objects","outcomes":["MATH.G5.GEOMET.3_D_OBJECTS.a","MATH.G5.GEOMET.3_D_OBJECTS.b"],"mastery":"The child uses the correct name for a flat shape and for a solid object. They say 'circle' for a flat shape but 'sphere' for a ball, and 'square' for a flat shape but 'cube' for a dice. They can explain that a 3-D object takes up space and can be held, while a 2-D shape is flat.","question_forms":["2-D or 3-D? sort the list","correct the wrong name","match flat shape to the solid it comes from","explain the difference"],"thinking":["recall","reasoning"],"horeb_skill_ids":["G5_3D_OBJECTS","G4_PLANE_FIGURES"],"prerequisites":[{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.a","kind":"outcome","strength":"essential","reason":"The child must already name squares, rectangles, triangles and circles to tell them apart from solids.","status":"proposed"},{"requires":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","kind":"skill","strength":"essential","reason":"Distinguishing 'circle' from 'sphere' needs both sets of names.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D","name":"Identify and describe the 2-D shapes that form the flat faces of 3-D objects","outcomes":["MATH.G5.GEOMET.3_D_OBJECTS.b"],"mastery":"For the five objects, the child names the flat shapes found on them:\n- a cube has only squares\n- a cuboid has rectangles (sometimes with two squares)\n- a cylinder has two circles plus a curved surface\n- a pyramid has triangles plus a square or triangular base\n- a sphere has no flat face\nThe child can identify the shape left when a face is traced or printed, including faces that cannot be seen in a picture. Proposed: they may say informally how many of each shape there are, but formal face counting is Grade 6.","question_forms":["what shape is this face?","trace or print a face and name it","which object made this print?","list all the flat shapes on an object","true or false with explanation"],"thinking":["recall","reasoning","problem solving"],"horeb_skill_ids":["G5_3D_OBJECTS","G4_PLANE_FIGURES","G6_3D_OBJECTS"],"prerequisites":[{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.a","kind":"outcome","strength":"essential","reason":"Naming a face depends on recognising the plane figure it forms.","status":"proposed"},{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.e","kind":"outcome","strength":"helpful","reason":"Knowing the properties of squares and rectangles helps the child decide which one a face is.","status":"proposed"},{"requires":"MATH.G4.GEOMET.PLANE_FIGURES.b","kind":"outcome","strength":"helpful","reason":"Drawing shapes from objects in Grade 4 prepares children to trace and draw faces of solids.","status":"proposed"},{"requires":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","kind":"skill","strength":"essential","reason":"Describing the faces of an object assumes the object itself is recognised.","status":"proposed"},{"requires":"MATH.G5.GEOMET.3_D_OBJECTS.2D_VS_3D","kind":"skill","strength":"helpful","reason":"Seeing a face as a flat part of a solid relies on the 2-D/3-D distinction.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS.M_EVERY_BOX_IS_CUBE","skill":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","error":"Calls any box-shaped object a cube, or cannot tell a cube from a cuboid.","example":{"question":"Wanjiku has a building brick. Is it a cube or a cuboid?","wrong_answer":"A cube","correct_answer":"A cuboid, because its faces are not all equal squares; some faces are long rectangles."},"cause":"'Cube' is learnt as a general word for 'box', without the condition that all faces are equal squares.","reveals":"Show a dice, a matchbox and a brick and ask which are cubes. A child with this idea picks all three.","help":"Have children press each face of a dice and a matchbox onto paper and compare: a cube's prints are all the same square.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS.M_PROTOTYPE_ORIENTATION","skill":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","error":"Recognises an object only in its usual position. For example, they do not recognise a cylinder lying on its side or a pyramid standing on its point.","example":{"question":"A tin of Kimbo is lying on its side on the table. What 3-D object is it?","wrong_answer":"It is not a cylinder now / a rectangle","correct_answer":"It is still a cylinder; turning an object does not change its shape."},"cause":"Pictures in books usually show cylinders upright and pyramids point-up, so the child links the name to one picture, not to the object's properties.","reveals":"Include pictures of familiar objects in unusual positions among the naming items and see whether accuracy drops.","help":"Let children turn real objects in their hands and name them in every position, and always include tilted or lying-down pictures in tasks.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS.M_SIZE_CHANGES_SHAPE","skill":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","error":"Thinks objects of very different size, colour or material cannot be the same shape.","example":{"question":"Is a plastic water tank the same 3-D object as a tin of milk?","wrong_answer":"No, the tank is much bigger.","correct_answer":"Yes, both are cylinders: two flat circular ends and a curved surface."},"cause":"The child classifies objects by everyday features such as size and use rather than by geometric shape.","reveals":"Ask the child to sort objects of mixed sizes (orange, football, marble, tin, tank picture). They group by size instead of by shape.","help":"Ask 'What stays the same if I make it bigger or smaller?' and sort big and small examples of each object together.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS.M_POINTED_MEANS_PYRAMID","skill":"MATH.G5.GEOMET.3_D_OBJECTS.NAME_3D_OBJECTS","error":"Calls any object with a point at the top a pyramid, including cones such as an ice-cream cone or a round hut roof.","example":{"question":"Is the roof of a round grass-thatched hut a pyramid?","wrong_answer":"Yes, it is pointed.","correct_answer":"No. A pyramid has flat triangular faces meeting at a point and a flat base with straight sides; the hut roof has a curved surface and a circular base."},"cause":"The child focuses on one feature (the point) and ignores whether the surfaces are flat or curved.","reveals":"Odd-one-out task with a square-based pyramid, a triangular-based pyramid and a cone. The child cannot pick the cone.","help":"Let the child run a finger over the sides: a pyramid has flat triangles and straight edges, but a cone has a curved surface.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES.M_CYLINDER_SURFACES","skill":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES","error":"Describes a cylinder as having only curved surfaces (or only flat ones), missing that it has both.","example":{"question":"Describe the surfaces of a tin of cooking fat.","wrong_answer":"It is round, so all its surfaces are curved.","correct_answer":"It has two flat circular surfaces (top and bottom) and one curved surface around the side."},"cause":"The child describes the object by its overall 'roundness' instead of examining each surface separately.","reveals":"Ask whether a tin can stand without rolling and why. The child cannot connect standing on its end to a flat surface.","help":"Have the child stand a tin on its end, then roll it on its side, and say which surface touches the table each time.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES.M_PYRAMID_ONE_CORNER","skill":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES","error":"Counts only the top point of a pyramid as a corner and ignores the corners of the base.","example":{"question":"How many corners does a square-based pyramid have?","wrong_answer":"1","correct_answer":"5 (one at the top and four around the square base)"},"cause":"The apex is the most noticeable feature, and corners at the base are hidden or seen as part of the table.","reveals":"Ask for the number of corners on a pictured pyramid. A wrong answer of 1 exposes the error.","help":"Let children touch and mark each corner of a model pyramid with a small piece of plasticine or a sticker, including those at the bottom.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES.M_ONLY_BALLS_ROLL","skill":"MATH.G5.GEOMET.3_D_OBJECTS.DESCRIBE_3D_FEATURES","error":"Believes only a sphere can roll, or that an object either rolls or slides but cannot do both.","example":{"question":"Which of these can roll: a football, a tin of milk, a matchbox?","wrong_answer":"Only the football","correct_answer":"The football and the tin. The tin rolls on its curved surface and can also slide or stand on its flat ends."},"cause":"Rolling is linked with balls in everyday play, and the child does not link rolling to having a curved surface.","reveals":"Ask 'roll, slide, or both?' for each object. The child gives only one answer for the cylinder.","help":"Do a simple ramp test with a book and real objects, then ask children to explain what kind of surface lets an object roll.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_VS_3D.M_PLANE_NAME_FOR_SOLID","skill":"MATH.G5.GEOMET.3_D_OBJECTS.2D_VS_3D","error":"Uses the name of a flat shape for a solid object, such as 'circle' for a ball or 'square' for a dice.","example":{"question":"What 3-D object is an orange?","wrong_answer":"A circle","correct_answer":"A sphere. A circle is a flat shape; an orange is solid and round all over."},"cause":"Everyday language and early learning use 2-D names for objects, and the child has not separated flat shapes from solids.","reveals":"Multiple-choice item with both 'circle' and 'sphere' (or 'square' and 'cube') as options.","help":"Put a paper circle next to a ball and ask which one you can hold and turn, then insist on the correct name for each.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_VS_3D.M_THIN_OBJECT_IS_2D","skill":"MATH.G5.GEOMET.3_D_OBJECTS.2D_VS_3D","error":"Thinks a thin real object, such as a coin, a chapati or a sheet of paper, is a 2-D shape.","example":{"question":"Is a five-shilling coin a 2-D shape or a 3-D object?","wrong_answer":"2-D, it is a circle.","correct_answer":"3-D. It is a very short cylinder with some thickness; its flat faces are circles."},"cause":"The child judges by how flat an object looks, not by whether it has thickness and takes up space.","reveals":"Sorting task that includes thin objects. The child places a coin or paper with the drawn shapes.","help":"Stack several coins to make a tall cylinder so the child sees each coin has thickness, then name the face (circle) and the object (cylinder) separately.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D.M_VISIBLE_FACES_ONLY","skill":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D","error":"When working from a picture, considers only the faces that can be seen and forgets the hidden ones.","example":{"question":"Mwangi traces round every face of a cube-shaped box on paper. How many squares does he draw?","wrong_answer":"3","correct_answer":"6"},"cause":"The child treats the drawing as the whole object and cannot imagine the back, bottom and other hidden faces.","reveals":"Use a picture-only question that needs hidden faces. An answer of 3 for a cube shows the child is reading only the drawing.","help":"Pair every picture with a real box first, and let children tick off faces with chalk as they trace them.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D.M_PYRAMID_ALL_TRIANGLES","skill":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D","error":"Says all the faces of a square-based pyramid are triangles and forgets the square base.","example":{"question":"What 2-D shapes are the faces of a square-based pyramid?","wrong_answer":"Triangles only","correct_answer":"Four triangles and one square (the base)."},"cause":"The base rests on the table and is not seen as a face, and the triangles stand out.","reveals":"Ask the child to list all the flat shapes, or to choose which object made a square print.","help":"Lift the pyramid and press its base in paint or on sand to show the square print it leaves.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D.M_SPHERE_HAS_CIRCLE_FACE","skill":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D","error":"Says a sphere has a circle as a face because its outline looks like a circle.","example":{"question":"Which 2-D shape is a flat face of a football?","wrong_answer":"A circle","correct_answer":"None. A sphere has one curved surface and no flat face (its outline only looks like a circle)."},"cause":"The child confuses the outline seen in a picture with a flat face that could be traced or printed.","reveals":"Ask 'Which objects could leave a circle print in wet sand?' The child includes the ball.","help":"Try to trace round a ball and a tin on paper: only the tin's flat end gives a proper circle face.","status":"draft"},{"code":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D.M_CYLINDER_SIDE_RECTANGLE_FACE","skill":"MATH.G5.GEOMET.3_D_OBJECTS.2D_FACES_IN_3D","error":"Says a cylinder has a rectangle face because its side view looks like a rectangle.","example":{"question":"What flat shapes are found on a tin of Kimbo?","wrong_answer":"Two circles and a rectangle","correct_answer":"Two circles; the side is a curved surface, not a flat rectangle."},"cause":"The child describes the outline of the side view rather than the actual surface, which is curved.","reveals":"A true/false item, 'A cylinder has a flat rectangular face'. Answering 'true' reveals the error.","help":"Let the child lay a ruler against the curved side to see it does not lie flat, unlike the circular ends.","status":"draft"}]},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION","number":"4.1","strand":"Data Handling","sub_strand":"Data Representation","sequence":401,"lessons":6,"content_topics":["Collecting data","Drawing table and recording data","Interpreting data"],"learning_experiences":["team up with peers to collect data involving day-to-day experiences such as marks, shoe number, age of learners in a class","discuss other sources of data such as the number and types of vehicles on a given road near school and home, discuss also number of bicycles or motor cycles","prepare data collection and recording tools and record data on books or charts","discuss and draw tally marks for the data","organise data in a table from real-life situations","discuss information represented by objects piled vertically","use digital devices and other resources to learn more on representing data in tables"],"key_inquiry_questions":["Why is representing data in tables important?"],"core_competences":"● Learning to learn: learner practises piling items as a form of data organisation. ● Digital literacy: learner uses digital devices and other resources to learn more about frequency tables.","values":"Unity: learner teams up with peers to collect data involving day-to-day experiences.","pcis":"Safety: learner carefully uses digital devices and other resources to learn more on representing data in tables.","links":"The learner is able to relate data representation to population distribution in the county in Social Studies.","design_notes":"1. Attitudinal outcome: outcome f ('appreciate use frequency tables in real life') is attitudinal and is not mapped to a skill. It is quoted as given; 'of' appears to be missing from the official wording. It links to the key inquiry question 'Why is representing data in tables important?', which is partly assessed through the 'explain why a table is useful' form in G5_INFER_FROM_FREQUENCY_TABLE.\n\n2. 'About 30 items' (outcome a) is ambiguous. It could mean about 30 observations (for example 30 learners asked) or 30 different kinds of item. This map takes it as about 30 observations, which fits the Grade 4 limit of 'at most 10 items' and the class-sized examples in the learning experiences. All numerical limits in this map are proposed: frequencies up to about 30, 3 to 6 categories, and data sets of about 25 to 35 items.\n\n3. Outcomes b and d overlap. This map treats b as a table for recording data (the Grade 4 style, including raw data) and d as a frequency table with tally and frequency columns and a total. The design does not state this distinction explicitly; it is proposed.\n\n4. Order of outcomes c and d. Outcome c ('draw tally marks') is mapped to drawing and tallying. Converting tallies to frequencies is placed under d, because a frequency table needs it. This split is proposed.\n\n5. 'Objects piled vertically' appears in the learning experiences, but piling is a Grade 6 outcome (G6 4.1c). In Grade 5 it is best treated as an informal discussion of a picture of the data, not as an assessed skill. Digital devices are named only as a learning resource.\n\n6. Tally notation: in this map, [||||/] stands for one gate, that is four upright strokes crossed by a fifth (5 in total). An assessment engine should render it as a proper tally image.\n\n7. HOREB alignment:\n- G5_TALLY matches outcomes c to e.\n- G5_BAR_GRAPHS and G5_PICTOGRAPHS have no matching outcome in this Grade 5 sub-strand. Pictographs and bar graphs appear in Grade 6 (4.1b and 4.1d), so HOREB may want to review the grade placement of these two skills.\n- G4_DATA is named 'Bar Graphs & Tables', but the Grade 4 design covers tables only.\n- G6_DATA_COLLECTION overlaps with outcome a in Grade 5, although its own Grade 6 outcomes start from frequency tables.\n\n8. Counting in fives is needed for G5_TALLY_TO_FREQUENCY. It belongs to the Numbers strand, which is not among the inputs, so it is not linked as a prerequisite code.","outcomes":[{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.a","letter":"a","text":"collect data of about 30 items relating to real-life experiences","status":"kicd_verified"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.b","letter":"b","text":"draw a table to record data from real-life situations","status":"kicd_verified"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.c","letter":"c","text":"draw tally marks of the collected data","status":"kicd_verified"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.d","letter":"d","text":"prepare a frequency table to represent data","status":"kicd_verified"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.e","letter":"e","text":"interpret data represented by frequency tables","status":"kicd_verified"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.f","letter":"f","text":"appreciate use frequency tables in real life","status":"kicd_verified"}],"skills":[{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION","name":"Plan a data collection: choose a question, categories and a method","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.a"],"mastery":"Given a real-life situation such as learners' ages, shoe sizes, marks, favourite foods or vehicles passing the school, the child states what will be counted, chooses clear categories that do not overlap (3 to 6 categories, with 'other' where needed), and chooses a method such as asking, observing or counting. Proposed limit: the plan should produce a data set of about 30 observations.","question_forms":["choose a suitable question to collect data","spot what is wrong with a set of categories","choose a method: ask, observe or count","identify which of these is data"],"thinking":["reasoning"],"horeb_skill_ids":["G6_DATA_COLLECTION"],"prerequisites":[{"requires":"MATH.G4.DATA_H.DATA.a","kind":"outcome","strength":"essential","reason":"Choosing a method and tool builds on identifying materials for collecting and recording data.","status":"proposed"},{"requires":"MATH.G4.DATA_H.DATA.b","kind":"outcome","strength":"helpful","reason":"Experience of a small collection (at most 10 items) shows why categories must be decided first.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COLLECT_DATA_30","name":"Collect and record about 30 observations from a real-life situation","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.a"],"mastery":"The child collects data on about 30 items, for example 30 classmates' favourite drinks or vehicles passing for 15 minutes. Each observation is recorded once, in a book or on a chart, and the child checks that the number recorded matches the number observed.","question_forms":["practical task: collect data from the class","check a record against the number of people asked","find the error in someone else's collected data"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G6_DATA_COLLECTION"],"prerequisites":[{"requires":"MATH.G4.DATA_H.DATA.b","kind":"outcome","strength":"essential","reason":"Collecting about 30 items extends collecting at most 10 items.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION","kind":"skill","strength":"essential","reason":"Without clear categories and a method, a collection of 30 items becomes muddled.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_RECORDING_TABLE","name":"Draw a table to record data","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.b"],"mastery":"The child draws a ruled table with a title, labelled column headings (for example 'Name | Age' or 'Type of vehicle | Number') and one row per item or category. The child enters data from a real-life situation in the correct cells. Proposed limit: up to about 30 rows of raw data, or up to 6 category rows.","question_forms":["draw a table for given data","choose or write the missing heading or title","enter given data into a table","find the mistake in a table"],"thinking":["procedure"],"horeb_skill_ids":["G4_DATA"],"prerequisites":[{"requires":"MATH.G4.DATA_H.DATA.c","kind":"outcome","strength":"essential","reason":"Drawing a recording table was introduced in Grade 4.","status":"proposed"},{"requires":"MATH.G4.DATA_H.DATA.d","kind":"outcome","strength":"essential","reason":"Entering data in the right cells was practised in Grade 4.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION","kind":"skill","strength":"helpful","reason":"The planned categories become the rows and headings of the table.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS","name":"Show a number as tally marks in groups of five","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.c"],"mastery":"The child draws any whole number up to about 30 as tally marks. Each group of five is a 'gate' of four upright strokes crossed by a fifth, written [||||/] in this map, and the remainder is shown as single strokes. For example, 13 is [||||/] [||||/] |||.","question_forms":["draw tallies for a number","match a number to its tally","spot the wrongly drawn tally"],"thinking":["recall","procedure"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G4.DATA_H.DATA.d","kind":"outcome","strength":"helpful","reason":"Tallies are a faster way of recording data in a table.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_RAW_DATA","name":"Tally collected data into categories","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.c"],"mastery":"The child works through a raw list of about 30 observations, either words or numbers such as shoe sizes. For each observation the child makes one tally mark against the correct category, without skipping or repeating any. The child then checks that the total number of tally marks equals the number of observations.","question_forms":["tally a list of raw data","tally numerical data (sizes, ages, marks)","find the item that was missed or tallied twice"],"thinking":["procedure"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS","kind":"skill","strength":"essential","reason":"The child must be able to form tally groups before tallying a list.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.COLLECT_DATA_30","kind":"skill","strength":"helpful","reason":"Tallying the child's own collected data gives it meaning.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_TO_FREQUENCY","name":"Convert tally marks to frequencies","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.d"],"mastery":"The child reads a set of tally marks (up to about 30) and writes the number correctly. The child counts each gate as five and then counts on in ones.","question_forms":["write the number shown by the tallies","complete the frequency column from the tally column","which tally shows the bigger number"],"thinking":["procedure"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS","kind":"skill","strength":"essential","reason":"Knowing that a gate stands for five is needed to read tallies.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.PREPARE_FREQUENCY_TABLE","name":"Prepare a frequency table","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.d"],"mastery":"From raw data of about 30 items, the child prepares a titled frequency table. It has the columns 'item or category | tally | frequency', one row per category (not one per observation), and a total row. The child checks that the total equals the number of items collected.","question_forms":["prepare a frequency table from raw data","complete a partly filled frequency table","check whether the total is correct","fill the missing frequency given the total"],"thinking":["procedure","reasoning"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_RAW_DATA","kind":"skill","strength":"essential","reason":"The tally column is built by tallying the raw data.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_TO_FREQUENCY","kind":"skill","strength":"essential","reason":"The frequency column comes from counting the tallies.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_RECORDING_TABLE","kind":"skill","strength":"essential","reason":"A frequency table is a table with a title, headings and rows.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE","name":"Read information directly from a frequency table","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.e"],"mastery":"The child reads the frequency of a given category, finds the category with a given frequency, and identifies the most and least common category. This includes numerical categories such as ages or shoe sizes, where the child must keep the value and its frequency apart. Proposed limit: frequencies up to about 30.","question_forms":["how many chose X","which category had N","most common / least common","read a table of numerical data (ages, shoe sizes)"],"thinking":["procedure"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G4.DATA_H.DATA.e","kind":"outcome","strength":"essential","reason":"Reading information from a table of raw data comes before reading frequencies.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_TO_FREQUENCY","kind":"skill","strength":"helpful","reason":"Tables may show tallies only, so the child must convert them to read them.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES","name":"Compare and combine frequencies from a table","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.e"],"mastery":"Using whole-number frequencies with a total of about 30, the child answers questions of these kinds: 'how many more or fewer', 'how many altogether', 'how many in two categories together' and 'how many did not choose X'.","question_forms":["word problem: how many more / fewer","total number surveyed","combine two categories","how many did not choose X"],"thinking":["procedure","problem solving"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE","kind":"skill","strength":"essential","reason":"Frequencies must be read correctly before they are compared or combined.","status":"proposed"}],"status":"proposed"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE","name":"Draw conclusions and make decisions from a frequency table","outcomes":["MATH.G5.DATA_H.DATA_REPRESENTATION.e"],"mastery":"The child says whether statements about the data are true or false and gives a reason. The child uses the table to make a sensible real-life decision, such as which fruit the canteen should buy most of, and keeps conclusions to the group that was surveyed.","question_forms":["true or false: explain using the table","make a decision and justify it","which statement does the table support","explain why a table is useful here"],"thinking":["reasoning","problem solving"],"horeb_skill_ids":["G5_TALLY"],"prerequisites":[{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE","kind":"skill","strength":"essential","reason":"Conclusions rest on reading the table correctly.","status":"proposed"},{"requires":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES","kind":"skill","strength":"helpful","reason":"Judging claims like 'more than half' needs the total and comparisons.","status":"proposed"},{"requires":"MATH.G4.DATA_H.DATA.e","kind":"outcome","strength":"helpful","reason":"Interpreting tables of raw data in Grade 4 begins this reasoning.","status":"proposed"}],"status":"proposed"}],"misconceptions":[{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION.M_OVERLAPPING_CATEGORIES","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION","error":"Chooses categories where one includes another, so some items fit two categories.","example":{"question":"Wanjiru will record vehicles passing the school gate using these categories: car, matatu, vehicle, motorcycle. What is wrong with her categories?","wrong_answer":"Nothing is wrong.","correct_answer":"'Vehicle' includes all the others, so a matatu could be recorded under 'matatu' or 'vehicle'. She should replace 'vehicle' with separate types such as lorry, bicycle or 'other'."},"cause":"The child lists words linked to the topic without checking that each item belongs to exactly one category.","reveals":"Give a category list containing a general word and ask where a particular item (a matatu) should go; children with this error will not notice two possible places.","help":"Before collecting, ask learners to sort a few real examples into the categories and check that each one fits in exactly one place.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION.M_DATA_ONLY_NUMBERS","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.PLAN_DATA_COLLECTION","error":"Thinks only numbers count as data, so rejects information such as colours, foods or types of vehicle.","example":{"question":"Which of these can be collected as data? A: the shoe sizes of 30 learners. B: the favourite foods of 30 learners. C: both A and B.","wrong_answer":"A only","correct_answer":"C. Favourite foods are data too: we count how many learners chose each food."},"cause":"Mathematics is linked only with numbers, and counting the choices is not yet seen as producing data.","reveals":"Offer one numerical and one category data set in a 'which is data' item; option A exposes the error.","help":"Collect a category set in class (for example favourite food: ugali, chapati, rice) and show that it becomes numbers once counted.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COLLECT_DATA_30.M_DOUBLE_COUNTING","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.COLLECT_DATA_30","error":"Records some people or items twice, or misses some, and does not check the total against the number observed.","example":{"question":"Juma asked his 30 classmates their favourite drink. He recorded: tea 12, uji 9, milk 8, juice 6. Is his record correct?","wrong_answer":"Yes, it is correct.","correct_answer":"No. 12 + 9 + 8 + 6 = 35, but only 30 learners were asked, so some answers were recorded more than once."},"cause":"The child does not see that the total of the records must equal the number of people or items observed.","reveals":"Give a record whose total does not match the stated number surveyed and ask whether it is correct.","help":"Have learners tick off each name on the class list as it is recorded, and add up the records at the end to compare with the class size.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COLLECT_DATA_30.M_DISTINCT_VALUES_ONLY","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.COLLECT_DATA_30","error":"Writes each different value only once instead of recording every observation, so repeated values are lost.","example":{"question":"Atieno asked 30 learners their shoe size and wrote down: 3, 4, 5, 6. What has gone wrong?","wrong_answer":"Nothing is wrong. Those are the sizes.","correct_answer":"She has recorded only the different sizes. She needs 30 entries, one for each learner (for example 4, 5, 4, 3, 5, ...), so that she can count how many learners wear each size."},"cause":"The child sees the task as finding out which sizes exist rather than how many learners have each size.","reveals":"Ask how many learners wear size 4 using her record; the child with this error cannot answer, or says 1.","help":"Ask 'How many people did you ask? How many entries have you got?' so that learners see there must be one record per person.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_RECORDING_TABLE.M_TABLE_NO_HEADINGS","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_RECORDING_TABLE","error":"Draws a table without a title or column headings, so a reader cannot tell what the entries mean.","example":{"question":"Achieng's table has two rows: 'Mango | 7' and 'Orange | 4'. A visitor asks, '7 what?' What should Achieng add?","wrong_answer":"Nothing. The numbers are clear.","correct_answer":"A title such as 'Favourite fruits of Grade 5 learners', and the column headings 'Fruit' and 'Number of learners'."},"cause":"The child knows what the numbers mean and does not think about a reader who did not collect the data.","reveals":"Show a table without headings and ask what is missing, or ask a learner to explain someone else's table.","help":"Swap tables between pairs and ask each pair to explain the other's table without talking to its owner; then add whatever was missing.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_RECORDING_TABLE.M_ROW_MISALIGNMENT","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_RECORDING_TABLE","error":"Writes an entry in the row next to the one it belongs to, so values are paired with the wrong names or categories.","example":{"question":"Record in a 'Name | Age' table: Otieno is 11, Akinyi is 10, Baraka is 12.","wrong_answer":"Otieno | 10, Akinyi | 12, Baraka | (blank). The ages have slipped up one row.","correct_answer":"Otieno | 11, Akinyi | 10, Baraka | 12"},"cause":"The child fills the columns separately and does not read across each row, often because the rows are not ruled.","reveals":"After recording, ask 'How old is Akinyi?' and check whether the answer read from the table matches the data given.","help":"Insist on ruled rows, and have learners fill one complete row (name and age) before moving to the next.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS.M_GATE_SIX_STROKES","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS","error":"Draws five upright strokes and then a crossing stroke, so each 'gate' actually stands for six.","example":{"question":"Show 7 using tally marks.","wrong_answer":"[|||||/] || (five upright strokes plus a crossing stroke, then two more; this is 8)","correct_answer":"[||||/] || (four upright strokes crossed by a fifth, then two strokes)"},"cause":"The child remembers 'groups of five with a line across' but not that the crossing line is the fifth stroke.","reveals":"Ask the child to count every stroke in their gate aloud; a multiple-choice item can include the six-stroke gate as a distractor.","help":"Count aloud while drawing ('one, two, three, four, and FIVE goes across'), using bottle tops or sticks first.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS.M_NO_GROUPING","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.DRAW_TALLY_GROUPS","error":"Draws a long row of single strokes without making groups of five, which makes counting slow and leads to mistakes.","example":{"question":"Show 13 using tally marks.","wrong_answer":"||||||||||||| (13 separate strokes)","correct_answer":"[||||/] [||||/] |||"},"cause":"The child sees tallies only as one mark for each item and not as a way to count quickly in fives.","reveals":"Show a long ungrouped row and a grouped tally and ask which is quicker to count, or time learners counting each.","help":"Let learners race to count 23 ungrouped strokes against 23 grouped ones, then discuss why the grouped tally was faster.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_RAW_DATA.M_TALLY_SKIP_OR_REPEAT","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_RAW_DATA","error":"Loses their place in the raw list, so some items are not tallied and others are tallied twice.","example":{"question":"Tally these drinks: tea, uji, tea, milk, tea, uji, milk, tea, uji, tea.","wrong_answer":"tea ||||, uji |||, milk || (only 9 marks; one tea was missed)","correct_answer":"tea [||||/] (5), uji ||| (3), milk || (2). The total is 10, the same as the number of items in the list."},"cause":"The child works through the list without marking which items have already been tallied.","reveals":"Ask whether the total number of tally marks equals the number of items in the list.","help":"Teach learners to cross out each item lightly as they tally it, and to check that the total number of marks equals the number of items.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_RAW_DATA.M_TALLY_THE_VALUE","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_RAW_DATA","error":"With numerical data, draws as many strokes as the value itself (for example 4 strokes for shoe size 4) instead of one stroke per learner.","example":{"question":"Shoe sizes: 4, 5, 4, 6, 5, 4. Draw the tally for size 4.","wrong_answer":"[||||/] [||||/] || (12 strokes: four for each of the three 4s)","correct_answer":"||| (3 strokes, because three learners wear size 4)"},"cause":"The child mixes up the value being recorded (size 4) with how many times it occurs.","reveals":"Use numerical data in tallying tasks and ask how many learners the tally stands for.","help":"Have each learner say 'one stroke for me' as their size is tallied, so learners see that each mark stands for one person.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_TO_FREQUENCY.M_GATE_READ_AS_FOUR","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.TALLY_TO_FREQUENCY","error":"Counts a gate as 4, counting only the upright strokes and ignoring the crossing stroke.","example":{"question":"What number do these tallies show? [||||/] [||||/] ||","wrong_answer":"10","correct_answer":"12 (5 + 5 + 2)"},"cause":"The child sees the crossing line as a way of closing the group rather than as a stroke that counts.","reveals":"Include 10 (gates counted as 4) and 14 (gates counted as 6) as distractors.","help":"Have learners count each gate aloud as 'five' and then count on in ones: 'five, ten, eleven, twelve'.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.PREPARE_FREQUENCY_TABLE.M_FREQ_TOTAL_UNCHECKED","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.PREPARE_FREQUENCY_TABLE","error":"Completes the frequency table without checking that the total frequency equals the number of items collected.","example":{"question":"Data were collected from 30 learners. The frequencies in the table are 8, 11, 6 and 4. Is the table complete?","wrong_answer":"Yes","correct_answer":"No. 8 + 11 + 6 + 4 = 29, so one learner is missing. The tallies should be checked again."},"cause":"The child sees the total row as something to fill in, not as a check on the work.","reveals":"Give a table whose total is one less or one more than the stated number surveyed and ask whether it is correct.","help":"Make 'Does my total match the number I collected?' the final step every time a frequency table is prepared.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.PREPARE_FREQUENCY_TABLE.M_ROW_PER_OBSERVATION","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.PREPARE_FREQUENCY_TABLE","error":"Makes a new row for each observation, each with frequency 1, instead of one row per category.","example":{"question":"Prepare a frequency table for these ages: 10, 11, 10, 10, 12, 11.","wrong_answer":"Six rows: 10 | 1, 11 | 1, 10 | 1, 10 | 1, 12 | 1, 11 | 1","correct_answer":"Three rows: Age 10 | 3, Age 11 | 2, Age 12 | 1. The total is 6."},"cause":"The child copies the raw recording table from Grade 4 and does not see that the purpose of a frequency table is to group the same values together.","reveals":"Ask 'How many learners are 10?' and see whether the child has to add up rows to answer.","help":"List the categories first (each value written once), then tally the data into them, and compare the result with the raw list.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE.M_VALUE_VS_FREQUENCY","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE","error":"With numerical categories, gives the frequency when the question asks for the value, or gives the value when it asks for the frequency.","example":{"question":"Age 10: 9 learners. Age 11: 14 learners. Age 12: 7 learners. Which age is the most common?","wrong_answer":"14","correct_answer":"11 years (14 learners are aged 11)"},"cause":"Both columns contain numbers, and the child picks the largest number without checking what the column heading says.","reveals":"Ask 'which age' and 'how many learners' questions on the same table; the distractor is the number from the other column.","help":"Have learners point to the column heading and say what the question is asking for, an age or a number of learners, before they answer.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE.M_BIGGEST_LABEL_IS_MOST","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.READ_FREQUENCY_TABLE","error":"Picks the category with the largest label, or the last row, as the most common instead of the one with the highest frequency.","example":{"question":"Shoe size 3: 5 learners. Size 4: 12 learners. Size 5: 9 learners. Size 6: 4 learners. Which size is worn by the most learners?","wrong_answer":"Size 6","correct_answer":"Size 4 (12 learners)"},"cause":"The child takes 'most' to mean the biggest number anywhere in the table, or the last row.","reveals":"Order the rows so that the largest label has the smallest frequency; children with this error choose the largest label.","help":"Ask learners to circle the largest number in the frequency column first, then read across to the category in that row.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES.M_HOW_MANY_MORE_ADD","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES","error":"Adds the two frequencies when asked 'how many more'.","example":{"question":"In 15 minutes, 12 matatus and 9 boda bodas passed the school. How many more matatus than boda bodas passed?","wrong_answer":"21","correct_answer":"3 (12 − 9)"},"cause":"The child hears the word 'more' and adds.","reveals":"Include the sum as a distractor in 'how many more' and 'how many fewer' items.","help":"Model the comparison by lining up 12 counters against 9 and asking how many are left without a partner.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES.M_TOTAL_IS_ROWS","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES","error":"Gives the number of categories, or a single frequency, when asked how many were surveyed altogether.","example":{"question":"Favourite drinks: tea 12, uji 8, milk 6, juice 4. How many learners were asked?","wrong_answer":"4","correct_answer":"30 (12 + 8 + 6 + 4)"},"cause":"The child counts the rows (the kinds of drink) rather than the learners.","reveals":"Offer the number of rows and the largest frequency as distractors.","help":"Ask 'What does each row stand for, and what does each number stand for?' before learners find the total.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES.M_NOT_CHOOSING_MISREAD","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.COMPARE_TOTAL_FREQUENCIES","error":"When asked how many did NOT choose a category, gives that category's own frequency.","example":{"question":"Favourite drinks: tea 12, uji 8, milk 6, juice 4. How many learners did not choose tea?","wrong_answer":"12","correct_answer":"18 (30 − 12, or 8 + 6 + 4)"},"cause":"The child reads the category name in the question and does not notice the word 'not'.","reveals":"Use 'not' questions with the category's own frequency as a distractor.","help":"Have learners underline 'not' and cover the tea row with a hand, then add up the rows that are left.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE.M_MOST_POPULAR_IS_MAJORITY","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE","error":"Thinks that the most popular category must have been chosen by more than half of the group.","example":{"question":"Favourite games of 30 learners: football 12, netball 8, volleyball 6, athletics 4. True or false: more than half of the learners chose football.","wrong_answer":"True, because football is the most popular.","correct_answer":"False. Half of 30 is 15, and 12 is less than 15. Football is the most chosen game, but most learners (18) chose something else."},"cause":"The child treats 'most popular' and 'chosen by most learners' as the same thing.","reveals":"Ask a true-or-false item where the top category is below half the total.","help":"Have learners always find half of the total and compare the top frequency with it before saying 'most learners'.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE.M_OVERGENERALISE","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE","error":"Applies a conclusion from one class to everyone, for example all children in Kenya.","example":{"question":"In a survey of one Grade 5 class of 30, football was chosen by 12 learners, more than any other game. Which statement does the table support? A: All children in Kenya prefer football. B: In this class, more learners chose football than any other game.","wrong_answer":"A","correct_answer":"B. The data are only about this class."},"cause":"The child does not yet see that data describe only the group they were collected from.","reveals":"Include an overgeneralised statement among the options in a 'which statement is supported' item.","help":"Ask 'Who did we actually ask?' and have learners start their conclusions with 'In our class ...'.","status":"draft"},{"code":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE.M_OPINION_OVER_DATA","skill":"MATH.G5.DATA_H.DATA_REPRESENTATION.INFER_FROM_FREQUENCY_TABLE","error":"Makes a decision from personal preference instead of from the data in the table.","example":{"question":"The canteen asked 30 learners for their favourite fruit: banana 11, mango 9, orange 6, pawpaw 4. Which fruit should the canteen buy most of?","wrong_answer":"Mango, because it is the sweetest.","correct_answer":"Banana, because the most learners (11) chose it."},"cause":"The child does not yet see the purpose of collecting data, which is to base decisions on evidence rather than opinion.","reveals":"Ask for the answer and a reason; a reason that does not mention a number from the table shows the error.","help":"Require every decision to be backed by a number from the table: 'I choose ___ because ___ learners chose it.'","status":"draft"}]}]}$CURR$::jsonb;
BEGIN
  INSERT INTO public.curriculum_substrands (code, subject_key, grade, strand, sub_strand, sequence, source, framework, lessons, detail)
  SELECT s->>'code', d->>'subject_key', (d->>'grade')::int, s->>'strand', s->>'sub_strand', (s->>'sequence')::int, 'kicd_2024', d->>'framework', (s->>'lessons')::int,
         jsonb_build_object('number', s->'number', 'content_topics', s->'content_topics', 'learning_experiences', s->'learning_experiences', 'key_inquiry_questions', s->'key_inquiry_questions',
           'core_competences', s->'core_competences', 'values', s->'values', 'pcis', s->'pcis', 'links', s->'links', 'design_notes', s->'design_notes')
  FROM jsonb_array_elements(d->'sub_strands') s
  ON CONFLICT (code) DO UPDATE SET strand = EXCLUDED.strand, sub_strand = EXCLUDED.sub_strand, sequence = EXCLUDED.sequence, source = EXCLUDED.source, framework = EXCLUDED.framework, lessons = EXCLUDED.lessons, detail = EXCLUDED.detail;

  INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status)
  SELECT o->>'code', s->>'code', o->>'letter', o->>'text', o->>'status'
  FROM jsonb_array_elements(d->'sub_strands') s, jsonb_array_elements(s->'outcomes') o
  ON CONFLICT (code) DO UPDATE SET text = EXCLUDED.text, status = EXCLUDED.status, updated_at = now();

  INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status)
  SELECT k->>'code', s->>'code', d->>'subject_key', (d->>'grade')::int, k->>'name',
         ARRAY(SELECT jsonb_array_elements_text(k->'outcomes')), k->>'mastery', COALESCE(k->'question_forms', '[]'::jsonb), COALESCE(k->'thinking', '[]'::jsonb),
         ARRAY(SELECT jsonb_array_elements_text(COALESCE(k->'horeb_skill_ids', '[]'::jsonb))), COALESCE(k->>'status', 'proposed')
  FROM jsonb_array_elements(d->'sub_strands') s, jsonb_array_elements(s->'skills') k
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, status = EXCLUDED.status, updated_at = now();

  INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status)
  SELECT k->>'code', p->>'requires', p->>'kind', COALESCE(p->>'strength', 'essential'), p->>'reason', COALESCE(p->>'status', 'proposed')
  FROM jsonb_array_elements(d->'sub_strands') s, jsonb_array_elements(s->'skills') k, jsonb_array_elements(COALESCE(k->'prerequisites', '[]'::jsonb)) p
  ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason, status = EXCLUDED.status;

  INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status)
  SELECT m->>'code', m->>'skill', m->>'error', m->'example', m->>'cause', m->>'reveals', m->>'help', COALESCE(m->>'status', 'draft')
  FROM jsonb_array_elements(d->'sub_strands') s, jsonb_array_elements(s->'misconceptions') m
  ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, status = EXCLUDED.status, updated_at = now();
END $$;

-- Reference data: the app reads it, only the service role writes it.
ALTER TABLE public.curriculum_substrands ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.curriculum_outcomes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.curriculum_skills ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.curriculum_prerequisites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.curriculum_misconceptions ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['curriculum_substrands','curriculum_outcomes','curriculum_skills','curriculum_prerequisites','curriculum_misconceptions'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS read_%1$s ON public.%1$s', t);
    EXECUTE format('CREATE POLICY read_%1$s ON public.%1$s FOR SELECT TO authenticated USING (true)', t);
    EXECUTE format('DROP POLICY IF EXISTS srv_%1$s ON public.%1$s', t);
    EXECUTE format('CREATE POLICY srv_%1$s ON public.%1$s FOR ALL TO service_role USING (true) WITH CHECK (true)', t);
  END LOOP;
END $$;
COMMIT;
